import dbus
class SystemdInhibitor:
    def __init__(self):
        self.bus = dbus.SystemBus()
        self.login1 = dbus.Interface(
            self.bus.get_object("org.freedesktop.login1", "/org/freedesktop/login1"),
            "org.freedesktop.login1.Manager"
        )
        self.lock = None
        self.lock_types = "sleep:handle-lid-switch"
    def inhibit_suspend(self, app_name, description):
        if not self.lock:
            self.lock = self.login1.Inhibit(
                self.lock_types,
                app_name,
                description,
                "block",
                dbus_interface="org.freedesktop.login1.Manager"
            ).take()
    def release_inhibition(self):
        if self.lock:
            self.lock.release()
            self.lock = None

