import os
import shutil
def organize_summaries(original_dataset_path, destination_path, source_path):
    for folder in os.listdir(original_dataset_path):
        if os.path.isdir(os.path.join(original_dataset_path, folder)):
            path = os.path.join(destination_path, folder)
            if not os.path.exists(path):
                os.makedirs(path)
            # Copy summaries from source_path to destination_path and organize them
            source_folder_path = os.path.join(source_path, folder)
            if os.path.exists(source_folder_path):
                for file in os.listdir(source_folder_path):
                    source_file_path = os.path.join(source_folder_path, file)
                    destination_file_path = os.path.join(path, file)
                    shutil.copy2(source_file_path, destination_file_path)

import torch
def generate_self_interaction_indices(T, num_agents):
    self_idx = torch.tensor(
        [
            [
                t * num_agents * num_agents + num_agents * i + i
                for i in range(num_agents)
            ]
            for t in range(T)
        ]
    )
    return self_idx
