import re
def validate_package_metadata(metadata: dict) -> bool:
    # Validation 1: Package name should not be empty and consist of alphanumeric characters and underscores only
    if not (metadata.get('name') and re.match(r'^[a-zA-Z0-9_]+$', metadata['name'])):
        return False

    # Validation 2: Validate the version number to ensure it follows the semantic versioning format (major.minor.patch)
    if not re.match(r'^\d+\.\d+\.\d+$', metadata.get('version', '')):
        return False

    # Validation 3: Check that the author's name and email are provided and are in a valid format
    if not (metadata.get('author') and metadata.get('author_email') and '@' in metadata['author_email']):
        return False

    # Validation 4: Verify that the URL is a valid HTTP or HTTPS URL
    url_pattern = re.compile(r'https?://\S+')
    if not (metadata.get('url') and url_pattern.match(metadata['url'])):
        return False

    # Validation 5: Confirm that the install dependencies are provided as a list of strings
    if not (metadata.get('install_requires') and isinstance(metadata['install_requires'], list)):
        return False

    return True

class DatetimeEncoder(json.JSONEncoder):
    """
    A type of JSONEncoder that knows how to handle date and datetime
    objects. Serialises to a standard ISO format, which is 
    usable directly in JS.
    """

    def default(self, obj):
        if isinstance(obj, datetime):
            return obj.strftime('%Y-%m-%dT%H:%M:%SZ')
        elif isinstance(obj, date):
            return obj.strftime('%Y-%m-%d')

import string
def default_format_mapping():
    """
    Return a default mapping of values.
    """
    return {'default_key1': 'default_value1', 'default_key2': 'default_value2'}
def safe_format_file(s, mapping, fpath):
    """
    Construct a filename from a string template.
    Extract values from the file name / path and use them to safely format a new filename.
    """
    t = string.Template(s)
    if 'def_mapping' in mapping:
        mapping = default_format_mapping().update(mapping)
    return t.safe_substitute(mapping)

