import jwt
def decode_user_token(user_token: str, private_key: str, check_if_admin: bool) -> Tuple[Optional[str], Optional[str]]:
    try:
        decoded_token = jwt.decode(user_token, private_key, algorithms=['HS256'])
        if check_if_admin and not decoded_token.get('is_admin', False):
            return "Unauthorized access", None
        user_id = decoded_token.get('user_id')
        if user_id is None:
            return "Invalid user token", None
        return None, user_id
    except jwt.ExpiredSignatureError:
        return "Token has expired", None
    except jwt.InvalidTokenError:
        return "Invalid token", None

