public ListNode rotateLinkedList(ListNode head, int k) {
    if (head == null || head.next == null || k == 0) {
        return head;
    }
    ListNode current = head;
    int length = 1;
    while (current.next != null) {
        current = current.next;
        length++;
    }
    current.next = head; // make it a circular linked list
    int breakAt = length - k % length - 1;
    ListNode breakHere = head;
    for (int i = 0; i < breakAt; i++) {
        breakHere = breakHere.next;
    }
    ListNode newHead = breakHere.next;
    breakHere.next = null;
    return newHead;
}
