import onnxruntime
class ONNXInterface:
    def __init__(self, model_path, tokenizer=None):
        self.model_path = model_path
        self.tokenizer = tokenizer
        self.model = onnxruntime.InferenceSession(model_path)
        if tokenizer:
            if isinstance(tokenizer, (BertTokenizer, AutoTokenizer, BertTokenizerFast, XLNetTokenizer)):
                self.tokenizer = tokenizer
            else:
                raise ValueError("Invalid tokenizer type provided")
    def process_input(self, input_text):
        if self.tokenizer:
            inputs = self.tokenizer(input_text, return_tensors="pt", padding=True, truncation=True)
            input_ids = inputs["input_ids"]
            attention_mask = inputs["attention_mask"]
            ort_inputs = {self.model.get_inputs()[0].name: input_ids.numpy(), self.model.get_inputs()[1].name: attention_mask.numpy()}
        else:
            ort_inputs = {"input_text": input_text}
        ort_outs = self.model.run(None, ort_inputs)
        return ort_outs

