import requests
class TestKafkaAvroSink:
    def test_kafka_avro_sink(self, kafka, schema_registry):
        # Define Avro schema for the data
        avro_schema = {
            "type": "record",
            "name": "TestMessage",
            "fields": [
                {"name": "id", "type": "int"},
                {"name": "name", "type": "string"}
            ]
        }
        # Register Avro schema in Schema Registry
        try:
            response = requests.post(f"{schema_registry.url}/subjects/test-message/versions", json={"schema": json.dumps(avro_schema)})
            response.raise_for_status()
        except requests.exceptions.RequestException as e:
            print(f"Failed to register schema: {e}")
            return
        # Produce a sample message with the defined schema and send it to Kafka
        message = {"id": 1, "name": "Test"}
        try:
            kafka.produce_message("test-topic", message, avro_schema)
        except Exception as e:
            print(f"Failed to produce message to Kafka: {e}")
            return
        # Consume the message from Kafka topic and verify the Avro schema
        try:
            consumed_message = kafka.consume_message("test-topic")
            reader = io.BytesIO(consumed_message)
            datum_reader = io.DatumReader(writer_schema=schema.Parse(json.dumps(avro_schema)))
            data_file_reader = DataFileReader(reader, datum_reader)
            for record in data_file_reader:
                print(f"Consumed message: {record}")
        except Exception as e:
            print(f"Failed to consume message from Kafka: {e}")
            return

