        self._type = doc_type
    def es_insert(self, insert_data):
        """
        es insert data
        args: insert_data
        return:
        """
        try:
            self.es.index(index=self._index, doc_type=self._type, body=insert_data)
        except Exception as e:
            raise e
    def es_update(self, id_info, update_info):
        """
        es update data
        args: update_info, id_info
        return:
        """
        try:
            self.es.update(index=self._index, doc_type=self._type, id=id_info, body={"doc": update_info})
        except Exception as e:
            raise e

