from enum import Enum
class CompressionFormat(Enum):
    gz = "gzip"
    bz2 = "bzip2"
    xz = "xz"
    none = "none"
    @property
    def full_name(self) -> str:
        """
        Returns a more-complete name of this format.
        For example, "gzip" "bzip2", "xz", and "none".
        """
        return {CompressionFormat.gz: "gzip", CompressionFormat.bz2: "bzip2"}.get(self, self.name)
    @property
    def is_compressed(self) -> bool:
        """
        Returns True if the compression format is compressed, False otherwise.
        """
        return self in {CompressionFormat.gz, CompressionFormat.bz2, CompressionFormat.xz}

import sys
import socket
def port_scanner(ip, port):
    try:
        port = int(port)
        if port < 1 or port > 65535:
            print("Invalid port number")
            return
    except ValueError:
        print("Invalid port number")
        return
    try:
        socket.inet_aton(ip)
    except socket.error:
        print("Invalid IP address")
        return
    s = socket.socket()
    s.settimeout(3)
    try:
        s.connect((ip, port))
        print(f"Port {port} is open")
    except socket.timeout:
        print(f"Connection to port {port} timed out")
    except ConnectionRefusedError:
        print(f"Port {port} is closed")
    except Exception as e:
        print("Connection error: " + str(e))
    finally:
        s.close()
if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python port_scanner.py [IP_address] [port_number]")
    else:
        ip = sys.argv[1]
        port = sys.argv[2]
        port_scanner(ip, port)

