from ansible.module_utils.basic import AnsibleModule
import requests
def main():
    module = AnsibleModule(
        argument_spec=dict(
            name=dict(type='str', required=True),
            attributes=dict(type='dict', required=False, default={}),
            state=dict(type='str', required=False, default='present', choices=['present', 'absent'])
        )
    )
    base_url = 'https://foreman.example.com/api/v2/locations'
    headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}
    auth = ('username', 'password')  # Replace with actual Foreman credentials
    name = module.params['name']
    attributes = module.params['attributes']
    state = module.params['state']
    if state == 'present':
        payload = {'name': name, **attributes}
        response = requests.post(base_url, json=payload, auth=auth, headers=headers)
    elif state == 'absent':
        location_id = get_location_id(name, auth, headers)
        if location_id:
            delete_url = f'{base_url}/{location_id}'
            response = requests.delete(delete_url, auth=auth, headers=headers)
        else:
            module.exit_json(changed=False, msg=f"Location '{name}' not found, no action required.")
    if response.status_code == 201 or response.status_code == 200:
        module.exit_json(changed=True, msg=f"Location '{name}' {state}ed successfully.")
    else:
        module.fail_json(msg=f"Failed to {state} location '{name}'. Error: {response.text}")
def get_location_id(name, auth, headers):
    base_url = 'https://foreman.example.com/api/v2/locations'
    response = requests.get(base_url, auth=auth, headers=headers)
    locations = response.json()['results']
    for location in locations:
        if location['name'] == name:
            return location['id']
    return None
if __name__ == '__main__':
    main()

def process_module_data(mod_yaml, name, stream, version, context, arch, summary, description, module_licenses, content_licenses, rpms_nevras):
    # Validate input arguments
    if not isinstance(mod_yaml, str) or not mod_yaml:
        raise ValueError("mod_yaml must be a non-empty string")
    if not isinstance(name, str) or not name:
        raise ValueError("name must be a non-empty string")
    if not isinstance(stream, str) or not stream:
        raise ValueError("stream must be a non-empty string")
    if not isinstance(version, int) or version < 0:
        raise ValueError("version must be a non-negative integer")
    if not isinstance(context, str):
        raise ValueError("context must be a string")
    if not isinstance(arch, str):
        raise ValueError("arch must be a string")
    if not isinstance(summary, str) or not summary:
        raise ValueError("summary must be a non-empty string")
    if not isinstance(description, str) or not description:
        raise ValueError("description must be a non-empty string")
    if not isinstance(module_licenses, list) or not all(isinstance(license, str) for license in module_licenses):
        raise ValueError("module_licenses must be a list of strings")
    if not isinstance(content_licenses, list) or not all(isinstance(license, str) for license in content_licenses):
        raise ValueError("content_licenses must be a list of strings")
    if not isinstance(rpms_nevras, list) or not all(isinstance(rpm, str) for rpm in rpms_nevras):
        raise ValueError("rpms_nevras must be a list of strings")
    # Process and return the data
    processed_data = {
        "mod_yaml": mod_yaml,
        "name": name,
        "stream": stream,
        "version": version,
        "context": context,
        "arch": arch,
        "summary": summary,
        "description": description,
        "module_licenses": module_licenses,
        "content_licenses": content_licenses,
        "rpms_nevras": rpms_nevras
    }
    return processed_data

from datetime import datetime, timedelta
def format_time_difference(start_time, end_time):
    total_time_diff = end_time - start_time
    if total_time_diff.total_seconds() < 10:
        return 'just now'
    else:
        years = total_time_diff.days // 365
        days = total_time_diff.days % 365
        hours, remainder = divmod(total_time_diff.seconds, 3600)
        minutes, seconds = divmod(remainder, 60)
        time_parts = []
        if years:
            time_parts.append(f'{years} year{"s" if years > 1 else ""}')
        if days:
            time_parts.append(f'{days} day{"s" if days > 1 else ""}')
        if hours:
            time_parts.append(f'{hours} hour{"s" if hours > 1 else ""}')
        if minutes:
            time_parts.append(f'{minutes} minute{"s" if minutes > 1 else ""}')
        if seconds:
            time_parts.append(f'{seconds} second{"s" if seconds > 1 else ""}')
        formatted_time_diff = ', '.join(time_parts)
        return formatted_time_diff

