import os
import fsspec
class FileSystemMapper:
    def __init__(self, base_path):
        self.base_path = base_path
    def write_file(self, file_path, content):
        full_path = os.path.join(self.base_path, file_path)
        with open(full_path, "w") as file:
            file.write(content)
    def read_file(self, file_path):
        full_path = os.path.join(self.base_path, file_path)
        with open(full_path, "r") as file:
            return file.read()
    def file_exists(self, file_path):
        full_path = os.path.join(self.base_path, file_path)
        return os.path.exists(full_path)
    @staticmethod
    def compare_mappers(mapper1, mapper2):
        return mapper1 == mapper2
def test_file_system_mapper(tmpdir):
    file_system_mapper = FileSystemMapper(tmpdir)
    file_system_mapper.write_file("afolder/anotherfile", "test2")

    assert file_system_mapper.file_exists("afile") == False
    assert file_system_mapper.read_file("afolder/anotherfile") == "test2"

    m = fsspec.get_mapper("file://" + tmpdir)
    assert "afile" in m
    assert m["afolder/anotherfile"] == b"test2"
    fs = fsspec.filesystem("file")
    m2 = fs.get_mapper(tmpdir)
    m3 = fs.get_mapper("file://" + tmpdir)
    assert FileSystemMapper.compare_mappers(m, m2) == True
    assert FileSystemMapper.compare_mappers(m, m3) == True

