            counts = [dice.count(x) for x in set(dice)]
            self.scores[8] = 25 if 2 in counts and 3 in counts else 0
        return self.scores[8]
    def score_small_straight(self, dice: List[int]) -> int:
        if self.scores[9] is None:
            sorted_dice = sorted(set(dice))
            self.scores[9] = 30 if len(sorted_dice) >= 4 and max(sorted_dice) - min(sorted_dice) >= 3 else 0
        return self.scores[9]
    def score_large_straight(self, dice: List[int]) -> int:
        if self.scores[10] is None:
            sorted_dice = sorted(set(dice))
