def digits_match(die1: int, die2: int, digit1: int, digit2: int) -> bool:
    return (str(digit1) in str(die1) and str(digit2) in str(die1)) or (str(digit1) in str(die2) and str(digit2) in str(die2))
def are_dice_compatible(die1: int, die2: int) -> bool:
    if not digits_match(die1, die2, 3, 6) and not digits_match(die1, die2, 3, 9):
        return False
    if not digits_match(die1, die2, 4, 9) and not digits_match(die1, die2, 4, 6):
        return False
    if not digits_match(die1, die2, 6, 4) and not digits_match(die1, die2, 9, 4):
        return False
    if not digits_match(die1, die2, 8, 1):
        return False
    return True

class ConnectRequest:
    CRI_LENGTH = 4  # Length of ConnectRequest Information (CRI) in bytes
    def __init__(self, control_endpoint, data_endpoint, request_type, flags):
        self.control_endpoint = control_endpoint
        self.data_endpoint = data_endpoint
        self.request_type = request_type
        self.flags = flags
    def to_knx(self):
        def cri_to_knx():
            return bytes(
                (
                    ConnectRequest.CRI_LENGTH,
                    self.request_type.value,
                    self.flags,
                    0x00,  # Reserved
                )
            )
        return (
            self.control_endpoint.to_knx() + self.data_endpoint.to_knx() + cri_to_knx()
        )
    def __repr__(self) -> str:
        return f"ConnectRequest(control_endpoint={self.control_endpoint}, data_endpoint={self.data_endpoint}, request_type={self.request_type}, flags={self.flags})"

import random
class MarkovChain:
    def __init__(self, states):
        self.states = list(set(states))
        self.transition = {}
        self.build_transition_matrix(states)
    def build_transition_matrix(self, states):
        for state in self.states:
            transitions = [states[i+1] for i in range(len(states)-1) if states[i] == state]
            transition_counts = {state: transitions.count(state) / len(transitions) for state in set(transitions)}
            self.transition[state] = [(next_state, prob) for next_state, prob in transition_counts.items()]
    def sample_next(self, state):
        next_states, probabilities = zip(*self.transition[state])
        return random.choices(next_states, weights=probabilities)[0]
    def build_sequence(self, length, start_state):
        sequence = [start_state]
        current_state = start_state
        for _ in range(length - 1):
            next_state = self.sample_next(current_state)
            sequence.append(next_state)
            current_state = next_state
        return sequence
def test_chain():
    chain = MarkovChain([1, 2, 3, 1, 2])
    assert len(chain.states) == 3
    assert isinstance(chain.transition, dict)
    assert isinstance(chain.transition[1], list)
    assert chain.sample_next(1) == 2
    assert len(chain.build_sequence(10, 1)) == 10
test_chain()

class LayerManager:
    def __init__(self, net):
        """
        Initialize the LayerManager with a neural network model.
        """
        self.net = net
    def freeze_to(self, N:int) -> None:
        """
        Freeze the first N layers of the model.
        """
        for l, param in enumerate(self.net.parameters()):
            param.requires_grad = False
            if l >= N:
                break
    def unfreeze_to(self, N:int) -> None:
        """
        Unfreeze the first N layers of the model.
        """
        for l, param in enumerate(self.net.parameters()):
            param.requires_grad = True
            if l >= N:
