import math
class Vector2:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __eq__(self, other):
        return self.x == other.x and self.y == other.y
    @property
    def magnitude(self):
        return math.sqrt(self.x ** 2 + self.y ** 2)
    @property
    def theta(self):
        return math.atan2(self.y, self.x)
    def as_tuple(self):
        return self.x, self.y
