import argparse
import os
import subprocess
import sys
# { unit_test_path: nproc_per_node }
DISTRIBUTED_UNIT_TESTS = {}
UNIT_TEST_PASS = True
EXCLUDE_UNIT_TESTS = []
def parse_args():
    parser = argparse.ArgumentParser(description="Run Primus unit tests")
    parser.add_argument(
        "--jax",
        action="store_true",
        help="Run only JAX unit test: tests/trainer/test_maxtext_trainer.py",
    )
    return parser.parse_args()
def get_all_unit_tests(run_jax_only=False):
    """
    When run_jax_only = True:
        only return tests/trainer/test_maxtext_trainer.py
    Otherwise:
        return all tests except test_maxtext_trainer.py
    """
    global DISTRIBUTED_UNIT_TESTS, EXCLUDE_UNIT_TESTS
    cur_dir = "./tests"
    unit_tests = {}
    if run_jax_only:
        jax_ut = "trainer/test_maxtext_trainer.py"
        jax_ut_full = os.path.join(cur_dir, jax_ut)
        return {jax_ut_full: 1}
    EXCLUDE_UNIT_TESTS = [
        "trainer/test_maxtext_trainer.py",
    ]
    for root, dirs, files in os.walk(cur_dir):
        for file_name in files:
            if not file_name.endswith(".py") or not file_name.startswith("test_"):
                continue
            # Construct relative path from tests/
            rel_path = os.path.relpath(os.path.join(root, file_name), start=cur_dir)
            if rel_path in EXCLUDE_UNIT_TESTS:
                continue
            if file_name not in DISTRIBUTED_UNIT_TESTS:
                unit_tests[os.path.join(root, file_name)] = 1
            else:
                unit_tests[os.path.join(root, file_name)] = DISTRIBUTED_UNIT_TESTS[file_name]
    return unit_tests
def launch_unit_test(ut_path, nproc_per_node):
    global UNIT_TEST_PASS
    if nproc_per_node == 1:
        cmd = f"pytest --maxfail=1 {ut_path} -s"
    else:
        cmd = f"torchrun --nnodes 1 --nproc-per-node {nproc_per_node} {ut_path}"
    proc = subprocess.Popen(cmd, shell=True)
    proc.wait()
    if proc.returncode != 0:
        UNIT_TEST_PASS = False
def main():
    args = parse_args()
    unit_tests = get_all_unit_tests(run_jax_only=args.jax)
    for ut_path, gpus in unit_tests.items():
        launch_unit_test(ut_path, gpus)
    if not UNIT_TEST_PASS:
        print("Unit Tests failed! More details please check log.")
        sys.exit(1)
    else:
        print("Unit Tests pass!")
if __name__ == "__main__":
    main()

from abc import ABCMeta, abstractmethod
import torch
from lightx2v.utils.registry_factory import CONV2D_WEIGHT_REGISTER
from lightx2v_platform.base.global_var import AI_DEVICE
class Conv2dWeightTemplate(metaclass=ABCMeta):
    def __init__(self, weight_name, bias_name, stride, padding, dilation, groups):
        self.weight_name = weight_name
        self.bias_name = bias_name
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.config = {}
    @abstractmethod
    def load(self, weight_dict):
        pass
    @abstractmethod
    def apply(self, input_tensor):
        pass
    def set_config(self, config=None):
        if config is not None:
            self.config = config
@CONV2D_WEIGHT_REGISTER("Default")
class Conv2dWeight(Conv2dWeightTemplate):
    def __init__(self, weight_name, bias_name, stride=1, padding=0, dilation=1, groups=1):
        super().__init__(weight_name, bias_name, stride, padding, dilation, groups)
    def load(self, weight_dict):
        self.weight = weight_dict[self.weight_name].to(AI_DEVICE)
        self.bias = weight_dict[self.bias_name].to(AI_DEVICE) if self.bias_name is not None else None
    def apply(self, input_tensor):
        input_tensor = torch.nn.functional.conv2d(input_tensor, weight=self.weight, bias=self.bias, stride=self.stride, padding=self.padding, dilation=self.dilation, groups=self.groups)
        return input_tensor
    def to_cpu(self, non_blocking=False):
        self.weight = self.weight.cpu(non_blocking=non_blocking)
        if self.bias is not None:
            self.bias = self.bias.cpu(non_blocking=non_blocking)
    def to_cuda(self, non_blocking=False):
        self.weight = self.weight.to(AI_DEVICE, non_blocking=non_blocking)
        if self.bias is not None:
            self.bias = self.bias.to(AI_DEVICE, non_blocking=non_blocking)
    def state_dict(self, destination=None):
        if destination is None:
            destination = {}
        destination[self.weight_name] = self.weight.cpu().detach().clone()
        if self.bias is not None:
            destination[self.bias_name] = self.bias.cpu().detach().clone()
        return destination

