import os
import requests
import json
import sys
class SlackHub:
    def __init__(self):
        self.token = os.getenv("SLACK_BOT_TOKEN")
        self.base_url = "https://slack.com/api"
    def _call(self, endpoint, data=None):
        headers = {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json; charset=utf-8"
        }
        response = requests.post(f"{self.base_url}/{endpoint}", headers=headers, json=data)
        return response.json()
    def send(self, target, message, thread_ts=None):
        data = {"channel": target, "text": message}
        if thread_ts:
            data["thread_ts"] = thread_ts
        return self._call("chat.postMessage", data)
    def search(self, query):
        # Slack search API requires different headers/method usually
        params = {"query": query}
        headers = {"Authorization": f"Bearer {self.token}"}
        response = requests.get(f"{self.base_url}/search.messages", headers=headers, params=params)
        return response.json()
if __name__ == "__main__":
    import argparse
    hub = SlackHub()

    parser = argparse.ArgumentParser()
    parser.add_argument("action", choices=["send", "search", "list"])
    parser.add_argument("--target")
    parser.add_argument("--message")
    parser.add_argument("--query")
    args = parser.parse_args()
    if args.action == "list":
        print(json.dumps(hub._call("conversations.list", {"types": "public_channel,private_channel"})))
    elif args.action == "send":
        print(json.dumps(hub.send(args.target, args.message)))
    elif args.action == "search":
        print(json.dumps(hub.search(args.query)))

from typing import Callable, Match, Optional
import re
from ._emoji_codes import EMOJI
_ReStringMatch = Match[str]  # regex match object
_ReSubCallable = Callable[[_ReStringMatch], str]  # Callable invoked by re.sub
_EmojiSubMethod = Callable[[_ReSubCallable, str], str]  # Sub method of a compiled re
def _emoji_replace(
    text: str,
    default_variant: Optional[str] = None,
    _emoji_sub: _EmojiSubMethod = re.compile(r"(:(\S*?)(?:(?:\-)(emoji|text))?:)").sub,
) -> str:
    """Replace emoji code in text."""
    get_emoji = EMOJI.__getitem__
    variants = {"text": "\uFE0E", "emoji": "\uFE0F"}
    get_variant = variants.get
    default_variant_code = variants.get(default_variant, "") if default_variant else ""
    def do_replace(match: Match[str]) -> str:
        emoji_code, emoji_name, variant = match.groups()
        try:
            return get_emoji(emoji_name.lower()) + get_variant(
                variant, default_variant_code
            )
        except KeyError:
            return emoji_code
    return _emoji_sub(do_replace, text)

import functools
import importlib
import inspect
import os
import pkgutil
from typing import Literal
import torch
from mojo_opset.utils.logging import get_logger
logger = get_logger(__name__)
@functools.lru_cache
def get_platform() -> Literal["npu", "mlu", "meta_device"]:
    """
    Detect whether the system has NPU or MLU, fallback device is meta_device.
    """
    try:
        if torch.npu.is_available():
            logger.info("Ascend NPU detected")
            return "npu"
    except Exception as e:
        logger.debug(f"Failed to check NPU availability: {e}")
    try:
        if torch.mlu.is_available():
            logger.info("Cambricon MLU detected")
            return "mlu"
    except Exception as e:
        logger.debug(f"Failed to check MLU availability: {e}")
    logger.warning("No accelerator detected")
    return "meta_device"
def get_impl_by_platform():
    import_op_map = {}
    from mojo_opset.core.function import MojoFunction
    from mojo_opset.core.operator import MojoOperator
    platform = get_platform()
    try:
        caller_frame = inspect.stack()[1]
        caller_module = inspect.getmodule(caller_frame[0])
        if not caller_module or not hasattr(caller_module, "__file__"):
            logger.error("Could not determine the caller's module file path. Cannot discover operators.")
            return {}
        caller_dir = os.path.dirname(caller_module.__file__)
        package_name = getattr(caller_module, "__package__", "")
        api_dir_lists = ["operators", "functions"]
        for api_dir in api_dir_lists:
            api_dir_path = os.path.join(caller_dir, api_dir)
            api_package_name = f"{package_name}.{api_dir}"
            for _, module_name, _ in pkgutil.iter_modules([api_dir_path]):
                full_module_name = f"{api_package_name}.{module_name}"
                module = importlib.import_module(full_module_name)
                for name, op in inspect.getmembers(module, inspect.isclass):
                    if (
                        (issubclass(op, MojoOperator) or issubclass(op, MojoFunction))
                        and op not in [MojoOperator, MojoFunction]
                        and op.__module__ == full_module_name
                        and platform in getattr(op, "supported_platforms_list", [])
                    ):
                        logger.debug(f"Found supported operator '{name}' in {full_module_name}")
                        import_op_map[name] = op
    except (ImportError, IndexError):
        import traceback
        logger.error(f"Failed to discover operators: {traceback.format_exc()}")
        return {}
    return import_op_map

import regex as re
from typing import List, Dict, Iterable, Tuple
from .config import WINDOW_SIZE, WINDOW_STEP
def _load_list(path: str):
    with open(path, "r", encoding="utf-8") as f:
        return [ln.strip() for ln in f if ln.strip()]
def compile_lexicons(root: str) -> Dict[str, List[str]]:
    import os
    lex = {}
    names = [
        "hedges.txt","modals.txt","meta_markers.txt","backtracks.txt",
        "action_verbs.txt","verify_markers.txt","positive_words.txt","negative_words.txt"
    ]
    for fn in names:
        lex[fn.split(".")[0]] = _load_list(os.path.join(root, "resources", "lexicons", fn))
    return lex
def simple_tokens(s: str) -> List[str]:
    return re.findall(r"\p{L}[\p{L}\p{N}'-]*", s.lower())
def count_phrases(text: str, phrases: List[str]) -> int:
    t = text.lower()
    count = 0
    for p in phrases:
        count += len(re.findall(re.escape(p), t))
    return count
def window_iter(turns: List[Dict], size: int = WINDOW_SIZE, step: int = WINDOW_STEP):
    for i in range(0, max(0, len(turns)-size+1), step):
        yield i, turns[i:i+size]
def extract_features(turns: List[Dict], lex: Dict[str, List[str]]) -> List[Dict]:
    feats = []
    for t in turns:
        text = t.get("text", "")
        toks = simple_tokens(text)
        n_tok = max(1, len(toks))
        f = {
            "hedges": count_phrases(text, lex["hedges"]) / n_tok,
            "modals": count_phrases(text, lex["modals"]) / n_tok,
            "meta": count_phrases(text, lex["meta_markers"]) / n_tok,
            "backtrack": count_phrases(text, lex["backtracks"]) / n_tok,
            "action": count_phrases(text, lex["action_verbs"]) / n_tok,
            "verify": count_phrases(text, lex["verify_markers"]) / n_tok,
            "q_ratio": text.count("?") / max(1, text.count(".")+text.count("?")+text.count("!")),
            "exclaim": text.count("!") / max(1, len(text)),
            "pos": sum(1 for w in toks if w in set(lex["positive_words"])) / n_tok,
            "neg": sum(1 for w in toks if w in set(lex["negative_words"])) / n_tok,
            "len": n_tok
        }
        feats.append(f)
    return feats

