import os
import sys
class CheckGraphModuleParsable:
    def __init__(self, config=None):
        if config is None:
            config = {}
        self.config = self._make_config(**config)
        self.num_handled_models = 0
    def _make_config(
        self,
        model_path_prefix,
        output_dir,
        resume=False,
        limits_handled_models=None,
    ):
        return {
            "model_path_prefix": model_path_prefix,
            "output_dir": output_dir,
            "resume": resume,
            "limits_handled_models": limits_handled_models,
        }
    def __call__(self, rel_model_path):
        model_path = os.path.join(self.config["model_path_prefix"], rel_model_path)
        if self.config["resume"] and self._is_model_path_handled(rel_model_path):
            return
        gm = parse_immutable_model_path_into_sole_graph_module(model_path)
        output_dir = Path(self.config["output_dir"]) / rel_model_path
        output_dir.mkdir(parents=True, exist_ok=True)
        (output_dir / "num_ops.txt").write_text(str(self._get_num_ops(gm)))
        self._inc_num_handled_models()
    def _get_num_ops(self, gm):
        ignored = {"placeholder", "output"}
        return len([node for node in gm.graph.nodes if node.op not in ignored])
    def _is_model_path_handled(self, rel_model_path):
        return (Path(self.config["output_dir"]) / rel_model_path).exists()
    def _inc_num_handled_models(self):
        self.num_handled_models += 1
        limits = self.config["limits_handled_models"]
        if limits is not None:
            if self.num_handled_models >= limits:
                print(
                    "`num_handled_models` exceeds config `limits_handled_models`",
                    file=sys.stderr,
                )
                sys.exit(0)

import torch
from megatron.core.dist_checkpointing.strategies.filesystem_async import FileSystemWriterAsync
class ROCmFileSystemWriterAsync(FileSystemWriterAsync):
    """
    FileSystemWriterAsync wrapper for ROCm compatibility.
    On ROCm/HIP, using non_blocking=True causes tensors to be stored in pinned memory,
    which triggers segmentation faults when forking subprocesses afterward.
    """
    @staticmethod
    def preload_tensors(*args, **kwargs):
        # Change argument non_blocking to False on HIP platform
        # The tensors will be stored in pinned memory if non_blocking=True
        # Currently on the ROCm platform, forking a subprocess afterward
        # with pinned_memory=True will trigger segmentation fault
        if torch.version.hip:
            print("HIP/ROCm detected: setting non_blocking=False in preload_tensors")
            if "non_blocking" in kwargs:
                kwargs["non_blocking"] = False
            elif len(args) > 1 and isinstance(args[-1], bool):
                # non_blocking is typically the last argument
                args = args[:-1] + (False,)
        return FileSystemWriterAsync.preload_tensors(*args, **kwargs)

from typing import Optional
from loguru import logger
from .worker import TorchrunInferenceWorker
class DistributedInferenceService:
    def __init__(self):
        self.worker = None
        self.is_running = False
        self.args = None
    def start_distributed_inference(self, args) -> bool:
        self.args = args
        if self.is_running:
            logger.warning("Distributed inference service is already running")
            return True
        try:
            self.worker = TorchrunInferenceWorker()
            if not self.worker.init(args):
                raise RuntimeError("Worker initialization failed")
            self.is_running = True
            logger.info(f"Rank {self.worker.rank} inference service started successfully")
            return True
        except Exception as e:
            logger.error(f"Error starting inference service: {str(e)}")
            self.stop_distributed_inference()
            return False
    def stop_distributed_inference(self):
        if not self.is_running:
            return
        try:
            if self.worker:
                self.worker.cleanup()
            logger.info("Inference service stopped")
        except Exception as e:
            logger.error(f"Error stopping inference service: {str(e)}")
        finally:
            self.worker = None
            self.is_running = False
    async def submit_task_async(self, task_data: dict) -> Optional[dict]:
        if not self.is_running or not self.worker:
            logger.error("Inference service is not started")
            return None
        if self.worker.rank != 0:
            return None
        try:
            if self.worker.processing:
                logger.info(f"Waiting for previous task to complete before processing task {task_data.get('task_id')}")
            self.worker.processing = True
            result = await self.worker.process_request(task_data)
            self.worker.processing = False
            return result
        except Exception as e:
            self.worker.processing = False
            logger.error(f"Failed to process task: {str(e)}")
            return {
                "task_id": task_data.get("task_id", "unknown"),
                "status": "failed",
                "error": str(e),
                "message": f"Task processing failed: {str(e)}",
            }
    def server_metadata(self):
        assert hasattr(self, "args"), "Distributed inference service has not been started. Call start_distributed_inference() first."
        return {"nproc_per_node": self.worker.world_size, "model_cls": self.args.model_cls, "model_path": self.args.model_path}
    async def run_worker_loop(self):
        if self.worker and self.worker.rank != 0:
            await self.worker.worker_loop()

from typing_extensions import Literal, TypeAlias
Processor_id: TypeAlias = Literal[
    "canny", "depth", "softedge", "lineart", "lineart_anime", "openpose", "normal", "tile", "none", "inpaint"
]
class Annotator:
    def __init__(self, processor_id: Processor_id, model_path="models/Annotators", detect_resolution=None, device='cuda', skip_processor=False):
        if not skip_processor:
            if processor_id == "canny":
                from controlnet_aux.processor import CannyDetector
                self.processor = CannyDetector()
            elif processor_id == "depth":
                from controlnet_aux.processor import MidasDetector
                self.processor = MidasDetector.from_pretrained(model_path).to(device)
            elif processor_id == "softedge":
                from controlnet_aux.processor import HEDdetector
                self.processor = HEDdetector.from_pretrained(model_path).to(device)
            elif processor_id == "lineart":
                from controlnet_aux.processor import LineartDetector
                self.processor = LineartDetector.from_pretrained(model_path).to(device)
            elif processor_id == "lineart_anime":
                from controlnet_aux.processor import LineartAnimeDetector
                self.processor = LineartAnimeDetector.from_pretrained(model_path).to(device)
            elif processor_id == "openpose":
                from controlnet_aux.processor import OpenposeDetector
                self.processor = OpenposeDetector.from_pretrained(model_path).to(device)
            elif processor_id == "normal":
                from controlnet_aux.processor import NormalBaeDetector
                self.processor = NormalBaeDetector.from_pretrained(model_path).to(device)
            elif processor_id == "tile" or processor_id == "none" or processor_id == "inpaint":
                self.processor = None
            else:
                raise ValueError(f"Unsupported processor_id: {processor_id}")
        else:
            self.processor = None
        self.processor_id = processor_id
        self.detect_resolution = detect_resolution

    def to(self,device):
        if hasattr(self.processor,"model") and hasattr(self.processor.model,"to"):
            self.processor.model.to(device)
    def __call__(self, image, mask=None):
        width, height = image.size
        if self.processor_id == "openpose":
            kwargs = {
                "include_body": True,
                "include_hand": True,
                "include_face": True
            }
        else:
            kwargs = {}
        if self.processor is not None:
            detect_resolution = self.detect_resolution if self.detect_resolution is not None else min(width, height)
            image = self.processor(image, detect_resolution=detect_resolution, image_resolution=min(width, height), **kwargs)
        image = image.resize((width, height))
        return image

