import base64
from typing import TYPE_CHECKING, Any, Dict, Optional
if TYPE_CHECKING:
    from api.db.models import ExternalCredentialModel
def build_auth_header(credential: "ExternalCredentialModel") -> Dict[str, str]:
    """Build authentication header based on credential type.
    Supports the following credential types:
    - bearer_token: Authorization: Bearer <token>
    - api_key: Custom header with API key
    - basic_auth: Authorization: Basic <base64(username:password)>
    - custom_header: Any custom header name/value pair
    Args:
        credential: The ExternalCredentialModel instance
    Returns:
        Dict with header name and value, or empty dict if credential type
        is not recognized or is 'none'
    """
    cred_type = credential.credential_type
    cred_data = credential.credential_data or {}
    if cred_type == "bearer_token":
        token = cred_data.get("token", "")
        return {"Authorization": f"Bearer {token}"}
    elif cred_type == "api_key":
        header_name = cred_data.get("header_name", "X-API-Key")
        api_key = cred_data.get("api_key", "")
        return {header_name: api_key}
    elif cred_type == "basic_auth":
        username = cred_data.get("username", "")
        password = cred_data.get("password", "")
        encoded = base64.b64encode(f"{username}:{password}".encode()).decode()
        return {"Authorization": f"Basic {encoded}"}
    elif cred_type == "custom_header":
        header_name = cred_data.get("header_name", "X-Custom")
        header_value = cred_data.get("header_value", "")
        return {header_name: header_value}
    return {}
def build_auth_header_from_data(
    credential_type: str,
    credential_data: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    """Build authentication header from raw credential data.
    This is a convenience function when you have credential data
    directly rather than a full ExternalCredentialModel.
    Args:
        credential_type: Type of credential (bearer_token, api_key, etc.)
        credential_data: Dict containing credential-specific fields
    Returns:
        Dict with header name and value
    """
    cred_data = credential_data or {}
    if credential_type == "bearer_token":
        token = cred_data.get("token", "")
        return {"Authorization": f"Bearer {token}"}
    elif credential_type == "api_key":
        header_name = cred_data.get("header_name", "X-API-Key")
        api_key = cred_data.get("api_key", "")
        return {header_name: api_key}
    elif credential_type == "basic_auth":
        username = cred_data.get("username", "")
        password = cred_data.get("password", "")
        encoded = base64.b64encode(f"{username}:{password}".encode()).decode()
        return {"Authorization": f"Basic {encoded}"}
    elif credential_type == "custom_header":
        header_name = cred_data.get("header_name", "X-Custom")
        header_value = cred_data.get("header_value", "")
        return {header_name: header_value}
    return {}

import requests
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider
logger = logging.getLogger(__name__)
class HoverDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "hover"
    PROVIDER_NAME = "Hover"
    PROVIDER_DESCRIPTION = "Hover DNS (session-based auth)"
    REQUIRED_CREDENTIALS = ["username", "password"]

    BASE_URL = "https://www.hover.com/api"

    def __init__(self, credentials: Dict[str, Any]):
        super().__init__(credentials)
        self._session = None

    def _authenticate(self) -> Tuple[bool, str]:
        if self._session:
            return True, "Already authenticated"
        self._session = requests.Session()
        try:
            resp = self._session.post(f'{self.BASE_URL}/login',
                data={'username': self.credentials['username'], 'password': self.credentials['password']}, timeout=30)
            if resp.status_code != 200 or not resp.json().get('succeeded'):
                self._session = None
                return False, "Authentication failed"
            return True, "Authenticated"
        except requests.RequestException as e:
            self._session = None
            return False, str(e)

    def _request(self, method: str, path: str, data: Optional[Dict] = None) -> Tuple[bool, Any]:
        ok, err = self._authenticate()
        if not ok:
            return False, err
        try:
            resp = self._session.request(method=method, url=f'{self.BASE_URL}{path}', json=data, timeout=30)
            if resp.status_code >= 400:
                return False, resp.reason
            return True, resp.json() if resp.text else None
        except requests.RequestException as e:
            return False, str(e)

    def create_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        relative = self.get_relative_record_name(record_name, domain)
        data = {'name': relative, 'type': 'TXT', 'content': record_value}
        success, result = self._request('POST', f'/domains/{domain}/dns', data)
        if not success:
            return False, f"Failed to create record: {result}"
        return True, "Record created successfully"

    def delete_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        success, result = self._request('GET', f'/domains/{domain}/dns')
        if not success:
            return False, f"Failed to list records: {result}"
        for rec in result.get('domains', [{}])[0].get('entries', []):
            if rec.get('type') == 'TXT' and rec.get('name') == self.get_relative_record_name(record_name, domain):
                self._request('DELETE', f'/dns/{rec["id"]}')
        return True, "Record deleted successfully"

    def test_connection(self) -> Tuple[bool, str]:
        success, result = self._request('GET', '/domains')
        if success:
            domains = result.get('domains', [])
            return True, f"Connected. Found {len(domains)} domain(s)"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'username', 'label': 'Username/Email', 'type': 'text', 'required': True},
            {'name': 'password', 'label': 'Password', 'type': 'password', 'required': True},
        ]

