import questionary


class Displayer:
    """
    Class for displaying all notes, handling user action, etc.
    """

    @staticmethod
    def display_notes(notes):
        """
        Display the list of notes to the user.
        :param notes: List of notes to be displayed
        """
        if not notes:
            print("No notes available.")
        else:
            print("Your notes:")
            for note in notes:
