def extract_target_info(json_data):
    # Initialize dictionary to store extracted information
    extracted_info = {}

    # Get list of targets, default to empty list if not present
    targets = json_data.get("targets", [])

    # Iterate through each target in the list
    for target in targets:
        # Extract relevant fields from the target
        target_name = target.get("target_name")
        target_type = target.get("type")
        dependencies = target.get("dependencies", [])

        # Store extracted information in the dictionary
        extracted_info[target_name] = {
            "type": target_type,
            "dependencies": dependencies
        }

    # Return the collected information
    return extracted_info

