    # Initialize the number of people form
    num_people_form = NumPeopleForm()

    # Generate distance forms based on the number of people
    # Note: This logic assumes cleaned_data is available, which typically requires validation first
    distance_forms = [DistanceForm(prefix=str(i)) for i in range(num_people_form.cleaned_data['num_people'])]

    # Validate the number of people form
    if num_people_form.is_valid():
        # Collect valid distances from each distance form
        distances = [form.cleaned_data['distance'] for form in distance_forms if form.is_valid()]

        # Proceed only if we have at least one valid distance
        if distances:
            average_distance = calculate_average_distance(
                num_people_form.cleaned_data['num_people'],
                distances
            )
