# Decorator to validate 'id' parameter
def validate_id(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Extract 'id' from kwargs
        id = kwargs.get('id')

        # Validate 'id': must exist, be an integer, and positive
        if id is None or not isinstance(id, int) or id <= 0:
            raise BadRequest("Invalid or missing 'id' parameter")

        return f(*args, **kwargs)

    return decorated_function

