import random
from typing import Union

def shuffle(data: Union[str, bytes], seed: int) -> Union[str, bytes]:
    # Set the random seed for reproducibility
    random.seed(seed)

    # Handle string input
    if isinstance(data, str):
        data_list = list(data)
        random.shuffle(data_list)
        return ''.join(data_list)

    # Handle bytes input
    elif isinstance(data, bytes):
        data_list = list(data)
        random.shuffle(data_list)
        return bytes(data_list)

    # Raise error for unsupported types
    else:
        raise ValueError("Input data must be a string or bytes object")

