class CustomLogger:
    def __init__(self, log_level):
        # Initialize logger with specified log level
        self.log_level = log_level

    def debug(self, message):
        # Print debug messages if log level allows
        if self.log_level <= 0:
            print(f"DEBUG: {message}")

    def info(self, message):
        # Print info messages if log level allows
        if self.log_level <= 1:
            print(f"INFO: {message}")

    def warning(self, message):
        # Print warning messages if log level allows
        if self.log_level <= 2:
            print(f"WARNING: {message}")

    def error(self, message):
        # Print error messages if log level allows
        if self.log_level <= 3:
            print(f"ERROR: {message}")

    def critical(self, message):
        # Print critical messages if log level allows
        if self.log_level <= 4:
            print(f"CRITICAL: {message}")

    def set_level(self, log_level):
        # Update the log level
        self.log_level = log_level

