from elasticsearch import Elasticsearch

class ElasticsearchHandler:
    def __init__(self, host, port, index, doc_type):
        # Initialize Elasticsearch client
        self.es = Elasticsearch([{'host': host, 'port': port}])
        self._index = index
        self._type = doc_type

