        return: None
        """
        try:
            self.es.index(index=self._index, doc_type=self._type, body=insert_data)
        except Exception as e:
            raise e

    def es_update(self, id_info, update_info):
        """
        Update data in Elasticsearch
        args: id_info (str/int), update_info (dict)
        return: None
        """
        try:
            self.es.update(
                index=self._index,
                doc_type=self._type,
                id=id_info,
                body={"doc": update_info}
            )
        except Exception as e:
