from typing import Optional, Sequence

def extract_template_arg(args: Optional[Sequence[str]] = None) -> str:
    # If no arguments provided, use command line arguments
    if args is None:
        import sys
        args = sys.argv[1:]

    # Iterate through arguments to find template specification
    for arg in args:
