# Check if two digits match on either die
def digits_match(die1: int, die2: int, digit1: int, digit2: int) -> bool:
    return (str(digit1) in str(die1) and str(digit2) in str(die1)) or \
           (str(digit1) in str(die2) and str(digit2) in str(die2))

# Determine if two dice are compatible based on digit requirements
def are_dice_compatible(die1: int, die2: int) -> bool:
    # Must have 3 and 6 or 3 and 9 on one die
    if not digits_match(die1, die2, 3, 6) and not digits_match(die1, die2, 3, 9):
        return False

    # Must have 4 and 9 or 4 and 6 on one die
    if not digits_match(die1, die2, 4, 9) and not digits_match(die1, die2, 4, 6):
        return False

    # Must have 6 and 4 or 9 and 4 on one die
    if not digits_match(die1, die2, 6, 4) and not digits_match(die1, die2, 9, 4):
        return False

    # Must have 8 and 1 on one die
    if not digits_match(die1, die2, 8, 1):
        return False

    return True

# ConnectRequest class definition
class ConnectRequest:
    # Length of ConnectRequest Information (CRI) in bytes
    CRI_LENGTH = 4

    def __init__(self, control_endpoint, data_endpoint, request_type, flags):
        self.control_endpoint = control_endpoint
        self.data_endpoint = data_endpoint
        self.request_type = request_type
        self.flags = flags

    def to_knx(self):
        # Helper function to convert CRI to KNX format
        def cri_to_knx():
            return bytes(
                (
                    ConnectRequest.CRI_LENGTH,
                    self.request_type.value,
                    self.flags,
                    0x00,  # Reserved byte
                )
            )

        # Combine endpoints and CRI into final KNX representation
        return (
            self.control_endpoint.to_knx() 
            + self.data_endpoint.to_knx() 
            + cri_to_knx()
        )

    def __repr__(self) -> str:
        return f"ConnectRequest(control_endpoint={self.control_endpoint}, data_endpoint={self.data_endpoint}, request_type={self.request_type}, flags={self.flags})"

# LayerManager class for managing neural network layers
class LayerManager:
    def __init__(self, net):
        """
        Initialize the LayerManager with a neural network model.
        """
        self.net = net

    def freeze_to(self, N: int) -> None:
        """
        Freeze the first N layers of the model.
        """
        for l, param in enumerate(self.net.parameters()):
            param.requires_grad = False
            if l >= N:
                break

    def unfreeze_to(self, N: int) -> None:
        """
        Unfreeze the first N layers of the model.
        """
        for l, param in enumerate(self.net.parameters()):
            param.requires_grad = True
            if l >= N:
                break

