from autobahn.twisted.websocket import connectWS, \
                                       listenWS, \
                                       WebSocketClientFactory, \
                                       WebSocketClientProtocol, \
                                       WebSocketServerFactory, \
                                       WebSocketServerProtocol

from twisted.internet import reactor


class MyClientProtocol(WebSocketClientProtocol):
    def onOpen(self):
        # Send initial greeting to server
        self.sendMessage("Hello, server!".encode('utf8'))

    def onMessage(self, payload, isBinary):
        if not isBinary:
            print("Received message from server: {}".format(payload.decode('utf8')))


class MyClientFactory(WebSocketClientFactory):
    protocol = MyClientProtocol


class MyServerProtocol(WebSocketServerProtocol):
    def onOpen(self):
        # Send initial greeting to client
        self.sendMessage("Hello, client!".encode('utf8'))

    def onMessage(self, payload, isBinary):
        if not isBinary:
            print("Received message from client: {}".format(payload.decode('utf8')))


class MyServerFactory(WebSocketServerFactory):
    protocol = MyServerProtocol


def startClient(uri):
    factory = MyClientFactory(uri)
    connectWS(factory)
    reactor.run()


def startServer(port):
    factory = MyServerFactory(u"ws://127.0.0.1:{}".format(port))
    listenWS(factory)
    reactor.run()

