# Function to count unique elements in a list
from typing import List

def count_unique_elements(arr: List[int]) -> int:
    # Check if input is a list
    if not isinstance(arr, list):
        raise TypeError("Input should be a list of integers")

    # Validate each element is an integer
    for num in arr:
        if not isinstance(num, int):
            raise ValueError("List should only contain integers")

    # Calculate unique elements using set
    unique_elements = set(arr)

    # Return the count of unique elements
    return len(unique_elements)

