from datetime import datetime

try:
    import requests
except ImportError:
    print(json.dumps({"error": "requests library required. Install with: pip install requests"}))
    sys.exit(1)

API_URL = "https://www.get-tldr.com/api/v1/summarize"

# Configuration setup: read from config file, fallback to env var or .env file
API_KEY = None
LOGFILE = os.path.expanduser("~/.config/get-tldr/skill.log")

# Try loading config from ~/.config/get-tldr/config.json
config_path = os.path.expanduser("~/.config/get-tldr/config.json")
try:
    with open(config_path, "r", encoding="utf-8") as f:
        cfg = json.load(f)
        API_KEY = cfg.get("api_token")
        # Use configured logfile if available
        if cfg.get("logfile") or cfg.get("log_file"):
            LOGFILE = os.path.expanduser(cfg.get("logfile") or cfg.get("log_file"))
except FileNotFoundError:
    pass
except Exception:
    # Ignore parse errors and continue to other fallbacks
    pass

# Fallback to environment variable
if not API_KEY:
    API_KEY = os.environ.get("GET_TLDR_API_KEY")

# Fallback to .env file in the same folder as this script
if not API_KEY:
    env_path = os.path.join(os.path.dirname(__file__), ".env")
    try:
        with open(env_path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                if k.strip() == "GET_TLDR_API_KEY":
                    API_KEY = v.strip().strip('"').strip("'")
                    break
    except FileNotFoundError:
        pass

# Final check for API key
if not API_KEY:
    print(json.dumps({
        "error": "Missing API key. Create ~/.config/get-tldr/config.json with api_token, "
                 "or set GET_TLDR_API_KEY env var or place it in this skill folder's .env."
    }))
    sys.exit(1)


def summarize(url: str):
    """
    Send URL to TL;DR API and return the response.
    """
    payload = {"input": url}
    headers = {
        "Content-Type": "application/json",
        "X-API-Key": API_KEY
    }

    resp = requests.post(API_URL, headers=headers, json=payload, timeout=30)

    try:
        resp.raise_for_status()
        return resp.json()
    except requests.HTTPError:
        try:
            return {"status_code": resp.status_code, "error": resp.json()}
        except Exception:
            return {"status_code": resp.status_code, "text": resp.text}
    except Exception:
        try:
            return resp.json()
        except Exception:
            return {
                "status_code": getattr(resp, 'status_code', None),
                "text": getattr(resp, 'text', str(resp))
            }


if __name__ == '__main__':
    # Validate command-line arguments
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Missing URL argument"}))
        sys.exit(2)

    url = sys.argv[1]

    # Basic URL validation
    parsed = urlparse(url)
    if parsed.scheme not in ("http", "https"):
        print(json.dumps({
            "error": "Invalid URL scheme; must start with http:// or https://",
            "url": url
        }))
        sys.exit(2)

    # Call summarization API
    result = summarize(url)

    # Log the request (ignore logging errors)
    try:
        sent_payload = {"input": url}
        with open(LOGFILE, "a", encoding="utf-8") as lf:
            lf.write(json.dumps({
                "timestamp": datetime.utcnow().isoformat() + "Z",
                "sent": sent_payload,
                "response": result
            }, ensure_ascii=False) + "\n")
    except Exception:
        pass

    # Output result as formatted JSON
    print(json.dumps(result, ensure_ascii=False, indent=2))

