from pathlib import Path
from graph_net.torch.fx_graph_cache_util import (
    parse_immutable_model_path_into_sole_graph_module,
)
import os
import sys


class CheckGraphModuleParsable:
    def __init__(self, config=None):
        # Initialize with default or provided config
        if config is None:
            config = {}
        self.config = self._make_config(**config)
        self.num_handled_models = 0

    def _make_config(
        self,
        model_path_prefix,
        output_dir,
        resume=False,
        limits_handled_models=None,
    ):
        # Construct and return configuration dictionary
        return {
            "model_path_prefix": model_path_prefix,
            "output_dir": output_dir,
            "resume": resume,
            "limits_handled_models": limits_handled_models,
        }

    def __call__(self, rel_model_path):
        # Build full model path and process if not already handled
        model_path = os.path.join(self.config["model_path_prefix"], rel_model_path)

        # Skip if resuming and model already processed
        if self.config["resume"] and self._is_model_path_handled(rel_model_path):
            return

        # Parse the graph module from the model path
        gm = parse_immutable_model_path_into_sole_graph_module(model_path)

        # Create output directory structure
        output_dir = Path(self.config["output_dir"]) / rel_model_path
        output_dir.mkdir(parents=True, exist_ok=True)

        # Write number of operations to file
        (output_dir / "num_ops.txt").write_text(str(self._get_num_ops(gm)))

        # Increment counter for handled models
        self._inc_num_handled_models()

    def _get_num_ops(self, gm):
        # Count operations excluding placeholders and outputs
        ignored = {"placeholder", "output"}
        return len([node for node in gm.graph.nodes if node.op not in ignored])

    def _is_model_path_handled(self, rel_model_path):
        # Check if the model has already been processed
        return (Path(self.config["output_dir"]) / rel_model_path).exists()

    def _inc_num_handled_models(self):
        # Increment handled models count and check against limit
        self.num_handled_models += 1
        limits = self.config["limits_handled_models"]

        # Exit if limit is exceeded
        if limits is not None:
            if self.num_handled_models >= limits:
                print(
                    "`num_handled_models` exceeds config `limits_handled_models`",
                    file=sys.stderr,
                )
                sys.exit(0)

# ROCm-compatible async filesystem writer for distributed checkpointing
import torch

from megatron.core.dist_checkpointing.strategies.filesystem_async import FileSystemWriterAsync


class ROCmFileSystemWriterAsync(FileSystemWriterAsync):
    """
    FileSystemWriterAsync wrapper for ROCm compatibility.

    On ROCm/HIP, using non_blocking=True causes tensors to be stored in pinned memory,
    which triggers segmentation faults when forking subprocesses afterward.
    """

    @staticmethod
    def preload_tensors(*args, **kwargs):
        # Change argument non_blocking to False on HIP platform
        # The tensors will be stored in pinned memory if non_blocking=True
        # Currently on the ROCm platform, forking a subprocess afterward
        # with pinned_memory=True will trigger segmentation fault

        if torch.version.hip:
            print("HIP/ROCm detected: setting non_blocking=False in preload_tensors")

            if "non_blocking" in kwargs:
                kwargs["non_blocking"] = False
            elif len(args) > 1 and isinstance(args[-1], bool):
                # non_blocking is typically the last argument
                args = args[:-1] + (False,)

        return FileSystemWriterAsync.preload_tensors(*args, **kwargs)

