            elif processor_id == "lineart":
                from controlnet_aux.processor import LineartDetector
                self.processor = LineartDetector.from_pretrained(model_path).to(device)

            elif processor_id == "lineart_anime":
                from controlnet_aux.processor import LineartAnimeDetector
                self.processor = LineartAnimeDetector.from_pretrained(model_path).to(device)

            elif processor_id == "openpose":
                from controlnet_aux.processor import OpenposeDetector
                self.processor = OpenposeDetector.from_pretrained(model_path).to(device)

            elif processor_id == "normal":
                from controlnet_aux.processor import NormalBaeDetector
                self.processor = NormalBaeDetector.from_pretrained(model_path).to(device)

            elif processor_id in ("tile", "none", "inpaint"):
                self.processor = None

            else:
                raise ValueError(f"Unsupported processor_id: {processor_id}")
        else:
            self.processor = None

        # Store configuration
        self.processor_id = processor_id
        self.detect_resolution = detect_resolution

    def to(self, device):
        # Move underlying model to specified device if applicable
        if hasattr(self.processor, "model") and hasattr(self.processor.model, "to"):
            self.processor.model.to(device)

    def __call__(self, image, mask=None):
        width, height = image.size

        # Set up openpose-specific parameters
        if self.processor_id == "openpose":
            kwargs = {
                "include_body": True,
                "include_hand": True,
                "include_face": True
            }
        else:
            kwargs = {}

        # Process image if processor is available
        if self.processor is not None:
            detect_resolution = (
                self.detect_resolution 
                if self.detect_resolution is not None 
                else min(width, height)
            )
            image = self.processor(
                image, 
                detect_resolution=detect_resolution, 
                image_resolution=min(width, height), 
                **kwargs
            )

        # Resize back to original dimensions
        image = image.resize((width, height))
        return image

import os

class MemoryLimitNotFoundError(Exception):
    """Raised when the memory limit could not be determined from the cgroup context."""
    pass


def get_cgroup_memory_limit() -> int:
    """Retrieves the memory limit for the current container from the cgroup filesystem.

    This function supports both cgroup v1 and cgroup v2 and reads the appropriate file
    to obtain the memory limit in bytes.

    Returns:
        int: The memory limit in bytes.

    Raises:
        MemoryLimitNotFoundError: If the memory limit could not be determined.
    """
    # Check for cgroup v2
    cgroup_v2_path = "/sys/fs/cgroup/memory.max"

    if os.path.exists(cgroup_v2_path):
        try:
            with open(cgroup_v2_path, "r", encoding="utf-8") as fd:
                value = fd.read().strip()

                if value == "max":
                    raise MemoryLimitNotFoundError(
                        "No memory limit set in cgroup v2 (value is 'max')."
                    )

                return int(value)

        except (OSError, ValueError) as ex:
            raise MemoryLimitNotFoundError(
                f"Failed to read cgroup v2 memory limit: {ex}"
            ) from ex

    # Check for cgroup v1
    cgroup_v1_path = "/sys/fs/cgroup/memory/memory.limit_in_bytes"

    if os.path.exists(cgroup_v1_path):
        try:
            with open(cgroup_v1_path, "r", encoding="utf-8") as fd:
                value = fd.read().strip()
                limit = int(value)

                # On some systems, "unlimited" might be represented by a very large number
                if limit >= 1 << 60:  # Treat as no limit
                    raise MemoryLimitNotFoundError(
                        "Memory limit is effectively unlimited in cgroup v1."
                    )

                return limit

        except (OSError, ValueError) as ex:
            raise MemoryLimitNotFoundError(
                f"Failed to read cgroup v1 memory limit: {ex}"
            ) from ex

    raise MemoryLimitNotFoundError("Cgroup memory limit file not found.")

