from __future__ import absolute_import, division, print_function

import re
import datasets

# Citation information
_CITATION = """\
@inproceedings{panayotov2015librispeech,
  title={Librispeech: an ASR corpus based on public domain audio books},
  author={Panayotov, Vassil and Chen, Guoguo and Povey, Daniel and Khudanpur, Sanjeev},
  booktitle={Acoustics, Speech and Signal Processing (ICASSP), 2015 IEEE International Conference on},
  pages={5206--5210},
  year={2015},
  organization={IEEE}
}
"""

# Dataset description
_DESCRIPTION = """\
Language modeling resources to be used in conjunction with the LibriSpeech ASR corpus.
"""

# URLs for data retrieval
_URL = "http://www.openslr.org/11"
_DL_URL = "http://www.openslr.org/resources/11/librispeech-lm-norm.txt.gz"


class LibrispeechLmConfig(datasets.BuilderConfig):
    """Builder config for LibriSpeech LM"""

    def __init__(self, **kwargs):
        # Extract language model corpus path from kwargs or use default
        self.lm_corpus_path = kwargs.pop("lm_corpus_path", None)

        super().__init__(
            **kwargs,
        )

    def __post_init__(self):
        # Set default corpus path if not provided
        if self.lm_corpus_path is None:
            self.lm_corpus_path = _DL_URL


class LibrispeechLm(datasets.GeneratorBasedBuilder):
    """LibriSpeech language modeling dataset."""

    VERSION = datasets.Version("0.1.0")
    BUILDER_CONFIG_CLASS = LibrispeechLmConfig

    def _info(self):
        return datasets.DatasetInfo(
            description=_DESCRIPTION,
            features=datasets.Features({"text": datasets.Value("string")}),
            supervised_keys=("text", "text"),
            homepage=_URL,
            citation=_CITATION,
        )

    def _split_generators(self, dl_manager):
        """Returns SplitGenerators."""
        path_dic = {}

        for split_name, files in self.config.data_files.items():
            if split_name == "train":  # concatenation lm_corpus and train transcripts
                path_dic[split_name] = dl_manager.download_and_extract(
                    [self.config.lm_corpus_path] + files
                )
            else:
                path_dic[split_name] = dl_manager.download_and_extract(files)

        return [
            datasets.SplitGenerator(
                name=split_name, gen_kwargs={"archive_path": archive_path}
            )
            for split_name, archive_path in path_dic.items()
        ]

    def _generate_examples(self, archive_path):
        """Yields examples."""
        key = 0

        for p in archive_path:
            with open(p, "r", encoding="utf-8") as f:
                for line in f:
                    # Remove IDs in transcripts using regex
                    line = re.sub(r"\d+-\d+-\d+\s", "", line)
                    text = line.strip()

                    # Skip empty lines and very long sentences (>1000 char) to prevent OOM
                    if text and len(text) < 1000:
                        yield key, {"text": text}

                    key += 1

# Constellix DNS Provider implementation
import requests
import hmac
import hashlib
import base64
import time
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class ConstellixDnsProvider(BaseDnsProvider):
    # Provider metadata
    PROVIDER_TYPE = "constellix"
    PROVIDER_NAME = "Constellix"
    PROVIDER_DESCRIPTION = "Constellix Managed DNS API"
    REQUIRED_CREDENTIALS = ["api_key", "secret_key"]

    BASE_URL = "https://api.dns.constellix.com/v4"

    def _get_headers(self) -> Dict[str, str]:
        timestamp = str(int(time.time() * 1000))

        # Generate HMAC hash
        hmac_hash = hmac.new(
            self.credentials['secret_key'].encode(),
            timestamp.encode(),
            hashlib.sha1
        ).digest()

        token = base64.b64encode(hmac_hash).decode()

        return {
            'x-cns-security-token': f'{self.credentials["api_key"]}:{token}:{timestamp}',
            'Content-Type': 'application/json',
        }

    def _request(self, method: str, path: str, data: Optional[Dict] = None) -> Tuple[bool, Any]:
        url = f"{self.BASE_URL}{path}"

        try:
            resp = requests.request(
                method=method,
                url=url,
                headers=self._get_headers(),
                json=data,
                timeout=30
            )

            if resp.status_code >= 400:
                return False, resp.reason

            return True, resp.json() if resp.text else None

        except requests.RequestException as e:
            return False, str(e)

    def _find_domain(self, domain: str) -> Optional[Dict]:
        success, result = self._request('GET', '/domains')

        if not success:
            return None

        domains = result.get('data', [])
        domain_parts = domain.split('.')

        # Try to match domain from longest to shortest suffix
        for i in range(len(domain_parts) - 1):
            name = '.'.join(domain_parts[i:])

            for d in domains:
                if d['name'] == name:
