import base64
from typing import Optional

def decode_base64(data: str) -> Optional[str]:
    """Decode base64 data, supporting urlsafe and missing padding."""
    cleaned = data.strip()

    if not cleaned:
        return None

    # Add padding if necessary
    cleaned += "=" * (-len(cleaned) % 4)

    # Try decoding with urlsafe first, then standard base64
    for decoder in (base64.urlsafe_b64decode, base64.b64decode):
        try:
            return decoder(cleaned).decode("utf-8")
        except (ValueError, UnicodeDecodeError):
            continue

    return None

# Export command implementation
from ..process import Process
from ..command_decorators import command
from . import register_command


@command()
@register_command('export')
def cmd_export(process: Process) -> int:
    """
    Set or display environment variables
    Usage: export [VAR=value ...]
    """
    # If no arguments provided, display all environment variables
    if not process.args:
        if hasattr(process, 'env'):
            for key, value in sorted(process.env.items()):
                process.stdout.write(f"{key}={value}\n".encode('utf-8'))
        return 0

    # Set environment variables from arguments
    for arg in process.args:
        if '=' in arg:
            var_name, var_value = arg.split('=', 1)
            var_name = var_name.strip()
            var_value = var_value.strip()

            # Validate variable name
            if var_name and var_name.replace('_', '').replace('-', '').isalnum():
                if hasattr(process, 'env'):
                    process.env[var_name] = var_value
            else:
                process.stderr.write(f"export: invalid variable name: {var_name}\n")
                return 1
        else:
            process.stderr.write(f"export: usage: export VAR=value\n")
            return 1

    return 0

