def _post(path, body, key):
    """Make POST request to SkillPay API"""
    req = urllib.request.Request(
        f"{API}{path}", 
        data=json.dumps(body).encode(),
        headers={
            "Content-Type": "application/json", 
            "X-API-Key": key
        }, 
        method="POST"
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        return json.loads(e.read())

def _get(path, key):
    """Make GET request to SkillPay API"""
    req = urllib.request.Request(
        f"{API}{path}", 
        headers={"X-API-Key": key}
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        return json.loads(e.read())

def charge(uid, amount=0.005, key=None):
    """Charge a user for using the service"""
    k = _key(key)
    if not k:
        return {"success": False, "error": "SKILLPAY_API_KEY not set"}

    d = _post(
        "/billing/charge", 
        {
            "user_id": uid, 
            "skill_id": SKILL_ID, 
            "amount": amount,
            "currency": "USDT", 
            "description": "Prompt Artist"
        }, 
        k
    )

    if d.get("success"):
        return {"success": True, "charged": amount, "data": d}

    return {
        "success": False, 
        "needs_payment": bool(d.get("payment_url")),
        "payment_url": d.get("payment_url", ""), 
        "balance": d.get("balance", 0),
        "message": d.get("message", "charge failed")
    }

def balance(uid, key=None):
    """Check user's account balance"""
    k = _key(key)
    if not k:
        return {"success": False, "error": "SKILLPAY_API_KEY not set"}

    return {
        "success": True, 
        "data": _get(f"/billing/balance?user_id={uid}", k)
    }

def payment_link(uid, amount=5.0, key=None):
    """Generate a payment link for user"""
    k = _key(key)
    if not k:
        return {"success": False, "error": "SKILLPAY_API_KEY not set"}

    return {
        "success": True, 
        "data": _post(
            "/billing/payment-link",
            {"user_id": uid, "skill_id": SKILL_ID, "Amount": amount}, 
            k
        )
    }

if __name__ == "__main__":
    # Command-line interface setup
    p = argparse.ArgumentParser()
    p.add_argument("--user-id", required=True)
    p.add_argument("--amount", type=float, default=0.005)
    p.add_argument("--api-key", default=None)

    g = p.add_mutually_exclusive_group()
    g.add_argument("--charge", action="store_true", default=True)
    g.add_argument("--balance", action="store_true")
    g.add_argument("--payment-link", action="store_true")

    a = p.parse_args()

    # Execute requested operation
    if a.balance:
        r = balance(a.user_id, a.api_key)
    elif a.payment_link:
        r = payment_link(a.user_id, a.amount or 5.0, a.api_key)
    else:
        r = charge(a.user_id, a.amount, a.api_key)

    # Output result and exit
    print(json.dumps(r, indent=2, ensure_ascii=False))
    sys.exit(0 if r.get("success") else 1)

# Normalizes JSON schema types to lowercase for compatibility with standard JSON Schema
from typing import Any, ClassVar, cast

from klaude_code.core.tool.context import ToolContext
from klaude_code.protocol import llm_param, message, tools


def _normalize_schema_types(schema: dict[str, Any]) -> dict[str, Any]:
    """Recursively normalize JSON schema type values to lowercase.

    Some LLMs (e.g., Gemini 3) generate type values in uppercase like "OBJECT", "STRING".
    Standard JSON Schema requires lowercase type values.
    """
    result: dict[str, Any] = {}

    for key, value in schema.items():
        if key == "type" and isinstance(value, str):
            result[key] = value.lower()
        elif isinstance(value, dict):
            result[key] = _normalize_schema_types(cast(dict[str, Any], value))
        elif isinstance(value, list):
            normalized_list: list[Any] = []

            for item in cast(list[Any], value):
                if isinstance(item, dict):
                    normalized_list.append(_normalize_schema_types(cast(dict[str, Any], item)))
                else:
                    normalized_list.append(item)

            result[key] = normalized_list
        else:
            result[key] = value

    return result


class ReportBackTool:
    """Special tool for sub-agents to return structured output and end the task.

    This tool is dynamically injected when a parent agent calls a sub-agent with
    an output_schema. The schema for this tool's parameters is defined by the
    parent agent, allowing structured data to be returned.

    Note: This class does not inherit from ToolABC because it's not registered
    in the global tool registry. Instead, it's handled specially by the
    TurnExecutor and SubAgentManager.
    """

    _schema: ClassVar[dict[str, Any]] = {}

    @classmethod
    def for_schema(cls, schema: dict[str, Any]) -> type["ReportBackTool"]:
        """Create a tool class with the specified output schema.

        Args:
            schema: JSON Schema defining the expected structure of the report_back arguments.

        Returns:
            A new class with the schema set as a class variable.
        """
        normalized = _normalize_schema_types(schema)
        return type("ReportBackTool", (ReportBackTool,), {"_schema": normalized})

    @classmethod
    def schema(cls) -> llm_param.ToolSchema:
        """Generate the tool schema for this report_back tool."""
        return llm_param.ToolSchema(
            name=tools.REPORT_BACK,
            type="function",
            description=(
                "Report the final structured result back to the parent agent. "
                "Call this when you have completed the task and want to return structured data. "
                "The task will end after this tool is called."
            ),
            parameters=cls._schema,
        )

    @classmethod
    async def call(cls, arguments: str, context: ToolContext) -> message.ToolResultMessage:
        del arguments
        del context

        """Execute the report_back tool.

        The actual handling of report_back results is done by TurnExecutor.
        This method just returns a success status to maintain the tool call flow.
        """
        return message.ToolResultMessage(
            status="success",
            output_text="Result reported successfully. Task will end.",
        )

# Fill PDF form fields from JSON data
import json
import sys

from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter


def fill_pdf_fields(input_pdf_path: str, fields_json_path: str, output_pdf_path: str):
    # Load field definitions from JSON file
    with open(fields_json_path) as f:
        fields = json.load(f)

    # Group fields by page for easier processing
    fields_by_page = {}
    for field in fields:
        if "value" in field:
            field_id = field["field_id"]
            page = field["page"]
            if page not in fields_by_page:
                fields_by_page[page] = {}
            fields_by_page[page][field_id] = field["value"]

    # Read input PDF and validate fields
    reader = PdfReader(input_pdf_path)
    has_error = False
    field_info = get_field_info(reader)
    fields_by_ids = {f["field_id"]: f for f in field_info}

    # Validate each field against the PDF's actual field definitions
    for field in fields:
        existing_field = fields_by_ids.get(field["field_id"])
        if not existing_field:
            has_error = True
            print(f"ERROR: `{field['field_id']}` is not a valid field ID")
        elif field["page"] != existing_field["page"]:
            has_error = True
            print(
                f"ERROR: Incorrect page number for `{field['field_id']}` (got {field['page']}, expected {existing_field['page']})"
            )
        else:
            if "value" in field:
                err = validation_error_for_field_value(existing_field, field["value"])
                if err:
                    print(err)
                    has_error = True

    # Exit with error if any validation failed
    if has_error:
        sys.exit(1)

    # Fill the form fields and write output PDF
    writer = PdfWriter(clone_from=reader)
    for page, field_values in fields_by_page.items():
        writer.update_page_form_field_values(writer.pages[page - 1], field_values, auto_regenerate=False)

    writer.set_need_appearances_writer(True)
    with open(output_pdf_path, "wb") as f:
        writer.write(f)


def validation_error_for_field_value(field_info, field_value):
    field_type = field_info["type"]
    field_id = field_info["field_id"]

    if field_type == "checkbox":
        checked_val = field_info["checked_value"]
        unchecked_val = field_info["unchecked_value"]
        if field_value != checked_val and field_value != unchecked_val:
            return (
                f'ERROR: Invalid value "{field_value}" for checkbox field "{field_id}". '
                f'The checked value is "{checked_val}" and the unchecked value is "{unchecked_val}"'
            )

    elif field_type == "radio_group":
        option_values = [opt["value"] for opt in field_info["radio_options"]]
        if field_value not in option_values:
            return (
                f'ERROR: Invalid value "{field_value}" for radio group field "{field_id}". '
                f'Valid values are: {option_values}'
            )

    elif field_type == "choice":
        choice_values = [opt["value"] for opt in field_info["choice_options"]]
        if field_value not in choice_values:
            return (
                f'ERROR: Invalid value "{field_value}" for choice field "{field_id}". '
                f'Valid values are: {choice_values}'
            )

    return None


def monkeypatch_pydpf_method():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject

    original_get_inherited = DictionaryObject.get_inherited

    def patched_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in result)
        ):
            result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = patched_get_inherited


if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    monkeypatch_pydpf_method()
    input_pdf = sys.argv[1]
    fields_json = sys.argv[2]
    output_pdf = sys.argv[3]

    fill_pdf_fields(input_pdf, fields_json, output_pdf)

