# Import necessary modules
import argparse
import os
import sys
import json
import requests
from typing import Dict

def get_api_key(provided_key: str | None) -> str | None:
    # Return provided key if available, otherwise check environment variable
    if provided_key:
        return provided_key
    return os.environ.get("SCRAPE_CREATORS_API_KEY")

def make_request(url: str, params: dict, api_key: str) -> dict:
    headers = {"x-api-key": api_key}
    try:
        response = requests.get(url, headers=headers, params=params)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(json.dumps({"error": str(e)}), file=sys.stderr)
        return {}

def search_tiktok(query: str, search_type: str, api_key: str) -> Dict:
    # Determine URL based on search type
    url = "https://api.scrapecreators.com/v1/tiktok/search/keyword" if search_type == "keyword" else "https://api.scrapecreators.com/v1/tiktok/search/hashtag"

    # Prepare parameters accordingly
    params = {"query": query} if search_type == "keyword" else {"hashtag": query.replace("#", "")}

    data = make_request(url, params, api_key)
    videos = data.get("data", [])

    # Sort by play count to prioritize viral content
    sorted_videos = sorted(videos, key=lambda v: v.get("stats", {}).get("playCount", 0), reverse=True)
    top_videos = sorted_videos[:5]

    return {
        "query": query,
        "type": search_type,
        "top_results": [
            {
                "url": f"https://www.tiktok.com/@{v.get('author', {}).get('uniqueId', 'unknown')}/video/{v.get('item_id', v.get('id', ''))}",
                "author": v.get("author", {}).get("uniqueId", "unknown"),
                "caption": v.get("desc", ""),
                "views": v.get("stats", {}).get("playCount", 0),
                "likes": v.get("stats", {}).get("diggCount", 0)
            } for v in top_videos
        ]
    }

def search_ig_reels(query: str, api_key: str) -> Dict:
    # Instagram Reels search endpoint (keyword-based only)
    url = "https://api.scrapecreators.com/v2/instagram/reels/search"
    params = {"query": query}

    data = make_request(url, params, api_key)
    reels = data.get("items", [])

    # Sort by play_count descending
    sorted_reels = sorted(reels, key=lambda r: r.get("play_count", 0), reverse=True)
    top_reels = sorted_reels[:5]

    return {
        "query": query,
        "type": "keyword (reels)",
        "top_results": [
            {
                "url": f"https://www.instagram.com/reel/{r.get('code')}/",
                "author": r.get("user", {}).get("username", "unknown"),
                "caption": r.get("caption", {}).get("text", "") if r.get("caption") else "",
                "views": r.get("play_count", 0),
                "likes": r.get("like_count", 0)
            } for r in top_reels
        ]
    }

def main():
    # Set up argument parser
    parser = argparse.ArgumentParser(description="Search TikTok and Instagram Reels by keyword or hashtag.")
    parser.add_argument("--platform", choices=["tiktok", "instagram"], required=True)
    parser.add_argument("--type", choices=["keyword", "hashtag"], required=True, help="Note: Instagram currently uses keyword search for Reels.")
    parser.add_argument("--query", required=True, help="The search query (e.g., 'dinner recipes' or 'healthyfood')")
    parser.add_argument("--api-key", help="ScrapeCreators API Key")

    args = parser.parse_args()

    # Get API key
    api_key = get_api_key(args.api_key)
    if not api_key:
        print(json.dumps({"error": "SCRAPE_CREATORS_API_KEY environment variable is required."}), file=sys.stderr)
        sys.exit(1)

    # Route to appropriate search function
    if args.platform == "tiktok":
        data = search_tiktok(args.query, args.type, api_key)
    else:
        # For Instagram, always use reels search regardless of type
        data = search_ig_reels(args.query, api_key)

    # Output final result
    print(json.dumps({
        "status": "success",
        "platform": args.platform,
        "search_results": data
    }, indent=2))

if __name__ == "__main__":
    main()

# Cron job API endpoints
from __future__ import annotations

import uuid
from fastapi import APIRouter, Depends, HTTPException, Request

from .manager import CronManager
from .models import CronJobSpec, CronJobView

router = APIRouter(prefix="/cron", tags=["cron"])


def get_cron_manager(request: Request) -> CronManager:
    mgr = getattr(request.app.state, "cron_manager", None)
    if mgr is None:
        raise HTTPException(
            status_code=503,
            detail="cron manager not initialized",
        )
    return mgr


@router.get("/jobs", response_model=list[CronJobSpec])
async def list_jobs(mgr: CronManager = Depends(get_cron_manager)):
    return await mgr.list_jobs()


@router.get("/jobs/{job_id}", response_model=CronJobView)
async def get_job(job_id: str, mgr: CronManager = Depends(get_cron_manager)):
    job = await mgr.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="job not found")
    return CronJobView(spec=job, state=mgr.get_state(job_id))


@router.post("/jobs", response_model=CronJobSpec)
async def create_job(
    spec: CronJobSpec,
    mgr: CronManager = Depends(get_cron_manager),
):
    # server generates id; ignore client-provided spec.id
    job_id = str(uuid.uuid4())
    created = spec.model_copy(update={"id": job_id})
    await mgr.create_or_replace_job(created)
    return created


@router.put("/jobs/{job_id}", response_model=CronJobSpec)
async def replace_job(
    job_id: str,
    spec: CronJobSpec,
    mgr: CronManager = Depends(get_cron_manager),
):
    if spec.id != job_id:
        raise HTTPException(status_code=400, detail="job_id mismatch")
    await mgr.create_or_replace_job(spec)
    return spec


@router.delete("/jobs/{job_id}")
async def delete_job(
    job_id: str,
    mgr: CronManager = Depends(get_cron_manager),
):
    ok = await mgr.delete_job(job_id)
    if not ok:
        raise HTTPException(status_code=404, detail="job not found")
    return {"deleted": True}


@router.post("/jobs/{job_id}/pause")
async def pause_job(job_id: str, mgr: CronManager = Depends(get_cron_manager)):
    try:
        await mgr.pause_job(job_id)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e)) from e
    return {"paused": True}


@router.post("/jobs/{job_id}/resume")
async def resume_job(
    job_id: str,
    mgr: CronManager = Depends(get_cron_manager),
):
    try:
        await mgr.resume_job(job_id)
    except Exception as e:
        raise HTTPException(status_code=400, detail=str(e)) from e
    return {"resumed": True}


@router.post("/jobs/{job_id}/run")
async def run_job(job_id: str, mgr: CronManager = Depends(get_cron_manager)):
    try:
        await mgr.run_job(job_id)
    except KeyError as e:
        raise HTTPException(status_code=404, detail="job not found") from e
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e)) from e
    return {"started": True}


@router.get("/jobs/{job_id}/state")
async def get_job_state(
    job_id: str,
    mgr: CronManager = Depends(get_cron_manager),
):
    job = await mgr.get_job(job_id)
    if not job:
        raise HTTPException(status_code=404, detail="job not found")
    return mgr.get_state(job_id).model_dump(mode="json")

