        buffered = BytesIO()
        image.save(buffered, format="PNG")
        encoded_image_text = base64.b64encode(buffered.getvalue()).decode("utf-8")
        base64_qwen = f"data:image;base64,{encoded_image_text}"
        return base64_qwen

    def _extract_scores(self, text_outputs):
        scores = []
        pattern = r"Final Score:\s*([1-5](?:\.\d+)?)"
        for text in text_outputs:
            match = re.search(pattern, text)
            if match:
                try:
                    scores.append(float(match.group(1)))
                except ValueError:
                    scores.append(0.0)
            else:
                scores.append(0.0)
        return scores

    def evaluate_image(self, prompt, image):
        question = f"<image>\nYou are given a text caption and a generated image based on that caption. Your task is to evaluate this image based on two key criteria:\n1. Alignment with the Caption: Assess how well this image aligns with the provided caption. Consider the accuracy of depicted objects, their relationships, and attributes as described in the caption.\n2. Overall Image Quality: Examine the visual quality of this image, including clarity, detail preservation, color accuracy, and overall aesthetic appeal.\nBased on the above criteria, assign a score from 1 to 5 after 'Final Score:'.\nYour task is provided as follows:\nText Caption: [{prompt}]"
        images_base64 = self.pil_image_to_base64(image)
        response = self.client.chat.completions.create(
            model="UnifiedReward-7b-v1.5",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {"url": images_base64},
                        },
                        {
                            "type": "text",
                            "text": question,
                        },
                    ],
                },
            ],
            temperature=0,
            stream=False,
        )
        return response.choices[0].message.content

    def evaluate_batch_image(self, images, prompts):
        results = [
            self.evaluate_image(prompt, img) for prompt, img in zip(prompts, images)
        ]
        return results

    def calculate_reward(self, images, metadata):
        import torch
        from PIL import Image

        def _error(msg: str):
            logger.error(msg)
            return {
                "error": msg,
                "scores": None,
                "input_info": metadata.get("input_info", {}),
                "duration": "0.00",
                "decoded_duration": metadata.get("decode_duration", "N/A"),
                "type": self.reward_name,
            }

        t0 = time.perf_counter()

        # Validate inputs
        if images is None:
            return _error("[unified_reward] images tensor is None.")

        if not isinstance(images, torch.Tensor) or images.dim() != 4:
            return _error(
                f"[unified_reward] expects 4D torch.Tensor in BHWC/NHWC layout (B,H,W,C); got type={type(images)} shape={getattr(images, 'shape', None)} dtype={getattr(images, 'dtype', None)}"
            )

        if images.shape[0] == 0:
            return _error("[unified_reward] images batch size is zero.")

        x = images
        if x.dtype != torch.uint8:
            x = x.to(torch.uint8)

        # Ensure NHWC layout
        if x.shape[-1] == 3:
            x_nhwc = x
        elif x.shape[1] == 3:
            x_nhwc = x.permute(0, 2, 3, 1).contiguous()
        else:
            raise ValueError(f"channel dim must be 3, got shape {x.shape}")

        # Convert to PIL images
        pil_images = [
            Image.fromarray(x_nhwc[i].cpu().numpy()) for i in range(x_nhwc.shape[0])
        ]

        # Process prompts
        prompts = metadata.get("prompts")
        if prompts is None:
            return _error("[unified_reward] prompts are required and cannot be None.")
        if isinstance(prompts, str):
            prompts = [prompts]
        if len(prompts) != len(pil_images):
            return _error(
                f"[unified_reward] prompts length ({len(prompts)}) must match batch size ({len(pil_images)})."
            )

        # Evaluate images
        text_outputs = self.evaluate_batch_image(pil_images, prompts)
        scores = self._extract_scores(text_outputs)

        # Normalize scores to [0, 1]
        scores = [sc / 5.0 for sc in scores]

        duration = f"{(time.perf_counter() - t0):.2f}"

        return {
            "scores": {"unified_reward": scores},
            "input_info": metadata.get("input_info", {}),
            "duration": duration,
            "decoded_duration": metadata.get("decode_duration", "N/A"),
            "type": self.reward_name,
        }

# Import necessary modules
import sys
import re
from datetime import datetime

# Mapping of month names to numbers
MONTH_MAP = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'may': 5, 'june': 6, 'july': 7, 'august': 8,
    'september': 9, 'october': 10, 'november': 11, 'december': 12,
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'sept': 9, 'oct': 10,
    'nov': 11, 'dec': 12
}

# Supported date formats
DATE_FORMATS = [
    '%B %d, %Y', '%b %d, %Y',
    '%d %B %Y', '%d %b %Y',
    '%m/%d/%Y', '%d/%m/%Y',
    '%Y-%m-%d', '%Y/%m/%d'
]

def parse_date(date_str: str) -> str:
    """Parse various date formats to ISO format (YYYY-MM-DD)."""
    date_str = date_str.strip()

    # Try standard formats first
    for fmt in DATE_FORMATS:
        try:
            dt = datetime.strptime(date_str, fmt)
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            continue

    # Fallback: regex pattern for "Month DD, YYYY" variations
    pattern = r'(\w+)\s+(\d{1,2}),?\s+(\d{4})'
    match = re.search(pattern, date_str, re.I)
    if match:
        month_name, day, year = match.groups()
        month_num = MONTH_MAP.get(month_name.lower())
        if month_num:
            return f'{year}-{month_num:02d}-{int(day):02d}'

    return ''

def parse_time(time_str: str) -> str:
    """Parse various time formats to HH:MM format."""
    if not time_str:
        return ''

    time_str = time_str.strip()

    # Pattern: HH:MM AM/PM or HH:MM
    pattern1 = r'(\d{1,2}):(\d{2})\s*(am|pm)?'
    match = re.search(pattern1, time_str, re.I)
    if match:
        hour, minute, ampm = int(match.group(1)), int(match.group(2)), match.group(3)
        if ampm:
            ampm = ampm.lower()
            if ampm == 'pm' and hour != 12:
                hour += 12
            elif ampm == 'am' and hour == 12:
                hour = 0
        return f'{hour:02d}:{minute:02d}'

    # Pattern: H AM/PM (no minutes)
    pattern2 = r'(\d{1,2})\s*(am|pm)'
    match = re.search(pattern2, time_str, re.I)
    if match:
        hour, ampm = int(match.group(1)), match.group(2).lower()
        if ampm == 'pm' and hour != 12:
            hour += 12
        elif ampm == 'am' and hour == 12:
            hour = 0
        return f'{hour:02d}:00'

    return ''

def main():
    # Check command line arguments
    if len(sys.argv) < 3:
        print("Usage: date_parser.py <date|time> <value>", file=sys.stderr)
        sys.exit(1)

    mode = sys.argv[1]
    value = sys.argv[2]

    if mode == 'date':
        print(parse_date(value))
    elif mode == 'time':
        print(parse_time(value))
    else:
        print(f"Unknown mode: {mode}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

import os
from pathlib import Path
from typing import Optional

def _to_posix(p: str) -> str:
    """Normalize path separators to forward slashes on Windows."""
    return p.replace("\\", "/") if os.name == "nt" else p


def get_relative_file_path(lean_project_path: Path, file_path: str) -> Optional[str]:
    """
    Convert path relative to project path.

    Args:
        lean_project_path (Path): Path to the Lean project root.
        file_path (str): File path.

    Returns:
        str: Relative file path (always forward slashes).
    """
    file_path_obj = Path(file_path)

    # Absolute path under project
    if file_path_obj.is_absolute() and file_path_obj.exists():
        try:
            return _to_posix(str(file_path_obj.relative_to(lean_project_path)))
        except ValueError:
            return None

    # Relative to project path
    path = lean_project_path / file_path
    if path.exists():
        return _to_posix(str(path.relative_to(lean_project_path)))

    # Relative to CWD, but only if inside project root
    cwd = Path.cwd()
    path = cwd / file_path
    if path.exists():
        try:
            return _to_posix(str(path.resolve().relative_to(lean_project_path)))
        except ValueError:
            return None

    return None


def get_file_contents(abs_path: str) -> str:
    for enc in ("utf-8", "latin-1"):
        try:
            with open(abs_path, "r", encoding=enc) as f:
                return f.read()
        except UnicodeDecodeError:
            continue

    with open(abs_path, "r", encoding="utf-8", errors="replace") as f:
        return f.read()

