from func_timeout import FunctionTimedOut, func_timeout

# Custom exception class for timeout errors
class TimeoutError(Exception):
    """Generic SDK Tool TimeoutError (wraps func-timeout)."""
    pass

def run_with_timeout(func, timeout, *args, **kwargs):
    # Execute function with timeout constraint
    try:
        return func_timeout(timeout, func, args=args, kwargs=kwargs)
    except FunctionTimedOut:
        # Raise custom timeout error if operation exceeds time limit
        raise TimeoutError(f"Operation timed out after {timeout} seconds")

# Import required utilities for wrapping methods
from areal.utils.wrapper import (
    wrap,
    wrap_get_method,
    wrap_get_method_name,
    wrap_remove_meta,
    wrapable,
)


class Calculator:
    def __init__(self):
        self.remaining = 2

    @wrapable()
    def add(self, a, b):
        return a + b + self.remaining

    @wrapable(name="multiply")
    def mul(self, x, y):
        return x * y * self.remaining


class EnhancedCalculator:
    def __init__(self, obj: Calculator):
        super().__init__()
        self.prefix = "Result:"
        self.calculator = obj
        wrap(self, obj, self._wrap_call)

    def _wrap_call(self, *args, **kwargs):
        method_name = wrap_get_method_name(kwargs)
        method = wrap_get_method(kwargs)
        kwargs = wrap_remove_meta(kwargs)

        print("wrap method: ", method_name)
        print("wrap method: ", method)
        return method(*args, **kwargs)


def test_wrapper():
    calc = Calculator()
    enhancer = EnhancedCalculator(calc)

    assert enhancer.add(2, 3) == 7
    assert enhancer.multiply(4, 5) == 40


if __name__ == "__main__":
    test_wrapper()

import asyncio
import random
import aiohttp

from miles.utils.misc import load_function
from miles.utils.types import Sample

# Import reward computation utilities
from .deepscaler import get_deepscaler_rule_based_reward
from .f1 import f1_score
from .gpqa import compute_gpqa_reward
from .math_dapo_utils import compute_score as compute_score_dapo
from .math_utils import extract_answer as extract_boxed_answer
from .math_utils import grade_answer_verl


async def remote_rm(args, sample: Sample):
    # Prepare payload for remote reward model
    payload = {
        "prompt": sample.prompt,
        "response": sample.response,
        "label": sample.label,
    }

    session_kwargs = {}

    async with aiohttp.ClientSession(**session_kwargs) as session:
        async with session.post(args.rm_url, json=payload) as resp:
            resp.raise_for_status()
            return await resp.json()


async def async_rm(args, sample: Sample, **kwargs):
    # Use custom RM if specified
    if args.custom_rm_path is not None:
        rm_function = load_function(args.custom_rm_path)
        return await rm_function(args, sample, **kwargs)

    # Extract metadata and RM type
    metadata = sample.metadata if isinstance(sample.metadata, dict) else {}
    rm_type = (metadata.get("rm_type") or args.rm_type or "").strip()

    response = sample.response
    label = sample.label

    # Handle boxed answer extraction if needed
    if rm_type.startswith("boxed_"):
        response = extract_boxed_answer(response) or ""
        rm_type = rm_type[len("boxed_"):]

    # Dispatch to appropriate reward function
    if rm_type == "remote_rm":
        return await remote_rm(args, sample)
    elif rm_type == "deepscaler":
        return get_deepscaler_rule_based_reward(response, label)
    elif rm_type == "dapo":
        return compute_score_dapo(response, label)
    elif rm_type == "math":
        return 1 if grade_answer_verl(response, label) else 0
    elif rm_type == "f1":
        return f1_score(response, label)[0]
    elif rm_type == "gpqa":
        return compute_gpqa_reward(response, label, metadata=metadata)
    elif rm_type == "ifbench":
        from .ifbench import compute_ifbench_reward
        return compute_ifbench_reward(response, label, metadata=metadata)
    elif rm_type == "random":
        return random.randint(0, 1)
    elif rm_type:
        raise NotImplementedError(f"Rule-based RM for {rm_type} is not implemented.")
    else:
        raise NotImplementedError("Rule-based RM type is not specified.")


async def batched_async_rm(
    args,
    samples: list[Sample],
    inplace_set_reward_field: bool = False,
    **kwargs,
) -> list[int | float] | None:
    # Set rewards in-place if requested
    if inplace_set_reward_field:
        rewards = await batched_async_rm(args, samples, **kwargs)
        for sample, reward in zip(samples, rewards, strict=True):
            assert (
                sample.reward is None
            ), f"Overriding sample.reward from {sample.reward} to {reward}, is this intended?"
            sample.reward = reward
        return None

    # Use custom RM for batch processing if specified
    if args.custom_rm_path is not None:
        rm_function = load_function(args.custom_rm_path)
        return await rm_function(args, samples, **kwargs)

    # Create and execute concurrent tasks
    tasks = [async_rm(args, sample, **kwargs) for sample in samples]
    rewards = await asyncio.gather(*tasks)
    return rewards

# Abstract base class for file handlers
from abc import ABCMeta, abstractmethod

class BaseFileHandler(metaclass=ABCMeta):
    # `str_like` is a flag to indicate whether the type of file object is
    # str-like object or bytes-like object. Pickle only processes bytes-like
    # objects but json only processes str-like object. If it is str-like
    # object, `StringIO` will be used to process the buffer.
    str_like = True

    @abstractmethod
    def load_from_fileobj(self, file, **kwargs):
        pass

    @abstractmethod
    def dump_to_fileobj(self, obj, file, **kwargs):
        pass

    @abstractmethod
    def dump_to_str(self, obj, **kwargs):
        pass

    def load_from_path(self, filepath, mode="r", **kwargs):
        with open(filepath, mode) as f:
