import re
from pathlib import Path

# Define root directory (one level up from current file's location)
ROOT = Path(__file__).resolve().parents[1]

# Define regex patterns for platform-specific checks
PATTERNS = {
    "shebang_bash": re.compile(r"^#!.*\b(bash|sh)\b"),
    "chown_chmod": re.compile(r"\b(chown|chmod|id -u|id -g)\b"),
    "pulse_audio": re.compile(r"\b(pulseaudio|pactl)\b"),
    "s6": re.compile(r"\bs6-"),
    "unix_socket": re.compile(r"unix:"),
    "docker_compose": re.compile(
        r"docker[- ]?compose|Dockerfile|docker-compose.yml", 
        re.IGNORECASE
    ),
}

# Initialize report list
REPORT = []

# Scan all files in the root directory recursively
for p in ROOT.rglob("*"):
    # Only process regular files with specific extensions or no extension
    if p.is_file() and p.suffix in (".sh", ".py", ""):
        try:
            # Read file content, ignoring encoding errors
            text = p.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            # Skip files that cannot be read
            continue

        # Check each pattern against the file content
        for name, pat in PATTERNS.items():
            if pat.search(text):
                REPORT.append((name, str(p)))

# Output results
if not REPORT:
    print("No platform-specific patterns found.")
else:
    print("Platform-specific scan results:")

    # Group findings by pattern type
    by_type = {}
    for name, path in REPORT:
        by_type.setdefault(name, []).append(path)

    # Print grouped results
    for name, paths in by_type.items():
        print(f"\n[{name}]")
        for p in paths[:30]:
            print(" -", p)
        if len(paths) > 30:
            print("  ... and more")

print("\nScan complete.")

