class Order:
    """Order Type"""

    def __init__(self, order_type, side, amount, price=None):
        # Validate order type
        if order_type not in ['market', 'limit']:
            raise ValueError(
                "Order types can only be of type ['market', 'limit'], but was given: {}".format(order_type))

        self.type = order_type

        # Validate order side
        if side not in ['buy', 'sell']:
            raise ValueError("Order side can only be of type ['buy', 'sell'], but was given: {}".format(order_type))

        self.side = side

        # Validate amount
        if amount <= 0:
            raise ValueError("Size must be greater than zero, but was given: {}".format(amount))

        self.amount = amount

        # Validate price for limit orders
        if self.type == 'limit' and price is None:
            raise ValueError("Limit orders require a price but None was given")

        if price <= 0:
            raise ValueError("Price must be greater than zero but was given: {}".format(price))

        self.price = price

