from typing import Iterable, List
import attr

@attr.s
class FilterState:
    """A filter state instance."""
    threshold: int = attr.ib()
    is_active: bool = attr.ib()

@attr.s
class CmStatus:
    status: str = attr.ib()
    message: str = attr.ib()

def filter_entries(data: Iterable[CmStatus], state: FilterState) -> List[CmStatus]:
    if not state.is_active:
        return list(data)

    return [item for item in data if len(item.message) > state.threshold]

# Apache Beam pipeline to process CSV data and compute average age of adults
import apache_beam as beam
from apache_beam.options.pipeline_options import PipelineOptions
import csv

class AdultFilterFn(beam.DoFn):
    def process(self, record):
        if int(record['age']) >= 18:
            yield record

class AgeAverageCombiner(beam.CombineFn):
    def create_accumulator(self):
        return (0, 0)  # (total_age, person_count)

    def add_input(self, accumulator, value):
        return accumulator[0] + int(value['age']), accumulator[1] + 1

    def merge_accumulators(self, partial_accumulators):
        totals, counts = zip(*partial_accumulators)
        return sum(totals), sum(counts)

    def extract_output(self, final_accumulator):
        total_sum, count = final_accumulator
        return total_sum / count if count > 0 else 0

def execute_pipeline(source_file, destination_file):
    pipeline_opts = PipelineOptions()
    with beam.Pipeline(options=pipeline_opts) as pipeline:
        raw_lines = pipeline | 'LoadCSV' >> beam.io.ReadFromText(source_file, skip_header_lines=1)
        parsed_data = raw_lines | 'ConvertToDict' >> beam.Map(lambda line: next(csv.DictReader([line], fieldnames=['id', 'name', 'age'])))
        adult_records = parsed_data | 'SelectAdults' >> beam.ParDo(AdultFilterFn())
