# Systemd inhibitor for preventing system suspend
import dbus

class PowerManagementLock:
    def __init__(self):
        self.system_bus = dbus.SystemBus()
        self.logind_manager = dbus.Interface(
            self.system_bus.get_object("org.freedesktop.login1", "/org/freedesktop/login1"),
            "org.freedesktop.login1.Manager"
        )
        self.inhibition_fd = None
        self.inhibit_modes = "sleep:handle-lid-switch"

    def prevent_suspend(self, application_name, reason):
        if not self.inhibition_fd:
            self.inhibition_fd = self.logind_manager.Inhibit(
                self.inhibit_modes,
                application_name,
                reason,
                "block",
                dbus_interface="org.freedesktop.login1.Manager"
            ).take()

    def allow_suspend(self):
        if self.inhibition_fd:
            self.inhibition_fd.release()
            self.inhibition_fd = None

