# Organize summary files from source to destination directories
import os
import shutil

def reorganize_summaries(base_dir, target_dir, source_dir):
    for subdir in os.listdir(base_dir):
        full_subdir_path = os.path.join(base_dir, subdir)
        if os.path.isdir(full_subdir_path):
            target_subdir_path = os.path.join(target_dir, subdir)
            if not os.path.exists(target_subdir_path):
                os.makedirs(target_subdir_path)
            # Transfer summary files from source to target location
            source_subdir_path = os.path.join(source_dir, subdir)
            if os.path.exists(source_subdir_path):
                for filename in os.listdir(source_subdir_path):
                    src_file = os.path.join(source_subdir_path, filename)
                    dst_file = os.path.join(target_subdir_path, filename)
                    shutil.copy2(src_file, dst_file)

# Generate indices for self-interaction terms in a tensor
import torch

def compute_self_interaction_positions(T, agent_count):
    self_indices = torch.tensor(
        [
            [
                t * agent_count * agent_count + agent_count * i + i
                for i in range(agent_count)
            ]
            for t in range(T)
        ]
    )
    return self_indices

