import re

def check_package_info(data: dict) -> bool:
    # Check 1: Package name must not be empty and should only contain alphanumeric characters and underscores
    if not (data.get('name') and re.match(r'^[a-zA-Z0-9_]+$', data['name'])):
        return False

    # Check 2: Ensure version number follows semantic versioning (major.minor.patch)
    if not re.match(r'^\d+\.\d+\.\d+$', data.get('version', '')):
        return False

    # Check 3: Author name and email must be present, and email must contain '@'
    if not (data.get('author') and data.get('author_email') and '@' in data['author_email']):
        return False

    # Check 4: Verify URL is valid HTTP or HTTPS link
    url_regex = re.compile(r'https?://\S+')
    if not (data.get('url') and url_regex.match(data['url'])):
        return False

    # Check 5: Install dependencies must be provided as a list
    if not (data.get('install_requires') and isinstance(data['install_requires'], list)):
        return False

    return True

# Security improvements for authentication callback view
from django.middleware.csrf import CsrfViewMiddleware
from django.utils.crypto import constant_time_compare
import logging

logger = logging.getLogger(__name__)

def secure_callback_view(request):
    # 1. CSRF Protection: Ensure CSRF middleware is enabled and use decorator if needed
    # @csrf_protect  # Uncomment if not using global CsrfViewMiddleware

    # 2. Secure state comparison using constant-time comparison
    stored_state = request.session.get('stored_state')
    provided_state = request.GET.get('state')

    # Validate state exists in session and matches securely
    if stored_state is None or not constant_time_compare(stored_state, provided_state):
        return HttpResponseBadRequest("Invalid state parameter")

    # 3. Secure logging: Avoid logging sensitive user identifiers at INFO level
    # sub = get_user_identifier(...)  # Example source of 'sub'
    # logger.debug(f"User identifier processed: {sub}")  # Use DEBUG instead of INFO

    # 4. Input validation and sanitization for parameters
    code = request.GET.get('code', '').strip()
    if not code:
        return HttpResponseBadRequest("Missing authorization code")

    # Additional validation (length, format checks as appropriate)
    if len(code) > 256:
        return HttpResponseBadRequest("Invalid authorization code length")

    # 5. Session management: Verify required session variables exist
    required_session_vars = ['stored_nonce', 'redirect_uri']
    for var in required_session_vars:
        if var not in request.session:
            return HttpResponseBadRequest(f"Missing required session data: {var}")

    # Proceed with secure token exchange after validation...
    return HttpResponse("Authentication successful")

