class DateTimeSerializer(json.JSONEncoder):
    """
    A custom JSONEncoder that handles datetime and date objects.
    Converts them to ISO format strings that are compatible with JavaScript.
    """

    def default(self, item):
        if isinstance(item, datetime.datetime):
