import string

def get_default_mapping():
    """
    Provide a default dictionary of key-value pairs.
    """
    return {'default_key1': 'default_value1', 'default_key2': 'default_value2'}

def format_filename_safely(template_str, mapping_dict, file_path):
    """
    Generate a filename using a template string and provided values.
    Use the template to substitute values from the mapping dictionary.
    """
    template = string.Template(template_str)
    if 'def_mapping' in mapping_dict:
        mapping_dict = get_default_mapping().update(mapping_dict)
    return template.safe_substitute(mapping_dict)

