import jwt
from typing import Optional, Tuple

def parse_user_jwt(auth_token: str, secret_key: str, require_admin: bool) -> Tuple[Optional[str], Optional[str]]:
    try:
        payload = jwt.decode(auth_token, secret_key, algorithms=['HS256'])
        if require_admin and not payload.get('is_admin', False):
            return "Access denied", None
        user_identifier = payload.get('user_id')
        if user_identifier is None:
            return "Malformed token", None
        return None, user_identifier
    except jwt.ExpiredSignatureError:
        return "Token expired", None
    except jwt.InvalidTokenError:
        return "Token invalid", None

# Graph compression utility class
class GraphReducer:
    def reduce_graph_structure(self, adj_list):
        # Phase 1: Eliminate disconnected nodes
        disconnected = [vertex for vertex in adj_list if not adj_list[vertex]]
        for vertex in disconnected:
            del adj_list[vertex]

        # Phase 2: Combine vertices with single connection
        for vertex in list(adj_list):
            if len(adj_list[vertex]) == 1:
                adjacent = adj_list[vertex][0]
                del adj_list[vertex]
                for v in adj_list:
                    if vertex in adj_list[v]:
                        adj_list[v] = [adjacent if item == vertex else item for item in adj_list[v]]

        # Phase 3: Renumber node identifiers
        vertex_mapping = {vertex: idx for idx, vertex in enumerate(adj_list)}
        reduced_graph = {vertex_mapping[vertex]: [vertex_mapping[neighbor] for neighbor in connections] 
                         for vertex, connections in adj_list.items()}
        return reduced_graph

# Verification suite
def verify_graph_reduction():
    reducer = GraphReducer()

    # Scenario A: Graph containing isolated vertices
    scenario_a = {0: [1], 1: [], 2: [3], 3: []}
    result_a = reducer.reduce_graph_structure(scenario_a)
    assert result_a == {0: [1], 1: [2]}

    # Scenario B: Graph with reducible linear chains
    scenario_b = {0: [1], 1: [2], 2: [3], 3: []}
    result_b = reducer.reduce_graph_structure(scenario_b)
    assert result_b == {0: [1], 1: [2]}

    # Scenario C: Large chain graph
    big_chain = {i: [i+1] for i in range(99999)}
    result_c = reducer.reduce_graph_structure(big_chain)
    assert len(result_c) == 1
    assert len(result_c[0]) == 1

    print("All verification scenarios passed successfully.")

verify_graph_reduction()

