class DataDriftDetector:
    _GLOBAL_SLOW_DRIFT = "global_and_slow_gradual"

    def __init__(self, point_a, point_b, point_c, drift_mode):
        self._point_a = point_a
        self._point_b = point_b
        self._point_c = point_c
        self.drift_mode = drift_mode
        self.window_size = None

    def configure_window(self, window_length):
        if (
            window_length > self._point_b - self._point_a
            or window_length > self._point_c - self._point_b
        ) and self.drift_mode == self._GLOBAL_SLOW_DRIFT:
            raise ValueError(
                f'The specified "window_length" ({window_length}) exceeds allowed maximum'
            )
        self.window_size = window_length

