# Resolve dependencies for a given subject
from collections import deque

def resolve_dependencies(target):
    processing_queue = deque([(target.configuration.schema, [], None)])
    while processing_queue:
        current_schema, path_tokens, current_dependency = processing_queue.popleft()
        if current_dependency:
            schema_structure = current_dependency.construct_schema(name=current_dependency.token)
            if current_dependency.token and schema_structure.required:
                schema_structure = schema_structure.clone(required=False)
        else:
            schema_structure = target.configuration.schema.clone(required=False, name=path_tokens[-1] if path_tokens else None)
        target.schemas[path_tokens[-1] if path_tokens else None] = schema_structure
        for attribute, nested_dependency in target.dependencies.items():
            processing_queue.append((nested_dependency.unit, path_tokens + [attribute], nested_dependency))

