import onnxruntime

class ONNXInterface:
    def __init__(self, model_file, tokenizer=None):
        self.model_file = model_file
        self.tokenizer = tokenizer
        self.session = onnxruntime.InferenceSession(model_file)
        if tokenizer:
            if isinstance(tokenizer, (BertTokenizer, AutoTokenizer, BertTokenizerFast, XLNetTokenizer)):
                self.tokenizer = tokenizer
            else:
                raise ValueError("Unsupported tokenizer class provided")

    def preprocess_input(self, text_data):
        if self.tokenizer:
            encoded = self.tokenizer(text_data, return_tensors="pt", padding=True, truncation=True)
            input_ids = encoded["input_ids"]
            attention_mask = encoded["attention_mask"]
            session_inputs = {
                self.session.get_inputs()[0].name: input_ids.numpy(), 
                self.session.get_inputs()[1].name: attention_mask.numpy()
            }
        else:
            session_inputs = {"raw_text": text_data}

        outputs = self.session.run(None, session_inputs)
        return outputs

