# Shuffle a string or bytes using a given seed
import random
from typing import Union

def shuffle_text(data: Union[str, bytes], seed_value: int) -> Union[str, bytes]:
    random.seed(seed_value)
    if isinstance(data, str):
        char_list = list(data)
        random.shuffle(char_list)
        return ''.join(char_list)
    elif isinstance(data, bytes):
        byte_list = list(data)
        random.shuffle(byte_list)
        return bytes(byte_list)
    else:
        raise TypeError("Input must be either a string or bytes object")

