import asyncio
from typing import Any, Callable

class AsyncCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.storage = {}
        self.mutex = asyncio.Lock()

    async def fetch_or_store(self, identifier: str, coroutine_func: Callable[..., Any]) -> Any:
        async with self.mutex:
            if identifier in self.storage:
                return self.storage[identifier]

            computed_result = await coroutine_func()

            if len(self.storage) >= self.capacity:
                self.storage.popitem(last=False)  # Evict the oldest entry when capacity exceeded

            self.storage[identifier] = computed_result
            return computed_result

    async def retrieve(self, key: str) -> Any:
        async with self.mutex:
            return self.storage.get(key)

# Custom logging implementation with configurable verbosity
import logging

class LoggerHandler:
    def __init__(self, severity_threshold):
        self.severity_threshold = severity_threshold

    def debug_msg(self, text):
        if self.severity_threshold <= 0:
            print(f"DEBUG: {text}")

    def info_msg(self, text):
        if self.severity_threshold <= 1:
            print(f"INFO: {text}")

    def warn_msg(self, text):
        if self.severity_threshold <= 2:
            print(f"WARNING: {text}")

    def err_msg(self, text):
        if self.severity_threshold <= 3:
            print(f"ERROR: {text}")

    def crit_msg(self, text):
        if self.severity_threshold <= 4:
            print(f"CRITICAL: {text}")

    def update_level(self, new_severity):
        self.severity_threshold = new_severity

