# Define compression format enumeration
from enum import Enum

class CompressionType(Enum):
    gzip = "gzip"
    bzip2 = "bzip2"
    xz = "xz"
    uncompressed = "none"

    @property
    def descriptive_name(self) -> str:
        """
        Provides an extended name for the compression format.
        Examples include "gzip", "bzip2", "xz", and "none".
        """
        return {CompressionType.gzip: "gzip", CompressionType.bzip2: "bzip2"}.get(self, self.name)

    @property
    def has_compression(self) -> bool:
        """
        Indicates whether this format involves compression.
        Returns True for compressed formats, False otherwise.
        """
        return self in {CompressionType.gzip, CompressionType.bzip2, CompressionType.xz}

