def check_port_status(target_ip, target_port):
    try:
        # Validate and convert port number
        target_port = int(target_port)
        if target_port < 1 or target_port > 65535:
            print("Invalid port number")
            return
    except ValueError:
        print("Invalid port number")
        return

    try:
        # Validate IP address format
        socket.inet_aton(target_ip)
    except socket.error:
        print("Invalid IP address")
        return

    # Create socket connection attempt
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(3)

    try:
        # Attempt to connect to the target
        sock.connect((target_ip, target_port))
        print(f"Port {target_port} is open")
    except socket.timeout:
        print(f"Connection to port {target_port} timed out")
    except ConnectionRefusedError:
        print(f"Port {target_port} is closed")
    except Exception as err:
        print("Connection error: " + str(err))
    finally:
        # Ensure socket is always closed
        sock.close()

# Main execution block
if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python port_scanner.py [IP_address] [port_number]")
    else:
        ip_addr = sys.argv[1]
        port_num = sys.argv[2]
        check_port_status(ip_addr, port_num)

