logger = logging.getLogger(__name__)

@dataclass
class DownloadConfig:
    datasets: List[str]
    target_dir: str

class MedicalDatasetDownloader:
    def fetch_datasets(self, config: DownloadConfig):
        try:
            for dataset_name in config.datasets:
                if dataset_name == 'ISIC':
                    metadata_downloader = IsicMetadataDownloader()
                    image_downloader = IsicImageDownloader()
                    metadata_downloader.download_metadata(config.target_dir)
                    image_downloader.download_images(config.target_dir)
                elif dataset_name == 'PH2':
                    ph2_downloader = Ph2Downloader()
                    ph2_downloader.download_dataset(config.target_dir)
                elif dataset_name == 'PadUfes20':
                    pad_ufes_20_downloader = PadUfes20Downloader()
                    pad_ufes_20_downloader.download_dataset(config.target_dir)
                elif dataset_name == 'Mednode':
                    mednode_downloader = MednodeDownloader()
                    mednode_downloader.download_dataset(config.target_dir)
                else:
                    logger.warning(f"Unsupported dataset: '{dataset_name}'")
        except Exception as error:
            logger.error(f"Download process failed: {error}")

# Import required modules for AWS DynamoDB interaction
import os
import boto3
from boto3.dynamodb.conditions import Key

class ProjectDataFetcher:
    def __init__(self, project_table_name=None):
        # Initialize DynamoDB resource and table reference
        self.dynamodb_resource = boto3.resource('dynamodb')
        if project_table_name is None:
            project_table_name = os.environ['PROJECT_TABLE']
        self.project_table = self.dynamodb_resource.Table(project_table_name)
        self.data_store = {}  # Initialize storage for retrieved data

    def fetch_project_records(self, project_identifier):
        # Query DynamoDB table for project data by projectId
        query_response = self.project_table.query(
            KeyConditionExpression=Key('projectId').eq(project_identifier),
            Select='ALL_ATTRIBUTES'
        )

        # Process query results and store in data_store
        if 'Items' in query_response and query_response['Items']:
            self.data_store = query_response['Items'][0]
        else:
            self.data_store = {}  # Store empty dict when no matching items found

