class BaseJobStorage(metaclass=ABCMeta):
    """ 
    Defines the interface for physical storage handling jobs and associated files in a workflow system.
    """
    def __init__(self, settings=None):
        """
        Sets up the job storage with an optional configuration object.
        """
        self.settings = settings

    @abstractmethod
    def save_job(self, job_instance):
        """
        Abstract method to persist a job into the storage layer.
        """
        pass

    @abstractmethod
    def load_job(self, job_identifier):
        """
        Abstract method to fetch a job from storage using its unique identifier.
        """
        pass

    @abstractmethod
    def save_artifact(self, artifact):
        """
        Abstract method to store a file or data artifact in the storage system.
        """
        pass

    @abstractmethod
    def load_artifact(self, artifact_id):
        """
        Abstract method to retrieve a stored artifact by its identifier.
        """
        pass

