# Function to move a file from source to destination
import shutil
from pathlib import Path

def transfer_file(src, dest):
    try:
        # Ensure the destination directory exists
        dest_dir = Path(dest).parent
        dest_dir.mkdir(parents=True, exist_ok=True)
        shutil.move(src, dest)
        return True
    except Exception as error:
        return str(error)

# Ansible module to manage Foreman locations
from ansible.module_utils.basic import AnsibleModule
import requests

def main():
    # Define module arguments
    module = AnsibleModule(
        argument_spec=dict(
            location_name=dict(type='str', required=True),
            extra_attrs=dict(type='dict', required=False, default={}),
            desired_state=dict(type='str', required=False, default='present', choices=['present', 'absent'])
        )
    )

    # Configuration for Foreman API
    api_endpoint = 'https://foreman.example.com/api/v2/locations'
    request_headers = {'Content-Type': 'application/json', 'Accept': 'application/json'}
    credentials = ('username', 'password')  # Replace with actual Foreman credentials

    # Extract parameters from module
    location_name = module.params['location_name']
    additional_attributes = module.params['extra_attrs']
    target_state = module.params['desired_state']

    if target_state == 'present':
        # Create or update location
        payload_data = {'name': location_name, **additional_attributes}
        api_response = requests.post(api_endpoint, json=payload_data, auth=credentials, headers=request_headers)

    elif target_state == 'absent':
        # Delete location if it exists
        loc_id = fetch_location_id(location_name, credentials, request_headers)
        if loc_id is not None:
            delete_endpoint = f'{api_endpoint}/{loc_id}'
            api_response = requests.delete(delete_endpoint, auth=credentials, headers=request_headers)
        else:
            module.exit_json(changed=False, msg=f"Location '{location_name}' does not exist, no changes needed.")

    # Handle response based on status code
    if api_response.status_code in [201, 200]:
        module.exit_json(changed=True, msg=f"Location '{location_name}' {target_state}d successfully.")
    else:
        module.fail_json(msg=f"Operation failed for location '{location_name}'. Details: {api_response.text}")

def fetch_location_id(name, auth, headers):
    base_url = 'https://foreman.example.com/api/v2/locations'
    response = requests.get(base_url, auth=auth, headers=headers)
    location_list = response.json()['results']
    for item in location_list:
        if item['name'] == name:
            return item['id']
    return None

if __name__ == '__main__':
    main()

# Process module data with validation and return structured output
def handle_module_info(module_yaml, mod_name, stream_id, ver_num, ctx_val, arch_type, short_desc, full_desc, mod_lics, cont_lics, rpm_list):
    # Validate input parameters
    if not isinstance(module_yaml, str) or not module_yaml:
        raise ValueError("module_yaml must be a non-empty string")
    if not isinstance(mod_name, str) or not mod_name:
        raise ValueError("mod_name must be a non-empty string")
    if not isinstance(stream_id, str) or not stream_id:
        raise ValueError("stream_id must be a non-empty string")
    if not isinstance(ver_num, int) or ver_num < 0:
        raise ValueError("ver_num must be a non-negative integer")
    if not isinstance(ctx_val, str):
        raise ValueError("ctx_val must be a string")
    if not isinstance(arch_type, str):
        raise ValueError("arch_type must be a string")
    if not isinstance(short_desc, str) or not short_desc:
        raise ValueError("short_desc must be a non-empty string")
    if not isinstance(full_desc, str) or not full_desc:
        raise ValueError("full_desc must be a non-empty string")
    if not isinstance(mod_lics, list) or not all(isinstance(lic, str) for lic in mod_lics):
        raise ValueError("mod_lics must be a list of strings")
    if not isinstance(cont_lics, list) or not all(isinstance(lic, str) for lic in cont_lics):
        raise ValueError("cont_lics must be a list of strings")
    if not isinstance(rpm_list, list) or not all(isinstance(pkg, str) for pkg in rpm_list):
        raise ValueError("rpm_list must be a list of strings")

    # Build and return the processed information
    formatted_result = {
