        "module_licenses": mod_lics,
        "content_licenses": cont_lics,
        "rpms_nevras": rpm_list
    }
    return formatted_result

# Calculate and format the time difference between two timestamps
from datetime import datetime, timedelta

def calculate_elapsed_time(start_timestamp, end_timestamp):
    elapsed_duration = end_timestamp - start_timestamp
    if elapsed_duration.total_seconds() < 10:
        return 'just now'
    else:
        years = elapsed_duration.days // 365
        remaining_days = elapsed_duration.days % 365
        hours, seconds_remainder = divmod(elapsed_duration.seconds, 3600)
        minutes, seconds = divmod(seconds_remainder, 60)
        duration_components = []
        if years:
            duration_components.append(f'{years} year{"s" if years > 1 else ""}')
        if remaining_days:
            duration_components.append(f'{remaining_days} day{"s" if remaining_days > 1 else ""}')
        if hours:
            duration_components.append(f'{hours} hour{"s" if hours > 1 else ""}')
        if minutes:
            duration_components.append(f'{minutes} minute{"s" if minutes > 1 else ""}')
        if seconds:
            duration_components.append(f'{seconds} second{"s" if seconds > 1 else ""}')
        formatted_duration = ', '.join(duration_components)
        return formatted_duration

