# Modified version of the original code with Type I clone transformations
import os
import fsspec

class FileStorageHandler:
    def __init__(self, root_directory):
        self.root_directory = root_directory

    def save_content(self, relative_path, data):
        absolute_path = os.path.join(self.root_directory, relative_path)
        with open(absolute_path, "w") as output_file:
            output_file.write(data)

    def load_content(self, relative_path):
        absolute_path = os.path.join(self.root_directory, relative_path)
        with open(absolute_path, "r") as input_file:
            return input_file.read()

    def check_existence(self, relative_path):
        absolute_path = os.path.join(self.root_directory, relative_path)
        return os.path.exists(absolute_path)

    @staticmethod
    def are_identical_handlers(handler1, handler2):
        return handler1 == handler2

def validate_file_storage_handler(tmpdir):
    file_storage_handler = FileStorageHandler(tmpdir)
    file_storage_handler.save_content("subdir/datafile", "sample_data")

    assert file_storage_handler.check_existence("missingfile") == False
    assert file_storage_handler.load_content("subdir/datafile") == "sample_data"

    mapper = fsspec.get_mapper("file://" + tmpdir)
    assert "missingfile" not in mapper
    assert mapper["subdir/datafile"] == b"sample_data"

    fs_backend = fsspec.filesystem("file")
    mapper_b = fs_backend.get_mapper(tmpdir)
    mapper_c = fs_backend.get_mapper("file://" + tmpdir)

    assert FileStorageHandler.are_identical_handlers(mapper, mapper_b) == True
    assert FileStorageHandler.are_identical_handlers(mapper, mapper_c) == True

