# Convert milliseconds timestamp to datetime object
def milliseconds_to_datetime(timestamp_ms):
    return datetime.utcfromtimestamp(timestamp_ms / 1000.0)

# Retrieve log streams sorted by last event time
def fetch_log_streams_with_last_event(logs_client, group_name):
    streams_with_events = []
    parameters = {
        "logGroupName": group_name,
        "orderBy": "LastEventTime",
        "descending": True
    }

    # Use paginator to handle large result sets
    pager = logs_client.get_paginator("describe_log_streams")
    for page in pager.paginate(**parameters):
        for stream in page["logStreams"]:
            stream_name = stream["logStreamName"]
            # Get last event timestamp or fall back to creation time
            event_time_ms = stream.get("lastEventTimestamp", stream.get("creationTime"))
            last_event = milliseconds_to_datetime(event_time_ms)
            streams_with_events.append({
                "logStreamName": stream_name, 
                "lastEventTimestamp": last_event
            })
    return streams_with_events

