# Connection request class for KNX communication
class ConnectionRequest:
    REQUEST_INFO_SIZE = 4  # Size of Request Information (RI) in bytes
    def __init__(self, control_channel, data_channel, req_type, flag_values):
        self.control_channel = control_channel
        self.data_channel = data_channel
        self.req_type = req_type
        self.flag_values = flag_values

    def to_knx_bytes(self):
        def ri_to_knx():
            return bytes(
                (
                    ConnectionRequest.REQUEST_INFO_SIZE,
                    self.req_type.value,
                    self.flag_values,
                    0x00,  # Reserved byte
                )
            )
        return (
            self.control_channel.to_knx() + 
            self.data_channel.to_knx() + 
            ri_to_knx()
        )

    def __str__(self) -> str:
        return f"ConnectionRequest(control_channel={self.control_channel}, data_channel={self.data_channel}, req_type={self.req_type}, flag_values={self.flag_values})"

# Generate a Markov chain and test its functionality
import random

class MarkovProcess:
    def __init__(self, state_list):
        self.state_list = list(set(state_list))
        self.transition_probs = {}
        self.create_transition_table(state_list)

    def create_transition_table(self, state_list):
        for current_state in self.state_list:
            possible_next = [state_list[i+1] for i in range(len(state_list)-1) if state_list[i] == current_state]
            freq_dict = {s: possible_next.count(s) / len(possible_next) for s in set(possible_next)}
            self.transition_probs[current_state] = [(nxt, p) for nxt, p in freq_dict.items()]

    def get_next_state(self, current):
        candidates, weights = zip(*self.transition_probs[current])
        return random.choices(candidates, weights=weights)[0]

    def generate_path(self, steps, initial):
        path = [initial]
        present = initial
        for _ in range(steps - 1):
            future = self.get_next_state(present)
            path.append(future)
            present = future
        return path

def verify_model():
    model = MarkovProcess([1, 2, 3, 1, 2])
    assert len(model.state_list) == 3
    assert isinstance(model.transition_probs, dict)
    assert isinstance(model.transition_probs[1], list)
    assert model.get_next_state(1) == 2
    assert len(model.generate_path(10, 1)) == 10

verify_model()

