# Traffic monitoring system to detect high traffic conditions
from collections import deque

class NetworkTrafficMonitor:
    def __init__(self, buffer_size, warning_limit):
        self.buffer = deque(maxlen=buffer_size)
        self.current_count = 0
        self.warning_threshold = warning_limit
        self.warning_active = False

    def record_traffic(self, count):
        self.current_count += count

    def average_traffic_rate(self):
        self.buffer.append(self.current_count)
        average = sum(self.buffer) / len(self.buffer) if self.buffer else 0

        if not self.warning_active and average > self.warning_threshold:
            self.warning_active = True
            print(f"Warning: Elevated traffic detected - rate={average}, limit={self.warning_threshold}")
        elif self.warning_active and average <= self.warning_threshold:
            self.warning_active = False
            print("Warning cleared - traffic levels normalized")

        self.current_count = 0

