# Import necessary modules for PyTorch model definition
import torch
import torch.nn as nn

class EntityEmbedding(nn.Module):
    def __init__(self, hidden_size, gamma_val, epsilon_val, use_double_embedding):
        super(EntityEmbedding, self).__init__()
        self.gamma = gamma_val
        self.epsilon = epsilon_val
        self.embedding_range = nn.Parameter(
            torch.Tensor([(self.gamma.item() + self.epsilon) / hidden_size]),
            requires_grad=False
        )
        self.entity_dim = hidden_size * 2 if use_double_embedding else hidden_size

    def update_embedding_range(self, gamma_val, epsilon_val, hidden_size):
        self.embedding_range = nn.Parameter(
            torch.Tensor([(gamma_val + epsilon_val) / hidden_size]),
            requires_grad=False
        )

    def set_entity_dimension(self, use_double_embedding):
        self.entity_dim = hidden_size * 2 if use_double_embedding else hidden_size

# Extract license details from a given text 
def parse_license_data(license_content: str) -> dict:
    data = {"license_category": "", "allowed_actions": [], "restricted_conditions": []}
    lines = license_content.split('\n')
    for line in lines:
        if line.strip() and not line.strip().startswith('#'):
            data["license_category"] = line.strip()
            break
    collect_allowed = False
    collect_restricted = False
    for line in lines:
        if "WARRANTIES OR CONDITIONS OF ANY" in line:
            collect_allowed = True
            continue
        if "restrictions" in line.lower():
            collect_allowed = False
            collect_restricted = True
            continue
        if collect_allowed and line.strip() and not line.strip().startswith('#'):
            data["allowed_actions"].append(line.strip())
        if collect_restricted and line.strip() and not line.strip().startswith('#'):
            data["restricted_conditions"].append(line.strip())
    return data

