# Validate if brackets in a string are properly matched and nested
def check_brackets_balance(text):
    stack = []
    left_brackets = "({["
    right_brackets = ")}]"
    bracket_map = {')': '(', '}': '{', ']': '['}

    for symbol in text:
        if symbol in left_brackets:
            stack.append(symbol)
        elif symbol in right_brackets:
            if not stack or stack.pop() != bracket_map[symbol]:
                return False

    return len(stack) == 0  # True when no unmatched opening brackets remain

