# Compute SHA-256 hashes for files listed in a JSON configuration
import json
from hashlib import sha256
from pathlib import Path

def compute_file_checksum(filepath):
    try:
        with open(filepath, 'rb') as f:
            data = f.read()
            checksum = sha256(data).hexdigest()
            return checksum
    except FileNotFoundError:
        return None
    except Exception as err:
        print(f"Exception while hashing {filepath}: {err}")
        return None

def execute():
    config_path = 'input_files.json'
    result_path = 'output_hashes.json'

    # Load input file list
    try:
        with open(config_path, 'r') as file:
            file_list = json.load(file)
    except FileNotFoundError:
        print(f"Configuration file '{config_path}' is missing.")
        return
    except json.JSONDecodeError as decode_err:
        print(f"Invalid JSON in '{config_path}': {decode_err}")
        return

    # Process each file and collect hashes
    hash_map = {}
    for path in file_list:
        checksum = compute_file_checksum(path)
        if checksum:
            hash_map[path] = checksum

    # Save results to output file
    try:
        with open(result_path, 'w') as out_file:
            json.dump(hash_map, out_file, indent=4)
        print(f"Hash values saved to '{result_path}'.")
    except IOError as io_err:
        print(f"Failed to write output to '{result_path}': {io_err}")

if __name__ == "__main__":
    execute()

