# XOR-based file encryption/decryption tool
import sys

def transform_file(input_path, output_path, cipher_key):
    try:
        with open(input_path, 'rb') as in_file, open(output_path, 'wb') as out_file:
            key_data = cipher_key.encode('utf-8')
            key_size = len(key_data)
            position = 0
            while True:
                chunk = in_file.read(1)
                if not chunk:
                    break
                transformed_byte = bytes([chunk[0] ^ key_data[position]])
                out_file.write(transformed_byte)
                position = (position + 1) % key_size
    except FileNotFoundError:
        print("Input file missing!")
        sys.exit(2)

def revert_file(input_path, output_path, cipher_key):
    transform_file(input_path, output_path, cipher_key)  # Reversal uses identical logic

def main():
    if len(sys.argv) < 4:
        print("Syntax: cryptolocker.py <INPUT_FILE> <OUTPUT_FILE> <PASSWORD>")
        sys.exit(2)
    input_path = sys.argv[1]
    output_path = sys.argv[2]
    cipher_key = sys.argv[3]
    if len(cipher_key) < 7:
        print("Password must be at least 7 characters!")
        sys.exit(2)
    if len(cipher_key) > 11:
        print("Password exceeds maximum length!")
        sys.exit(2)
    transform_file(input_path, output_path, cipher_key)

if __name__ == "__main__":
    main()

