# Group consecutive identical elements together
from typing import List, Any, Tuple

def group_consecutive(items: List[Any]) -> List[Tuple[Any, List[Any]]]:
    output = []
    current_key = None
    current_group = []

    for element in items:
        if element != current_key:
            if current_key is not None:
                output.append((current_key, current_group))
            current_key = element
            current_group = [element]
        else:
            current_group.append(element)

    if current_key is not None:
        output.append((current_key, current_group))

    return output

# Filter out paths that match any exclusion pattern
def filter_paths(paths, exclusions):
    kept_paths = []
    for item in paths:
        skip = False
        for pattern in exclusions:
            if item.startswith(pattern.rstrip("/")):
                skip = True
                break
        if not skip:
            kept_paths.append(item)
    return kept_paths

