def process_request_error_gen(handler_name: str):
    def decorator(fn: TFunc) -> TFunc:
        @wraps(fn)
        def wrapper(*params: Any, **options: Any) -> Any:
            try:
                yield from fn(*params, **options)
            except RpcException as exc:
                if issubclass(type(exc), ClientCall):
                    metadata = extract_metadata_from_exception(exc)
                    # Perform specific action with metadata
                    print(f"Error handler '{handler_name}' called with metadata: {metadata}")
        return wrapper
    return decorator

