# QR payload encoding/decoding utilities for transport
from __future__ import annotations
import base64
import binascii
from typing import Final, Literal

# Supported encoding formats for QR payloads
QrPayloadFormat = Literal["raw", "base64"]
QR_FORMAT_RAW: Final[QrPayloadFormat] = "raw"
QR_FORMAT_BASE64: Final[QrPayloadFormat] = "base64"

def encode_for_qr(
    data: bytes,
    *,
    format_type: QrPayloadFormat = QR_FORMAT_BASE64,
) -> bytes | str:
    """Encode frame bytes for QR code transmission."""
    if format_type == QR_FORMAT_RAW:
        return data
    if format_type != QR_FORMAT_BASE64:
        raise ValueError(f"unsupported QR format: {format_type}")
    encoded = base64.b64encode(data).decode("ascii")
    return encoded.rstrip("=")

def decode_from_qr(
    payload: bytes | str,
    *,
    format_type: QrPayloadFormat = QR_FORMAT_BASE64,
) -> bytes:
    """Decode frame bytes from QR code payload."""
    if format_type == QR_FORMAT_RAW:
        if isinstance(payload, bytes):
            return payload
        raise ValueError("invalid raw QR payload")
    if format_type != QR_FORMAT_BASE64:
        raise ValueError(f"unsupported QR format: {format_type}")
    return _decode_base64_qr_data(payload)

def _decode_base64_qr_data(payload: bytes | str) -> bytes:
    """Decode unpadded base64 QR payload text."""
    if isinstance(payload, bytes):
        try:
            text = payload.decode("ascii")
        except UnicodeDecodeError as exc:
            raise ValueError("invalid base64 QR payload") from exc
    else:
        text = payload
    cleaned = "".join(text.split())
    if "=" in cleaned:
        raise ValueError("invalid base64 QR payload")
    try:
        decoded = base64.b64decode(_add_padding_to_base64(cleaned), validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("invalid base64 QR payload") from exc
    canonical = base64.b64encode(decoded).decode("ascii").rstrip("=")
    if canonical != cleaned:
        raise ValueError("invalid base64 QR payload")
    return decoded

def _add_padding_to_base64(text: str) -> str:
    """Add required padding to unpadded base64 text."""
    padding = (-len(text)) % 4
    return text + ("=" * padding)

__all__ = [
    "QR_FORMAT_BASE64",
    "QR_FORMAT_RAW",
    "QrPayloadFormat",
    "decode_from_qr",
    "encode_for_qr",
]

# Compare multiple NumPy data files for equality
import argparse

try:
    import argcomplete
except ImportError:
    argcomplete = None

import numpy as np

def parse_args():
    parser = argparse.ArgumentParser(description="Check if all provided NumPy files contain identical data")
    parser.add_argument("data_files", metavar="file", nargs="+", help="Path to NumPy data files")

    if argcomplete:
        argcomplete.autocomplete(parser)

    return parser.parse_args()

def main():
    arguments = parse_args()

    # Need at least two files to compare
    if len(arguments.data_files) <= 1:
        return 0

    # Load the first file as reference
    reference_data = np.load(arguments.data_files[0])

    # Compare with remaining files
    for filepath in arguments.data_files[1:]:
        current_data = np.load(filepath)
        if not np.array_equal(reference_data, current_data):
            return 1

    return 0

if __name__ == "__main__":
    exit(main())

