# GPU device detection and diagnostics module
import logging
import os
import torch

logger = logging.getLogger("gpu-service")

def detect_device() -> torch.device:
    """Automatically detect available GPU or fall back to CPU.
    Supports CUDA (NVIDIA) and ROCm (AMD) backends."""

    env_device = os.environ.get("TORCH_DEVICE")
    if env_device:
        logger.info(f"Using device override: TORCH_DEVICE={env_device}")
        return torch.device(env_device)

    if torch.cuda.is_available():
        gpu_name = torch.cuda.get_device_name(0)
        logger.info(f"GPU found: {gpu_name}")
        return torch.device("cuda")

    logger.warning("No GPU detected - switching to CPU (performance may be reduced)")
    return torch.device("cpu")


def collect_device_stats(device: torch.device) -> dict:
    """Gather and return diagnostic information about the device."""
    stats = {
        "device": str(device),
        "pytorch_version": torch.__version__,
        "cuda_version": torch.version.cuda if torch.cuda.is_available() else None,
    }

    if device.type == "cuda":
        stats["device_name"] = torch.cuda.get_device_name(0)
        total_mem = torch.cuda.get_device_properties(0).total_memory
        stats["vram_total_mb"] = round(total_mem / 1024 / 1024)
        stats["vram_used_mb"] = round(torch.cuda.memory_allocated(0) / 1024 / 1024)
    else:
        stats["device_name"] = "cpu"

    return stats

