# Custom logger for model checkpoints during training
import os, torch
from accelerate import Accelerator

class CheckpointHandler:
    def __init__(self, save_directory, prefix_to_remove=None, state_transform=lambda x: x):
        self.save_directory = save_directory
        self.prefix_to_remove = prefix_to_remove
        self.state_transform = state_transform
        self.step_count = 0

    def on_batch_end(self, accelerator: Accelerator, model: torch.nn.Module, checkpoint_interval=None):
        self.step_count += 1
        if checkpoint_interval is not None and self.step_count % checkpoint_interval == 0:
            self.export_model(accelerator, model, f"step-{self.step_count}.safetensors")

    def on_epoch_end(self, accelerator: Accelerator, model: torch.nn.Module, current_epoch):
        accelerator.wait_for_everyone()
        if accelerator.is_main_process:
            model_state = accelerator.get_state_dict(model)
            model_state = accelerator.unwrap_model(model).export_trainable_state_dict(
                model_state, remove_prefix=self.prefix_to_remove
            )
            model_state = self.state_transform(model_state)
            os.makedirs(self.save_directory, exist_ok=True)
            file_path = os.path.join(self.save_directory, f"epoch-{current_epoch}.safetensors")
            accelerator.save(model_state, file_path, safe_serialization=True)

    def on_training_finish(self, accelerator: Accelerator, model: torch.nn.Module, checkpoint_interval=None):
        if checkpoint_interval is not None and self.step_count % checkpoint_interval != 0:
            self.export_model(accelerator, model, f"step-{self.step_count}.safetensors")

    def export_model(self, accelerator: Accelerator, model: torch.nn.Module, filename):
        accelerator.wait_for_everyone()
        if accelerator.is_main_process:
            model_state = accelerator.get_state_dict(model)
            model_state = accelerator.unwrap_model(model).export_trainable_state_dict(
                model_state, remove_prefix=self.prefix_to_remove
            )
            model_state = self.state_transform(model_state)
            os.makedirs(self.save_directory, exist_ok=True)
            full_path = os.path.join(self.save_directory, filename)
            accelerator.save(model_state, full_path, safe_serialization=True)

import torch
import torch.nn as nn
from torch.distributed.tensor import (
    DeviceMesh,
    DTensor,
    Replicate,
    Shard,
    distribute_tensor,
)
from torch.distributed.tensor.parallel import (
    ColwiseParallel,
    RowwiseParallel,
    SequenceParallel,
)

def _distribute_parameter(_module, param_name, device_mesh, source_rank, placements):
    original_param = getattr(_module, param_name)
    distributed_param = nn.Parameter(
        distribute_tensor(original_param, device_mesh, placements, src_data_rank=source_rank),
        requires_grad=original_param.requires_grad,
    )
    assert distributed_param.requires_grad == original_param.requires_grad
    _module.register_parameter(param_name, distributed_param)

class ColwiseParallelLora(ColwiseParallel):
    def _partition_linear_fn(self, name, module, device_mesh):
        # colwise shard weight/bias to Shard(0), weight be Shard(0)
        # means Colwise as Linear is input * weight^T + bias, where
        # weight would become Shard(1)
        def _extract_module_and_subname(module, full_name):
            if full_name.endswith("lora_A.weight"):
                assert hasattr(module, "lora_A"), f"lora_A not found in {module}"
                return module.lora_A, "weight"
            elif full_name.endswith("lora_B.weight"):
                assert hasattr(module, "lora_B"), f"lora_B not found in {module}"
                return module.lora_B, "weight"
            else:
                return module, full_name

        for full_name, param in module.named_parameters():
            target_module, target_name = _extract_module_and_subname(module, full_name)
            _distribute_parameter(target_module, target_name, device_mesh, self.src_data_rank, [Shard(0)])

        # Register forward hook on lora_A to all-gather its low rank output
        def lora_a_output_hook(module, input, output):
            if isinstance(output, DTensor):
                if any(isinstance(p, Shard) for p in output.placements):
                    output = output.redistribute(device_mesh=output.device_mesh, placements=[Replicate()])
            return output

        if hasattr(module, "lora_A"):
            module.lora_A.register_forward_hook(lora_a_output_hook)

    def _partition_embedding_fn(self, name, module, device_mesh):
        # colwise shard embedding.weight is straight forward as Shard(1)
        for param_name, param in module.named_parameters():
            _distribute_parameter(module, param_name, device_mesh, self.src_data_rank, [Shard(1)])

class RowwiseParallelLora(RowwiseParallel):
    def _partition_linear_fn(self, name, module, device_mesh):
        # Rowwise shard weight to Shard(1), bias to Replicate(), weight be Shard(1)
        # means Rowwise as nn.Linear is input * weight^T + bias, where
        # weight would become Shard(0)
        _distribute_parameter(module, "weight", device_mesh, self.src_data_rank, [Shard(1)])
        if getattr(module, "bias", None) is not None:
            _distribute_parameter(module, "bias", device_mesh, self.src_data_rank, [Replicate()])

        if hasattr(module, "lora_A"):
            _distribute_parameter(module.lora_A, "weight", device_mesh, self.src_data_rank, [Shard(1)])
            _distribute_parameter(module.lora_B, "weight", device_mesh, self.src_data_rank, [Shard(1)])

        if hasattr(module, "lora_magnitude"):
            _distribute_parameter(module, "lora_magnitude", device_mesh, self.src_data_rank, [Replicate()])

    def _partition_embedding_fn(self, name, module, device_mesh):
        # rowwise shard embedding.weight is Shard(0)
        for param_name, param in module.named_parameters():
            _distribute_parameter(module, param_name, device_mesh, self.src_data_rank, [Shard(0)])

class SequenceParallelLora(SequenceParallel):
    def _replicate_module_fn(self, name: str, module: nn.Module, device_mesh: DeviceMesh):
        for param_key, param in module.named_parameters():
            # simple replication with fixed ones_ init from LayerNorm/RMSNorm, which allow
            # us to simply just use from_local
            replicated_param = torch.nn.Parameter(
                DTensor.from_local(param, device_mesh, [Replicate()], run_check=False),
                requires_grad=param.requires_grad,
            )
            module.register_parameter(param_key, replicated_param)

def convert_to_lora(plan):
    CLASS_MAPPING = {
        ColwiseParallel: ColwiseParallelLora,
        RowwiseParallel: RowwiseParallelLora,
        SequenceParallel: SequenceParallelLora,
    }
    plan.__class__ = CLASS_MAPPING.get(type(plan), plan.__class__)
    return plan

