    sys.exit(1)


def generate_summary(url: str):
    request_body = {"input": url}
    request_headers = {"Content-Type": "application/json", "X-API-Key": API_TOKEN}
    response = requests.post(API_ENDPOINT, headers=request_headers, json=request_body, timeout=30)
    try:
        response.raise_for_status()
        return response.json()
    except requests.HTTPError:
        try:
            return {"status_code": response.status_code, "error": response.json()}
        except Exception:
            return {"status_code": response.status_code, "text": response.text}
    except Exception:
        try:
            return response.json()
        except Exception:
            return {"status_code": getattr(response, 'status_code', None), "text": getattr(response, 'text', str(response))}


if __name__ == '__main__':
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Missing URL argument"}))
