    # basic URL validation
    parsed_url = urlparse(target_url)
    if parsed_url.scheme not in ("http", "https"):
        print(json.dumps({"error": "Invalid URL scheme; must start with http:// or https://", "url": target_url}))
        sys.exit(2)
    summary_result = generate_summary(target_url)
    # append a log entry: timestamp, sent payload and response payload (ignore errors)
    try:
        request_payload = {"input": target_url}
        with open(LOG_FILE_PATH, "a", encoding="utf-8") as log_file:
            log_file.write(json.dumps({
                "timestamp": datetime.utcnow().isoformat() + "Z",
                "sent": request_payload,
                "response": summary_result
            }, ensure_ascii=False) + "\n")
    except Exception:
        pass
    print(json.dumps(summary_result, ensure_ascii=False, indent=2))

