# Primus unit test runner script
import argparse
import os
import subprocess
import sys

# Map of unit test paths to number of processes per node
DISTRIBUTED_TESTS = {}
TESTS_PASSED = True
SKIP_TESTS = []

def argument_parser():
    parser = argparse.ArgumentParser(description="Execute Primus unit tests")
    parser.add_argument(
        "--jax",
        action="store_true",
        help="Run only JAX unit test: tests/trainer/test_maxtext_trainer.py",
    )
    return parser.parse_args()

def collect_unit_tests(jax_only=False):
    """
    When jax_only = True:
        only return tests/trainer/test_maxtext_trainer.py
    Otherwise:
        return all tests except test_maxtext_trainer.py
    """
    global DISTRIBUTED_TESTS, SKIP_TESTS
    test_dir = "./tests"
    selected_tests = {}

    if jax_only:
        jax_test = "trainer/test_maxtext_trainer.py"
        jax_test_full = os.path.join(test_dir, jax_test)
        return {jax_test_full: 1}

    SKIP_TESTS = [
        "trainer/test_maxtext_trainer.py",
    ]

    for root, directories, filenames in os.walk(test_dir):
        for filename in filenames:
            if not filename.endswith(".py") or not filename.startswith("test_"):
                continue

            # Compute relative path from tests/
            rel_path = os.path.relpath(os.path.join(root, filename), start=test_dir)
            if rel_path in SKIP_TESTS:
                continue

            full_path = os.path.join(root, filename)
            if filename not in DISTRIBUTED_TESTS:
                selected_tests[full_path] = 1
            else:
                selected_tests[full_path] = DISTRIBUTED_TESTS[filename]

    return selected_tests

def run_test(test_path, num_processes):
    global TESTS_PASSED
    if num_processes == 1:
        command = f"pytest --maxfail=1 {test_path} -s"
    else:
        command = f"torchrun --nnodes 1 --nproc-per-node {num_processes} {test_path}"

    process = subprocess.Popen(command, shell=True)
    process.wait()

    if process.returncode != 0:
        TESTS_PASSED = False

def main():
    options = argument_parser()
    test_list = collect_unit_tests(jax_only=options.jax)

    for test_path, processes in test_list.items():
        run_test(test_path, processes)

    if not TESTS_PASSED:
        print("Unit Tests failed! More details please check log.")
        sys.exit(1)
    else:
        print("Unit Tests pass!")

if __name__ == "__main__":
    main()

# Abstract base class for Conv2d weight management
from abc import ABCMeta, abstractmethod
import torch
from lightx2v.utils.registry_factory import CONV2D_WEIGHT_REGISTER
from lightx2v_platform.base.global_var import AI_DEVICE

class Conv2dWeightHandler(metaclass=ABCMeta):
    def __init__(self, weight_key, bias_key, stride_val, padding_val, dilation_val, groups_val):
        self.weight_key = weight_key
        self.bias_key = bias_key
        self.stride_val = stride_val
        self.padding_val = padding_val
        self.dilation_val = dilation_val
        self.groups_val = groups_val
        self.settings = {}

    @abstractmethod
    def acquire(self, weight_collection):
        pass

    @abstractmethod
    def execute(self, input_data):
        pass

    def configure(self, settings=None):
        if settings is not None:
            self.settings = settings

@CONV2D_WEIGHT_REGISTER("Standard")
class StandardConv2dWeight(Conv2dWeightHandler):
    def __init__(self, weight_key, bias_key, stride=1, padding=0, dilation=1, groups=1):
        super().__init__(weight_key, bias_key, stride, padding, dilation, groups)

    def acquire(self, weight_collection):
        self.weight_tensor = weight_collection[self.weight_key].to(AI_DEVICE)
        self.bias_tensor = weight_collection[self.bias_key].to(AI_DEVICE) if self.bias_key is not None else None

    def execute(self, input_data):
        output = torch.nn.functional.conv2d(input_data, 
                                           weight=self.weight_tensor, 
                                           bias=self.bias_tensor, 
                                           stride=self.stride_val, 
                                           padding=self.padding_val, 
                                           dilation=self.dilation_val, 
                                           groups=self.groups_val)
        return output

    def move_to_cpu(self, non_blocking=False):
        self.weight_tensor = self.weight_tensor.cpu(non_blocking=non_blocking)
        if self.bias_tensor is not None:
            self.bias_tensor = self.bias_tensor.cpu(non_blocking=non_blocking)

    def move_to_gpu(self, non_blocking=False):
        self.weight_tensor = self.weight_tensor.to(AI_DEVICE, non_blocking=non_blocking)
        if self.bias_tensor is not None:
            self.bias_tensor = self.bias_tensor.to(AI_DEVICE, non_blocking=non_blocking)

    def export_state(self, target_dict=None):
        if target_dict is None:
            target_dict = {}
        target_dict[self.weight_key] = self.weight_tensor.cpu().detach().clone()
        if self.bias_tensor is not None:
            target_dict[self.bias_key] = self.bias_tensor.cpu().detach().clone()
        return target_dict

