# Define data class for model metadata
from dataclasses import dataclass
from typing import Dict, List, Optional

@dataclass
class ModelInfo:
    """Stores information about a model including input specifications and type"""
    identifier: str
    input_dimensions: Dict[str, List[int]]
    input_types: Dict[str, str]
    architecture: Optional[str] = None  # e.g., "bert", "resnet", "gpt"
    vocabulary_length: Optional[int] = None  # Number of unique tokens in tokenizer
    hidden_dimension: Optional[
        int
    ] = None  # Dimensionality of the embedding layer (derived from weights)

    def __post_init__(self):
        """Perform validation checks on metadata"""
        if not self.input_dimensions:
            raise ValueError("input_dimensions cannot be empty")
        if not self.input_types:
            raise ValueError("input_types cannot be empty")
        # Verify that input dimensions and types share identical keys
        if set(self.input_dimensions.keys()) != set(self.input_types.keys()):
            raise ValueError("input_dimensions and input_types must have matching keys")

