# Slack integration utility module
import os
import requests
import json
import sys

class SlackConnector:
    def __init__(self):
        self.api_token = os.getenv("SLACK_BOT_TOKEN")
        self.api_base = "https://slack.com/api"

    def _execute_request(self, method, endpoint, payload=None, params=None):
        auth_headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json; charset=utf-8" if method == "POST" else None
        }

        # Clean up headers - remove Content-Type for GET requests
        if method == "GET":
            auth_headers.pop("Content-Type", None)

        url = f"{self.api_base}/{endpoint}"

        if method == "POST":
            response = requests.post(url, headers=auth_headers, json=payload)
        elif method == "GET":
            response = requests.get(url, headers=auth_headers, params=params)

        return response.json()

    def post_message(self, channel_id, text_content, parent_thread=None):
        message_payload = {"channel": channel_id, "text": text_content}
        if parent_thread:
            message_payload["thread_ts"] = parent_thread
        return self._execute_request("POST", "chat.postMessage", message_payload)

    def find_messages(self, search_term):
        query_params = {"query": search_term}
        auth_headers = {"Authorization": f"Bearer {self.api_token}"}
        response = requests.get(f"{self.api_base}/search.messages", headers=auth_headers, params=query_params)
        return response.json()

if __name__ == "__main__":
    import argparse

    connector = SlackConnector()

    cli_parser = argparse.ArgumentParser(description="Slack integration tool")
    cli_parser.add_argument("command", choices=["post", "find", "list"])
    cli_parser.add_argument("--channel")
    cli_parser.add_argument("--content")
    cli_parser.add_argument("--keyword")
    cli_args = cli_parser.parse_args()

    if cli_args.command == "list":
        result = connector._execute_request("POST", "conversations.list", {"types": "public_channel,private_channel"})
        print(json.dumps(result))
    elif cli_args.command == "post":
        result = connector.post_message(cli_args.channel, cli_args.content)
        print(json.dumps(result))
    elif cli_args.command == "find":
        result = connector.find_messages(cli_args.keyword)
        print(json.dumps(result))

# Replace emoji codes in a string with actual emoji characters
from typing import Callable, Match, Optional
import re
from ._emoji_codes import EMOJI

_ReStringMatch = Match[str]  # regex match object
_ReSubCallable = Callable[[_ReStringMatch], str]  # Callable invoked by re.sub
_EmojiSubMethod = Callable[[_ReSubCallable, str], str]  # Sub method of a compiled re

def _emoji_replace(
    text: str,
    default_variant: Optional[str] = None,
    _emoji_sub: _EmojiSubMethod = re.compile(r"(:(\S*?)(?:(?:\-)(emoji|text))?:)").sub,
) -> str:
    """Replace emoji code in text."""
    get_emoji = EMOJI.__getitem__
    variant_map = {"text": "\uFE0E", "emoji": "\uFE0F"}
    get_variant_code = variant_map.get
    default_variant_code = variant_map.get(default_variant, "") if default_variant else ""

    def perform_replacement(match: Match[str]) -> str:
        full_match, emoji_name, variant_type = match.groups()
        try:
            return get_emoji(emoji_name.lower()) + get_variant_code(
                variant_type, default_variant_code
            )
        except KeyError:
            return full_match

    return _emoji_sub(perform_replacement, text)

# Detect the platform (NPU, MLU, or fallback to meta_device)
import functools
import importlib
import inspect
import os
import pkgutil
from typing import Literal
import torch
from mojo_opset.utils.logging import get_logger

logger = get_logger(__name__)

@functools.lru_cache
def detect_accelerator() -> Literal["npu", "mlu", "meta_device"]:
    """
    Determine if the system uses NPU or MLU; default to meta_device if none found.
    """
    try:
        if torch.npu.is_available():
            logger.info("Ascend NPU detected")
            return "npu"
    except Exception as err:
        logger.debug(f"Failed to check NPU availability: {err}")

    try:
        if torch.mlu.is_available():
            logger.info("Cambricon MLU detected")
            return "mlu"
    except Exception as err:
        logger.debug(f"Failed to check MLU availability: {err}")

    logger.warning("No accelerator detected")
    return "meta_device"

def load_operators_by_platform():
    operator_registry = {}
    from mojo_opset.core.function import MojoFunction
    from mojo_opset.core.operator import MojoOperator

    current_platform = detect_accelerator()

    try:
        # Get caller's context for module discovery
        stack_info = inspect.stack()[1]
        calling_module = inspect.getmodule(stack_info[0])

        if not calling_module or not hasattr(calling_module, "__file__"):
            logger.error("Could not determine the caller's module file path. Cannot discover operators.")
            return {}

        base_dir = os.path.dirname(calling_module.__file__)
        parent_package = getattr(calling_module, "__package__", "")

        search_paths = ["operators", "functions"]
        for folder_name in search_paths:
            folder_path = os.path.join(base_dir, folder_name)
            full_package = f"{parent_package}.{folder_name}"

            for _, mod_name, _ in pkgutil.iter_modules([folder_path]):
                complete_mod_name = f"{full_package}.{mod_name}"
                loaded_module = importlib.import_module(complete_mod_name)

                for class_name, cls_obj in inspect.getmembers(loaded_module, inspect.isclass):
                    if (
                        (issubclass(cls_obj, MojoOperator) or issubclass(cls_obj, MojoFunction))
                        and cls_obj not in [MojoOperator, MojoFunction]
                        and cls_obj.__module__ == complete_mod_name
                        and current_platform in getattr(cls_obj, "supported_platforms_list", [])
                    ):
                        logger.debug(f"Found supported operator '{class_name}' in {complete_mod_name}")
                        operator_registry[class_name] = cls_obj

    except (ImportError, IndexError):
        import traceback
        logger.error(f"Failed to discover operators: {traceback.format_exc()}")
        return {}

    return operator_registry

# Calculate linguistic features from conversation turns
import regex as re
from typing import List, Dict, Iterable, Tuple
from .config import WINDOW_SIZE, WINDOW_STEP

def _load_list(filepath: str):
    with open(filepath, "r", encoding="utf-8") as file:
        return [line.strip() for line in file if line.strip()]

def compile_lexicons(base_dir: str) -> Dict[str, List[str]]:
    import os
    lexicon = {}
    filenames = [
        "hedges.txt","modals.txt","meta_markers.txt","backtracks.txt",
        "action_verbs.txt","verify_markers.txt","positive_words.txt","negative_words.txt"
    ]
    for fname in filenames:
        key_name = fname.split(".")[0]
        lexicon[key_name] = _load_list(os.path.join(base_dir, "resources", "lexicons", fname))
    return lexicon

def tokenize_simple(text: str) -> List[str]:
    return re.findall(r"\p{L}[\p{L}\p{N}'-]*", text.lower())

def count_occurrences(text: str, word_list: List[str]) -> int:
    t_lower = text.lower()
    total = 0
    for phrase in word_list:
        total += len(re.findall(re.escape(phrase), t_lower))
    return total

def sliding_window(sequence: List[Dict], window: int = WINDOW_SIZE, step: int = WINDOW_STEP):
    for idx in range(0, max(0, len(sequence)-window+1), step):
        yield idx, sequence[idx:idx+window]

def compute_features(turns: List[Dict], lex: Dict[str, List[str]]) -> List[Dict]:
    results = []
    for turn in turns:
        utterance = turn.get("text", "")
        tokens = tokenize_simple(utterance)
        token_count = max(1, len(tokens))

        feature_dict = {
            "hedges": count_occurrences(utterance, lex["hedges"]) / token_count,
            "modals": count_occurrences(utterance, lex["modals"]) / token_count,
            "meta": count_occurrences(utterance, lex["meta_markers"]) / token_count,
            "backtrack": count_occurrences(utterance, lex["backtracks"]) / token_count,
            "action": count_occurrences(utterance, lex["action_verbs"]) / token_count,
            "verify": count_occurrences(utterance, lex["verify_markers"]) / token_count,
            "question_ratio": utterance.count("?") / max(1, utterance.count(".") + utterance.count("?") + utterance.count("!")),
            "exclamation": utterance.count("!") / max(1, len(utterance)),
            "positive": sum(1 for token in tokens if token in set(lex["positive_words"])) / token_count,
            "negative": sum(1 for token in tokens if token in set(lex["negative_words"])) / token_count,
            "length": token_count
        }
        results.append(feature_dict)
    return results

