# Modified version with renamed variables and reordered logic
import torch, os
from einops import rearrange

# Try importing different attention implementations
try:
    import flash_attn_interface
    HAS_FLASH_ATTN_3 = True
except ModuleNotFoundError:
    HAS_FLASH_ATTN_3 = False

try:
    import flash_attn
    HAS_FLASH_ATTN_2 = True
except ModuleNotFoundError:
    HAS_FLASH_ATTN_2 = False

try:
    from sageattention import sageattn
    HAS_SAGE_ATTN = True
except ModuleNotFoundError:
    HAS_SAGE_ATTN = False

try:
    import xformers.ops as xops
    HAS_XFORMERS = True
except ModuleNotFoundError:
    HAS_XFORMERS = False

def determine_attention_backend():
    env_backend = os.environ.get('DIFFSYNTH_ATTENTION_IMPLEMENTATION')
    if env_backend is not None:
        return env_backend.strip().lower()
    elif HAS_FLASH_ATTN_3:
        return "flash_attention_3"
    elif HAS_FLASH_ATTN_2:
        return "flash_attention_2"
    elif HAS_SAGE_ATTN:
        return "sage_attention"
    elif HAS_XFORMERS:
        return "xformers"
    else:
        return "torch"

SELECTED_ATTENTION_BACKEND = determine_attention_backend()

def transform_qkv_tensors(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                          q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                          target_format="b n s d", shape_params=None):
    shape_params = {} if shape_params is None else shape_params

    if q_format != target_format:
        q = rearrange(q, f"{q_format} -> {target_format}", **shape_params)
    if k_format != target_format:
        k = rearrange(k, f"{k_format} -> {target_format}", **shape_params)
    if v_format != target_format:
        v = rearrange(v, f"{v_format} -> {target_format}", **shape_params)

    return q, k, v

def transform_output_tensor(output: torch.Tensor, output_format="b n s d", 
                            required_format="b n s d", shape_params=None):
    shape_params = {} if shape_params is None else shape_params

    if output_format != required_format:
        output = rearrange(output, f"{required_format} -> {output_format}", **shape_params)

    return output

def torch_scaled_dot_product(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                             q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                             out_format="b n s d", shape_params=None, attn_mask=None, scale_factor=None):
    in_format, out_format = "b n s d", "b n s d"
    q, k, v = transform_qkv_tensors(q, k, v, q_format, k_format, v_format, in_format, shape_params)
    out = torch.nn.functional.scaled_dot_product_attention(q, k, v, attn_mask, scale=scale_factor)
    out = transform_output_tensor(out, out_format, out_format, shape_params)
    return out

def flash_attn_3_forward(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                         q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                         out_format="b n s d", shape_params=None, scale_factor=None):
    in_format, out_format = "b s n d", "b s n d"
    q, k, v = transform_qkv_tensors(q, k, v, q_format, k_format, v_format, in_format, shape_params)
    out = flash_attn_interface.flash_attn_func(q, k, v, softmax_scale=scale_factor)
    if isinstance(out, tuple):
        out = out[0]
    out = transform_output_tensor(out, out_format, out_format, shape_params)
    return out

def flash_attn_2_forward(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                         q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                         out_format="b n s d", shape_params=None, scale_factor=None):
    in_format, out_format = "b s n d", "b s n d"
    q, k, v = transform_qkv_tensors(q, k, v, q_format, k_format, v_format, in_format, shape_params)
    out = flash_attn.flash_attn_func(q, k, v, softmax_scale=scale_factor)
    out = transform_output_tensor(out, out_format, out_format, shape_params)
    return out

def sage_attn_forward(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                      q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                      out_format="b n s d", shape_params=None, scale_factor=None):
    in_format, out_format = "b n s d", "b n s d"
    q, k, v = transform_qkv_tensors(q, k, v, q_format, k_format, v_format, in_format, shape_params)
    out = sageattn(q, k, v, sm_scale=scale_factor)
    out = transform_output_tensor(out, out_format, out_format, shape_params)
    return out

def xformers_efficient_attn(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                            q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                            out_format="b n s d", shape_params=None, scale_factor=None):
    in_format, out_format = "b s n d", "b s n d"
    q, k, v = transform_qkv_tensors(q, k, v, q_format, k_format, v_format, in_format, shape_params)
    out = xops.memory_efficient_attention(q, k, v, scale=scale_factor)
    out = transform_output_tensor(out, out_format, out_format, shape_params)
    return out

def execute_attention(q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, 
                      q_format="b n s d", k_format="b n s d", v_format="b n s d", 
                      out_format="b n s d", shape_params=None, attn_mask=None, 
                      scale_factor=None, force_compatibility=False):
    if force_compatibility or (attn_mask is not None):
        return torch_scaled_dot_product(q, k, v, q_format, k_format, v_format, out_format, 
                                        shape_params, attn_mask=attn_mask, scale_factor=scale_factor)
    else:
        if SELECTED_ATTENTION_BACKEND == "flash_attention_3":
            return flash_attn_3_forward(q, k, v, q_format, k_format, v_format, out_format, 
                                       shape_params, scale_factor=scale_factor)
        elif SELECTED_ATTENTION_BACKEND == "flash_attention_2":
            return flash_attn_2_forward(q, k, v, q_format, k_format, v_format, out_format, 
                                       shape_params, scale_factor=scale_factor)
        elif SELECTED_ATTENTION_BACKEND == "sage_attention":
            return sage_attn_forward(q, k, v, q_format, k_format, v_format, out_format, 
                                    shape_params, scale_factor=scale_factor)
        elif SELECTED_ATTENTION_BACKEND == "xformers":
            return xformers_efficient_attn(q, k, v, q_format, k_format, v_format, out_format, 
                                          shape_params, scale_factor=scale_factor)
        else:
            return torch_scaled_dot_product(q, k, v, q_format, k_format, v_format, out_format, 
                                            shape_params, scale_factor=scale_factor)

# Timezone utilities with fixed offset support
from datetime import timedelta, tzinfo
from typing import Optional, Tuple, Union

ZERO_TIMEDELTA: timedelta = timedelta(0)

class FixedOffsetTimezone(tzinfo):
    """Fixed offset timezone, specified in minutes east from UTC.
    Implementation derived from the Python `standard library documentation
    <http://docs.python.org/library/datetime.html#tzinfo-objects>`_.
    The __getinitargs__ method allows for proper pickling and copying.
    """
    def __init__(self, offset_value: Union[float, timedelta], timezone_name: str) -> None:
        if isinstance(offset_value, timedelta):
            self._offset = offset_value
        else:
            self._offset = timedelta(minutes=offset_value)
        self._name = timezone_name

    def __getinitargs__(self) -> Tuple[timedelta, str]:
        return self._offset, self._name

    def utcoffset(self, dt: Optional[datetime]) -> timedelta:
        return self._offset

    def tzname(self, dt: Optional[datetime]) -> str:
        return self._name

    def dst(self, dt: Optional[datetime]) -> timedelta:
        return ZERO_TIMEDELTA

UTC_TIMEZONE: FixedOffsetTimezone = FixedOffsetTimezone(0, "UTC")
"""Fixed offset timezone representing Coordinated Universal Time (UTC)."""

# Apply squared ReLU activation using PyTorch
import torch
import torch.nn.functional as F
from megatron.core.jit import jit_fuser

@jit_fuser
def squared_relu_activation(input_tensor: torch.Tensor) -> torch.Tensor:
    """Compute the square of the ReLU activation."""
    relu_output = F.relu(input_tensor)
    return torch.pow(relu_output, 2)

# Check if a list contains only elements of a specific type
from typing import Any, TypeGuard, TypeVar

T = TypeVar("T")

def is_list_of_type(
    target_type: type[T],
    items: list[Any],
) -> TypeGuard[list[T]]:
    return len(items) > 0 and all(isinstance(item, target_type) for item in items)

# Module for managing UCM connectors with lazy loading
import importlib
from typing import Callable
from ucm.logger import init_logger
from ucm.store.ucmstore import UcmKVStoreBase

logger = init_logger(__name__)

class UcmConnectorFactory:
    # Dictionary mapping connector names to factory functions
    _registry: dict[str, Callable[[], type[UcmKVStoreBase]]] = {}

    @classmethod
    def register_connector(cls, name: str, module_path: str, class_name: str) -> None:
        """Register a new connector type using lazy module loading."""
        if name in cls._registry:
            raise ValueError(f"Connector '{name}' is already registered.")

        def loader() -> type[UcmKVStoreBase]:
            module = importlib.import_module(module_path)
            return getattr(module, class_name)

        cls._registry[name] = loader

    @classmethod
    def create_connector(cls, connector_name: str, config: dict) -> UcmKVStoreBase:
        if connector_name in cls._registry:
            connector_cls = cls._registry[connector_name]()
        else:
            raise ValueError(f"Unsupported connector type: {connector_name}")

        assert issubclass(connector_cls, UcmKVStoreBase)
        logger.info(f"Initializing connector: {connector_name}")
        return connector_cls(config)

# Register available connector types
UcmConnectorFactory.register_connector(
    "UcmNfsStore", "ucm.store.nfsstore.nfsstore_connector", "UcmNfsStore"
)
UcmConnectorFactory.register_connector(
    "UcmPcStore", "ucm.store.pcstore.pcstore_connector", "UcmPcStore"
)
UcmConnectorFactory.register_connector(
    "UcmMooncakeStore",
    "ucm.store.mooncakestore.mooncake_connector",
    "UcmMooncakeStore",
)

# Scan subreddits for metadata, posts, and strategy analysis
import sys
from typing import Any, Dict, List
from . import cascade_fetcher
from .deep_reader import read_top_posts
from .strategy_extractor import extract_strategy

def _log_message(msg: str) -> None:
    print(f"[scanner] {msg}", file=sys.stderr)

def _fetch_about_safely(subreddit: str) -> Dict[str, Any]:
    try:
        return cascade_fetcher.fetch_about(subreddit)
    except Exception as err:
        _log_message(f"fetch_about({subreddit}) failed: {err}")
        return {"error": str(err)}

def _process_about(raw_data: Dict) -> Dict[str, Any]:
    if "error" in raw_data:
        return raw_data
    return {
        "name": raw_data.get("display_name", raw_data.get("subreddit", "")),
        "title": raw_data.get("title", ""),
        "subscribers": raw_data.get("subscribers", 0),
        "active_users": raw_data.get("accounts_active", raw_data.get("active_user_count", 0)),
        "description": raw_data.get("public_description", "")[:200],
        "created_utc": raw_data.get("created_utc", ""),
    }

def scan_subreddit(
    subreddit: str, sort_method: str = "top",
    period: str = "week", max_posts: int = 25,
) -> Dict[str, Any]:
    _log_message(f"Scanning r/{subreddit} ({sort_method}/{period}, limit={max_posts})")
    about_info = _process_about(_fetch_about_safely(subreddit))
    _log_message(f"r/{subreddit}: about fetched")
    posts_list = read_top_posts(subreddit, sort_method, period, max_posts)
    _log_message(f"r/{subreddit}: {len(posts_list)} posts fetched")
    strategy_result = extract_strategy(posts_list)
    return {
        "subreddit": subreddit,
        "about": about_info,
        "posts_fetched": len(posts_list),
        "strategy": strategy_result,
        "data_source": "cascade",
    }

def bulk_scan(
    subreddit_list: List[str], sort_method: str = "top",
    period: str = "week", max_posts: int = 25,
) -> Dict[str, Any]:
    output: Dict[str, Any] = {}
    for sr in subreddit_list:
        try:
            output[sr] = scan_subreddit(sr, sort_method, period, max_posts)
        except Exception as err:
            _log_message(f"r/{sr} scan failed: {err}")
            output[sr] = {"subreddit": sr, "error": str(err)}
    return {"subreddits": output, "comparison": _analyze_results(output)}

def _analyze_results(scan_results: Dict[str, Dict]) -> Dict[str, Any]:
    successful = {k: v for k, v in scan_results.items() if "error" not in v}
    if len(successful) < 2:
        return {"note": "Need 2+ successful scans for comparison"}
    return {
        "by_subscribers": _sort_by_attribute(successful, ["about", "subscribers"]),
        "by_engagement": _sort_by_engagement_level(successful),
    }

def _sort_by_attribute(data: Dict[str, Dict], field_path: List[str]) -> List[Dict]:
    entries: List[Dict] = []
    for name, info in data.items():
        current = info
        for attr in field_path:
            current = current.get(attr, {}) if isinstance(current, dict) else {}
        entries.append({"subreddit": name, "value": current if not isinstance(current, dict) else 0})
    return sorted(entries, key=lambda item: item["value"], reverse=True)

def _sort_by_engagement_level(data: Dict[str, Dict]) -> List[Dict]:
    entries: List[Dict] = []
    for name, info in data.items():
        content_types = info.get("strategy", {}).get("content_types", {})
        average_scores = [v.get("avg_score", 0) for v in content_types.values()]
        avg_val = round(sum(average_scores) / len(average_scores), 1) if average_scores else 0
        entries.append({"subreddit": name, "avg_score_across_types": avg_val})
    return sorted(entries, key=lambda item: item["avg_score_across_types"], reverse=True)

