# Process graph modules from model paths and count operations
from pathlib import Path
from graph_net.torch.fx_graph_cache_util import (
    parse_immutable_model_path_into_sole_graph_module,
)
import os
import sys

class GraphModuleProcessor:
    def __init__(self, settings=None):
        if settings is None:
            settings = {}
        self.settings = self._configure_settings(**settings)
        self.processed_count = 0

    def _configure_settings(
        self,
        base_model_path,
        result_directory,
        continue_processing=False,
        max_models_to_process=None,
    ):
        return {
            "base_model_path": base_model_path,
            "result_directory": result_directory,
            "continue_processing": continue_processing,
            "max_models_to_process": max_models_to_process,
        }

    def __call__(self, relative_model_path):
        full_model_path = os.path.join(self.settings["base_model_path"], relative_model_path)

        if self.settings["continue_processing"] and self._is_already_processed(relative_model_path):
            return

        graph_module = parse_immutable_model_path_into_sole_graph_module(full_model_path)
        destination_dir = Path(self.settings["result_directory"]) / relative_model_path
        destination_dir.mkdir(parents=True, exist_ok=True)

        (destination_dir / "operation_count.txt").write_text(str(self._count_operations(graph_module)))
        self._update_processed_count()

    def _count_operations(self, gm):
        excluded_ops = {"placeholder", "output"}
        return len([node for node in gm.graph.nodes if node.op not in excluded_ops])

    def _is_already_processed(self, relative_model_path):
        return (Path(self.settings["result_directory"]) / relative_model_path).exists()

    def _update_processed_count(self):
        self.processed_count += 1
        threshold = self.settings["max_models_to_process"]
        if threshold is not None:
            if self.processed_count >= threshold:
                print(
                    "Processed model count has reached the configured limit",
                    file=sys.stderr,
                )
                sys.exit(0)

import torch
from megatron.core.dist_checkpointing.strategies.filesystem_async import FileSystemWriterAsync

class ROCmFileSystemWriterAsync(FileSystemWriterAsync):
    """
    FileSystemWriterAsync wrapper for ROCm compatibility.
    On ROCm/HIP, using non_blocking=True causes tensors to be stored in pinned memory,
    which triggers segmentation faults when forking subprocesses afterward.
    """
    @staticmethod
    def preload_tensors(*args, **kwargs):
        # Modify the non_blocking parameter to False on HIP platform
        # When non_blocking=True, tensors are stored in pinned memory
        # Forking a subprocess after setting pinned_memory=True on ROCm leads to segfaults
        if torch.version.hip:
            print("HIP/ROCm environment detected: overriding non_blocking to False")
            if "non_blocking" in kwargs:
                kwargs["non_blocking"] = False
            elif len(args) > 1 and isinstance(args[-1], bool):
                # non_blocking is usually passed as the final positional argument
                args = args[:-1] + (False,)
        return FileSystemWriterAsync.preload_tensors(*args, **kwargs)

# Distributed inference service implementation using Torchrun
from typing import Optional
from loguru import logger
from .worker import TorchrunInferenceWorker

class DistributedInferenceService:
    def __init__(self):
        self.inference_worker = None
        self.active = False
        self.config = None

    def begin_distributed_inference(self, config_params) -> bool:
        self.config = config_params
        if self.active:
            logger.warning("Distributed inference service is already active")
            return True
        try:
            self.inference_worker = TorchrunInferenceWorker()
            if not self.inference_worker.setup(config_params):
                raise RuntimeError("Worker setup failed")
            self.active = True
            logger.info(f"Rank {self.inference_worker.global_rank} inference service started successfully")
            return True
        except Exception as error:
            logger.error(f"Error starting inference service: {str(error)}")
            self.terminate_distributed_inference()
            return False

    def terminate_distributed_inference(self):
        if not self.active:
            return
        try:
            if self.inference_worker:
                self.inference_worker.shutdown()
            logger.info("Inference service stopped")
        except Exception as error:
            logger.error(f"Error stopping inference service: {str(error)}")
        finally:
            self.inference_worker = None
            self.active = False

    async def enqueue_task_async(self, task_info: dict) -> Optional[dict]:
        if not self.active or not self.inference_worker:
            logger.error("Inference service is not active")
            return None
        if self.inference_worker.global_rank != 0:
            return None
        try:
            if self.inference_worker.busy:
                logger.info(f"Waiting for previous task to complete before processing task {task_info.get('task_id')}")
            self.inference_worker.busy = True
            output = await self.inference_worker.handle_request(task_info)
            self.inference_worker.busy = False
            return output
        except Exception as error:
            self.inference_worker.busy = False
            logger.error(f"Failed to process task: {str(error)}")
            return {
                "task_id": task_info.get("task_id", "unknown"),
                "status": "failed",
                "error": str(error),
                "message": f"Task processing failed: {str(error)}",
            }

    def get_server_info(self):
        assert hasattr(self, "config"), "Distributed inference service has not been started. Call begin_distributed_inference() first."
        return {"nproc_per_node": self.inference_worker.world_size, "model_cls": self.config.model_cls, "model_path": self.config.model_path}

    async def execute_worker_loop(self):
        if self.inference_worker and self.inference_worker.global_rank != 0:
            await self.inference_worker.background_loop()

# Define the allowed processor identifiers
from typing_extensions import Literal, TypeAlias

ProcessorName: TypeAlias = Literal[
    "canny", "depth", "softedge", "lineart", "lineart_anime", "openpose", "normal", "tile", "none", "inpaint"
]

class ImageProcessor:
    def __init__(self, processor_name: ProcessorName, model_dir="models/Annotators", target_resolution=None, device='cuda', disable_processor=False):
        if not disable_processor:
            if processor_name == "canny":
                from controlnet_aux.processor import CannyDetector
                self.detector = CannyDetector()
            elif processor_name == "depth":
                from controlnet_aux.processor import MidasDetector
                self.detector = MidasDetector.from_pretrained(model_dir).to(device)
            elif processor_name == "softedge":
                from controlnet_aux.processor import HEDdetector
                self.detector = HEDdetector.from_pretrained(model_dir).to(device)
            elif processor_name == "lineart":
                from controlnet_aux.processor import LineartDetector
                self.detector = LineartDetector.from_pretrained(model_dir).to(device)
            elif processor_name == "lineart_anime":
                from controlnet_aux.processor import LineartAnimeDetector
                self.detector = LineartAnimeDetector.from_pretrained(model_dir).to(device)
            elif processor_name == "openpose":
                from controlnet_aux.processor import OpenposeDetector
                self.detector = OpenposeDetector.from_pretrained(model_dir).to(device)
            elif processor_name == "normal":
                from controlnet_aux.processor import NormalBaeDetector
                self.detector = NormalBaeDetector.from_pretrained(model_dir).to(device)
            elif processor_name == "tile" or processor_name == "none" or processor_name == "inpaint":
                self.detector = None
            else:
                raise ValueError(f"Unsupported processor name: {processor_name}")
        else:
            self.detector = None

        self.processor_name = processor_name
        self.target_resolution = target_resolution

    def move_to_device(self, device):
        if hasattr(self.detector, "model") and hasattr(self.detector.model, "to"):
            self.detector.model.to(device)

    def __call__(self, img, segmentation_mask=None):
        img_width, img_height = img.size
        if self.processor_name == "openpose":
            processing_params = {
                "include_body": True,
                "include_hand": True,
                "include_face": True
            }
        else:
            processing_params = {}

        if self.detector is not None:
            resolution_setting = self.target_resolution if self.target_resolution is not None else min(img_width, img_height)
            img = self.detector(img, detect_resolution=resolution_setting, image_resolution=min(img_width, img_height), **processing_params)

        img = img.resize((img_width, img_height))
        return img

