# Determine memory constraints from container environment
import os

class MemoryConstraintException(Exception):
    """Exception raised when memory constraints cannot be ascertained from the cgroup setup."""

def retrieve_container_memory_cap() -> int:
    """Fetches the memory ceiling for the active container via the cgroup filesystem.
    This utility accommodates both cgroup v1 and v2, reading the corresponding file
    to extract the memory cap in bytes.

    Returns:
        int: The memory ceiling in bytes.

    Raises:
        MemoryConstraintException: If the memory ceiling cannot be established.
    """
    # Probe for cgroup v2 configuration
    cgroup_v2_file = "/sys/fs/cgroup/memory.max"
    if os.path.isfile(cgroup_v2_file):
        try:
            with open(cgroup_v2_file, "r", encoding="utf-8") as stream:
                content = stream.read().strip()
                if content == "max":
                    raise MemoryConstraintException(
                        "No memory restriction defined in cgroup v2 (value is 'max')."
                    )
                return int(content)
        except (OSError, ValueError) as err:
            raise MemoryConstraintException(
                f"Unable to parse cgroup v2 memory cap: {err}"
            ) from err

    # Fallback to cgroup v1 configuration
    cgroup_v1_file = "/sys/fs/cgroup/memory/memory.limit_in_bytes"
    if os.path.isfile(cgroup_v1_file):
        try:
            with open(cgroup_v1_file, "r", encoding="utf-8") as stream:
                content = stream.read().strip()
                cap = int(content)
                # Some systems use a huge number to indicate no limit
                if cap >= 1 << 60:  # Consider as unlimited
                    raise MemoryConstraintException(
                        "Memory cap is effectively infinite in cgroup v1."
                    )
                return cap
        except (OSError, ValueError) as err:
            raise MemoryConstraintException(
                f"Unable to parse cgroup v1 memory cap: {err}"
            ) from err

    raise MemoryConstraintException("Cgroup memory configuration file unavailable.")

