    def __init__(self, test_name: str, explanation: str, is_info: bool = False):
        self.test_name = test_name
        self.explanation = explanation
        self.findings: List[Dict[str, Any]] = []
        self.can_fix = False
        self.repair_query: Optional[str] = None
        self.repair_function: Optional[Callable] = None
        self.is_info = is_info  # Set to True if this is merely informational

