    def __init__(self):
        # Initialize configuration from environment variables with defaults
        self.model_name = os.getenv("EMBEDDING_MODEL_NAME", "all-MiniLM-L6-v2")
        self.use_openai = os.getenv("USE_OPENAI_EMBEDDINGS", "false").lower() == "true"
        self.openai_api_key = os.getenv("OPENAI_API_KEY")
        self.openai_model = os.getenv("OPENAI_EMBEDDING_MODEL", "text-embedding-3-small")

    @classmethod
    def get_instance(cls):
        """Singleton getter: creates instance if it doesn't exist."""
        if cls._instance is None:
            cls._instance = cls()
        return cls._instance

    def _load_local_model(self):
        """Load the local embedding model using sentence-transformers."""
        if self._model is None:
            try:
                from sentence_transformers import SentenceTransformer
                logger.info(f"Initializing local embedding model: {self.model_name}")
                self._model = SentenceTransformer(self.model_name)
            except ImportError:
                logger.error("sentence-transformers package not found. Install via: pip install sentence-transformers")
                raise
            except Exception as e:
                logger.error(f"Error loading embedding model: {e}")
                raise

    async def generate_embedding(self, text: str) -> List[float]:
        """Generate vector representation for input text."""
        if not text:
            return []
        if self.use_openai:
            return await self._generate_openai_embedding(text)
        else:
            return await self._generate_local_embedding_via_proxy(text)

    async def _generate_local_embedding_via_proxy(self, text: str) -> List[float]:
        """Route embedding request through a dedicated ML inference process."""
        from ..ml.inference_server import inference_proxy
        try:
            embedding = inference_proxy.run_inference(
                "generate_embedding", 
                {"text": text, "model_name": self.model_name}
            )
            return embedding
        except Exception as e:
            logger.warning(f"Inference proxy error for embedding: {e}. Switching to local fallback.")
            # Fallback: load model directly in current process if proxy fails
            self._load_local_model()
            embedding = self._model.encode(text)
            return embedding.tolist()

    async def _generate_openai_embedding(self, text: str) -> List[float]:
        """Generate embeddings using OpenAI's API."""
        try:
            from openai import AsyncOpenAI
            client = AsyncOpenAI(api_key=self.openai_api_key)
            response = await client.embeddings.create(
                input=[text],
                model=self.openai_model
            )
            return response.data[0].embedding
        except ImportError:
            logger.error("openai library missing. Install via: pip install openai")
            raise
        except Exception as e:
            logger.error(f"OpenAI embedding generation failed: {e}")
            raise

    def get_dimension(self) -> int:
        """Return the dimensionality of generated embeddings."""
        if self.use_openai:
            # Default OpenAI models have fixed dimensions
            # text-embedding-3-small and ada-002 both use 1536 dimensions
            return 1536 
        else:
            self._load_local_model()
            # Most sentence-transformers models output either 384 or 768 dimensions
            return self._model.get_sentence_embedding_dimension()

