# Display dictionary or JSON-like data as Rich Text
from rich.text import Text

def show_dict(data) -> Text:
    """Generate a Rich Text representation of a dictionary.
    This function is deprecated. Use show_json instead.
    """
    return show_json(data)

def show_json(json_data) -> Text:
    """Generate a Rich Text representation of JSON-like data.
    Supports dictionaries, lists, strings, numbers, booleans, and None values.
    """
    output = Text()

    if isinstance(json_data, dict):
        for key, value in json_data.items():
            if value is None:
                continue  # omit None fields

            output.append(f"\n  {key}: ", style="bold")

            if isinstance(value, str):
                # Process multiline strings with correct indentation
                if "\n" in value:
                    output.append("\n")
                    for part in value.split("\n"):
                        output.append(f"    {part}\n")
                else:
                    output.append(f'"{value}"')
            elif isinstance(value, (list, dict)):
                output.append(str(value))
            else:
                output.append(str(value))

    elif isinstance(json_data, list):
        output.append(f"[List containing {len(json_data)} elements]\n")
        for idx, element in enumerate(json_data):
            output.append(f"  [{idx}]: ", style="bold")
            if isinstance(element, str):
                output.append(f'"{element}"\n')
            else:
                output.append(f"{element}\n")

    elif isinstance(json_data, str):
        # Format multiline strings with proper indentation
        if "\n" in json_data:
            output.append("Text:\n")
            for segment in json_data.split("\n"):
                output.append(f"  {segment}\n")
        else:
            output.append(f'"{json_data}"')

    elif json_data is None:
        output.append("null")

    else:
        # Render numbers, booleans, and other primitive types
        output.append(str(json_data))

    return output

