# Validation result model for volcengine-api
from typing import Any, Dict, List, Optional

class CheckResult:
    """Simple validation result structure used by volcengine-api.
    This class maintains a minimal interface: indicates if validation succeeded,
    holds error messages, and optionally includes additional contextual data.
    """
    __slots__ = ("passed", "messages", "metadata")

    def __init__(self, passed: bool, messages: Optional[List[str]] = None, metadata: Optional[Dict[str, Any]] = None):
        self.passed = bool(passed)
        self.messages = list(messages) if messages is not None else []
        self.metadata = dict(metadata) if metadata is not None else {}

    def as_dict(self) -> Dict[str, Any]:
        return {"passed": self.passed, "messages": self.messages, "metadata": self.metadata}

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, CheckResult):
            return NotImplemented
        return (self.passed == other.passed and 
                self.messages == other.messages and 
                self.metadata == other.metadata)

    def __str__(self) -> str:
        return f"CheckResult(passed={self.passed}, messages={self.messages}, metadata={self.metadata})"

