from collections import OrderedDict
import torch
from megatron.core.inference.inference_request import InferenceRequest
from megatron.core.inference.text_generation_controllers.text_generation_controller import (
    TextGenerationController,
)

class TokenizerAdapter:
    """Adapts tokenizer for consistent usage during inference."""
    # pylint: disable=C0115,C0116
    def __init__(self, tokenizer_obj):
        self.eod = tokenizer_obj.eos_token_id
        self.vocab_size = None
        self._tokenizer_obj = tokenizer_obj

    def detokenize(self, token_list):
        # pylint: disable=C0115,C0116
        return self._tokenizer_obj.decode(token_list, skip_special_tokens=False)

    def tokenize(self, input_text):
        # pylint: disable=C0115,C0116
        return self._tokenizer_obj.encode(input_text, add_special_tokens=False)

class VLMTextGenerationController(TextGenerationController):
    """Text generation controller for Vision-Language Models supporting image inputs."""
    # pylint: disable=C0115,C0116
    def __init__(self, model_wrapper, tokenizer_obj, img_processor):
        super().__init__(model_wrapper, TokenizerAdapter(tokenizer_obj))
        self.image_processor = img_processor

    def tokenize_prompt(self, prompt_text: str, image_data):
        # pylint: disable=C0115,C0116
        tokens = self.tokenizer.tokenize(prompt_text)

        if image_data is None:
            image_dict = dict(
                pixel_values=torch.zeros(
                    1, 4, 3, self.image_processor.size["height"], self.image_processor.size["width"]
                ),
                aspect_ratio_ids=torch.tensor([0], dtype=torch.long),
                num_tiles=[0],
            )
        else:
            image_dict = self.image_processor.preprocess(image_data, return_tensors="pt")
            image_dict = {
                k: v[0] for k, v in image_dict.items() if k in ["pixel_values", "aspect_ratio_ids", "num_tiles"]
            }

        return tokens, image_dict

    def prep_inference_input(
        self,
        prompts_tokens: torch.Tensor,
        active_requests: OrderedDict[str, InferenceRequest],
        use_attention_mask: bool = False,
    ):
        """Prepare input data for inference by delegating to the wrapped model's method.
        Args:
            prompts_tokens (torch.Tensor): A tensor of shape [batch_size, max_sequence_length]
            active_requests (OrderedDict[int, InferenceRequest]): The input active requests
            use_attention_mask (bool): Whether to use an attention mask. Should be set to True only
                when exclusively doing prefill (no decode) with variable prompt lengths.
                Currently unused and added to match an expected interface in Mcore.
        """
        images = list(map(lambda req: req.encoder_prompt, active_requests.values()))
        return self.inference_wrapped_model.prep_inference_input(
            prompts_tokens=prompts_tokens,
            image_dict=images,
        )

class QwenVLTextGenerationController(VLMTextGenerationController):
    """Text generation controller specifically for QwenVL model"""
    def __init__(self, inference_wrapped_model, tokenizer_obj, image_processor, processor):
        super().__init__(inference_wrapped_model, tokenizer_obj, image_processor)

        class QwenVLTokenizer(TokenizerAdapter):
            # pylint: disable=C0115,C0116
            def detokenize(self, token_list):
                updated_tokens = []
                for token in token_list:
                    if token == 151652:
                        updated_tokens.append(token)
                        updated_tokens.append(151655)
                    elif token != 151655:
                        updated_tokens.append(token)
                return self._tokenizer_obj.decode(updated_tokens, skip_special_tokens=False)

        self.tokenizer = QwenVLTokenizer(tokenizer_obj)
        self.processor = processor

    def tokenize_prompt(self, prompt_text: str, image_data):
        """Tokenize prompt and process image following the VLM controller API"""
        inputs = self.processor(
            text=[prompt_text],
            images=image_data,
            padding=True,
            return_tensors="pt",
        )
        tokens = inputs["input_ids"][0]

        if "pixel_values" in inputs:
            image_dict = {
                "pixel_values": inputs["pixel_values"],
                "image_grid_thw": inputs["image_grid_thw"],
            }
        else:
            image_dict = None

        return tokens.tolist(), image_dict

