# Modified version of ConvNormRelu and PoseSequenceDiscriminator classes
import torch
import torch.nn.functional as F
from torch import nn

class ConvNormActivation(nn.Module):
    def __init__(self, conv_dim='1d', input_features=3, output_features=64, is_downsampling=False,
                 filter_size=None, step_size=None, pad_size=None, normalization='BN', slope_leaky=False):
        super().__init__()
        if filter_size is None:
            if is_downsampling:
                filter_size, step_size, pad_size = 4, 2, 1
            else:
                filter_size, step_size, pad_size = 3, 1, 1

        if conv_dim == '2d':
            self.conv_layer = nn.Conv2d(
                input_features,
                output_features,
                filter_size,
                step_size,
                pad_size,
                bias=False,
            )
            if normalization == 'BN':
                self.norm_layer = nn.BatchNorm2d(output_features)
            elif normalization == 'IN':
                self.norm_layer = nn.InstanceNorm2d(output_features)
            else:
                raise NotImplementedError
        elif conv_dim == '1d':
            self.conv_layer = nn.Conv1d(
                input_features,
                output_features,
                filter_size,
                step_size,
                pad_size,
                bias=False,
            )
            if normalization == 'BN':
                self.norm_layer = nn.BatchNorm1d(output_features)
            elif normalization == 'IN':
                self.norm_layer = nn.InstanceNorm1d(output_features)
            else:
                raise NotImplementedError

        nn.init.kaiming_normal_(self.conv_layer.weight)
        self.activation = nn.LeakyReLU(negative_slope=0.2, inplace=False) if slope_leaky else nn.ReLU(inplace=True)

    def forward(self, input_tensor):
        output = self.conv_layer(input_tensor)
        if isinstance(self.norm_layer, nn.InstanceNorm1d):
            # Apply InstanceNorm on channel dimension for 1D data
            output = self.norm_layer(output.permute((0, 2, 1))).permute((0, 2, 1))
        else:
            output = self.norm_layer(output)
        output = self.activation(output)
        return output


class MotionSequenceDiscriminator(nn.Module):
    def __init__(self, config):
        super().__init__()
        self.config = config
        use_leaky = self.config.MODEL.DISCRIMINATOR.LEAKY_RELU

        self.discriminator_layers = nn.Sequential(
            ConvNormActivation('1d', config.MODEL.DISCRIMINATOR.INPUT_CHANNELS, 256, is_downsampling=True, slope_leaky=use_leaky),  # B, 256, 64
            ConvNormActivation('1d', 256, 512, is_downsampling=True, slope_leaky=use_leaky),  # B, 512, 32
            ConvNormActivation('1d', 512, 1024, filter_size=3, step_size=1, pad_size=1, slope_leaky=use_leaky),  # B, 1024, 16
            nn.Conv1d(1024, 1, filter_size=3, step_size=1, pad_size=1, bias=True)  # B, 1, 16
        )

    def forward(self, input_data):
        # Reshape input to (batch, channels, sequence_length)
        reshaped_input = input_data.reshape(input_data.size(0), input_data.size(1), -1).transpose(1, 2)
        features = self.discriminator_layers(reshaped_input)
        result = features.squeeze(1)
        return result

