# Time step embedding utility for diffusion models
import math
import torch
import torch.nn as nn
from einops import rearrange, repeat

def generate_time_embedding(time_values, embedding_dim, max_period=10000, only_repeat=False, dtype=torch.float32):
    if not only_repeat:
        half_dim = embedding_dim // 2
        frequencies = torch.exp(-math.log(max_period) * torch.arange(start=0, end=half_dim, dtype=torch.float32, device=time_values.device) / half_dim)
        arguments = time_values[:, None].float() * frequencies[None]
        embedded = torch.cat([torch.cos(arguments), torch.sin(arguments)], dim=-1)
        if embedding_dim % 2:
            embedded = torch.cat([embedded, torch.zeros_like(embedded[:, :1])], dim=-1)
    else:
        embedded = repeat(time_values, "b -> b d", d=embedding_dim)
    return embedded.to(dtype)

class TemporalFeatureEmbedder(nn.Module):
    def __init__(self, feature_size, projection_dim=None, max_period=10000, only_repeat=False):
        super().__init__()
        self.feature_size = feature_size
        self.projection_dim = projection_dim if projection_dim is not None else feature_size
        self.max_period = max_period
        self.only_repeat = only_repeat
        self.temporal_projection = nn.Sequential(
            nn.Linear(self.feature_size, projection_dim),
            nn.SiLU(),
            nn.Linear(projection_dim, projection_dim),
        )

    @property
    def data_type(self) -> torch.dtype:
        """The data type of the module (assuming that all the module parameters have the same data type)."""
        parameters = tuple(self.parameters())
        if len(parameters) > 0:
            return parameters[0].dtype
        else:
            buffers = tuple(self.buffers())
            return buffers[0].dtype

    def forward(self, time_steps):
        encoded = generate_time_embedding(time_steps, self.feature_size, self.max_period, self.only_repeat, dtype=self.data_type)
        return self.temporal_projection(encoded)

def check_date(date_str):
    """You need to create a function that checks a provided date string and
    returns True if the date is correct otherwise False.
    The date is considered valid if all of the following conditions are met:
    1. The date string is not blank.
    2. The day value does not fall below 1 or exceed 31 for months 1,3,5,7,8,10,12. 
       For months 4,6,9,11 the day must be between 1 and 30. 
       For February (month 2), the day should be between 1 and 29.
    3. The month value must be between 1 and 12.
    4. The date must follow the format: mm-dd-yyyy
    for example: 
    check_date('03-11-2000') => True
    check_date('15-01-2012') => False
    check_date('04-0-2040') => False
    check_date('06-04-2020') => True
    check_date('06/04/2020') => False
    """
    if not date_str:
        return False

    try:
        segments = date_str.split('-')
        if len(segments) != 3:
            return False

        mm, dd, yyyy = segments

        if len(mm) != 2 or len(dd) != 2 or len(yyyy) != 4:
            return False

        month_num = int(mm)
        day_num = int(dd)
        year_num = int(yyyy)

        if month_num < 1 or month_num > 12:
            return False

        if day_num < 1:
            return False

        if month_num in [1, 3, 5, 7, 8, 10, 12]:
            if day_num > 31:
                return False
        elif month_num in [4, 6, 9, 11]:
            if day_num > 30:
                return False
        elif month_num == 2:
            if day_num > 29:
                return False

        return True
    except:
        return False

# Modified version of the test_interrupt_session function
import json
import pytest
from strands import Agent, tool
from strands.hooks import BeforeToolCallEvent, HookProvider
from strands.session import FileSessionManager

@pytest.fixture
def approval_hook():
    class CustomHook(HookProvider):
        def register_hooks(self, registry):
            registry.add_callback(BeforeToolCallEvent, self.handle_approval)

        def handle_approval(self, event):
            if event.tool_use["name"] == "forecast_tool":
                return
            response = event.interrupt("approval_required", reason="user confirmation needed")
            if response != "APPROVE":
                event.cancel_tool = "operation denied"
    return CustomHook()

@pytest.fixture
def clock_tool():
    @tool(name="clock_tool")
    def get_time():
        return "12:00"
    return get_time

@pytest.fixture
def forecast_tool():
    @tool(name="forecast_tool")
    def get_weather():
        return "sunny"
    return get_weather

@pytest.fixture
def smart_agent(approval_hook, clock_tool, forecast_tool):
    return Agent(hooks=[approval_hook], tools=[clock_tool, forecast_tool])

def test_interrupt_handling(approval_hook, clock_tool, forecast_tool, tmpdir):
    # First session run to trigger interrupt
    storage = FileSessionManager(session_id="strands-test-interrupt", storage_dir=tmpdir)
    agent_instance = Agent(hooks=[approval_hook], session_manager=storage, tools=[clock_tool, forecast_tool])

    initial_result = agent_instance("What time is it and what's the weather?")
    actual_stop = initial_result.stop_reason
    expected_stop = "interrupt"
    assert actual_stop == expected_stop

    # Extract interrupt details
    first_interrupt = initial_result.interrupts[0]

    # Restart with same session for continuation
    storage = FileSessionManager(session_id="strands-test-interrupt", storage_dir=tmpdir)
    agent_instance = Agent(hooks=[approval_hook], session_manager=storage, tools=[clock_tool, forecast_tool])

    # Provide approval response
    responses = [
        {
            "interruptResponse": {
                "interruptId": first_interrupt.id,
                "response": "APPROVE",
            },
        },
    ]

    final_result = agent_instance(responses)
    actual_stop = final_result.stop_reason
    expected_stop = "end_turn"
    assert actual_stop == expected_stop

    # Verify both tools were executed
    result_text = json.dumps(final_result.message).lower()
    assert all(item in result_text for item in ["12:00", "sunny"])

