# Test implementation for MLA decoding with split KV cache
import math
import pytest
import torch
import tilegym
from tests import common

class Test_MLADecodingSplitKV(common.PyTestCase):
    @staticmethod
    def reference_impl(q, q_pos_emb, kv_cache, k_pos_emb, scale=None, dtype=torch.half):
        """Reference implementation using PyTorch for MLA decoding (same as test_mla_decoding.py)"""
        if scale is None:
            scale = 1.0 / (math.sqrt(q.size(-1) + q_pos_emb.size(-1)))
        original_dtype = q.dtype
        q = q.to(dtype)
        q_pos_emb = q_pos_emb.to(dtype)
        kv_cache = kv_cache.to(dtype)
        k_pos_emb = k_pos_emb.to(dtype)

        # Compute attention scores: Q*K^T + QPE*KPE^T
        attention_scores = torch.matmul(q, kv_cache.transpose(1, 2)).float()
        if k_pos_emb.numel() > 0:
            attention_scores = attention_scores + torch.matmul(q_pos_emb, k_pos_emb.transpose(1, 2)).float()
        attention_scores = attention_scores * scale

        # Apply softmax
        max_vals = torch.max(attention_scores, dim=-1)[0]
        exp_scores = torch.exp(attention_scores - max_vals.unsqueeze(-1))
        sum_exp = torch.sum(exp_scores, dim=-1)
        normalized_probs = exp_scores / (sum_exp.unsqueeze(-1))

        # Apply attention to values
        output = torch.matmul(normalized_probs.to(original_dtype).to(dtype), kv_cache).to(original_dtype)
        return output

    @staticmethod
    def _compute_scale_factor(q_tensor, qpe_tensor):
        """Calculate the default attention scale factor"""
        return 1.0 / (math.sqrt(q_tensor.size(-1) + qpe_tensor.size(-1)))

    _supported_backends = ["cutile"]

    @pytest.mark.parametrize("num_attention_heads", [16, 32])
    @pytest.mark.parametrize("sequence_length", [129, 1024, 8192, 11049])
    @pytest.mark.parametrize("kv_chunk_size", [128, 512])
    @pytest.mark.parametrize("precision", [torch.float16])
    @pytest.mark.parametrize("backend", _supported_backends)
    def test_operation(self, num_attention_heads, sequence_length, kv_chunk_size, precision, backend, gpu_arch):
        """Test functional correctness of MLA decoding with split-kv"""
        if tilegym.is_backend_available(backend):
            tilegym.set_backend(backend)
        else:
            pytest.skip(f"Backend {backend} is not available")

        self.setUp()

        # Skip test if CUDA is not available
        if not torch.cuda.is_available():
            pytest.skip("CUDA not available, skipping MLA Split-KV test")

        # Test parameters
        batch_size = 1
        embedding_dim = 512
        positional_embedding_dim = 64

        # Create random input tensors
        torch.manual_seed(42)  # For reproducibility
        device = torch.device("cuda")
        query = torch.randn(batch_size, num_attention_heads, embedding_dim, device=device).to(precision)
        query_pos_emb = torch.randn(batch_size, num_attention_heads, positional_embedding_dim, device=device).to(precision)
        key_value_cache = torch.randn(batch_size, sequence_length, embedding_dim, device=device).to(precision)
        key_pos_emb = torch.randn(batch_size, sequence_length, positional_embedding_dim, device=device).to(precision)

        # Compute softmax scale
        scale = self._compute_scale_factor(query, query_pos_emb)

        def split_kv_function():
            return tilegym.ops.mla_decoding_split_kv(query, query_pos_emb, key_value_cache, key_pos_emb, scale, kv_chunk_size)

        def reference_function():
            return self.reference_impl(query, query_pos_emb, key_value_cache, key_pos_emb, scale)

        self.assertCorrectness(split_kv_function, reference_function, {}, atol=1e-2, rtol=1e-2, multiple_outputs=False)

