# Modified version of Robocasa input/output transforms
import dataclasses
import einops
import numpy as np
from openpi import transforms
from openpi.models import model as _model

def generate_robocasa_sample() -> dict:
    """Generates a synthetic input example for the Robocasa policy."""
    return {
        "observation/state": np.random.rand(8),  # eef_pos (3) + eef_quat (4) + gripper (1)
        "observation/image": np.random.randint(256, size=(3, 224, 224), dtype=np.uint8),  # base view
        "observation/wrist_image": np.random.randint(256, size=(3, 224, 224), dtype=np.uint8),  # wrist camera
        "instruction": "perform an action",
    }

def _process_image(img_array) -> np.ndarray:
    img_array = np.asarray(img_array)
    if np.issubdtype(img_array.dtype, np.floating):
        img_array = (255 * img_array).astype(np.uint8)
    if img_array.shape[0] == 3:
        img_array = einops.rearrange(img_array, "c h w -> h w c")
    return img_array

@dataclasses.dataclass(frozen=True)
class RobocasaInputFormatter(transforms.DataTransformFn):
    """
    Converts raw inputs to the model's expected format for both training and inference.
    For Robocasa, we use two 128x128 camera views: base (left agentview) and wrist.
    """
    # Specifies which model architecture will be used.
    # Keep unchanged when adapting to other datasets.
    network_type: _model.ModelType

    def __call__(self, sample: dict) -> dict:
        # Convert images to uint8 in HWC format
        # During inference, images arrive from robocasa_env as (C,H,W) float or uint8
        base_view = _process_image(sample["observation/image"])
        wrist_view = _process_image(sample["observation/wrist_image"])

        # Construct formatted inputs dictionary. Do not alter the keys below.
        formatted_inputs = {
            "state": sample["observation/state"],
            "image": {
                "base_0_rgb": base_view,  # 128x128 base view
                "left_wrist_0_rgb": wrist_view,  # 128x128 wrist view
                # Add zero-padded right wrist since only one wrist camera exists
                "right_wrist_0_rgb": np.zeros_like(wrist_view),
            },
            "image_mask": {
                "base_0_rgb": np.True_,
                "left_wrist_0_rgb": np.True_,
                # Only mask padded images for pi0 model; skip for pi0-FAST. Maintain this for custom datasets.
                "right_wrist_0_rgb": np.False_,
            },
        }

        # Extend actions to match model's action dimension. Retain this pattern for new datasets.
        # Actions are present only during training.
        if "actions" in sample:
            formatted_inputs["actions"] = sample["actions"]

        # Forward the instruction (language command) to the model.
        # Preserve this structure for new datasets (adjust key name if needed;
        # output dict must always contain the "instruction" key).
        if "instruction" in sample:
            formatted_inputs["instruction"] = sample["instruction"]

        return formatted_inputs

@dataclasses.dataclass(frozen=True)
class RobocasaOutputFormatter(transforms.DataTransformFn):
    """
    Transforms model outputs back into dataset-specific format for inference.
    For Robocasa, different robots have varying action dimensions:
    - Panda arm only: 7D actions (7 joint angles)
    - PandaOmron (with mobile base): 12D actions (7 arm + 5 base)

    Args:
        target_action_dim: Desired action dimension. If None, inferred from robot config.
                          Common values: 7 (Panda), 12 (PandaOmron)
    """
    target_action_dim: int | None = None

    def __call__(self, result: dict) -> dict:
        predicted_actions = np.asarray(result["actions"])

        # Use specified action dimension if provided
        if self.target_action_dim is not None:
            return {"actions": predicted_actions[:, : self.target_action_dim]}

        # Auto-detect: retain original dims if 7 or 12; otherwise default to 12D
        if predicted_actions.shape[-1] in [7, 12]:
            return {"actions": predicted_actions}
        else:
            # Default to 12D for PandaOmron
            return {"actions": predicted_actions[:, :12]}

# Script to check Tesla software update status via Tessie API
import argparse
import os
import sys
import requests

def retrieve_api_token():
    """Fetch API token from environment variables"""
    api_token = os.environ.get('TESSIE_API_KEY')
    if not api_token:
        print("Error: TESSIE_API_KEY environment variable not set", file=sys.stderr)
        sys.exit(1)
    return api_token

def main():
    parser = argparse.ArgumentParser(description='Check Tesla software updates')
    parser.add_argument('--vin', help='Vehicle VIN (optional, uses first vehicle if not specified)')

    arguments = parser.parse_args()
    api_token = retrieve_api_token()

    headers = {'Authorization': f'Bearer {api_token}'}

    try:
        # Fetch vehicle list
        response = requests.get('https://api.tessie.com/vehicles', headers=headers)
        response.raise_for_status()
        vehicle_data = response.json()

        if arguments.vin:
            # Locate specific vehicle by VIN
            target_vehicle = None
            for car in vehicle_data.get('results', []):
                if car.get('vin') == arguments.vin:
                    target_vehicle = car
                    break

            if not target_vehicle:
                print(f"Error: Vehicle with VIN {arguments.vin} not found", file=sys.stderr)
                sys.exit(1)
        else:
            # Use first vehicle if no VIN provided
            vehicles_list = vehicle_data.get('results', [])
            if not vehicles_list:
                print("Error: No vehicles found in account", file=sys.stderr)
                sys.exit(1)
            target_vehicle = vehicles_list[0]

        # Extract software update information
        update_info = target_vehicle.get('last_state', {}).get('vehicle_state', {}).get('software_update')

        if update_info and update_info.get('status'):
            version_number = update_info.get('version', 'unknown')
            current_status = update_info.get('status')

            if current_status == 'available':
                print(f"UPDATE_AVAILABLE: Software update {version_number} is ready to install!")
            elif current_status == 'downloading':
                progress_percent = update_info.get('download_perc', 0)
                print(f"UPDATE_DOWNLOADING: Downloading update {version_number} ({progress_percent}%)")
            elif current_status == 'installing':
                installation_percent = update_info.get('install_perc', 0)
                print(f"UPDATE_INSTALLING: Installing update {version_number} ({installation_percent}%)")
            elif current_status == 'scheduled':
                print(f"UPDATE_SCHEDULED: Update {version_number} is scheduled")
            else:
                print("NO_UPDATE")
        else:
            print("NO_UPDATE")

    except requests.exceptions.RequestException as error:
        print(f"Error: Failed to check for updates: {error}", file=sys.stderr)
        sys.exit(1)
    except Exception as error:
        print(f"Error: {error}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

