            if split_label == "train":
                # For training: download both LM corpus and transcript files
                archive_paths[split_label] = dl_manager.download_and_extract(
                    [self.config.lm_corpus_path] + file_list
                )
            else:
                # For dev/test: only download transcript files
                archive_paths[split_label] = dl_manager.download_and_extract(file_list)

        # Construct and return list of SplitGenerator instances
        return [
            datasets.SplitGenerator(
                name=split_label, 
                gen_kwargs={"archive_path": archive_path}
            )
            for split_label, archive_path in archive_paths.items()
        ]

    def _generate_examples(self, archive_path):
        """Generate individual examples from downloaded archives."""
        example_id = 0

        # Iterate over all provided file paths
        for filepath in archive_path:
            with open(filepath, "r", encoding="utf-8") as file_obj:
                for raw_line in file_obj:
                    # Clean up line: remove speaker/utterance IDs if present
                    cleaned_line = re.sub(r"\d+-\d+-\d+\s", "", raw_line)
                    text = cleaned_line.strip()

                    # Filter out empty lines and overly long sequences (>1000 chars)
                    if text and len(text) < 1000:
                        yield example_id, {"text": text}

                    example_id += 1

