import requests
import hmac
import hashlib
import base64
import time
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider
logger = logging.getLogger(__name__)

class ConstellixDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "constellix"
    PROVIDER_NAME = "Constellix"
    PROVIDER_DESCRIPTION = "Constellix Managed DNS API"
    REQUIRED_CREDENTIALS = ["api_key", "secret_key"]

    API_ENDPOINT = "https://api.dns.constellix.com/v4"

    def _build_auth_headers(self) -> Dict[str, str]:
        current_time = str(int(time.time() * 1000))
        signature = hmac.new(
            self.credentials['secret_key'].encode(),
            current_time.encode(),
            hashlib.sha1
        ).digest()
        auth_token = base64.b64encode(signature).decode()
        return {
            'x-cns-security-token': f'{self.credentials["api_key"]}:{auth_token}:{current_time}',
            'Content-Type': 'application/json',
        }

    def _send_request(self, method: str, endpoint: str, payload: Optional[Dict] = None) -> Tuple[bool, Any]:
        full_url = f"{self.API_ENDPOINT}{endpoint}"
        try:
            response = requests.request(method=method, url=full_url, headers=self._build_auth_headers(), json=payload, timeout=30)
            if response.status_code >= 400:
                return False, response.reason
            return True, response.json() if response.text else None
        except requests.RequestException as error:
            return False, str(error)

    def _locate_domain(self, domain: str) -> Optional[Dict]:
        success, data = self._send_request('GET', '/domains')
        if not success:
            return None
        available_domains = data.get('data', [])
        parts = domain.split('.')
        for index in range(len(parts) - 1):
            candidate = '.'.join(parts[index:])
            for d in available_domains:
                if d['name'] == candidate:
                    return d
        return None

    def add_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        dom = self._locate_domain(domain)
        if not dom:
            return False, f"Could not locate domain {domain}"
        relative_name = self.get_relative_record_name(record_name, dom['name'])
        payload = {'name': relative_name, 'ttl': ttl, 'roundRobin': [{'value': f'"{record_value}"'}]}
        success, result = self._send_request('POST', f'/domains/{dom["id"]}/records/txt', payload)
        if not success:
            return False, f"Failed to create record: {result}"
        return True, "Record created successfully"

    def remove_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        dom = self._locate_domain(domain)
        if not dom:
            return False, f"Could not locate domain {domain}"
        success, records = self._send_request('GET', f'/domains/{dom["id"]}/records/txt')
        if not success:
            return False, f"Failed to list records: {records}"
        relative_name = self.get_relative_record_name(record_name, dom['name'])
        for rec in records.get('data', []):
            if rec.get('name') == relative_name:
                self._send_request('DELETE', f'/domains/{dom["id"]}/records/txt/{rec["id"]}')
        return True, "Record deleted successfully"

    def validate_connection(self) -> Tuple[bool, str]:
        success, domains_data = self._send_request('GET', '/domains')
        if success:
            domains_list = domains_data.get('data', [])
            return True, f"Connected. Found {len(domains_list)} domain(s)"
        return False, f"Connection failed: {domains_data}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'api_key', 'label': 'API Key', 'type': 'password', 'required': True},
            {'name': 'secret_key', 'label': 'Secret Key', 'type': 'password', 'required': True,
             'help': 'Constellix portal > User Administration > API'},
        ]

