import base64
from typing import Optional

def decode_base64_string(encoded_data: str) -> Optional[str]:
    """Decode base64 encoded string, handling URL-safe variants and padding issues."""
    cleaned = encoded_data.strip()
    if not cleaned:
        return None

    # Add necessary padding to make length multiple of 4
    cleaned += "=" * (-len(cleaned) % 4)

    # Try both standard and URL-safe decoders
    for decoder_func in (base64.urlsafe_b64decode, base64.b64decode):
        try:
            decoded_bytes = decoder_func(cleaned)
            return decoded_bytes.decode("utf-8")
        except (ValueError, UnicodeDecodeError):
            continue

    return None

# Modified version of the export command implementation
from ..process import Process
from ..command_decorators import command
from . import register_command

@command()
@register_command('export')
def cmd_export_command(process: Process) -> int:
    """
    Set or display environment variables
    Usage: export [VAR=value ...]
    """
    # If no arguments provided, show current environment
    if not process.arguments:
        if hasattr(process, 'environment'):
            for var_key, var_val in sorted(process.environment.items()):
                process.output_stream.write(f"{var_key}={var_val}\n".encode('utf-8'))
        return 0

    # Process each argument to set environment variables
    for item in process.arguments:
        if '=' in item:
            variable_name, variable_value = item.split('=', 1)
            variable_name = variable_name.strip()
            variable_value = variable_value.strip()

            # Check if variable name is valid
            if variable_name and variable_name.replace('_', '').replace('-', '').isalnum():
                if hasattr(process, 'environment'):
                    process.environment[variable_name] = variable_value
            else:
                process.error_stream.write(f"export: invalid variable name: {variable_name}\n")
                return 1
        else:
            process.error_stream.write(f"export: usage: export VAR=value\n")
            return 1

    return 0

