# Fill form fields in a PDF using JSON data
import json
import sys
from pypdf import PdfReader, PdfWriter
from extract_form_field_info import get_field_info

def populate_pdf_form(input_pdf_path: str, fields_json_path: str, output_pdf_path: str):
    with open(fields_json_path) as file:
        field_data = json.load(file)

    organized_fields = {}
    for item in field_data:
        if "value" in item:
            field_identifier = item["field_id"]
            page_number = item["page"]
            if page_number not in organized_fields:
                organized_fields[page_number] = {}
            organized_fields[page_number][field_identifier] = item["value"]

    document_reader = PdfReader(input_pdf_path)
    encountered_error = False
    form_field_details = get_field_info(document_reader)
    field_map = {f["field_id"]: f for f in form_field_details}

    for item in field_data:
        current_field = field_map.get(item["field_id"])
        if not current_field:
            encountered_error = True
            print(f"ERROR: `{item['field_id']}` is not a valid field ID")
        elif item["page"] != current_field["page"]:
            encountered_error = True
            print(f"ERROR: Incorrect page number for `{item['field_id']}` (got {item['page']}, expected {current_field['page']})")
        else:
            if "value" in item:
                validation_msg = validate_field_value(current_field, item["value"])
                if validation_msg:
                    print(validation_msg)
                    encountered_error = True

    if encountered_error:
        sys.exit(1)

    document_writer = PdfWriter(clone_from=document_reader)
    for page_num, field_values in organized_fields.items():
        document_writer.update_page_form_field_values(
            document_writer.pages[page_num - 1], 
            field_values, 
            auto_regenerate=False
        )

    document_writer.set_need_appearances_writer(True)

    with open(output_pdf_path, "wb") as output_file:
        document_writer.write(output_file)

def validate_field_value(field_description, input_value):
    field_kind = field_description["type"]
    field_name = field_description["field_id"]

    if field_kind == "checkbox":
        selected_val = field_description["checked_value"]
        deselected_val = field_description["unchecked_value"]
        if input_value != selected_val and input_value != deselected_val:
            return f'ERROR: Invalid value "{input_value}" for checkbox field "{field_name}". The checked value is "{selected_val}" and the unchecked value is "{deselected_val}"'

    elif field_kind == "radio_group":
        available_options = [opt["value"] for opt in field_description["radio_options"]]
        if input_value not in available_options:
            return f'ERROR: Invalid value "{input_value}" for radio group field "{field_name}". Valid values are: {available_options}'

    elif field_kind == "choice":
        available_choices = [opt["value"] for opt in field_description["choice_options"]]
        if input_value not in available_choices:
            return f'ERROR: Invalid value "{input_value}" for choice field "{field_name}". Valid values are: {available_choices}'

    return None

def patch_pypdf_method():
    from pypdf.generic import DictionaryObject
    from pypdf.constants import FieldDictionaryAttributes

    original_get_inherited = DictionaryObject.get_inherited

    def modified_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if key == FieldDictionaryAttributes.Opt:
            if isinstance(result, list) and all(isinstance(v, list) and len(v) == 2 for v in result):
                result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = modified_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    patch_pypdf_method()
    input_pdf_file = sys.argv[1]
    fields_json_file = sys.argv[2]
    output_pdf_file = sys.argv[3]

    populate_pdf_form(input_pdf_file, fields_json_file, output_pdf_file)

import os
import argparse
import json
import re
from llava.eval.m4c_evaluator import TextVQAAccuracyEvaluator

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument('--annotation-file', type=str)
    parser.add_argument('--result-file', type=str)
    parser.add_argument('--result-dir', type=str)
    return parser.parse_args()

def extract_question(prompt):
    if prompt.startswith('OCR tokens: '):
        pattern = r"Question: (.*?) Short answer:"
        match = re.search(pattern, prompt, re.DOTALL)
        question = match.group(1)
    elif 'Reference OCR token: ' in prompt and len(prompt.split('\n')) == 3:
        if prompt.startswith('Reference OCR token:'):
            question = prompt.split('\n')[1]
        else:
            question = prompt.split('\n')[0]
    elif len(prompt.split('\n')) == 2:
        question = prompt.split('\n')[0]
    else:
        assert False
    return question.lower()

def evaluate_single(annotation_path, prediction_path):
    experiment_name = os.path.splitext(os.path.basename(prediction_path))[0]
    print(experiment_name)

    with open(annotation_path) as f:
        annotations_data = json.load(f)['data']

    annotations_dict = {
        (item['image_id'], item['question'].lower()): item 
        for item in annotations_data
    }

    predictions = [json.loads(line) for line in open(prediction_path)]

    evaluation_samples = []
    for pred in predictions:
        key = (pred['question_id'], extract_question(pred['prompt']))
        gt_annotation = annotations_dict[key]
        evaluation_samples.append({
            "pred_answer": pred['text'],
            "gt_answers": gt_annotation['answers'],
        })

    evaluator = TextVQAAccuracyEvaluator()
    accuracy = 100. * evaluator.eval_pred_list(evaluation_samples)
    print(f'Samples: {len(evaluation_samples)}\nAccuracy: {accuracy:.2f}%\n')

if __name__ == "__main__":
    config = parse_arguments()

    if config.result_file is not None:
        evaluate_single(config.annotation_file, config.result_file)

    if config.result_dir is not None:
        for filename in sorted(os.listdir(config.result_dir)):
            if not filename.endswith('.jsonl'):
                print(f'Skipping {filename}')
                continue
            full_path = os.path.join(config.result_dir, filename)
            evaluate_single(config.annotation_file, full_path)

# Weighted Sum Aggregator Implementation
from typing import Dict
from openjudge.graders.schema import GraderError, GraderRank, GraderResult, GraderScore
from openjudge.runner.aggregator.base_aggregator import BaseAggregator

class WeightedSumAggregator(BaseAggregator):
    """
    Combines multiple grader scores using weighted averaging.
    This class aggregates numerical scores from various graders by applying
    specified weights to produce a single composite score per sample.
    """
    def __init__(self, label: str, weight_map: Dict[str, float] = None):
        """
        Construct the weighted sum aggregator.
        Args:
            label: Identifier for this aggregator instance
            weight_map: Mapping of grader identifiers to their respective weights.
                        If omitted, uniform weights will be assigned automatically.
        """
        super().__init__(label)
        self.weight_map = weight_map or {}

    def __call__(self, results: Dict[str, GraderResult], **options) -> GraderResult:
        """
        Aggregate results from multiple graders via weighted summation for one sample.
        Args:
            results: Dictionary linking grader names to their GraderResult instances
            **options: Extra parameters (reserved for future use)
        Returns:
            A unified GraderResult representing the aggregated outcome
        """
        if not results:
            return GraderError(
                name=self.name,
                reason="No grading output available for aggregation",
                error="Missing grading data for processing",
            )

        # Assign equal weights when none are provided
        if not self.weight_map:
            graders = list(results.keys())
            base_weight = 1.0 / len(graders) if graders else 0.0
            weight_map = {g: base_weight for g in graders}
        else:
            weight_map = self.weight_map

        total_weighted_score = 0.0
        cumulative_weight = 0.0
        detailed_results = {}

        # Process each grader's result
        for grader_id, outcome in results.items():
            if isinstance(outcome, GraderScore):
                w = weight_map.get(grader_id, 0.0)
                total_weighted_score += outcome.score * w
                cumulative_weight += w
                detailed_results[grader_id] = {
                    "score": outcome.score,
                    "weight": w,
                    "note": outcome.reason,
                }
            elif isinstance(outcome, GraderError):
                detailed_results[grader_id] = {
                    "issue": outcome.error,
                }
            elif isinstance(outcome, GraderRank):
                detailed_results[grader_id] = {
                    "position": outcome.rank,
                    "note": outcome.reason,
                }

        # Normalize and compute final score
        if cumulative_weight > 0:
            final_value = total_weighted_score / cumulative_weight
        else:
            final_value = 0.0

        # Build explanation string
        explanation_segments = []
        for identifier, details in detailed_results.items():
            if "score" in details:
                explanation_segments.append(
                    f"{identifier}: {details['score']:.3f} (weight: {details['weight']:.2f})",
                )
            elif "issue" in details:
                explanation_segments.append(f"{identifier}: ISSUE")
            elif "position" in details:
                explanation_segments.append(f"{identifier}: position {details['position']}")

        explanation = f"Weighted combination of {', '.join(explanation_segments)}"

        # Output final aggregated result
        return GraderScore(
            name=self.name,
            score=final_value,
            reason=explanation,
            metadata={
                "weights": weight_map,
            },
        )

