import base64
from typing import TYPE_CHECKING, Any, Dict, Optional

if TYPE_CHECKING:
    from api.db.models import ExternalCredentialModel


def create_auth_header(cred: "ExternalCredentialModel") -> Dict[str, str]:
    """Construct authentication header according to credential type.
    Handles the following credential formats:
    - bearer_token: Authorization: Bearer <token>
    - api_key: Custom header with API key
    - basic_auth: Authorization: Basic <base64(username:password)>
    - custom_header: Any user-defined header name/value pair
    Args:
        cred: The ExternalCredentialModel instance
    Returns:
        Dictionary containing header key and value, or empty dict if
        credential type is unknown or 'none'
    """
    auth_type = cred.credential_type
    auth_data = cred.credential_data or {}

    if auth_type == "bearer_token":
        token_val = auth_data.get("token", "")
        return {"Authorization": f"Bearer {token_val}"}
    elif auth_type == "api_key":
        header_key = auth_data.get("header_name", "X-API-Key")
        api_key_val = auth_data.get("api_key", "")
        return {header_key: api_key_val}
    elif auth_type == "basic_auth":
        user = auth_data.get("username", "")
        passwd = auth_data.get("password", "")
        encoded_str = base64.b64encode(f"{user}:{passwd}".encode()).decode()
        return {"Authorization": f"Basic {encoded_str}"}
    elif auth_type == "custom_header":
        header_key = auth_data.get("header_name", "X-Custom")
        header_val = auth_data.get("header_value", "")
        return {header_key: header_val}
    return {}


def create_auth_header_from_values(
    credential_type: str,
    credential_data: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    """Create authentication header using raw credential data.
    Useful when working with credential information directly instead of
    through an ExternalCredentialModel object.
    Args:
        credential_type: Type of credential (bearer_token, api_key, etc.)
        credential_data: Dictionary with credential-specific parameters
    Returns:
        Dictionary with header name and corresponding value
    """
    data = credential_data or {}

    if credential_type == "bearer_token":
        token_val = data.get("token", "")
        return {"Authorization": f"Bearer {token_val}"}
    elif credential_type == "api_key":
        header_key = data.get("header_name", "X-API-Key")
        api_key_val = data.get("api_key", "")
        return {header_key: api_key_val}
    elif credential_type == "basic_auth":
        user = data.get("username", "")
        passwd = data.get("password", "")
        encoded_str = base64.b64encode(f"{user}:{passwd}".encode()).decode()
        return {"Authorization": f"Basic {encoded_str}"}
    elif credential_type == "custom_header":
        header_key = data.get("header_name", "X-Custom")
        header_val = data.get("header_value", "")
        return {header_key: header_val}
    return {}

# DNS provider implementation for Hover using session-based authentication
import requests
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class HoverDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "hover"
    PROVIDER_NAME = "Hover"
    PROVIDER_DESCRIPTION = "Hover DNS (session-based auth)"
    REQUIRED_CREDENTIALS = ["username", "password"]

    API_ENDPOINT = "https://www.hover.com/api"

    def __init__(self, credentials: Dict[str, Any]):
        super().__init__(credentials)
        self._auth_session = None

    def _authenticate(self) -> Tuple[bool, str]:
        if self._auth_session:
            return True, "Already authenticated"
        self._auth_session = requests.Session()
        try:
            response = self._auth_session.post(f'{self.API_ENDPOINT}/login',
                data={'username': self.credentials['username'], 'password': self.credentials['password']}, timeout=30)
            if response.status_code != 200 or not response.json().get('succeeded'):
                self._auth_session = None
                return False, "Authentication failed"
            return True, "Authenticated"
        except requests.RequestException as e:
            self._auth_session = None
            return False, str(e)

    def _request(self, method: str, path: str, data: Optional[Dict] = None) -> Tuple[bool, Any]:
        ok, err = self._authenticate()
        if not ok:
            return False, err
        try:
            response = self._auth_session.request(method=method, url=f'{self.API_ENDPOINT}{path}', json=data, timeout=30)
            if response.status_code >= 400:
                return False, response.reason
            return True, response.json() if response.text else None
        except requests.RequestException as e:
            return False, str(e)

    def create_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        relative = self.get_relative_record_name(record_name, domain)
        payload = {'name': relative, 'type': 'TXT', 'content': record_value}
        success, result = self._request('POST', f'/domains/{domain}/dns', payload)
        if not success:
            return False, f"Failed to create record: {result}"
        return True, "Record created successfully"

    def delete_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        success, result = self._request('GET', f'/domains/{domain}/dns')
        if not success:
            return False, f"Failed to list records: {result}"
        for rec in result.get('domains', [{}])[0].get('entries', []):
            if rec.get('type') == 'TXT' and rec.get('name') == self.get_relative_record_name(record_name, domain):
                self._request('DELETE', f'/dns/{rec["id"]}')
        return True, "Record deleted successfully"

    def test_connection(self) -> Tuple[bool, str]:
        success, result = self._request('GET', '/domains')
        if success:
            domains = result.get('domains', [])
            return True, f"Connected. Found {len(domains)} domain(s)"
        return False, f"Connection failed: {result}"

    @classmethod
    def get_credential_schema(cls):
        return [
            {'name': 'username', 'label': 'Username/Email', 'type': 'text', 'required': True},
            {'name': 'password', 'label': 'Password', 'type': 'password', 'required': True},
        ]

# Mooncake Transfer Engine implementation with configuration loading
import json
import logging
import os
from dataclasses import dataclass

logger = logging.getLogger(__name__)

@dataclass
class MooncakeTransferEngineConfig:
    local_hostname: str
    metadata_server: str
    protocol: str
    device_name: str

    @staticmethod
    def from_file(file_path: str) -> "MooncakeTransferEngineConfig":
        with open(file_path) as file:
            config_data = json.load(file)
        return MooncakeTransferEngineConfig(
            local_hostname=config_data.get("local_hostname", None),
            metadata_server=config_data.get("metadata_server"),
            protocol=config_data.get("protocol", "rdma"),
            device_name=config_data.get("device_name", ""),
        )

    @staticmethod
    def load_from_env() -> "MooncakeTransferEngineConfig":
        config_file_path = os.getenv("MOONCAKE_CONFIG_PATH", "/data/nvme1/yongyang/FL/LightX2V/configs/mooncake_config.json")
        if config_file_path is None:
            raise ValueError("The environment variable 'MOONCAKE_CONFIG_PATH' is not set.")
        return MooncakeTransferEngineConfig.from_file(config_file_path)

class MooncakeTransferEngine:
    def __init__(self):
        self.engine = None
        try:
            from mooncake.engine import TransferEngine
            self.engine = TransferEngine()
        except ImportError as error:
            logger.warning(
                "Please install mooncake by following the instructions at https://github.com/kvcache-ai/Mooncake/blob/main/docs/source/getting_started/build.md to run with MooncakeTransferEngine."
            )
            # We allow continuing without engine for non-transfer operations or testing structure

        try:
            self.config = MooncakeTransferEngineConfig.load_from_env()
            logger.info("Mooncake Configuration loaded successfully.")
        except Exception as exception:
            logger.error(f"Failed to load Mooncake config: {exception}")
            raise

        self.initialize(
            self.config.local_hostname,
            self.config.metadata_server,
            self.config.protocol,
            self.config.device_name,
        )

        self.session_id = f"{self.config.local_hostname}:{self.engine.get_rpc_port()}"

    def register(self, ptr, length):
        if self.engine:
            ret = self.engine.register_memory(ptr, length)
            if ret != 0:
                logger.error("Mooncake memory registration failed.")
                raise RuntimeError("Mooncake memory registration failed.")

    def deregister(self, ptr):
        if self.engine:
            ret = self.engine.unregister_memory(ptr)
            if ret != 0:
                logger.error("Mooncake memory deregistration failed.")
                raise RuntimeError("Mooncake memory deregistration failed.")

    def initialize(
        self,
        local_hostname: str,
        metadata_server: str,
        protocol: str,
        device_name: str,
    ) -> None:
        """Initialize the mooncake instance."""
        if self.engine:
            self.engine.initialize(local_hostname, metadata_server, protocol, device_name)

    def transfer_sync(self, session_id: str, buffer: int, peer_buffer_address: int, length: int) -> int:
        """Synchronously transfer data to the specified address."""
        if self.engine:
            ret = self.engine.transfer_sync_write(session_id, buffer, peer_buffer_address, length)
            if ret < 0:
                logger.error("Transfer Return Error")
                raise Exception("Transfer Return Error")
            return ret
        return -1

    def get_localhost(self):
        return self.config.local_hostname

    def get_session_id(self):
        return self.session_id

# SkillPay API client for billing operations
import json, sys, argparse, os
import urllib.request, urllib.error

BASE_URL = "https://skillpay.me/api/v1"
APP_ID = "66a1cf1e-9177-4fd9-a417-8917978118e3"

def _get_api_key(key=None):
    return key or os.environ.get("SKILLPAY_API_KEY")

def _make_post_request(endpoint, payload, api_key):
    url = f"{BASE_URL}{endpoint}"
    data = json.dumps(payload).encode()
    headers = {"Content-Type": "application/json", "X-API-Key": api_key}
    request = urllib.request.Request(url, data=data, headers=headers, method="POST")

    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            return json.loads(response.read())
    except urllib.error.HTTPError as error:
        return json.loads(error.read())

def _make_get_request(endpoint, api_key):
    url = f"{BASE_URL}{endpoint}"
    headers = {"X-API-Key": api_key}
    request = urllib.request.Request(url, headers=headers)

    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            return json.loads(response.read())
    except urllib.error.HTTPError as error:
        return json.loads(error.read())

def deduct_funds(user_id, cost=0.005, api_key=None):
    key = _get_api_key(api_key)
    if not key: 
        return {"success": False, "error": "SKILLPAY_API_KEY not configured"}

    result = _make_post_request("/billing/charge", {
        "user_id": user_id, 
        "skill_id": APP_ID, 
        "amount": cost,
        "currency": "USDT", 
        "description": "Prompt Artist"
    }, key)

    if result.get("success"): 
        return {"success": True, "deducted": cost, "details": result}

    return {
        "success": False, 
        "requires_payment": bool(result.get("payment_url")),
        "payment_url": result.get("payment_url", ""),
        "current_balance": result.get("balance", 0),
        "note": result.get("message", "transaction failed")
    }

def check_account_balance(user_id, api_key=None):
    key = _get_api_key(api_key)
    if not key: 
        return {"success": False, "error": "SKILLPAY_API_KEY not configured"}

    return {
        "success": True, 
        "info": _make_get_request(f"/billing/balance?user_id={user_id}", key)
    }

def generate_payment_url(user_id, amount=5.0, api_key=None):
    key = _get_api_key(api_key)
    if not key: 
        return {"success": False, "error": "SKILLPAY_API_KEY not configured"}

    return {
        "success": True, 
        "link_data": _make_post_request("/billing/payment-link", {
            "user_id": user_id, 
            "skill_id": APP_ID, 
            "Amount": amount
        }, key)
    }

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="SkillPay API Client")
    parser.add_argument("--user-id", required=True, help="User identifier")
    parser.add_argument("--amount", type=float, default=0.005)
    parser.add_argument("--api-key", default=None)

    action_group = parser.add_mutually_exclusive_group()
    action_group.add_argument("--deduct", action="store_true", default=True)
    action_group.add_argument("--check-balance", action="store_true")
    action_group.add_argument("--generate-payment", action="store_true")

    args = parser.parse_args()

    if args.check_balance:
        result = check_account_balance(args.user_id, args.api_key)
    elif args.generate_payment:
        result = generate_payment_url(args.user_id, args.amount or 5.0, args.api_key)
    else:
        result = deduct_funds(args.user_id, args.amount, args.api_key)

    print(json.dumps(result, indent=2, ensure_ascii=False))
    sys.exit(0 if result.get("success") else 1)

from typing import Any, ClassVar, cast
from klaude_code.core.tool.context import ToolContext
from klaude_code.protocol import llm_param, message, tools

def _normalize_schema_types(schema: dict[str, Any]) -> dict[str, Any]:
    """Recursively normalize JSON schema type values to lowercase.
    Some LLMs (e.g., Gemini 3) generate type values in uppercase like "OBJECT", "STRING".
    Standard JSON Schema requires lowercase type values.
    """
    normalized_result: dict[str, Any] = {}
    for field_key, field_value in schema.items():
        if field_key == "type" and isinstance(field_value, str):
            normalized_result[field_key] = field_value.lower()
        elif isinstance(field_value, dict):
            normalized_result[field_key] = _normalize_schema_types(cast(dict[str, Any], field_value))
        elif isinstance(field_value, list):
            processed_list: list[Any] = []
            for element in cast(list[Any], field_value):
                if isinstance(element, dict):
                    processed_list.append(_normalize_schema_types(cast(dict[str, Any], element)))
                else:
                    processed_list.append(element)
            normalized_result[field_key] = processed_list
        else:
            normalized_result[field_key] = field_value
    return normalized_result


class ReportBackTool:
    """Special tool for sub-agents to return structured output and end the task.
    This tool is dynamically injected when a parent agent calls a sub-agent with
    an output_schema. The schema for this tool's parameters is defined by the
    parent agent, allowing structured data to be returned.
    Note: This class does not inherit from ToolABC because it's not registered
    in the global tool registry. Instead, it's handled specially by the
    TurnExecutor and SubAgentManager.
    """
    _output_schema: ClassVar[dict[str, Any]] = {}

    @classmethod
    def create_with_schema(cls, schema: dict[str, Any]) -> type["ReportBackTool"]:
        """Create a tool class with the specified output schema.
        Args:
            schema: JSON Schema defining the expected structure of the report_back arguments.
        Returns:
            A new class with the schema set as a class variable.
        """
        normalized = _normalize_schema_types(schema)
        return type("ReportBackTool", (ReportBackTool,), {"_output_schema": normalized})

    @classmethod
    def get_tool_schema(cls) -> llm_param.ToolSchema:
        """Generate the tool schema for this report_back tool."""
        return llm_param.ToolSchema(
            name=tools.REPORT_BACK,
            type="function",
            description=(
                "Report the final structured result back to the parent agent. "
                "Call this when you have completed the task and want to return structured data. "
                "The task will end after this tool is called."
            ),
            parameters=cls._output_schema,
        )

    @classmethod
    async def execute(cls, arguments: str, context: ToolContext) -> message.ToolResultMessage:
        del arguments
        del context
        """Execute the report_back tool.
        The actual handling of report_back results is done by TurnExecutor.
        This method just returns a success status to maintain the tool call flow.
        """
        return message.ToolResultMessage(
            status="success",
            output_text="Result reported successfully. Task will end.",
        )

# Fill PDF form fields using JSON data
import json
import sys
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def populate_pdf_forms(input_file: str, json_data_path: str, output_file: str):
    with open(json_data_path) as file:
        field_data = json.load(file)

    organized_fields = {}
    for item in field_data:
        if "data_value" in item:
            field_identifier = item["field_id"]
            page_number = item["page"]
            if page_number not in organized_fields:
                organized_fields[page_number] = {}
            organized_fields[page_number][field_identifier] = item["data_value"]

    pdf_reader = PdfReader(input_file)
    encountered_issues = False
    form_fields = get_field_info(pdf_reader)
    field_map = {f["field_id"]: f for f in form_fields}

    for item in field_data:
        current_field = field_map.get(item["field_id"])
        if not current_field:
            encountered_issues = True
            print(f"ERROR: `{item['field_id']}` is not a valid field ID")
        elif item["page"] != current_field["page"]:
            encountered_issues = True
            print(
                f"ERROR: Incorrect page number for `{item['field_id']}` (got {item['page']}, expected {current_field['page']})"
            )
        else:
            if "data_value" in item:
                issue = check_field_value(current_field, item["data_value"])
                if issue:
                    print(issue)
                    encountered_issues = True

    if encountered_issues:
        sys.exit(1)

    pdf_writer = PdfWriter(clone_from=pdf_reader)
    for page_num, values in organized_fields.items():
        pdf_writer.update_page_form_field_values(pdf_writer.pages[page_num - 1], values, auto_regenerate=False)

    pdf_writer.set_need_appearances_writer(True)
    with open(output_file, "wb") as output:
        pdf_writer.write(output)

def check_field_value(field_details, provided_value):
    field_category = field_details["type"]
    field_name = field_details["field_id"]

    if field_category == "checkbox":
        selected_val = field_details["checked_value"]
        deselected_val = field_details["unchecked_value"]
        if provided_value != selected_val and provided_value != deselected_val:
            return f'ERROR: Invalid value "{provided_value}" for checkbox field "{field_name}". The checked value is "{selected_val}" and the unchecked value is "{deselected_val}"'

    elif field_category == "radio_group":
        available_options = [opt["value"] for opt in field_details["radio_options"]]
        if provided_value not in available_options:
            return f'ERROR: Invalid value "{provided_value}" for radio group field "{field_name}". Valid values are: {available_options}'

    elif field_category == "choice":
        available_choices = [opt["value"] for opt in field_details["choice_options"]]
        if provided_value not in available_choices:
            return (
                f'ERROR: Invalid value "{provided_value}" for choice field "{field_name}". Valid values are: {available_choices}'
            )

    return None

def apply_pypdf_patch():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject
    original_method = DictionaryObject.get_inherited

    def modified_get_inherited(self, key: str, default=None):
        result = original_method(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in result)
        ):
            result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = modified_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    apply_pypdf_patch()
    input_pdf_file = sys.argv[1]
    json_input_file = sys.argv[2]
    output_pdf_file = sys.argv[3]
    populate_pdf_forms(input_pdf_file, json_input_file, output_pdf_file)

