# Define exit codes for different error types
from enum import IntEnum

class StatusCode(IntEnum):
    OK = 0
    CONNECTION_ISSUE = 10
    PROCESSING_FAILURE = 20
    INPUT_CHECK_FAILED = 30
    STORAGE_PROBLEM = 40

class DataLoadException(Exception):
    status_code = StatusCode.PROCESSING_FAILURE

class ConnectionFailure(DataLoadException):
    status_code = StatusCode.CONNECTION_ISSUE

class ProcessingFailure(DataLoadException):
    status_code = StatusCode.PROCESSING_FAILURE

class InputCheckFailed(DataLoadException):
    status_code = StatusCode.INPUT_CHECK_FAILED

class StorageProblem(DataLoadException):
    status_code = StatusCode.STORAGE_PROBLEM

