# Script to search for viral TikTok videos and Instagram Reels using the ScrapeCreators API
import argparse
import os
import sys
import json
import requests
from typing import Optional, Dict

def retrieve_api_key(key_arg: Optional[str]) -> Optional[str]:
    if key_arg:
        return key_arg
    return os.environ.get("SCRAPE_CREATORS_API_KEY")

def fetch_data(url: str, parameters: dict, api_token: str) -> dict:
    headers = {"x-api-key": api_token}
    try:
        response = requests.get(url, headers=headers, params=parameters)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as error:
        print(json.dumps({"error": str(error)}), file=sys.stderr)
        return {}

def tiktok_search(keyword: str, mode: str, api_token: str) -> Dict:
    base_url = "https://api.scrapecreators.com/v1/tiktok/search/"
    endpoint = "keyword" if mode == "keyword" else "hashtag"
    url = f"{base_url}{endpoint}"

    request_params = {"query": keyword} if mode == "keyword" else {"hashtag": keyword.replace("#", "")}

    raw_data = fetch_data(url, request_params, api_token)
    video_list = raw_data.get("data", [])

    # Sort by view count descending to prioritize popular content
    ranked_videos = sorted(video_list, key=lambda v: v.get("stats", {}).get("playCount", 0), reverse=True)
    top_ranked = ranked_videos[:5]

    return {
        "search_term": keyword,
        "mode": mode,
        "top_entries": [
            {
                "link": f"https://www.tiktok.com/@{v.get('author', {}).get('uniqueId', 'unknown')}/video/{v.get('item_id', v.get('id', ''))}",
                "creator": v.get("author", {}).get("uniqueId", "unknown"),
                "description": v.get("desc", ""),
                "views": v.get("stats", {}).get("playCount", 0),
                "favorites": v.get("stats", {}).get("diggCount", 0)
            } for v in top_ranked
        ]
    }

def instagram_reels_search(keyword: str, api_token: str) -> Dict:
    # Instagram Reels search uses keyword-based query only
    url = "https://api.scrapecreators.com/v2/instagram/reels/search"
    params = {"query": keyword}

    raw_response = fetch_data(url, params, api_token)
    reels_list = raw_response.get("items", [])

    # Rank by play count
    ordered_reels = sorted(reels_list, key=lambda r: r.get("play_count", 0), reverse=True)
    leading_reels = ordered_reels[:5]

    return {
        "search_term": keyword,
        "mode": "keyword (reels)",
        "top_entries": [
            {
                "link": f"https://www.instagram.com/reel/{r.get('code')}/",
                "creator": r.get("user", {}).get("username", "unknown"),
                "caption": r.get("caption", {}).get("text", "") if r.get("caption") else "",
                "views": r.get("play_count", 0),
                "likes": r.get("like_count", 0)
            } for r in leading_reels
        ]
    }

def main():
    parser = argparse.ArgumentParser(description="Search TikTok videos or Instagram Reels by keyword or hashtag.")
    parser.add_argument("--platform", choices=["tiktok", "instagram"], required=True)
    parser.add_argument("--type", choices=["keyword", "hashtag"], required=True, help="Instagram currently supports keyword search for Reels only.")
    parser.add_argument("--query", required=True, help="Search term (e.g., 'travel tips' or '#nature')")
    parser.add_argument("--api-key", help="ScrapeCreators API Key")

    arguments = parser.parse_args()

    api_key = retrieve_api_key(arguments.api_key)
    if not api_key:
        print(json.dumps({"error": "SCRAPE_CREATORS_API_KEY environment variable is required."}), file=sys.stderr)
        sys.exit(1)

    if arguments.platform == "tiktok":
        result = tiktok_search(arguments.query, arguments.type, api_key)
    else:
        # Route Instagram searches to Reels regardless of type for video-focused results
        result = instagram_reels_search(arguments.query, api_key)

    print(json.dumps({
        "status": "success",
        "platform": arguments.platform,
        "search_results": result
    }, indent=2))

if __name__ == "__main__":
    main()

