from abc import ABCMeta, abstractmethod

def create_dir_if_not_exists(directory_name, permissions=0o777):
    if directory_name == "":
        return
    directory_name = path.expanduser(directory_name)
    os.makedirs(directory_name, mode=permissions, exist_ok=True)

def check_method_exists(instance, method_name):
    return hasattr(instance, method_name) and callable(getattr(instance, method_name))

class AbstractDataBackend(metaclass=ABCMeta):
    """Abstract base class for data storage backends.
    Every concrete backend must implement two core methods: :meth:`retrieve()` and
    :meth:`retrieve_text()`.
    - :meth:`retrieve()` loads the file content as binary data (bytes).
    - :meth:`retrieve_text()` loads the file content as string data.
    """
    # Flag to indicate if the backend supports creating symbolic links
    # This property will be removed in upcoming versions.
    _supports_symlink = False

    @property
    def supports_symlink(self):
        return self._supports_symlink

    @property
    def backend_name(self):
        return self.__class__.__name__

    @abstractmethod
    def retrieve(self, file_path):
        pass

    @abstractmethod
    def retrieve_text(self, file_path):
        pass

