# Import necessary modules for system operations, regex matching, and date handling
import sys
import re
from datetime import datetime

# Mapping of month names to their numeric representations
MONTH_MAPPING = {
    'january': 1, 'february': 2, 'march': 3, 'april': 4,
    'may': 5, 'june': 6, 'july': 7, 'august': 8,
    'september': 9, 'october': 10, 'november': 11, 'december': 12,
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'sept': 9, 'oct': 10,
    'nov': 11, 'dec': 12
}

# List of supported date format patterns
DATE_PATTERNS = [
    '%B %d, %Y', '%b %d, %Y',
    '%d %B %Y', '%d %b %Y',
    '%m/%d/%Y', '%d/%m/%Y',
    '%Y-%m-%d', '%Y/%m/%d'
]

def convert_date(date_input: str) -> str:
    """Convert various date string formats into ISO standard (YYYY-MM-DD)."""
    date_input = date_input.strip()

    # Attempt parsing using predefined date formats
    for fmt in DATE_PATTERNS:
        try:
            parsed_dt = datetime.strptime(date_input, fmt)
            return parsed_dt.strftime('%Y-%m-%d')
        except ValueError:
            continue

    # Fallback: Use regex to extract month name, day, and year
    regex_pattern = r'(\w+)\s+(\d{1,2}),?\s+(\d{4})'
    match = re.search(regex_pattern, date_input, re.IGNORECASE)
    if match:
        month_str, day_str, year_str = match.groups()
        month_num = MONTH_MAPPING.get(month_str.lower())
        if month_num is not None:
            return f'{year_str}-{month_num:02d}-{int(day_str):02d}'

    return ''

def convert_time(time_input: str) -> str:
    """Convert various time string formats into HH:MM format."""
    if not time_input:
        return ''

    time_input = time_input.strip()

    # Pattern for HH:MM with optional AM/PM
    time_regex1 = r'(\d{1,2}):(\d{2})\s*(am|pm)?'
    match = re.search(time_regex1, time_input, re.IGNORECASE)
    if match:
        hour_val, minute_val, ampm_val = int(match.group(1)), int(match.group(2)), match.group(3)
        if ampm_val:
            ampm_val = ampm_val.lower()
            if ampm_val == 'pm' and hour_val != 12:
                hour_val += 12
            elif ampm_val == 'am' and hour_val == 12:
                hour_val = 0
        return f'{hour_val:02d}:{minute_val:02d}'

    # Pattern for H (no minutes) with AM/PM
    time_regex2 = r'(\d{1,2})\s*(am|pm)'
    match = re.search(time_regex2, time_input, re.IGNORECASE)
    if match:
        hour_val, ampm_val = int(match.group(1)), match.group(2).lower()
        if ampm_val == 'pm' and hour_val != 12:
            hour_val += 12
        elif ampm_val == 'am' and hour_val == 12:
            hour_val = 0
        return f'{hour_val:02d}:00'

    return ''

def main():
    if len(sys.argv) < 3:
        print("Usage: date_parser.py <date|time> <value>", file=sys.stderr)
        sys.exit(1)

    operation_mode = sys.argv[1]
    input_value = sys.argv[2]

    if operation_mode == 'date':
        print(convert_date(input_value))
    elif operation_mode == 'time':
        print(convert_time(input_value))
    else:
        print(f"Unknown mode: {operation_mode}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

import os
from pathlib import Path
from typing import Optional

def _normalize_path_separators(path_str: str) -> str:
    """Convert backslashes to forward slashes on Windows systems."""
    return path_str.replace("\\", "/") if os.name == "nt" else path_str

def get_relative_file_path(project_root: Path, file_path: str) -> Optional[str]:
    """Compute the relative path of a file with respect to the project root.

    Args:
        project_root (Path): The root directory of the Lean project.
        file_path (str): The absolute or relative path to the file.

    Returns:
        Optional[str]: The relative path using forward slashes, or None if not possible.
    """
    file_obj = Path(file_path)

    # Case 1: Absolute path that exists
    if file_obj.is_absolute() and file_obj.exists():
        try:
            rel_path = file_obj.relative_to(project_root)
            return _normalize_path_separators(str(rel_path))
        except ValueError:
            return None

    # Case 2: Relative to project root
    candidate_path = project_root / file_path
    if candidate_path.exists():
        try:
            rel_path = candidate_path.relative_to(project_root)
            return _normalize_path_separators(str(rel_path))
        except ValueError:
            return None

    # Case 3: Relative to current working directory, but must be inside project root
    cwd = Path.cwd()
    cwd_candidate = cwd / file_path
    if cwd_candidate.exists():
        try:
            resolved_path = cwd_candidate.resolve()
            rel_path = resolved_path.relative_to(project_root)
            return _normalize_path_separators(str(rel_path))
        except ValueError:
            return None

    return None

def read_file_content(abs_path: str) -> str:
    """Read file content trying multiple encodings.

    Args:
        abs_path (str): Absolute path to the file.

    Returns:
        str: File contents, decoded with appropriate encoding.
    """
    for encoding in ("utf-8", "latin-1"):
        try:
            with open(abs_path, "r", encoding=encoding) as file:
                return file.read()
        except UnicodeDecodeError:
            continue

    # Fallback: use utf-8 with error replacement
    with open(abs_path, "r", encoding="utf-8", errors="replace") as file:
        return file.read()

