# Modified version of DiffusersAEModel with renamed variables and reordered logic
import importlib
import warnings
from abc import abstractmethod

import torch
import torch.nn as nn
from diffusers.utils.accelerate_utils import apply_forward_hook


class DiffusersAEModel(nn.Module):
    """
    Support importing AutoEncoder from diffusers
    """

    def __init__(self, model_name, config_dict):
        super().__init__()
        module = importlib.import_module("diffusers")
        auto_class = getattr(module, model_name)
        self.model_id = model_name
        self.autoencoder = auto_class.from_pretrained(
            config_dict["from_pretrained"], 
            torch_dtype=config_dict.pop("dtype", None)
        )
        self.sample_flag = config_dict.get("do_sample", True)

        # Tiling configuration
        self._use_tiling = False  # True: use custom tiling; False: disable or use built-in tiling
        enable_tile = config_dict.pop("enable_tiling", False)
        self.tile_config = None
        if enable_tile:
            self.activate_tiling(tiling_options=config_dict.get("tiling_param", None))

        # Latent normalization settings
        # In diffusers, model.encode does not normalize latent at last; normalization is done elsewhere.
        # This implementation merges normalization into AE.encode.
        # Modes:
        # 1. value_shift_scale: (output - shift_factor) * scaling_factor
        # 2. channel_specified_shift_scale: (output - latents_mean) / latents_std
        self.apply_normalization = config_dict.pop("norm_latents", True)
        self.norm_strategy = config_dict.pop("norm_mode", "value_shift_scale")

    def activate_tiling(self, tiling_options=None):
        if hasattr(self.autoencoder, "enable_tiling"):
            if tiling_options:
                self.autoencoder.enable_tiling(**tiling_options)
                self.tile_config = tiling_options
            else:
                self.autoencoder.enable_tiling()
        else:
            self._use_tiling = True
            self.tile_config = tiling_options if tiling_options else self.tile_config
            warnings.warn(
                f"The autoencoder {self.model_id} in the diffusers library lacks native tiling support. "
                "Please ensure to call the custom tiling method to enable tiling. "
            )

    def deactivate_tiling(self):
        if hasattr(self.autoencoder, "disable_tiling"):
            self.autoencoder.disable_tiling()
        else:
            self._use_tiling = False

    @apply_forward_hook
    def encode(self, input_tensor, **kwargs):
        if self._use_tiling:
            result = self.custom_tiled_encode(input_tensor, **kwargs)
        else:
            result = self.autoencoder.encode(input_tensor, return_dict=True, **kwargs)
            if self.sample_flag:
                result = result.latent_dist.sample()
            else:
                result = result.latent_dist.mode()

        if self.apply_normalization:
            result = self.normalize_encoding(result)

        return result

    @abstractmethod
    def custom_tiled_encode(self, x, **kwargs):
        pass

    def normalize_encoding(self, latent_tensor):
        if self.norm_strategy == "value_shift_scale":
            if getattr(self.autoencoder.config, "shift_factor", None):
                normalized = (
                    latent_tensor - self.autoencoder.config.shift_factor
                ) * self.autoencoder.config.scale_factor
            else:
                normalized = latent_tensor * self.autoencoder.config.scale_factor
        elif self.norm_strategy == "channel_specified_shift_scale":
            mean_tensor = (
                torch.tensor(self.autoencoder.config.latents_mean).view(1, -1, 1, 1, 1).to(latent_tensor)
            )  # b c t h w
            std_tensor = (
                torch.tensor(self.autoencoder.config.latents_std).view(1, -1, 1, 1, 1).to(latent_tensor)
            )
            normalized = (latent_tensor - mean_tensor) / std_tensor
        else:
            raise NotImplementedError(
                f"Normalization strategy '{self.norm_strategy}' is not supported."
            )
        return normalized

    @apply_forward_hook
    def decode(self, latent_input, **kwargs):
        if self._use_tiling:
            return self.autoencoder.tiled_decode(latent_input).sample
        else:
            return self.autoencoder.decode(latent_input).sample

    @abstractmethod
    def custom_tiled_decode(self, x, **kwargs):
        pass

