# ADMET rule-based analysis using RDKit
import argparse
import json
import sys
from rdkit import Chem
from rdkit.Chem import Descriptors

def lipinski_rules(molecule):
    acceptors = Descriptors.NumHAcceptors(molecule)
    donors = Descriptors.NumHDonors(molecule)
    molecular_weight = Descriptors.MolWt(molecule)
    octanol_water = Descriptors.MolLogP(molecule)
    count_violations = sum([acceptors > 10, donors > 5, molecular_weight > 500, octanol_water > 5])
    return {"hba": acceptors, "hbd": donors, "mw": molecular_weight, "logp": octanol_water, "ro5_violations": count_violations}

def veber_rules(molecule):
    rotatable_bonds = Descriptors.NumRotatableBonds(molecule)
    polar_surface_area = Descriptors.TPSA(molecule)
    count_violations = sum([rotatable_bonds > 10, polar_surface_area > 140])
    return {"rotb": rotatable_bonds, "tpsa": polar_surface_area, "veber_violations": count_violations}

def substructure_alerts(molecule):
    smiles_string = Chem.MolToSmiles(molecule)
    alert_patterns = ['c1ncnc2c1ncn2', 'cc1ccc2nsnc2c1']  # example PAINS
    detected_alerts = [pattern for pattern in alert_patterns if pattern in smiles_string]
    return {"pains_alerts": detected_alerts, "num_alerts": len(detected_alerts)}

def main():
    argument_parser = argparse.ArgumentParser(description="RDKit ADMET rule-based")
    argument_parser.add_argument("--smiles", required=True)
    argument_parser.add_argument("--target_smiles", help="Batch comma-separated list")
    parsed_args = argument_parser.parse_args()

    def analyze(smiles_input):
        molecule = Chem.MolFromSmiles(smiles_input)
        if molecule is None:
            return {"smiles": smiles_input, "error": "Invalid"}
        return {"smiles": smiles_input, **lipinski_rules(molecule), **veber_rules(molecule), **substructure_alerts(molecule)}

    if parsed_args.target_smiles:
        output_results = [analyze(s.strip()) for s in parsed_args.target_smiles.split(",")]
        print(json.dumps({"screen": output_results}))
    else:
