# Modified version of the wrapper example with renamed variables and reordering
from areal.utils.wrapper import (
    wrap,
    wrap_get_method,
    wrap_get_method_name,
    wrap_remove_meta,
    wrapable,
)

class Arithmometer:
    def __init__(self):
        self.offset = 2

    @wrapable()
    def plus(self, val1, val2):
        return val1 + val2 + self.offset

    @wrapable(name="times")
    def times(self, factor1, factor2):
        return factor1 * factor2 * self.offset

class SuperArithmometer:
    def __init__(self, base_obj: Arithmometer):
        super().__init__()
        self.label = "Output:"
        self.base = base_obj
        wrap(self, base_obj, self._intercept_call)

    def _intercept_call(self, *arguments, **keywords):
        func_name = wrap_get_method_name(keywords)
        func_ref = wrap_get_method(keywords)
        keywords = wrap_remove_meta(keywords)
        print("wrapped function:", func_name)
        print("wrapped function:", func_ref)
        return func_ref(*arguments, **keywords)

def run_test():
    arith = Arithmometer()
    enhanced = SuperArithmometer(arith)
    assert enhanced.plus(2, 3) == 7
    assert enhanced.times(4, 5) == 40

if __name__ == "__main__":
    run_test()

import asyncio
import random
import aiohttp
from miles.utils.misc import load_function
from miles.utils.types import Sample
from .deepscaler import get_deepscaler_rule_based_reward
from .f1 import f1_score
from .gpqa import compute_gpqa_reward
from .math_dapo_utils import compute_score as compute_score_dapo
from .math_utils import extract_answer as extract_boxed_answer
from .math_utils import grade_answer_verl

async def remote_rm(config, item: Sample):
    data = {
        "prompt": item.prompt,
        "response": item.response,
        "label": item.label,
    }
    session_opts = {}
    async with aiohttp.ClientSession(**session_opts) as sess:
        async with sess.post(config.rm_url, json=data) as response:
            response.raise_for_status()
            return await response.json()

async def async_rm(config, item: Sample, **kwargs):
    if config.custom_rm_path is not None:
        rm_func = load_function(config.custom_rm_path)
        return await rm_func(config, item, **kwargs)

    meta = item.metadata if isinstance(item.metadata, dict) else {}
    rm_kind = (meta.get("rm_type") or config.rm_type or "").strip()
    model_response = item.response
    ground_truth = item.label

    if rm_kind.startswith("boxed_"):
        model_response = extract_boxed_answer(model_response) or ""
        rm_kind = rm_kind[len("boxed_"):]

    # This function is intended for remote or time-consuming reward model evaluation.
    # Implement the actual logic as needed.
    if rm_kind == "remote_rm":
        return await remote_rm(config, item)
    elif rm_kind == "deepscaler":
        return get_deepscaler_rule_based_reward(model_response, ground_truth)
    elif rm_kind == "dapo":
        return compute_score_dapo(model_response, ground_truth)
    elif rm_kind == "math":
        return 1 if grade_answer_verl(model_response, ground_truth) else 0
    elif rm_kind == "f1":
        return f1_score(model_response, ground_truth)[0]
    elif rm_kind == "gpqa":
        return compute_gpqa_reward(model_response, ground_truth, metadata=meta)
    elif rm_kind == "ifbench":
        from .ifbench import compute_ifbench_reward
        return compute_ifbench_reward(model_response, ground_truth, metadata=meta)
    elif rm_kind == "random":
        return random.randint(0, 1)
    elif rm_kind:
        raise NotImplementedError(f"Rule-based RM for {rm_kind} is not implemented.")
    else:
        raise NotImplementedError("Rule-based RM type is not specified.")

async def batched_async_rm(
    config,
    items: list[Sample],
    inplace_set_reward_field: bool = False,
    **kwargs,
) -> list[int | float] | None:
    if inplace_set_reward_field:
        rewards = await batched_async_rm(config, items, **kwargs)
        for sample_item, reward_val in zip(items, rewards, strict=True):
            assert (
                sample_item.reward is None
            ), f"Overriding sample_item.reward from {sample_item.reward} to {reward_val}, is this intended?"
            sample_item.reward = reward_val
        return None

    if config.custom_rm_path is not None:
        # Ensure the custom reward function is implemented in batch mode
        rm_func = load_function(config.custom_rm_path)
        return await rm_func(config, items, **kwargs)

    tasks = [async_rm(config, item, **kwargs) for item in items]
    results = await asyncio.gather(*tasks)
    return results

# Image generation script using Volcengine Seedream API
import argparse
import json
import os
import sys
import requests

def create_image(prompt, model_name, resolution, token, base_image=None, batch_mode=False, limit=1):
    endpoint = "https://ark.cn-beijing.volces.com/api/v3/images/generations"
    auth_headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {token}"
    }

    request_body = {
        "model": model_name,
        "prompt": prompt,
        "size": resolution,
    }

    if base_image:
        request_body["image"] = base_image

    if batch_mode:
        request_body["sequential_image_generation"] = "auto"
        request_body["sequential_image_generation_options"] = {"max_images": limit}
    else:
        request_body["sequential_image_generation"] = "disabled"

    try:
        api_response = requests.post(endpoint, headers=auth_headers, json=request_body)
        api_response.raise_for_status()
        response_data = api_response.json()

        if "data" in response_data and len(response_data["data"]) > 0:
            for entry in response_data["data"]:
                if "url" in entry:
                    print(f"MEDIA_URL: {entry['url']}")
                elif "b64_json" in entry:
                    # In a real scenario, we might want to save this to a file, 
                    # but for this skill we follow the pattern of providing a URL if possible.
                    print("ERROR: Received base64 data but expected URL.")
        else:
            print(f"ERROR: No image data in response. Full response: {json.dumps(response_data)}")

    except requests.exceptions.RequestException as error:
        print(f"ERROR: API request failed: {error}")
        if hasattr(error, 'response') and error.response is not None:
            print(f"Response body: {error.response.text}")
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description="Generate images using Volcengine Seedream API.")
    parser.add_argument("--prompt", required=True, help="Text prompt for image generation")
    parser.add_argument("--model", default="doubao-seedream-4-5-251128", help="Model ID or Endpoint ID")
    parser.add_argument("--resolution", default="2048x2048", help="Image size (e.g., 2K, 4K, 2048x2048)")
    parser.add_argument("--api-key", help="Volcengine API Key")
    parser.add_argument("--input-image", help="Input image URL or base64 (optional)")
    parser.add_argument("--batch", action="store_true", help="Enable sequential/batch image generation")
    parser.add_argument("--limit", type=int, default=1, help="Max images for batch generation (1-15)")
    arguments = parser.parse_args()

    token = arguments.api_key or os.environ.get("VOLC_API_KEY")
    if not token:
        print("ERROR: API key is required. Provide via --api-key or VOLC_API_KEY environment variable.")
        sys.exit(1)

    create_image(
        prompt=arguments.prompt,
        model_name=arguments.model,
        resolution=arguments.resolution,
        token=token,
        base_image=arguments.input_image,
        batch_mode=arguments.batch,
        limit=arguments.limit
    )

if __name__ == "__main__":
    main()

