# Custom import path for processing utilities
from ...processing_utils import ProcessorMixin

class WhisperProcessor(ProcessorMixin):
    r"""
    Constructs a Whisper processor which wraps a Whisper feature extractor and a Whisper tokenizer into a single
    processor.
    [`WhisperProcessor`] offers all the functionalities of [`WhisperFeatureExtractor`] and [`WhisperTokenizer`]. See
    the [`~WhisperProcessor.__call__`] and [`~WhisperProcessor.decode`] for more information.
    Args:
        feature_extractor (`WhisperFeatureExtractor`):
            An instance of [`WhisperFeatureExtractor`]. The feature extractor is a required input.
        tokenizer (`WhisperTokenizer`):
            An instance of [`WhisperTokenizer`]. The tokenizer is a required input.
    """
    feature_extractor_class = "WhisperFeatureExtractor"
    tokenizer_class = "WhisperTokenizer"

    def __init__(self, feature_extractor, tokenizer):
        super().__init__(feature_extractor, tokenizer)
        self.active_processor = self.feature_extractor
        self._inside_context_manager = False

    def get_decoder_prompt_ids(self, task=None, language=None, no_timestamps=True):
        return self.tokenizer.get_decoder_prompt_ids(task=task, language=language, no_timestamps=no_timestamps)

    def __call__(self, *args, **kwargs):
        """
        Forwards the `audio` argument to WhisperFeatureExtractor's [`~WhisperFeatureExtractor.__call__`] and the `text`
        argument to [`~WhisperTokenizer.__call__`]. Please refer to the doctsring of the above two methods for more
        information.
        """
        # Maintain backward compatibility
        if self._inside_context_manager:
            return self.active_processor(*args, **kwargs)

        audio_input = kwargs.pop("audio", None)
        sample_rate = kwargs.pop("sampling_rate", None)
        text_input = kwargs.pop("text", None)

        if len(args) > 0:
            audio_input = args[0]
            args = args[1:]

        if audio_input is None and text_input is None:
            raise ValueError("You need to specify either an `audio` or `text` input to process.")

        if audio_input is not None:
            audio_features = self.feature_extractor(audio_input, *args, sampling_rate=sample_rate, **kwargs)

        if text_input is not None:
            text_encodings = self.tokenizer(text_input, **kwargs)

        if text_input is None:
            return audio_features
        elif audio_input is None:
            return text_encodings
        else:
            audio_features["labels"] = text_encodings["input_ids"]
            return audio_features

    def batch_decode(self, *args, **kwargs):
        """
        This method forwards all its arguments to WhisperTokenizer's [`~PreTrainedTokenizer.batch_decode`]. Please
        refer to the docstring of this method for more information.
        """
        return self.tokenizer.batch_decode(*args, **kwargs)

    def decode(self, *args, **kwargs):
        """
        This method forwards all its arguments to WhisperTokenizer's [`~PreTrainedTokenizer.decode`]. Please refer to
        the docstring of this method for more information.
        """
        return self.tokenizer.decode(*args, **kwargs)

    def get_prompt_ids(self, text: str, return_tensors="np"):
        return self.tokenizer.get_prompt_ids(text, return_tensors=return_tensors)

# Index skills using Azure OpenAI embeddings
import os
import json
import hashlib
from typing import List, Dict, Any
from openai import AzureOpenAI

class SkillsIndexer:
    def __init__(self, azure_endpoint: str, azure_api_key: str):
        self.client = AzureOpenAI(
            api_version="2024-08-01-preview",
            azure_endpoint=azure_endpoint,
            api_key=azure_api_key
        )
        self.embedding_model_name = "text-embedding-ada-002"
        self.vector_dimension = 1536

    def create_embedding(self, text_input: str) -> List[float]:
        """Generate embedding vector for input text."""
        try:
            response = self.client.embeddings.create(
                input=text_input,
                model=self.embedding_model_name
            )
            return response.data[0].embedding
        except Exception as error:
            print(f"Error generating embedding: {error}")
            return [0.0] * self.vector_dimension

    def format_skill_content(self, skill_data: Dict[str, Any]) -> str:
        """Format skill data into a single text string for embedding."""
        sections = []
        if skill_data.get('title'):
            sections.append(f"Title: {skill_data['title']}")
        if skill_data.get('description'):
            sections.append(f"Description: {skill_data['description']}")
        if skill_data.get('content'):
            # Limit content length to prevent exceeding token limits
            content_snippet = skill_data['content'][:2000]
            sections.append(f"Content: {content_snippet}")
        if skill_data.get('tags'):
            sections.append(f"Tags: {', '.join(skill_data['tags'])}")
        if skill_data.get('domain'):
            sections.append(f"Domain: {skill_data['domain']}")

        return "\n".join(sections)

    def compute_skill_hash(self, skill_data: Dict[str, Any]) -> str:
        """Create unique identifier for skill using content hash."""
        content_string = f"{skill_data.get('title', '')}{skill_data.get('repo', '')}{skill_data.get('path', '')}"
        return hashlib.sha256(content_string.encode()).hexdigest()[:16]

    def process_skills_in_batches(self, skills_list: List[Dict[str, Any]], batch_limit: int = 50) -> List[Dict[str, Any]]:
        """Process and index multiple skills in batches."""
        processed_items = []

        total_batches = (len(skills_list) - 1) // batch_limit + 1
        for idx in range(0, len(skills_list), batch_limit):
            current_batch = skills_list[idx:idx + batch_limit]
            batch_number = idx // batch_limit + 1
            print(f"Processing batch {batch_number}/{total_batches}...")

            for skill_item in current_batch:
                formatted_text = self.format_skill_content(skill_item)
                vector = self.create_embedding(formatted_text)

                indexed_entry = {
                    'id': self.compute_skill_hash(skill_item),
                    'title': skill_item.get('title', 'Untitled'),
                    'content': skill_item.get('content', ''),
                    'embedding': vector,
                    'metadata': {
                        'source': skill_item.get('source', 'github'),
                        'repo': skill_item.get('repo', ''),
                        'path': skill_item.get('path', ''),
                        'tags': skill_item.get('tags', []),
                        'domain': skill_item.get('domain', ''),
                    }
                }
                processed_items.append(indexed_entry)

        return processed_items

# Scan for platform-specific patterns in files
import re
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parents[1]
SCAN_PATTERNS = {
    "bash_shebang": re.compile(r"^#!.*\b(bash|sh)\b"),
    "privilege_commands": re.compile(r"\b(chown|chmod|id -u|id -g)\b"),
    "audio_server": re.compile(r"\b(pulseaudio|pactl)\b"),
    "service_manager": re.compile(r"\bs6-"),
    "local_socket": re.compile(r"unix:"),
    "container_config": re.compile(
        r"docker[- ]?compose|Dockerfile|docker-compose.yml", re.IGNORECASE
    ),
}
FINDINGS = []

for item in BASE_DIR.rglob("*"):
    if item.is_file() and item.suffix in (".sh", ".py", ""):
        try:
            content = item.read_text(encoding="utf-8", errors="ignore")
        except Exception:
            continue

        for label, pattern in SCAN_PATTERNS.items():
            if pattern.search(content):
                FINDINGS.append((label, str(item)))

if not FINDINGS:
    print("No matching platform-specific patterns detected.")
else:
    print("Platform-specific scan results:")
    grouped = {}
    for tag, filepath in FINDINGS:
        grouped.setdefault(tag, []).append(filepath)

    for tag, files in grouped.items():
        print(f"\n[{tag}]")
        for f in files[:30]:
            print(" -", f)
        if len(files) > 30:
            print("  ... and more")

