# Define basic arithmetic and number theory tools
@tool
def calculate_sum(x: int, y: int) -> int:
    """Compute the sum of two integers."""
    return x + y

@tool
def calculate_product(x: int, y: int) -> int:
    """Compute the product of two integers."""
    return x * y

@tool
def check_prime(value: int) -> bool:
    """Determine whether a given integer is a prime number."""
    if value < 2:
        return False
    return all(value % divisor != 0 for divisor in range(2, int(value**0.5) + 1))

@tool
def find_prime_by_index(position: int) -> int:
    """Retrieve the prime number at the specified 1-based index."""
    if position < 1:
        return 0
    found_count = 0
    candidate = 2
    while found_count < position:
        if check_prime(candidate):
            found_count += 1
            if found_count == position:
                return candidate
        candidate += 1
    return candidate

# Main asynchronous function to run the agent
async def run_experiment():
    # Initialize the planning-and-execution agent with available tools
    planner_agent = PlanAndExecuteAgent(
        name="planner_executor_demo",
