# AI Note Task Creation Script
import os
import sys
import json
import requests
from typing import Dict, Any

def generate_ai_note_task(api_token: str, media_url: str) -> Dict[str, Any]:
    """Initialize an AI-powered note generation task.

    Args:
        api_token: Baidu API authentication token
        media_url: Accessible video URL for processing

    Returns:
        Task metadata including task identifier

    Raises:
        RuntimeError: When API call fails or returns error status
    """
    endpoint = "https://qianfan.baidubce.com/v2/tools/ai_note/task_create"
    request_headers = {
        "Authorization": f"Bearer {api_token}",
        "X-Appbuilder-From": "openclaw",
        "Content-Type": "application/json"
    }
    payload = {"url": media_url}

    try:
        response = requests.post(endpoint, headers=request_headers, json=payload, timeout=30)
        response.raise_for_status()
        api_response = response.json()

        if "code" in api_response:
            raise RuntimeError(api_response.get("detail", "API encountered an issue"))

        if "errno" in api_response and api_response["errno"] != 0:
            raise RuntimeError(api_response.get("errmsg", "Undefined error occurred"))

        return api_response["data"]

    except requests.exceptions.Timeout:
        raise RuntimeError("Connection timed out. The provided video URL might be unreachable.")
    except requests.exceptions.RequestException as network_error:
        raise RuntimeError(f"Network communication failed: {str(network_error)}")

def execute_main():
    # Validate command line arguments
    if len(sys.argv) < 2:
        print(json.dumps({
            "error": "Video URL parameter missing",
            "usage": "python ai_notes_task_create.py <video_url>"
        }, indent=2))
        sys.exit(1)

    video_source = sys.argv[1]
    credentials = os.getenv("BAIDU_API_KEY")

    # Verify API key availability
    if not credentials:
        print(json.dumps({
            "error": "BAIDU_API_KEY environment variable is not configured"
        }, indent=2))
        sys.exit(1)

    try:
        task_info = generate_ai_note_task(credentials, video_source)
        print(json.dumps({
            "status": "success",
            "message": "Task initialized successfully",
            "task_id": task_info.get("task_id"),
            "next_step": f"Monitor task progress: python ai_notes_task_query.py {task_info.get('task_id')}"
        }, indent=2))

    except RuntimeError as operational_error:
        print(json.dumps({
            "status": "error",
            "error": str(operational_error)
        }, indent=2))
        sys.exit(1)

    except Exception as unexpected_error:
        print(json.dumps({
            "status": "error",
            "error": f"Unexpected exception: {str(unexpected_error)}"
        }, indent=2))
        sys.exit(1)

if __name__ == "__main__":
    execute_main()

