import importlib

# Mapping of public attributes to their module paths and attribute names
_LAZY_IMPORTS = {
    "NeMoAutoDiffusionPipeline": (".auto_diffusion_pipeline", "NeMoAutoDiffusionPipeline"),
    "PipelineSpec": (".auto_diffusion_pipeline", "PipelineSpec"),
}

# Exported symbols in sorted order
