class TradeOrder:
    """Represents a trading order"""
    def __init__(self, order_kind, transaction_side, quantity, rate=None):
        if order_kind not in ['market', 'limit']:
            raise ValueError(
                "Order kinds can only be of type ['market', 'limit'], but was given: {}".format(order_kind))
        self.kind = order_kind
        if transaction_side not in ['buy', 'sell']:
            raise ValueError("Order side can only be of type ['buy', 'sell'], but was given: {}".format(order_kind))
        self.side = transaction_side
        if quantity <= 0:
            raise ValueError("Quantity must be greater than zero, but was given: {}".format(quantity))
        self.quantity = quantity
        if self.kind == 'limit' and rate is None:
            raise ValueError("Limit orders require a rate but None was given")
        if rate <= 0:
            raise ValueError("Rate must be greater than zero but was given: {}".format(rate))
        self.rate = rate

import torch
from diffusers.utils.torch_utils import randn_tensor
from diffusers.pipelines import DiffusionPipeline

class MMPipeline(DiffusionPipeline):
    def prepare_latents(self, tensor_shape, rng_generator, target_device, tensor_dtype, input_latents=None):
        if input_latents is None:
            input_latents = randn_tensor(tensor_shape, generator=rng_generator, device=target_device, dtype=tensor_dtype)
        else:
            input_latents = input_latents.to(target_device)
        if hasattr(self.scheduler, "init_noise_sigma"):
            # scale the initial noise by the standard deviation required by the scheduler
            input_latents = input_latents * self.scheduler.init_noise_sigma
        return input_latents

    def decode_latents(self, latent_input, value_bounds=(-1, 1), apply_normalization=True, **extra_kwargs):
        video_output = self.vae.decode(latent_input, **extra_kwargs)  # [b, c, t, h, w]
        if apply_normalization:
            low_val, high_val = value_bounds
            video_output.clamp_(min=low_val, max=high_val)
            video_output.sub_(low_val).div_(max(high_val - low_val, 1e-5))
        # [b, c, t, h, w] --> [b, t, h, w, c]
        video_output = video_output.mul(255).add_(0.5).clamp_(0, 255).permute(0, 2, 3, 4, 1).to("cpu", torch.uint8)
        return video_output

