from typing import Iterable, List
import attr

@attr.s
class FilterState:
    """A filter state instance."""
    idd: int = attr.ib()
    enabled: bool = attr.ib()

@attr.s
class CmStatus:
    provisioningStatus: str = attr.ib()
    cmComment: str = attr.ib()

def filter_entries(entries: Iterable[CmStatus], filter_state: FilterState) -> List[CmStatus]:
    if not filter_state.enabled:
        return list(entries)

    result = []
    for entry in entries:
        if len(entry.cmComment) > filter_state.idd:
            result.append(entry)
    return result

# Apache Beam pipeline to compute average age of adults (>=18 years old) from CSV data

import apache_beam as beam
from apache_beam.options.pipeline_options import PipelineOptions
import csv

class AdultFilter(beam.DoFn):
    def process(self, record):
        # Check if age is 18 or above and yield valid records
        if int(record['age']) >= 18:
            yield record

class AgeStatsCombiner(beam.CombineFn):
    def create_accumulator(self):
        # Initialize with zero sum and zero count
        return (0.0, 0)

    def add_input(self, acc, item):
        # Add current item's age to sum and increment count
        total_age, count = acc
        return (total_age + int(item['age']), count + 1)

    def merge_accumulators(self, partials):
        # Combine multiple accumulators by summing totals and counts
        totals, counts = zip(*partials)
        return (sum(totals), sum(counts))

    def extract_output(self, final_acc):
        # Compute average only if there are entries; otherwise return 0
        total, count = final_acc
        return total / count if count > 0 else 0

def execute_pipeline(source_path, dest_path):
    # Set up pipeline options
    opts = PipelineOptions()

    with beam.Pipeline(options=opts) as pipeline:
        # Read text lines, skip header row
        raw_lines = pipeline | 'LoadCSVData' >> beam.io.ReadFromText(
            source_path, 
            skip_header_lines=1
        )

        # Parse each line into a dictionary using CSV DictReader
        parsed_data = raw_lines | 'ConvertToDict' >> beam.Map(
            lambda line: next(csv.DictReader([line], fieldnames=['id', 'name', 'age']))
        )

        # Filter only adult records (age >= 18)
        adults_only = parsed_data | 'SelectAdults' >> beam.ParDo(AdultFilter())

        # Compute global average age across all adult records
        avg_adult_age = adults_only | 'ComputeAvgAge' >> beam.CombineGlobally(AgeStatsCombiner())

        # Write result to output file
        avg_adult_age | 'SaveResults' >> beam.io.WriteToText(dest_path)

if __name__ == '__main__':
    input_file = 'input.csv'
    output_file = 'output.csv'
    execute_pipeline(input_file, output_file)

# Function to compute sum of even values in a list
def calculate_even_total(values):
    total = 0
    for value in values:
        if value % 2 == 0:
            total += value
    return total

