# Reorganize summary files from source to destination based on folder structure

import os
import shutil

def restructure_summaries(base_dir, target_dir, source_dir):
    for item in os.listdir(base_dir):
        full_item_path = os.path.join(base_dir, item)
        if os.path.isdir(full_item_path):
            target_folder = os.path.join(target_dir, item)
            if not os.path.exists(target_folder):
                os.makedirs(target_folder)

            # Transfer summary files from source to target location
            source_item_path = os.path.join(source_dir, item)
            if os.path.exists(source_item_path):
                for filename in os.listdir(source_item_path):
                    src_file = os.path.join(source_item_path, filename)
                    dst_file = os.path.join(target_folder, filename)
                    shutil.copy2(src_file, dst_file)

import json
from datetime import datetime, date

class DateTimeSerializer(json.JSONEncoder):
    """
    A custom JSON encoder that handles datetime and date objects.
    Converts them into ISO 8601 formatted strings for compatibility
    with JavaScript's Date parsing.
    """

    def default(self, item):
        if isinstance(item, datetime):
            return item.strftime('%Y-%m-%dT%H:%M:%SZ')
        elif isinstance(item, date):
            return item.strftime('%Y-%m-%d')

