# Perform supervised evaluation of a model with reproducible randomness

import torch
import random

def evaluate_supervised(model, training_data_loader, seed_value, model_seed=None, quiet=False, store_inputs=False, use_gpu=False, **extra_kwargs):
    # Initialize random number generators for consistent results
    random.seed(seed_value)

    if model_seed is not None:
        torch.manual_seed(model_seed)  # Ensure deterministic behavior for PyTorch operations

    if use_gpu:
        target_device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        model.to(target_device)  # Transfer model to GPU if possible

    if not quiet:
        print("Running model evaluation...")

    if store_inputs:
        input_batch_list = []
        for batch_data, batch_labels in training_data_loader:
            input_batch_list.append(batch_data)

    # Compute evaluation metric(s) using the provided data loader
    performance_score = model.evaluate(training_data_loader)

    if not quiet:
        print("Evaluation finished successfully.")

    return performance_score

