def show_notification(text):
    try:
        # Use notify-send for desktop notifications
        subprocess.Popen(['notify-send', 'CPU Warning', text])
    except FileNotFoundError:
        # If notify-send is not available, print to console
        print(text)

def run_monitoring():
    while True:
        # Get current CPU usage with 1-second interval
        cpu_load = psutil.cpu_percent(interval=1)

        # Check if CPU usage is above threshold
        if cpu_load > 80:
            warning = f"CPU usage is high: {cpu_load}%"
            show_notification(warning)

        # Wait before next check
        time.sleep(1)

