from typing import Optional, Tuple
import jwt

def validate_user_token(user_token: str, secret_key: str, require_admin: bool) -> Tuple[Optional[str], Optional[str]]:
    try:
        payload = jwt.decode(user_token, secret_key, algorithms=['HS256'])

        if require_admin and not payload.get('is_admin', False):
            return "Access denied - admin privileges required", None

        user_identifier = payload.get('user_id')
        if user_identifier is None:
            return "Token missing user identification", None

        return None, user_identifier

    except jwt.ExpiredSignatureError:
        return "Authentication token expired", None
    except (jwt.DecodeError, jwt.InvalidTokenError):
        return "Malformed or invalid token", None

# Graph compression module that simplifies graph structure by removing 
# unnecessary nodes and renumbering remaining ones

class GraphSimplifier:
    def simplify(self, adjacency_dict):
        # Remove nodes with no outgoing edges (isolated)
        empty_nodes = [key for key in adjacency_dict if len(adjacency_dict[key]) == 0]
        for node in empty_nodes:
            adjacency_dict.pop(node)

        # Eliminate nodes connected to exactly one other node
        current_keys = list(adjacency_dict.keys())
        for vertex in current_keys:
            if len(adjacency_dict[vertex]) == 1:
                target = adjacency_dict[vertex][0]
                adjacency_dict.pop(vertex)

                # Update all references to the removed node
                for key in adjacency_dict:
                    adjacency_dict[key] = [
                        target if connection == vertex else connection 
                        for connection in adjacency_dict[key]
                    ]

        # Renumber remaining nodes sequentially starting from 0
        existing_nodes = list(adjacency_dict.keys())
        relabeling = {old_id: new_id for new_id, old_id in enumerate(existing_nodes)}

        simplified = {}
        for original_node, connections in adjacency_dict.items():
            new_node = relabeling[original_node]
            simplified[new_node] = [relabeling[conn] for conn in connections]

        return simplified

# Verification function
def verify_simplification():
    simplifier = GraphSimplifier()

    # Test 1: Graph containing disconnected nodes
    test_graph1 = {0: [1], 1: [], 2: [3], 3: []}
    result1 = simplifier.simplify(test_graph1)
    assert result1 == {0: [1], 1: [2]}

    # Test 2: Linear chain where intermediate nodes can be collapsed
    test_graph2 = {0: [1], 1: [2], 2: [3], 3: []}
    result2 = simplifier.simplify(test_graph2)
    assert result2 == {0: [1], 1: [2]}

    # Test 3: Long linear chain for performance check
    long_chain = {i: [i+1] for i in range(99999)}
    final_result = simplifier.simplify(long_chain)
    assert len(final_result) == 1
    assert len(final_result[0]) == 1

    print("All verification tests completed successfully.")

verify_simplification()

