from typing import List, Tuple
from enforce_typing import enforce_types

draw: int = 0
loss: int = -25
illegal_move: int = -1
legal_move: int = 1
capture_move: int = 5
king_move: int = 5

@enforce_types
def tuple_subtract(t1: Tuple[int, int], t2: Tuple[int, int]) -> Tuple[int, int]:
    return (t1[0] - t2[0], t1[1] - t2[1])

@enforce_types
def tuple_add(t1: Tuple[int, int], t2: Tuple[int, int]) -> Tuple[int, int]:
    return (t1[0] + t2[0], t1[1] + t2[1])

@enforce_types
def calculate_score(moves: List[Tuple[Tuple[int, int], Tuple[int, int]]]) -> int:
    score = 0
    for move in moves:
        start, end = move
        diff_x = end[0] - start[0]
        diff_y = end[1] - start[1]

        # Check for legal diagonal moves (distance 1)
        if abs(diff_x) == 1 and abs(diff_y) == 1:
            score += legal_move
        # Check for capture moves (distance 2)
        elif abs(diff_x) == 2 and abs(diff_y) == 2:
            score += capture_move
        # Check for king moves (distance 3)
        elif abs(diff_x) == 3 and abs(diff_y) == 3:
            score += king_move
        # All other moves are illegal
        else:
            score += illegal_move
    return score

