def validate_function_signatures(function_obj) -> None:
    import inspect

    # Get the function's signature using the built-in inspect module
    func_sig = inspect.signature(function_obj)

    # Iterate through each parameter in the function signature
    for param in func_sig.parameters.values():
        # Check if the parameter lacks an annotation
        if param.annotation == inspect.Parameter.empty:
