)
def bulk_create_teachers(self, request):
    try:
        uploaded_file = request.FILES["file"]
        # Read file content as text
        file_text = ""
        for chunk in uploaded_file.chunks():
            file_text += chunk.decode("utf-8")

        # Parse CSV data
        csv_data = StringIO(file_text)
        reader = csv.reader(csv_data)

        # Get teacher group
        try:
            teacher_role = Group.objects.get(name="Teacher")
        except Group.DoesNotExist:
            return Response({"error": "Teacher group not found"}, status=status.HTTP_400_BAD_REQUEST)

        # Prepare response structure
        result = {
            "created": [],
            "errors": []
        }

        for record in reader:
            # Validate row structure
            if len(record) != 3:
                result["errors"].append("Invalid CSV format: expected 3 columns")
                continue

            fname, lname, email_addr = record

            # Create or retrieve user
            user_obj, is_new = User.objects.get_or_create(
                username=email_addr,
                defaults={
                    'email': email_addr,
                    'first_name': fname,
                    'last_name': lname
                }
            )

            # Handle user creation status
            if is_new:
                user_obj.groups.add(teacher_role)
                result["created"].append(email_addr)
            else:
                result["errors"].append(f"User with email {email_addr} already exists")

        return Response(result, status=status.HTTP_201_CREATED)

    except KeyError:
        return Response({"error": "No file provided"}, status=status.HTTP_400_BAD_REQUEST)
    except Exception as exc:
        return Response({"error": str(exc)}, status=status.HTTP_400_BAD_REQUEST)

