# Custom decorator to enable method chaining by returning the instance
def enable_chain(func):
    def inner(self, *args, **kwargs):
        func(self, *args, **kwargs)
        return self
    return inner

# Decorator that schedules a method for later execution by storing it as an attribute
def schedule_execution(func):
    def inner(self, *args, **kwargs):
        def delayed_call():
            func(self, *args, **kwargs)
        setattr(self, f"schedule_{func.__name__}", delayed_call)
    return inner

# Decorator that ignores original logic and always returns a fixed value
def constant_result(fixed_value):
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            return fixed_value
        return wrapper
    return decorator

# Decorator that prevents method invocation by raising an error
def prevent_invocation(func):
    def wrapper(self, *args, **kwargs):
        raise RuntimeError(f"Function '{func.__name__}' is disabled")
    return wrapper

# Example class using alternative decorator names and logic
class ChainableExample:
