        print(f"First action executed with: {data}")

    @enable_chain
    def action_two(self, data):
        print(f"Second action executed with: {data}")

    @schedule_execution
    def deferred_task(self):
        print("Deferred task is now running")

    @constant_result(100)
    def get_constant(self):
        pass  # Original implementation ignored

    @prevent_invocation
    def restricted_operation(self):
