        if self.tokenizer is not None:
            tokenized_output = self.tokenizer(
                text_data, 
                return_tensors="pt", 
                padding=True, 
                truncation=True
            )

            input_ids_tensor = tokenized_output["input_ids"]
            attention_mask_tensor = tokenized_output["attention_mask"]

            ort_feed_dict = {
                self.session.get_inputs()[0].name: input_ids_tensor.numpy(),
                self.session.get_inputs()[1].name: attention_mask_tensor.numpy()
            }
        else:
            ort_feed_dict = {"raw_text": text_data}

        inference_results = self.session.run(None, ort_feed_dict)
        return inference_results

