# Custom logging implementation with configurable verbosity

class Logger:
    def __init__(self, verbosity):
        self.verbosity = verbosity

    def log_debug(self, msg):
        if self.verbosity <= 0:
            print(f"DEBUG: {msg}")

    def log_info(self, msg):
        if self.verbosity <= 1:
            print(f"INFO: {msg}")

    def log_warn(self, msg):
        if self.verbosity <= 2:
            print(f"WARNING: {msg}")

    def log_err(self, msg):
        if self.verbosity <= 3:
            print(f"ERROR: {msg}")

    def log_fatal(self, msg):
        if self.verbosity <= 4:
            print(f"CRITICAL: {msg}")

    def update_verbosity(self, level):
        self.verbosity = level

