    SUPERVISOR = 'admin'

class MessageFormatter:
    TEMPLATE_DIR = Environment(loader=FileSystemLoader('templates/'))

    def __init__(self, header: str = None, content: str = None, data: dict = None):
        self._custom_sections = {EmailLayout.HEADER: header, EmailLayout.CONTENT: content}
        self._template_data = data

    def format(self, template_name: str, section: EmailLayout, role: UserRole, extra_data: dict = None) -> str:
        """
        Generate an email message using Jinja templates and additional context.
        """
        merged_context = dict(extra_data or {}, layout=section.value, user_role=role.value)
        rendered = self.TEMPLATE_DIR.get_template(template_name).render(merged_context)
        custom_content = self._custom_sections.get(section)
        if custom_content:
            rendered += custom_content
        return rendered

