# Hangman Game Implementation - Alternative Version

import string
import random

def pick_random_word():
    words = ["hangman", "python", "programming", "challenge", "solution"]
    return random.choice(words)

def show_current_progress(target_word, letters_found):
    result = []
    for char in target_word:
        if char in letters_found:
            result.append(char)
        else:
            result.append('_')
    return ''.join(result)

def play_hangman():
    max_errors = 6
    secret_word = pick_random_word()
    found_letters = set()

    print("Welcome to Hangman!")
    print(show_current_progress(secret_word, found_letters))

    while max_errors > 0 and '_' in show_current_progress(secret_word, found_letters):
        user_input = input("Guess a letter: ").lower()

        # Validate input: must be single alphabetic character
        if len(user_input) != 1 or user_input not in string.ascii_letters:
            print("Please enter a single alphabetic character.")
            continue

        # Check if letter was already guessed
        if user_input in found_letters:
            print("You've already guessed that letter.")
            continue

        # Add new guess to found letters
        found_letters.add(user_input)

        # Check if guess is incorrect
        if user_input not in secret_word:
            max_errors -= 1
            print(f"Incorrect! You have {max_errors} attempts left.")

        print(show_current_progress(secret_word, found_letters))

    # Determine game outcome
    if '_' not in show_current_progress(secret_word, found_letters):
        print("Congratulations! You've guessed the word:", secret_word)
    else:
        print("Out of attempts! The word was:", secret_word)

play_hangman()

