import types

def validate_output_artifacts(output_artifacts, executor_output):
    # Make a deep copy of output_artifacts if it's provided, otherwise initialize as empty dict
    output_artifacts = copy.deepcopy(output_artifacts) if output_artifacts is not None else {}

    # Ensure type correctness for output_artifacts
    output_artifacts = output_artifacts  # type: MutableMapping[str, List[types.Artifact]]

    # Proceed only if executor_output contains relevant data
    if executor_output and hasattr(executor_output, 'output_artifacts'):
        # Check that all keys in executor_output.output_artifacts are present in output_artifacts
        if not set(executor_output.output_artifacts.keys()).issubset(set(output_artifacts.keys())):
            raise RuntimeError('Executor output contains more keys than output skeleton.')

        # Iterate through each artifact list in the output skeleton
        for key, artifact_list in output_artifacts.items():
            # Skip processing if this key is missing from executor output
            if key not in executor_output.output_artifacts:
                continue

