from enum import Enum

class CompressionType(Enum):
    gzip = "gzip"
    bzip2 = "bzip2"
    xz = "xz"
    uncompressed = "none"

    @property
    def descriptive_name(self) -> str:
        """
        Provides an extended identifier for the compression method.
        Examples include "gzip", "bzip2", "xz", and "none".
        """
        mapping = {
            CompressionType.gzip: "gzip",
            CompressionType.bzip2: "bzip2"
        }
        return mapping.get(self, self.value if self != CompressionType.uncompressed else "none")

    @property
    def has_compression(self) -> bool:
        """
        Indicates whether this format applies actual data compression.
        Returns True for compressed formats, False otherwise.
        """
        return self in {CompressionType.gzip, CompressionType.bzip2, CompressionType.xz}

# Port scanner utility to check if a specific port on a host is open

import sys
import socket

def check_port_status(target_ip, target_port):
    # Validate port number
    try:
        port_num = int(target_port)
        if port_num < 1 or port_num > 65535:
            print("Invalid port number")
            return
    except ValueError:
        print("Invalid port number")
        return

    # Validate IP address format
    try:
        socket.inet_aton(target_ip)
    except socket.error:
        print("Invalid IP address")
        return

    # Create socket and attempt connection
    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    sock.settimeout(3)

    try:
        result = sock.connect_ex((target_ip, port_num))
        if result == 0:
            print(f"Port {port_num} is open")
        else:
            error_msg = {
                10061: "Connection refused",
                110: "Connection timed out"
            }.get(result, "Unknown error")

            if result == 110:
                print(f"Connection to port {port_num} timed out")
            elif result == 10061:
                print(f"Port {port_num} is closed")
            else:
                print(f"Port {port_num} status: {error_msg}")
    except Exception as err:
        print(f"Connection error: {str(err)}")
    finally:
        sock.close()

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python port_scanner.py [IP_address] [port_number]")
    else:
        ip_addr = sys.argv[1]
        port_num = sys.argv[2]
        check_port_status(ip_addr, port_num)

class MemoryRegion:
    READABLE = 1
    WRITEABLE = 2

    def __init__(self, protection_flags):
        self.protection_flags = protection_flags

    def has_content(self):
        """
        @rtype: bool
        @return: True if the region has content.
        """
        # Implementation not provided for has_content()
        pass

    def is_readable(self):
        """
        @rtype: bool
        @return: True if all pages in this region are readable.
        """
        return self.has_content() and bool(self.protection_flags & self.READABLE)

    def is_writeable(self):
        """
        @rtype: bool
        @return: True if all pages in this region are writeable.
        """
        return self.has_content() and bool(self.protection_flags & self.WRITEABLE)

    def is_copy_on_write(self):
        """
        @rtype: bool
        @return: True if all pages in this region are marked as copy-on-write.
        """
        # A region is copy-on-write if it's readable but not writable,
        # or if it has both readable and writable flags set (which implies COW behavior)
        has_read = bool(self.protection_flags & self.READABLE)
        has_write = bool(self.protection_flags & self.WRITEABLE)

        # Copy-on-write typically means: readable + not writable, OR 
        # readable + writable (shared memory that uses COW when writing)
        return self.has_content() and (has_read and not has_write) or (has_read and has_write)

import torch
import torch.nn as nn

class ResidualRNNEncoder(RNNEncoder):
    def __init__(
            self, base_rnn, input_size, hidden_size, embedding_dim, device, bias=False,
            num_layers=1, dropout=0, bidirectional=False, pad_token=0, drop_rate=0.1
    ):
        super(ResidualRNNEncoder, self).__init__(
            base_rnn, input_size, hidden_size, embedding_dim, device, bias, num_layers, dropout, bidirectional, pad_token
        )
        self.residual_dropout = drop_rate

    def forward(self, input_sequence, sequence_lengths):
        batch_size = input_sequence.size(1)
        layer_count = self.num_directions * self.num_layers
        initial_hidden = torch.zeros(layer_count, batch_size, self.hidden_size, device=self.device)
        initial_cell = torch.zeros(layer_count, batch_size, self.hidden_size, device=self.device)

        temporal_outputs = []

        for time_step in range(input_sequence.size(0)):
            current_input = input_sequence[time_step, :, :]
            current_output, (hidden_state, cell_state) = self.rnn(
                current_input, (initial_hidden, initial_cell)
            )

            if time_step > 0 and self.residual_dropout > 0:
                previous_output = temporal_outputs[-1] if len(temporal_outputs) > 0 else \
                    torch.zeros_like(current_output)
                noisy_residual = torch.nn.functional.dropout(
                    previous_output, p=self.residual_dropout, training=self.training
                )
                current_output = current_output + noisy_residual

            temporal_outputs.append(current_output)

        final_outputs = torch.stack(temporal_outputs, dim=0)
        return final_outputs, (hidden_state, cell_state)

