import enum

class DynamicEnum(enum.Enum):
    @classmethod
    def register(cls, name, value):
        # Check for duplicate names or values in existing members
        if any(m.name == name for m in cls) or any(m.value == value for m in cls):
            raise ValueError(f"Duplicate entry: name '{name}' or value '{value}' already exists")

        # Dynamically create a new member and add it to the class
        new_member = object.__new__(cls)
        new_member._name_ = name
        new_member._value_ = value
        cls._member_map_[name] = new_member
        cls._member_names_.append(name)
        return new_member

    @classmethod
    def find_by_value(cls, val):
        for member in cls:
            if member.value == val:
                return member
        raise KeyError(f"No entry found with value '{val}'")

# Verification function
def validate_dynamic_enum():
    base_count = len(DynamicEnum)

    # Register a new member
    DynamicEnum.register('NEW_ITEM', 'n')
    assert len(DynamicEnum) == base_count + 1

    # Try registering duplicate (should fail)
    try:
        DynamicEnum.register('NEW_ITEM', 'n')
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

    # Try registering duplicate value with different name (should also fail)
    try:
        DynamicEnum.register('DIFF_NAME', 'n')
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

    # Look up by value
    assert DynamicEnum.find_by_value('n') is DynamicEnum.NEW_ITEM

    # Look up non-existent value
    try:
        DynamicEnum.find_by_value('z')
        assert False, "Should have raised KeyError"
    except KeyError:
        pass

