import os
from pathlib import Path

def transfer_file(src, dst):
    try:
        # Ensure the destination directory exists
        dst_dir = Path(dst).resolve().parent
        dst_dir.mkdir(parents=True, exist_ok=True)

        # Perform the file move operation
        Path(src).rename(dst)
        return True
    except Exception as err:
        return str(err)

# Ansible module to manage Foreman locations (Type III clone)
from ansible.module_utils.basic import AnsibleModule
import requests

def execute_module():
    # Define module arguments
    module_args = dict(
        location_name=dict(type='str', required=True),
        extra_attrs=dict(type='dict', required=False, default={}),
        desired_state=dict(type='str', required=False, default='present', 
                          choices=['present', 'absent'])
    )

    # Create the Ansible module instance
    result_module = AnsibleModule(
        argument_spec=module_args,
        supports_check_mode=True
    )

    # Configuration for Foreman API
    api_endpoint = 'https://foreman.example.com/api/v2/locations'
    request_headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }
    credentials = ('username', 'password')  # Replace with real credentials

    # Extract parameters from module
    loc_name = result_module.params['location_name']
    additional_params = result_module.params['extra_attrs']
    target_state = result_module.params['desired_state']

    # Handle 'present' state - create or update location
    if target_state == 'present':
        payload_data = {'name': loc_name}
        payload_data.update(additional_params)

        # Perform POST request to create location
        api_response = requests.post(
            api_endpoint, 
            json=payload_data, 
            auth=credentials, 
            headers=request_headers
        )

    # Handle 'absent' state - delete location if it exists
    elif target_state == 'absent':
        found_id = locate_location_by_name(loc_name, credentials, request_headers)

        if found_id is not None:
            # Location exists, proceed with deletion
            delete_endpoint = f'{api_endpoint}/{found_id}'
            api_response = requests.delete(
                delete_endpoint, 
                auth=credentials, 
                headers=request_headers
            )
        else:
            # Location doesn't exist, no action needed
            result_module.exit_json(
                changed=False, 
                msg=f"Location '{loc_name}' does not exist, no changes made."
            )

    # Process response and determine outcome
    if api_response.status_code in [200, 201]:
        result_module.exit_json(
            changed=True, 
            msg=f"Location '{loc_name}' {target_state}ed successfully."
        )
    else:
        result_module.fail_json(
            msg=f"Operation failed for location '{loc_name}'. Details: {api_response.text}"
        )

def locate_location_by_name(location_name, auth_info, http_headers):
    """Find location ID by name using API search"""
    base_url = 'https://foreman.example.com/api/v2/locations'

    try:
        response = requests.get(
            base_url, 
            auth=auth_info, 
            headers=http_headers
        )

        if response.status_code != 200:
            return None

        locations_list = response.json().get('results', [])

        for loc in locations_list:
            if loc.get('name') == location_name:
                return loc.get('id')

        return None

    except Exception:
        return None

if __name__ == '__main__':
    execute_module()

# Process module data with validation and structuring

def handle_module_info(yaml_content, module_name, stream_id, release_version, context_id, platform_arch, short_desc, long_desc, mod_lics, cont_lics, rpm_packages):
    # Validate all input parameters before processing
    if not isinstance(yaml_content, str) or len(yaml_content) == 0:
        raise ValueError("yaml_content must be a non-empty string")
    if not isinstance(module_name, str) or len(module_name) == 0:
        raise ValueError("module_name must be a non-empty string")
    if not isinstance(stream_id, str) or len(stream_id) == 0:
        raise ValueError("stream_id must be a non-empty string")
    if not isinstance(release_version, int) or release_version < 0:
        raise ValueError("release_version must be a non-negative integer")
    if not isinstance(context_id, str):
        raise ValueError("context_id must be a string")
    if not isinstance(platform_arch, str):
        raise ValueError("platform_arch must be a string")
    if not isinstance(short_desc, str) or len(short_desc) == 0:
        raise ValueError("short_desc must be a non-empty string")
    if not isinstance(long_desc, str) or len(long_desc) == 0:
        raise ValueError("long_desc must be a non-empty string")
    if not isinstance(mod_lics, list) or not all(isinstance(item, str) for item in mod_lics):
        raise ValueError("mod_lics must be a list of strings")
    if not isinstance(cont_lics, list) or not all(isinstance(item, str) for item in cont_lics):
        raise ValueError("cont_lics must be a list of strings")
    if not isinstance(rpm_packages, list) or not all(isinstance(item, str) for item in rpm_packages):
        raise ValueError("rpm_packages must be a list of strings")

    # Construct the structured output dictionary
    result = {
        "mod_yaml": yaml_content,
        "name": module_name,
        "stream": stream_id,
        "version": release_version,
        "context": context_id,
        "arch": platform_arch,
        "summary": short_desc,
        "description": long_desc,
        "module_licenses": mod_lics,
        "content_licenses": cont_lics,
        "rpms_nevras": rpm_packages
    }
    return result

