# Custom decorator to ensure service key length validation
def validate_service_key_length(min_length=12):
    def decorator(view_func):
        def _wrapped_view(request, *args, **kwargs):
            service_key = kwargs.get('service_key', '')
            if len(service_key) != min_length:
                return HttpResponseBadRequest("Invalid service key length")
            return view_func(request, *args, **kwargs)
        return _wrapped_view
    return decorator

@login_required
@require_GET
@validate_service_key_length(12)
