    # Retrieve the project using the provided code
    project = get_object_or_404(Project, code=project_code)

    # Store the service key in session and persist changes
    request.session["pd"] = service_key
    request.session.modified = True

    # Notify user of successful addition
    messages.success(request, "PD Connect service added successfully")
    return HttpResponse("PD Connect service added")

