# Find the earliest and latest event timestamps from a list of events

from datetime import datetime

def find_oldest_and_newest_events(events: list) -> tuple:
    oldest_event = None
    newest_event = None

    for event in events:
        current_time = event["started"]

        if oldest_event is None or current_time < oldest_event:
            oldest_event = current_time

        if newest_event is None or current_time > newest_event:
            newest_event = current_time

    return oldest_event, newest_event

# Custom exception for validation errors
class ValidationError(Exception):
    pass

class Item:
    def __init__(self, identifier):
        self.identifier = identifier

class ItemCollection(list):
    def __init__(self, *args):
        super().__init__(*args)

        # Ensure collection is not empty
        if len(self) == 0:
            raise ValidationError("Collection must contain at least one item")

        # Verify all items share the same identifier value
        reference_id = self[0].identifier
        for index, item in enumerate(self):
            if item.identifier != reference_id:
                raise ValidationError(
                    "All items in the collection must have identical identifiers"
                )

from typing import Union

class GameTimer:
    def __init__(self, current_state: "GameState", game_data: "GameInfo"):
        self.current_state = current_state
        self._game_data = game_data

    @property
    def elapsed_time(self) -> Union[int, float]:
        """ Returns time in seconds, assumes the game is played on 'faster' """
        return self.current_state.game_loop / 22.4  # Convert game loops to seconds

    @property
    def formatted_time(self) -> str:
        """ Returns time as string in min:sec format """
        total_seconds = self.elapsed_time
        minutes = int(total_seconds // 60)
        seconds = int(total_seconds % 60)
        return f"{minutes:02}:{seconds:02}"  # Format time as mm:ss

    @property
    def game_info(self) -> "GameInfo":
        return self._game_data

import requests
from bs4 import BeautifulSoup

def extract_news_show_links(url: str) -> str:
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
    }

    response = requests.get(url, headers=headers)
    html_content = response.text

    soup = BeautifulSoup(html_content, "html.parser")

    # Find all anchor tags with href starting with "/news/show"
    news_links = soup.find_all('a', href=lambda href: href and href.startswith('/news/show'))

    extracted_text = ""
    for link in news_links:
        text = link.get_text(strip=True)
        if text:
            extracted_text += text + " "

    return extracted_text.strip()

