# Image scraper script - fetches images from a given webpage URL

import os
import sys
import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
from urllib.request import urlretrieve

def check_webpage_accessibility(url):
    try:
        response = requests.head(url, timeout=10)
        return response.status_code == 200
    except requests.RequestException:
        return False

def extract_and_save_images(page_url, save_directory):
    try:
        page_response = requests.get(page_url)
        parsed_page = BeautifulSoup(page_response.content, 'html.parser')
        image_elements = parsed_page.find_all('img')

        for image_element in image_elements:
            image_source = image_element.get('src')
            if image_source:
                absolute_image_url = urljoin(page_url, image_source)
                filename = os.path.basename(urlparse(absolute_image_url).path)
                full_path = os.path.join(save_directory, filename)
                urlretrieve(absolute_image_url, full_path)
                print(f"Saved: {absolute_image_url} -> {full_path}")
    except requests.RequestException as error:
        print(f"Error occurred while fetching images: {error}")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python facescrapped.py <url> <output_dir>")
        sys.exit(1)

    target_url = sys.argv[1]
    destination_folder = sys.argv[2]

    if not check_webpage_accessibility(target_url):
        print("Invalid URL or unable to access the webpage.")
        sys.exit(1)

    if not os.path.isdir(destination_folder):
        os.makedirs(destination_folder)

    extract_and_save_images(target_url, destination_folder)

