from typing import List

class Scorer:
    def __init__(self):
        self.scores = [None] * 13  # Initialize scores list with 13 elements

    def score_three_of_kind(self, dice: List[int]) -> int:
        if self.scores[6] is None:
            found = False
            for value in set(dice):
                if dice.count(value) >= 3:
                    found = True
                    break
            self.scores[6] = sum(dice) if found else 0
        return self.scores[6]

    def score_four_of_kind(self, dice: List[int]) -> int:
        if self.scores[7] is None:
            found = False
            for value in set(dice):
                if dice.count(value) >= 4:
                    found = True
                    break
            self.scores[7] = sum(dice) if found else 0
        return self.scores[7]

    def score_full_house(self, dice: List[int]) -> int:
        if self.scores[8] is None:
            unique_values = list(set(dice))
            counts = []
            for val in unique_values:
                count = 0
                for die in dice:
                    if die == val:
                        count += 1
                counts.append(count)

            has_pair = False
            has_triple = False
            for c in counts:
                if c == 2:
                    has_pair = True
                if c == 3:
                    has_triple = True

            self.scores[8] = 25 if has_pair and has_triple else 0
        return self.scores[8]

    def score_small_straight(self, dice: List[int]) -> int:
        if self.scores[9] is None:
            unique_dice = []
            for d in dice:
                if d not in unique_dice:
                    unique_dice.append(d)
            unique_dice.sort()

            consecutive_count = 1
            max_consecutive = 1
            for i in range(1, len(unique_dice)):
                if unique_dice[i] == unique_dice[i-1] + 1:
                    consecutive_count += 1
                    if consecutive_count > max_consecutive:
                        max_consecutive = consecutive_count
                else:
                    consecutive_count = 1

            self.scores[9] = 30 if max_consecutive >= 4 else 0
        return self.scores[9]

    def score_large_straight(self, dice: List[int]) -> int:
        if self.scores[10] is None:
            unique_dice = []
            for d in dice:
                if d not in unique_dice:
                    unique_dice.append(d)
            unique_dice.sort()

            consecutive_count = 1
            max_consecutive = 1
            for i in range(1, len(unique_dice)):
                if unique_dice[i] == unique_dice[i-1] + 1:
                    consecutive_count += 1
                    if consecutive_count > max_consecutive:
                        max_consecutive = consecutive_count
                else:
                    consecutive_count = 1

            self.scores[10] = 40 if max_consecutive == 5 else 0
        return self.scores[10]

    def score_chance(self, dice: List[int]) -> int:
        if self.scores[11] is None:
            total = 0
            for die in dice:
                total += die
            self.scores[11] = total
        return self.scores[11]

    def total_score(self) -> int:
        above = 0
        for i in range(6, 12):
            if self.scores[i] is not None:
                above += self.scores[i]
        return above

