import requests

def get_repo_languages(repo_name):
    base_url = "https://api.github.com"
    repo_endpoint = f"{base_url}/repos/{repo_name}"

    request_headers = {
        'Accept': 'application/vnd.github.v3+json'
    }

    # Fetch repository details
    repo_response = requests.get(repo_endpoint, headers=request_headers)
    if repo_response.status_code != 200:
        raise Exception(f"Unable to retrieve repository data: {repo_response.status_code} - {repo_response.text}")

    repo_info = repo_response.json()
    languages_api_url = repo_info['languages_url']

    # Fetch language statistics
    lang_response = requests.get(languages_api_url, headers=request_headers)
    if lang_response.status_code != 200:
        raise Exception(f"Unable to retrieve language data: {lang_response.status_code} - {lang_response.text}")

    raw_lang_data = lang_response.json()

    # Convert to dictionary with language names and their byte counts
    language_summary = {}
    for lang_name, byte_count in raw_lang_data.items():
        language_summary[lang_name] = byte_count

    return language_summary

def filter_cities_by_divisor(city_list, divisor):
