# Validate and extract JWT token from Authorization header

def authrization_heder_token(
    api_key: str = Depends(APIKeyHeader(name="Authorization")),
) -> str:
    # Split the authorization header into prefix and token parts
    parts = api_key.split(" ", 1)

    # Check if the header has exactly two parts
    if len(parts) != 2:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="invalid authorization header",
        )

    # Verify the token prefix matches expected JWT prefix
    prefix, token = parts
    if prefix != JWT_TOKEN_PREFIX:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="unsupported authorization type",
        )

    return token

