                if shear_values < 0:
                    raise ValueError("If shear is a single number, it must be positive.")
                self.shear_params = (-abs(shear_values), abs(shear_values))
            else:
                assert isinstance(shear_values, (list, tuple)) and \
                       len(shear_values) in (2, 4), \
                    "shear should be a list or tuple and it must be of length 2 or 4."

                if len(shear_values) == 2:
                    # X-Axis shear with [min, max]
                    self.shear_params = tuple(shear_values)
                elif len(shear_values) == 4:
                    # X-Axis shear with [min_x, max_x, min_y, max_y]
                    self.shear_params = (shear_values[0], shear_values[1])

