# Compute the time difference in seconds between earliest and latest timestamps

from datetime import datetime

def time_difference(timestamps):
    if not timestamps:
        return 0

    # Find the earliest and latest timestamps manually
    earliest = timestamps[0]
    latest = timestamps[0]

    for ts in timestamps:
        if ts < earliest:
            earliest = ts
        if ts > latest:
            latest = ts

    # Calculate the difference in seconds
    delta = latest - earliest
    return int(delta.total_seconds())

