def parse_boolean(value):
    # Handle different input types to convert to boolean or None
    if isinstance(value, bool):
        return value  # Already a boolean, return as-is

    if isinstance(value, str):
        normalized = value.lower()
        if normalized in ('true', 't', '1'):
            return True
        elif normalized in ('false', 'f', '0'):
            return False

    return None  # Unrecognized format or unsupported type

class ConnectRequest:
    CRI_SIZE = 4  # Size of Connect Request Information (CRI) in bytes

    def __init__(self, ctrl_ep, data_ep, req_type, flgs):
        self.control_endpoint = ctrl_ep
        self.data_endpoint = data_ep
        self.request_type = req_type
        self.flags = flgs

    def to_knx(self):
        def build_cri():
            return bytes([
                ConnectRequest.CRI_SIZE,
                self.request_type.value,
                self.flags,
                0x00  # Padding byte
            ])

        return (
            self.control_endpoint.to_knx() +
            self.data_endpoint.to_knx() +
            build_cri()
        )

    def __repr__(self) -> str:
        return f"ConnectRequest(control_endpoint={self.control_endpoint}, data_endpoint={self.data_endpoint}, request_type={self.request_type}, flags={self.flags})"

import random

class StateSequenceModel:
    def __init__(self, observed_states):
        # Remove duplicates while preserving order for unique states
        self.unique_states = []
        for s in observed_states:
            if s not in self.unique_states:
                self.unique_states.append(s)

        # Store transition probabilities as a dictionary of lists
        self.transitions = {}
        self._compute_transitions(observed_states)

    def _compute_transitions(self, history):
        for current_state in self.unique_states:
            # Find all next states following the current state in the history
            next_candidates = []
            for i in range(len(history) - 1):
                if history[i] == current_state:
                    next_candidates.append(history[i + 1])

            # Calculate relative frequencies as probabilities
            if next_candidates:
                freq_dict = {}
                for candidate in next_candidates:
                    freq_dict[candidate] = freq_dict.get(candidate, 0) + 1

                total = len(next_candidates)
                self.transitions[current_state] = [
                    (state, count / total) 
                    for state, count in freq_dict.items()
                ]
            else:
                self.transitions[current_state] = []

    def predict_next_state(self, current):
        # Extract states and their corresponding weights
        possible_states, weights = zip(*self.transitions[current]) if self.transitions[current] else ([], [])
        # Use weighted random choice to select next state
        return random.choices(possible_states, weights=weights)[0]

    def generate_path(self, steps, initial_state):
        path = [initial_state]
        current = initial_state

        for _ in range(steps - 1):
            next_step = self.predict_next_state(current)
            path.append(next_step)
            current = next_step

        return path

def validate_model():
    model = StateSequenceModel([1, 2, 3, 1, 2])
    assert len(model.unique_states) == 3
    assert isinstance(model.transitions, dict)
    assert isinstance(model.transitions[1], list)
    assert model.predict_next_state(1) == 2
    assert len(model.generate_path(10, 1)) == 10

validate_model()

# Extract URL components using urllib.parse

from urllib.parse import urlparse, parse_qs

def extract_url_info(url):
    parsed = urlparse(url)
    params = parse_qs(parsed.query)

    # Convert query parameters to single values instead of lists
    param_dict = {}
    for key, value_list in params.items():
        param_dict[key] = value_list[0]

    return {
        'scheme': parsed.scheme,
        'host': parsed.netloc,
        'uri_path': parsed.path,
        'parameters': param_dict,
        'fragment_id': parsed.fragment
    }

class LayerManager:
    def __init__(self, network):
        """
        Initialize the LayerManager with a neural network model.
        """
        self.network = network

    def freeze_layers(self, count: int) -> None:
        """
        Freeze the first 'count' layers of the model by disabling gradient computation.
        """
        layer_index = 0
        for param in self.network.parameters():
            if layer_index >= count:
                break
            param.requires_grad = False
            layer_index += 1

    def unfreeze_layers(self, count: int) -> None:
        """
        Unfreeze the first 'count' layers of the model by enabling gradient computation.
        """
        layer_index = 0
        for param in self.network.parameters():
            if layer_index >= count:
                break
            param.requires_grad = True
            layer_index += 1

# Process SNMP MIB data with error handling and symbol extraction

from pysnmp.smi import builder, view, error
from pysnmp.smi.rfc1902 import MibScalarInstance

def process_snmp_mib_data(mib_info: dict) -> dict:
    mibBuilder = builder.MibBuilder()
    try:
        # Extract module and symbols from input
        module_name = mib_info['module_name']
        symbols_list = mib_info['symbols']

        # Import required symbols
        imported_syms = mibBuilder.importSymbols(module_name, *symbols_list)

        # Create scalar instance using provided value
        target_spin_lock_sym = imported_syms[0]  # First symbol is typically snmpTargetSpinLock
        scalar_value = mib_info['scalar_instance_value']

        _snmpTargetSpinLock = MibScalarInstance(
            target_spin_lock_sym.name, 
            (scalar_value,),
            target_spin_lock_sym.syntax.clone(scalar_value)
        )

        # Build dictionary of all requested symbols
        all_imported = {}
        for sym_name in symbols_list:
            all_imported[sym_name] = mibBuilder.importSymbols(module_name, sym_name)[0]

        return {
            'imported_symbols': all_imported,
            'scalar_instance': {
                'name': mib_info['scalar_instance_name'],
                'value': scalar_value
            }
        }
    except error.SmiError as err:
        return {'error': str(err)}

from collections import deque

class TrafficController:
    def __init__(self, buffer_capacity, warning_limit):
        self.buffer = deque(maxlen=buffer_capacity)
        self.current_rate = 0
        self.warning_threshold = warning_limit
        self.warning_active = False

    def record_traffic(self, count):
        self.current_rate += count

    def average_rate(self):
        self.buffer.append(self.current_rate)
        mean_val = sum(self.buffer) / len(self.buffer) if self.buffer else 0

        if not self.warning_active and mean_val > self.warning_threshold:
            self.warning_active = True
            print(f"Excessive traffic detected - rate={mean_val}, limit={self.warning_threshold}")
        elif self.warning_active and mean_val <= self.warning_threshold:
            self.warning_active = False
            print("Traffic alert cleared - traffic levels normalized")

        self.current_rate = 0

import torch
import torch.nn as nn

class EntityEmbedding(nn.Module):
    def __init__(self, hidden_dim, gamma, epsilon, use_double_embedding):
        super(EntityEmbedding, self).__init__()
        self.gamma = gamma
        self.epsilon = epsilon

        # Compute embedding range based on provided parameters
        range_value = (gamma + epsilon) / hidden_dim
        self.embedding_range = nn.Parameter(
            torch.tensor([range_value]),
            requires_grad=False
        )

        # Determine entity dimensionality based on flag
        if use_double_embedding:
            self.entity_dim = hidden_dim * 2
        else:
            self.entity_dim = hidden_dim

    def update_embedding_range(self, new_gamma, new_epsilon, new_hidden_dim):
        """Update the embedding range parameter with new values"""
        updated_range = (new_gamma + new_epsilon) / new_hidden_dim
        self.embedding_range = nn.Parameter(
            torch.tensor([updated_range]),
            requires_grad=False
        )

    def adjust_entity_dimensionality(self, enable_double):
        """Adjust entity dimension based on whether double embedding is enabled"""
        if enable_double:
            self.entity_dim = self.entity_dim // 2 * 2  # Ensure it's double the base
        else:
            self.entity_dim = self.entity_dim // 2  # Return to base dimension

def get_license_details(license_content: str) -> dict:
    result = {"license_type": "", "permissions": [], "limitations": []}
    lines = license_content.splitlines()

    # Find the first non-comment, non-empty line as license type
    for line in lines:
        stripped = line.strip()
        if stripped and not stripped.startswith('#'):
            result["license_type"] = stripped
            break

    collecting_permissions = False
    collecting_limitations = False

    for line in lines:
        stripped = line.strip()

        # Detect start of permissions section
        if "WITHOUT WARRANTIES OR CONDITIONS OF ANY" in line:
            collecting_permissions = True
            continue

        # Detect start of limitations section
        if "limitations" in line.lower() and "limitation" not in line.lower().replace("limitations", ""):
            collecting_permissions = False
            collecting_limitations = True
            continue

        # Collect permissions if active and line is valid
        if collecting_permissions and stripped and not stripped.startswith('#'):
            result["permissions"].append(stripped)

        # Collect limitations if active and line is valid
        if collecting_limitations and stripped and not stripped.startswith('#'):
            result["limitations"].append(stripped)

    return result

# Reimplementation of dataclass deserialization using pendulum with modified logic

from dataclasses import dataclass, field
from datetime import datetime, date, timezone
import pendulum

class CustomDeserializerMixin:
    @classmethod
    def create_from_mapping(cls, input_data):
        # Get all defined fields for this dataclass
        available_fields = cls.__dataclass_fields__

        # Prepare keyword arguments by processing each field
        processed_args = {}
        for field_name in available_fields:
            field_spec = available_fields[field_name]

            # Extract deserialization metadata if present
            deserialize_config = field_spec.metadata.get('deserialize', {})

            # Handle the value based on field type and metadata
            raw_value = input_data[field_name]

            if isinstance(deserialize_config, dict) and 'pendulum' in str(deserialize_config).lower():
                # Use pendulum to parse datetime/date strings
                parsed_value = pendulum.parse(raw_value)

                # Convert to target type if needed (e.g., datetime vs date)
                if field_spec.type == date and not isinstance(parsed_value, date):
                    parsed_value = parsed_value.date()
                elif field_spec.type == datetime and isinstance(parsed_value, date):
                    parsed_value = pendulum.instance(parsed_value).replace(tzinfo=timezone.utc)

                processed_args[field_name] = parsed_value
            else:
                # Direct assignment for non-pendulum fields
                processed_args[field_name] = raw_value

        return cls(**processed_args)

@dataclass
class DateTimeDataClass(CustomDeserializerMixin):
    x: datetime = field(metadata={"deserialize": "pendulum"})

# Test case 1: datetime parsing
