import unittest
import random

def unique_id_sequence(start, end):
    generated = set()
    while True:
        candidate = random.randint(start, end)
        if candidate not in generated:
            generated.add(candidate)
            yield candidate

class IdentifierTest(unittest.TestCase):
    def test_random_uuid_stream(self):
        generator = unique_id_sequence(1, 100)  # Using local generator for testing
        count = 10
        collected = {next(generator): idx for idx in range(count)}
        # Verify uniqueness of generated identifiers
        self.assertEqual(len(collected), count)
        for identifier in collected:
            self.assertIsInstance(identifier, int)  # Changed from UUID to int since we're using local IDs

    def test_range_limited_generator(self):
        lower_bound = 1
        upper_bound = 100
        id_source = unique_id_sequence(lower_bound, upper_bound)
        quantity = 10
        observed = set()
        for _ in range(quantity):
            value = next(id_source)
            observed.add(value)
            self.assertGreaterEqual(value, lower_bound, "ID below minimum")
            self.assertLessEqual(value, upper_bound, "ID above maximum")
        self.assertEqual(len(observed), quantity, "Duplicate IDs detected")

if __name__ == '__main__':
    unittest.main()

import json
import hashlib
from pathlib import Path

def compute_file_checksum(file_path):
    try:
        with open(file_path, 'rb') as file_obj:
            content = file_obj.read()
            checksum = hashlib.sha256(content).hexdigest()
            return checksum
    except FileNotFoundError:
        return None
    except OSError as e:
        print(f"OS error while processing '{file_path}': {e}")
        return None
    except Exception as e:
        print(f"Unexpected error for '{file_path}': {e}")
        return None

def process_files():
    input_json = 'input_files.json'
    output_json = 'output_hashes.json'

    # Load input JSON
    try:
        with open(input_json, 'r', encoding='utf-8') as f:
            files_list = json.load(f)
    except FileNotFoundError:
        print(f"Input configuration file '{input_json}' is missing.")
        return
    except json.JSONDecodeError as err:
        print(f"Invalid JSON in '{input_json}': {err}")
        return

    results = {}
    for path in files_list:
        checksum = compute_file_checksum(path)
        if checksum is not None:
            results[path] = checksum

    # Save results to output JSON
    try:
        with open(output_json, 'w', encoding='utf-8') as out_file:
            json.dump(results, out_file, indent=4, sort_keys=True)
        print(f"Checksums saved to '{output_json}'.")
    except IOError as io_err:
        print(f"Failed to write output file '{output_json}': {io_err}")

if __name__ == "__main__":
    process_files()

