    assert vector.length == 0.0
    assert vector.angle == 0.0
    assert vector.to_coordinates() == (0, 0)

# Custom implementation of a linked list with add and remove operations

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def add_node(self, value):
        # Add new node at the beginning (like a stack)
        new_node = Node(value)
        new_node.next = self.head
        self.head = new_node

    def remove_node(self, value):
        # Remove first occurrence of node with given value
        current = self.head
        prev = None

        while current:
            if current.data == value:
                if prev is None:
                    self.head = current.next
                else:
                    prev.next = current.next
                return True  # Removed successfully
            prev = current
            current = current.next
        return False  # Value not found

    def __str__(self):
        # Build string representation of the list
        nodes = []
        current = self.head
        while current:
            nodes.append(str(current.data))
            current = current.next
        return " -> ".join(nodes)

if __name__ == "__main__":
    my_list = LinkedList()
    my_list.add_node(3)
    my_list.add_node(7)
    my_list.add_node(5)
    my_list.add_node(2)
    print(my_list)  # Output: 2 -> 5 -> 7 -> 3
    my_list.remove_node(5)
    print(my_list)  # Output: 2 -> 7 -> 3
    my_list.remove_node(3)
    print(my_list)  # Output: 2 -> 7

# WebSocket client and server implementation using Twisted framework

from autobahn.twisted.websocket import WebSocketClientFactory, \
                                       WebSocketClientProtocol, \
                                       WebSocketServerFactory, \
                                       WebSocketServerProtocol, \
                                       connectWS, \
                                       listenWS
from twisted.internet import reactor

class CustomClientProtocol(WebSocketClientProtocol):
    def connectionMade(self):
        self.sendMessage("Hello, server!".encode('utf-8'))

    def onMessage(self, data, isBinary):
        if not isBinary:
            print("Message from server: {}".format(data.decode('utf-8')))

class CustomClientFactory(WebSocketClientFactory):
    protocol = CustomClientProtocol

class CustomServerProtocol(WebSocketServerProtocol):
    def connectionMade(self):
        self.sendMessage("Hello, client!".encode('utf-8'))

    def onMessage(self, data, isBinary):
        if not isBinary:
            print("Message from client: {}".format(data.decode('utf-8')))

class CustomServerFactory(WebSocketServerFactory):
    protocol = CustomServerProtocol

def launchClient(url):
    factory_instance = CustomClientFactory(url)
    connectWS(factory_instance)
    reactor.run()

def launchServer(port_number):
    server_url = u"ws://127.0.0.1:{}".format(port_number)
    factory_instance = CustomServerFactory(server_url)
    listenWS(factory_instance)
    reactor.run()

import sys

def transform_file(input_path, output_path, secret):
    try:
        with open(input_path, 'rb') as in_file, open(output_path, 'wb') as out_file:
            key_data = secret.encode('utf-8')
            key_size = len(key_data)
            pos = 0
            while True:
                chunk = in_file.read(1)
                if not chunk:
                    break
                transformed_byte = bytes([chunk[0] ^ key_data[pos]])
                out_file.write(transformed_byte)
                pos = (pos + 1) % key_size
    except FileNotFoundError:
        print("Input file could not be opened!")
        sys.exit(2)

def reverse_file(input_path, output_path, secret):
    transform_file(input_path, output_path, secret)  # Reversal uses the same operation

def main():
    if len(sys.argv) < 4:
        print("Syntax: cryptolocker.py <INPUT_FILE> <OUTPUT_FILE> <SECRET_KEY>")
        sys.exit(2)

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    secret_key = sys.argv[3]

    if len(secret_key) < 7:
        print("Secret key must be at least 7 characters!")
        sys.exit(2)

    if len(secret_key) > 11:
        print("Secret key cannot exceed 11 characters!")
        sys.exit(2)

    transform_file(input_file, output_file, secret_key)

if __name__ == "__main__":
    main()

