# Group consecutive identical elements into tuples of (key, list_of_elements)
from typing import List, Any, Tuple

def simplified_groupby(data: List[Any]) -> List[Tuple[Any, List[Any]]]:
    output = []
    current_key = None
    current_group = []

    for element in data:
        if element != current_key:
            if current_key is not None:
                output.append((current_key, current_group))
            current_key = element
            current_group = [element]
        else:
            current_group.append(element)

    if current_key is not None:
        output.append((current_key, current_group))

    return output

from pathlib import Path

def _filter_out_excluded_paths(input_paths, exclusion_patterns):
    filtered_paths = []
    for current_path in input_paths:
        should_exclude = False
        for pattern in exclusion_patterns:
            # Normalize the pattern by removing trailing slashes for comparison
            normalized_pattern = pattern.rstrip("/")
            if str(current_path).startswith(normalized_pattern):
                should_exclude = True
                break
        if not should_exclude:
            filtered_paths.append(current_path)
    return filtered_paths

