# QR payload encoding/decoding utilities for data transport

from __future__ import annotations
import base64
import binascii
from typing import Final, Literal

# Define supported encoding methods
QrPayloadCodec = Literal["raw", "base64"]
QR_PAYLOAD_CODEC_RAW: Final[QrPayloadCodec] = "raw"
QR_PAYLOAD_CODEC_BASE64: Final[QrPayloadCodec] = "base64"

def encode_qr_payload(
    data: bytes,
    *,
    method: QrPayloadCodec = QR_PAYLOAD_CODEC_BASE64,
) -> bytes | str:
    """Encode frame bytes for QR code transmission."""
    if method == QR_PAYLOAD_CODEC_RAW:
        return data
    if method != QR_PAYLOAD_CODEC_BASE64:
        raise ValueError(f"unsupported QR payload method: {method}")

    # Encode using base64 and remove padding
    encoded = base64.b64encode(data).decode("ascii")
    return encoded.rstrip("=")

def decode_qr_payload(
    payload: bytes | str,
    *,
    method: QrPayloadCodec = QR_PAYLOAD_CODEC_BASE64,
) -> bytes:
    """Decode frame bytes from QR code payload."""
    if method == QR_PAYLOAD_CODEC_RAW:
        if isinstance(payload, bytes):
            return payload
        raise ValueError("invalid raw QR payload")

    if method != QR_PAYLOAD_CODEC_BASE64:
        raise ValueError(f"unsupported QR payload method: {method}")

    return _decode_base64_qr_code(payload)

def _decode_base64_qr_code(payload: bytes | str) -> bytes:
    """Decode unpadded base64 QR code text."""
    if isinstance(payload, bytes):
        try:
            text = payload.decode("ascii")
        except UnicodeDecodeError as exc:
            raise ValueError("invalid base64 QR payload") from exc
    else:
        text = payload

    # Remove whitespace characters
    cleaned = "".join(text.split())

    # Check for padding characters (not allowed in QR payloads)
    if "=" in cleaned:
        raise ValueError("invalid base64 QR payload")

    try:
        # Pad the string to valid base64 length and decode
        padded_text = _add_padding_to_base64(cleaned)
        decoded = base64.b64decode(padded_text, validate=True)
    except (binascii.Error, ValueError) as exc:
        raise ValueError("invalid base64 QR payload") from exc

    # Verify correctness by re-encoding and comparing
    canonical = base64.b64encode(decoded).decode("ascii").rstrip("=")
    if canonical != cleaned:
        raise ValueError("invalid base64 QR payload")

    return decoded

def _add_padding_to_base64(text: str) -> str:
    """Add required padding to unpadded base64 text."""
    padding_needed = (4 - len(text) % 4) % 4
    return text + ("=" * padding_needed)

__all__ = [
    "QR_PAYLOAD_CODEC_BASE64",
    "QR_PAYLOAD_CODEC_RAW",
    "QrPayloadCodec",
    "decode_qr_payload",
    "encode_qr_payload",
]

# Compare multiple NumPy data files for equality

import argparse
import sys

try:
    import argcomplete
except ImportError:
    argcomplete = None

import numpy as np


def parse_args():
    parser = argparse.ArgumentParser(
        description="Check if all provided NumPy files contain identical data"
    )
    parser.add_argument(
        "files",
        metavar="file",
        nargs="+",
        help="NumPy data files to compare"
    )

    if argcomplete:
        argcomplete.autocomplete(parser)

    return parser.parse_args()


def main():
    arguments = parse_args()

    # Need at least two files to compare
    if len(arguments.files) < 2:
        return 0

    # Load the first file as reference
    reference_data = np.load(arguments.files[0])

    # Compare each subsequent file against the reference
    for filepath in arguments.files[1:]:
        current_data = np.load(filepath)

        # If any file differs, exit with error code
        if not np.array_equal(reference_data, current_data):
            return 1

    # All files match
    return 0


if __name__ == "__main__":
    sys.exit(main())

