import json
import requests
from qim3d.utils._logger import log

def _check_response_status(response: requests.Response) -> bool:
    # Verify if the HTTP request was successful
    if not response.ok:
        log.error(f'Failed to retrieve data for DOI ({response.reason})')
        return False
    return True

def _convert_doi_to_endpoint(doi: str) -> str:
    # Ensure URL format; prepend DOI resolver if needed
    if not doi.startswith('http'):
        endpoint = 'https://doi.org/' + doi
    else:
        endpoint = doi
    return endpoint

def _send_request(doi: str, headers: dict) -> requests.Response:
    # Resolve DOI to full URL
    endpoint = _convert_doi_to_endpoint(doi)
    # Perform GET request with timeout and header configuration
    result = requests.get(endpoint, headers=headers, timeout=10)
    if not _check_response_status(result):
        return None
    return result

def _log_and_extract_content(doi: str, headers: dict) -> str:
    response = _send_request(doi, headers)
    if response is None:
        return ""

    # Handle content decoding based on encoding information
    if response.encoding:
        content = response.content.decode(response.encoding)
    else:
        content = response.text

    log.info(content)
    return content

def fetch_bibtex_entry(doi: str) -> str:
    """Fetches BibTeX citation for a given DOI"""
    citation_headers = {'Accept': 'application/x-bibtex'}
    return _log_and_extract_content(doi, citation_headers)

def custom_header_request(doi: str, headers: dict) -> str:
    """
    Allows passing a custom Accept header for flexible metadata retrieval.

    Example usage:
        import qim3d
        doi = "https://doi.org/10.1101/2022.11.08.515664"
        headers = {"Accept": "text/bibliography"}
        result = qim3d.utils.custom_header_request(doi, headers)
    """
    return _log_and_extract_content(doi, headers)

def retrieve_metadata(doi: str) -> dict:
    """Retrieves structured metadata in CSL JSON format from DOI"""
    csl_headers = {'Accept': 'application/vnd.citationstyles.csl+json'}
    response = _send_request(doi, csl_headers)
    if response is None:
        return {}
    return json.loads(response.text)

def construct_citation(doi: str) -> str:
    """Constructs a formatted reference string using metadata retrieved from DOI"""
    metadata = retrieve_metadata(doi)
    if not metadata:
        return ""
    citation = format_citation_from_metadata(metadata)
    return citation

def format_citation_from_metadata(metadata: dict) -> str:
    """Formats a citation string from parsed metadata dictionary"""
    # Extract author names in "Family Given" format
    authors_list = [
        f"{author['family']} {author['given']}" 
        for author in metadata.get('author', [])
    ]
    authors_str = ', '.join(authors_list)

    # Extract year from date structure
    year = metadata.get('issued', {}).get('date-parts', [[None]])[0][0]

    # Extract other bibliographic fields
    title = metadata.get('title', '')
    publisher = metadata.get('publisher', '')
    url = metadata.get('URL', '')
    doi = metadata.get('DOI', '')

    # Assemble final reference string
    citation = f'{authors_str} ({year}). {title}. {publisher} ({url}). DOI: {doi}'
    return citation

import torch
import torch.nn as nn
from torch.distributed.tensor import (
    DeviceMesh,
    DTensor,
    Replicate,
    Shard,
    distribute_tensor,
)
from torch.distributed.tensor.parallel import (
    ColwiseParallel,
    RowwiseParallel,
    SequenceParallel,
)

def _apply_sharding_to_parameter(target_module, param_name, mesh, source_rank, placement_list):
    """Helper to create and register a distributed parameter."""
    original_param = getattr(target_module, param_name)
    dist_param = nn.Parameter(
        distribute_tensor(original_param, mesh, placement_list, src_data_rank=source_rank),
        requires_grad=original_param.requires_grad,
    )
    assert dist_param.requires_grad == original_param.requires_grad
    setattr(target_module, param_name, dist_param)


class LoRAColwise(ColwiseParallel):
    def _partition_linear_layer(self, layer_name, linear_module, device_mesh):
        # Helper to resolve LoRA-specific submodules
        def _resolve_lora_component(full_name):
            if full_name.endswith("lora_A.weight"):
                assert hasattr(linear_module, "lora_A"), f"Missing lora_A in {linear_module}"
                return linear_module.lora_A, "weight"
            elif full_name.endswith("lora_B.weight"):
                assert hasattr(linear_module, "lora_B"), f"Missing lora_B in {linear_module}"
                return linear_module.lora_B, "weight"
            else:
                return linear_module, full_name

        # Distribute all parameters (including LoRA A/B) column-wise (Shard(0))
        for full_name, _ in linear_module.named_parameters():
            target_mod, target_name = _resolve_lora_component(full_name)
            _apply_sharding_to_parameter(target_mod, target_name, device_mesh, self.src_data_rank, [Shard(0)])

        # Hook to replicate LoRA A output across devices before next layer
        def _lora_a_postprocess_hook(mod, inp, out):
            if isinstance(out, DTensor):
                if any(isinstance(p, Shard) for p in out.placements):
                    out = out.redistribute(device_mesh=out.device_mesh, placements=[Replicate()])
            return out

        if hasattr(linear_module, "lora_A"):
            linear_module.lora_A.register_forward_hook(_lora_a_postprocess_hook)

    def _partition_embedding_layer(self, emb_name, embedding_module, device_mesh):
        # Embedding weights are sharded along vocab dimension → Shard(1)
        for name, param in embedding_module.named_parameters():
            _apply_sharding_to_parameter(embedding_module, name, device_mesh, self.src_data_rank, [Shard(1)])


class LoRARowwise(RowwiseParallel):
    def _partition_linear_layer(self, layer_name, linear_module, device_mesh):
        # Weight: Shard(1), Bias: Replicate()
        _apply_sharding_to_parameter(linear_module, "weight", device_mesh, self.src_data_rank, [Shard(1)])
        bias_attr = getattr(linear_module, "bias", None)
        if bias_attr is not None:
            _apply_sharding_to_parameter(linear_module, "bias", device_mesh, self.src_data_rank, [Replicate()])

        # LoRA A/B weights also row-wise (Shard(1))
        if hasattr(linear_module, "lora_A"):
            _apply_sharding_to_parameter(linear_module.lora_A, "weight", device_mesh, self.src_data_rank, [Shard(1)])
        if hasattr(linear_module, "lora_B"):
            _apply_sharding_to_parameter(linear_module.lora_B, "weight", device_mesh, self.src_data_rank, [Shard(1)])

        # Magnitude scaling (if present): replicated
        if hasattr(linear_module, "lora_magnitude"):
            _apply_sharding_to_parameter(linear_module, "lora_magnitude", device_mesh, self.src_data_rank, [Replicate()])

    def _partition_embedding_layer(self, emb_name, embedding_module, device_mesh):
        # Embedding weights sharded along hidden dim → Shard(0)
        for name, param in embedding_module.named_parameters():
            _apply_sharding_to_parameter(embedding_module, name, device_mesh, self.src_data_rank, [Shard(0)])


class LoRASequenceParallel(SequenceParallel):
    def _replicate_module_parameters(self, module_name: str, module: nn.Module, mesh: DeviceMesh):
        # Ensure all parameters (e.g., LayerNorm/RMSNorm) are fully replicated
        for param_key, param_val in module.named_parameters():
            replicated_dtensor = torch.nn.Parameter(
                DTensor.from_local(param_val, mesh, [Replicate()], run_check=False),
                requires_grad=param_val.requires_grad,
            )
            module.register_parameter(param_key, replicated_dtensor)


def convert_to_lora_plan(parallel_plan):
    """Dynamically upgrades standard parallel plans to LoRA-aware variants."""
    mapping = {
        ColwiseParallel: LoRAColwise,
        RowwiseParallel: LoRARowwise,
        SequenceParallel: LoRASequenceParallel,
    }
    base_class = type(parallel_plan)
    upgraded_class = mapping.get(base_class, base_class)
    parallel_plan.__class__ = upgraded_class
    return parallel_plan

