                for line in f:
                    stripped_line = line.strip()
                    if stripped_line and not stripped_line.startswith("#") and "=" in stripped_line:
                        key_part, value_part = stripped_line.split("=", 1)
                        if key_part.strip() == "GET_TLDR_API_KEY":
                            api_key = value_part.strip().strip('"').strip("'")
                            break
        except FileNotFoundError:
            pass

    return api_key, config_paths[1] or os.path.expanduser("~/.config/get-tldr/skill.log")


def validate_url(url_string):
    """Validate URL has proper scheme."""
    parsed = urlparse(url_string)
    return parsed.scheme in ("http", "https")


def send_summary_request(api_url, api_key, input_url):
    """Send request to summarization API and handle responses."""
    import requests

    payload = {"input": input_url}
    headers = {
        "Content-Type": "application/json",
        "X-API-Key": api_key
    }

    try:
        response = requests.post(api_url, headers=headers, json=payload, timeout=30)
        response.raise_for_status()
        return response.json()
    except requests.HTTPError as http_err:
        try:
            error_data = response.json()
        except Exception:
            error_data = {"text": response.text}
        return {"status_code": response.status_code, "error": error_data}
    except Exception:
        try:
            return response.json()
        except Exception:
            return {
                "status_code": getattr(response, 'status_code', None),
                "text": getattr(response, 'text', str(response))
            }


def log_interaction(log_file_path, url, result):
    """Append interaction record to log file."""
    timestamp = datetime.now(timezone.utc).isoformat()
    log_entry = {
        "timestamp": timestamp,
        "sent": {"input": url},
        "response": result
    }

    try:
        with open(log_file_path, "a", encoding="utf-8") as log_file:
            log_file.write(json.dumps(log_entry, ensure_ascii=False) + "\n")
    except Exception:
        pass


if __name__ == '__main__':
    # Configuration loading
    API_KEY, LOGFILE = load_config()

    if not API_KEY:
        print(json.dumps({
            "error": "Missing API key. Create ~/.config/get-tldr/config.json with api_token, or set GET_TLDR_API_KEY env var or place it in this skill folder's .env."
        }))
        sys.exit(1)

    # Argument validation
    if len(sys.argv) < 2:
        print(json.dumps({"error": "Missing URL argument"}))
        sys.exit(2)

    target_url = sys.argv[1]

    if not validate_url(target_url):
        print(json.dumps({
            "error": "Invalid URL scheme; must start with http:// or https://",
            "url": target_url
        }))
        sys.exit(2)

    # Perform summarization
    summary_result = send_summary_request(
        "https://www.get-tldr.com/api/v1/summarize",
        API_KEY,
        target_url
    )

    # Log the interaction
    log_interaction(LOGFILE, target_url, summary_result)

    # Output result
    print(json.dumps(summary_result, ensure_ascii=False, indent=2))

