import argparse
import os
import subprocess
import sys

# Map of test paths to number of processes (default 1)
DISTRIBUTED_TESTS = {}
TESTS_PASSED = True
SKIP_TESTS = []

def parse_arguments():
    parser = argparse.ArgumentParser(description="Execute Primus unit tests")
    parser.add_argument(
        "--jax",
        action="store_true",
        help="Run only JAX-specific unit test: tests/trainer/test_maxtext_trainer.py",
    )
    return parser.parse_args()

def collect_unit_tests(jax_only=False):
    """
    When jax_only is True:
        Return only the JAX trainer test file.
    Otherwise:
        Return all test files except those in SKIP_TESTS.
    """
    global DISTRIBUTED_TESTS, SKIP_TESTS, TESTS_PASSED
    base_dir = "./tests"
    selected_tests = {}

    if jax_only:
        jax_test = "trainer/test_maxtext_trainer.py"
        full_path = os.path.join(base_dir, jax_test)
        return {full_path: 1}

    SKIP_TESTS = [
        "trainer/test_maxtext_trainer.py",
    ]

    for dirpath, _, filenames in os.walk(base_dir):
        for filename in filenames:
            if not filename.endswith(".py") or not filename.startswith("test_"):
                continue

            # Compute relative path from base_dir
            full_file_path = os.path.join(dirpath, filename)
            rel_path = os.path.relpath(full_file_path, start=base_dir)

            if rel_path in SKIP_TESTS:
                continue

            nproc = DISTRIBUTED_TESTS.get(filename, 1)
            selected_tests[full_file_path] = nproc

    return selected_tests

def run_test(test_path, num_processes):
    global TESTS_PASSED
    if num_processes == 1:
        command = f"pytest --maxfail=1 {test_path} -s"
    else:
        command = f"torchrun --nnodes 1 --nproc-per-node {num_processes} {test_path}"

    process = subprocess.Popen(command, shell=True)
    process.wait()

    if process.returncode != 0:
        TESTS_PASSED = False

def main():
    arguments = parse_arguments()
    test_list = collect_unit_tests(jax_only=arguments.jax)

    for test_file, processes in test_list.items():
        run_test(test_file, processes)

    if not TESTS_PASSED:
        print("Unit Tests failed! More details please check log.")
        sys.exit(1)
    else:
        print("Unit Tests pass!")

if __name__ == "__main__":
    main()

# Abstract base class for Conv2D weight handling with registration support
from abc import ABCMeta, abstractmethod
import torch
from lightx2v.utils.registry_factory import CONV2D_WEIGHT_REGISTER
from lightx2v_platform.base.global_var import AI_DEVICE

class Conv2dWeightHandler(metaclass=ABCMeta):
    def __init__(self, weight_key, bias_key, stride_val, pad_val, dil_val, group_val):
        self.weight_key = weight_key
        self.bias_key = bias_key
        self.stride_val = stride_val
        self.pad_val = pad_val
        self.dil_val = dil_val
        self.group_val = group_val
        self.settings = {}

    @abstractmethod
    def initialize_weights(self, weight_map):
        pass

    @abstractmethod
    def process_tensor(self, input_data):
        pass

    def configure(self, config_dict=None):
        if config_dict is not None:
            self.settings.update(config_dict)

@CONV2D_WEIGHT_REGISTER("Standard")
class StandardConv2dWeight(Conv2dWeightHandler):
    def __init__(self, weight_key, bias_key, stride=1, padding=0, dilation=1, groups=1):
        super().__init__(weight_key, bias_key, stride, padding, dilation, groups)

    def initialize_weights(self, weight_map):
        self.weight_tensor = weight_map[self.weight_key].to(AI_DEVICE)
        self.bias_tensor = weight_map[self.bias_key].to(AI_DEVICE) if self.bias_key is not None else None

    def process_tensor(self, input_data):
        return torch.nn.functional.conv2d(
            input_data, 
            weight=self.weight_tensor, 
            bias=self.bias_tensor, 
            stride=self.stride_val, 
            padding=self.pad_val, 
            dilation=self.dil_val, 
            groups=self.group_val
        )

    def move_to_cpu(self, async_mode=False):
        self.weight_tensor = self.weight_tensor.cpu(async_mode=async_mode)
        if self.bias_tensor is not None:
            self.bias_tensor = self.bias_tensor.cpu(async_mode=async_mode)

    def move_to_gpu(self, async_mode=False):
        self.weight_tensor = self.weight_tensor.to(AI_DEVICE, async_mode=async_mode)
        if self.bias_tensor is not None:
            self.bias_tensor = self.bias_tensor.to(AI_DEVICE, async_mode=async_mode)

    def export_state(self, target_dict=None):
        if target_dict is None:
            target_dict = {}
        target_dict[self.weight_key] = self.weight_tensor.cpu().detach().clone()
        if self.bias_tensor is not None:
            target_dict[self.bias_key] = self.bias_tensor.cpu().detach().clone()
        return target_dict

