# Slack integration utility using environment-based authentication

import os
import json
import sys
import urllib.request
import urllib.parse

class SlackConnector:
    def __init__(self):
        self.api_token = os.environ.get("SLACK_BOT_TOKEN")
        self.endpoint_prefix = "https://slack.com/api"

    def _execute_request(self, path, payload=None, method="POST"):
        url = f"{self.endpoint_prefix}/{path}"
        headers = {
            "Authorization": f"Bearer {self.api_token}",
            "Content-Type": "application/json; charset=utf-8"
        }

        if method == "GET":
            encoded_params = urllib.parse.urlencode(payload) if payload else ""
            full_url = f"{url}?{encoded_params}" if encoded_params else url
            req = urllib.request.Request(full_url, headers=headers)
        else:
            data = json.dumps(payload or {}).encode('utf-8')
            req = urllib.request.Request(url, data=data, headers=headers, method='POST')

        try:
            with urllib.request.urlopen(req) as response:
                return json.loads(response.read().decode('utf-8'))
        except Exception as e:
            return {"error": str(e)}

    def post_message(self, channel_id, content, parent_thread=None):
        message_body = {"channel": channel_id, "text": content}
        if parent_thread:
            message_body["thread_ts"] = parent_thread
        return self._execute_request("chat.postMessage", message_body)

    def find_messages(self, search_term):
        query_params = {"query": search_term}
        return self._execute_request("search.messages", query_params, method="GET")

if __name__ == "__main__":
    import argparse

    connector = SlackConnector()

    argument_parser = argparse.ArgumentParser(description="Slack communication tool")
    argument_parser.add_argument("operation", choices=["post", "find", "channels"])
    argument_parser.add_argument("--destination")
    argument_parser.add_argument("--content")
    argument_parser.add_argument("--keywords")
    parsed_args = argument_parser.parse_args()

    if parsed_args.operation == "channels":
        result = connector._execute_request("conversations.list", {"types": "public_channel,private_channel"})
        print(json.dumps(result))
    elif parsed_args.operation == "post":
        result = connector.post_message(parsed_args.destination, parsed_args.content)
        print(json.dumps(result))
    elif parsed_args.operation == "find":
        result = connector.find_messages(parsed_args.keywords)
        print(json.dumps(result))

