import json
from volcengine.ApiInfo import ApiInfo
from typing import Any
from volcengine import Credentials
from volcengine import ServiceInfo
from volcengine.base import Service

class DiagnosisService(Service.Service):
    def __init__(self, region: str, endpoint: str, api_info_map: dict, service_name: str, access_key: str, secret_key: str):
        # Initialize timeout and schema settings
        self.connect_timeout = 10
        self.socket_read_timeout = 10
        self.protocol = 'https'
        self.headers = {}
        self.headers["Content-Type"] = "application/json"

        # Store configuration
        self.gateway_endpoint = endpoint
        self.credentials = Credentials.Credentials(access_key, secret_key, service_name, region)
        self.service_config = ServiceInfo.ServiceInfo(
            self.gateway_endpoint,
            self.headers,
            self.credentials,
            self.connect_timeout,
            self.socket_read_timeout,
            self.protocol
        )
        self.api_definitions = api_info_map

        # Initialize parent class
        Service.Service.__init__(self, self.service_config, self.api_definitions)

    def execute_get_request(self, operation_name: str, query_params: dict, multi_value=False) -> str:
        raw_response = super(DiagnosisService, self).get(operation_name, query_params, multi_value)
        try:
            parsed_response = json.loads(raw_response)
        except Exception as error:
            raise Exception(f"Failed to parse JSON response: {error}, Response: {raw_response}")

        if "ResponseMetadata" not in parsed_response:
            raise Exception(f"Missing ResponseMetadata in response for '{operation_name}', Response: {raw_response}")
        elif "Error" in parsed_response["ResponseMetadata"]:
            error_details = parsed_response["ResponseMetadata"]["Error"]
            raise Exception(f"Operation '{operation_name}' failed with error: {error_details}")

        return parsed_response

