from typing import Any, TypeGuard, TypeVar

T = TypeVar("T")

def is_list_of_type(
    target_type: type[T],
    items: list[Any],
) -> TypeGuard[list[T]]:
    if not items:
        return False
    for item in items:
        if not isinstance(item, target_type):
            return False
    return True

# Factory pattern implementation for UCM connectors with lazy module loading

import importlib
from typing import Dict, Callable, Type
from ucm.logger import init_logger
from ucm.store.ucmstore import UcmKVStoreBase

logger = init_logger(__name__)

class UcmConnectorFactory:
    # Dictionary to store connector registrations: name -> loader function
    _connector_registry: Dict[str, Callable[[], Type[UcmKVStoreBase]]] = {}

    @classmethod
    def register(cls, name: str, module_path: str, class_name: str) -> None:
        """Register a new connector type using lazy module loading."""
        if name in cls._connector_registry:
            raise ValueError(f"Connector '{name}' has already been registered.")

        def create_instance():
            loaded_module = importlib.import_module(module_path)
            return getattr(loaded_module, class_name)

        cls._connector_registry[name] = create_instance

    @classmethod
    def build_connector(cls, connector_type: str, configuration: dict) -> UcmKVStoreBase:
        """Create and return an instance of the specified connector."""
        if connector_type in cls._connector_registry:
            connector_class = cls._connector_registry[connector_type]()
        else:
            raise ValueError(f"Unsupported connector type: {connector_type}")

        assert issubclass(connector_class, UcmKVStoreBase)
        logger.info(f"Initializing connector: {connector_type}")
        return connector_class(configuration)

# Register standard connector implementations
UcmConnectorFactory.register(
    "UcmNfsStore", 
    "ucm.store.nfsstore.nfsstore_connector", 
