# Reimplemented version of the subreddit scanner with equivalent functionality
import sys
from typing import Any, Dict, List, Optional

def _log(msg: str) -> None:
    print(f"[scanner] {msg}", file=sys.stderr)

def _get_nested_value(data: Dict, keys: List[str]) -> Any:
    """Safely retrieve nested dictionary values using a list of keys."""
    current = data
    for key in keys:
        if isinstance(current, dict):
            current = current.get(key, {})
        else:
            return {}
    return current if not isinstance(current, dict) else 0

def _format_subreddit_info(raw_data: Dict[str, Any]) -> Dict[str, Any]:
    """Convert raw subreddit info into standardized format."""
    if "error" in raw_data:
        return raw_data

    # Extract fields with fallbacks and truncation
    name = raw_data.get("display_name") or raw_data.get("subreddit", "")
    title = raw_data.get("title", "")
    subscribers = raw_data.get("subscribers", 0)
    active_users = (
        raw_data.get("accounts_active") or 
        raw_data.get("active_user_count", 0)
    )
    description = (raw_data.get("public_description") or "")[:200]
    created_utc = raw_data.get("created_utc", "")

    return {
        "name": name,
        "title": title,
        "subscribers": subscribers,
        "active_users": active_users,
        "description": description,
        "created_utc": created_utc,
    }

def _fetch_subreddit_about(subreddit: str, fetcher_func) -> Dict[str, Any]:
    """Wrapper to safely fetch subreddit 'about' information."""
    try:
        raw_info = fetcher_func(subreddit)
        return _format_subreddit_info(raw_info)
    except Exception as exc:
        _log(f"fetch_about({subreddit}) failed: {exc}")
        return {"error": str(exc)}

def _calculate_avg_engagement(strategy_data: Dict) -> float:
    """Calculate average score across content types in strategy data."""
    content_types = strategy_data.get("content_types", {})
    if not isinstance(content_types, dict):
        return 0.0

    scores = []
    for type_data in content_types.values():
        if isinstance(type_data, dict):
            avg_score = type_data.get("avg_score", 0)
            scores.append(avg_score)

    if not scores:
        return 0.0

    return round(sum(scores) / len(scores), 1)

def scan_subreddit(
    subreddit: str,
    sort: str = "top",
    timeframe: str = "week",
    limit: int = 25,
    fetcher=None,
    post_reader=None,
    strategy_extractor=None,
) -> Dict[str, Any]:
    """Scan a single subreddit for metadata and content analysis."""
    _log(f"Scanning r/{subreddit} ({sort}/{timeframe}, limit={limit})")

    # Use provided modules/functions or defaults
    from . import cascade_fetcher
    from .deep_reader import read_top_posts
    from .strategy_extractor import extract_strategy

    about_info = _fetch_subreddit_about(subreddit, cascade_fetcher.fetch_about)
    _log(f"r/{subreddit}: about fetched")

    posts = read_top_posts(subreddit, sort, timeframe, limit)
    _log(f"r/{subreddit}: {len(posts)} posts fetched")

    strategy = extract_strategy(posts)

    return {
        "subreddit": subreddit,
        "about": about_info,
        "posts_fetched": len(posts),
        "strategy": strategy,
        "data_source": "cascade",
    }

def bulk_scan(
    subreddits: List[str],
    sort: str = "top",
    timeframe: str = "week",
    limit: int = 25,
) -> Dict[str, Any]:
    """Scan multiple subreddits and generate comparative analysis."""
    results: Dict[str, Any] = {}

    for sub in subreddits:
        try:
            results[sub] = scan_subreddit(sub, sort, timeframe, limit)
        except Exception as e:
            _log(f"r/{sub} scan failed: {e}")
            results[sub] = {"subreddit": sub, "error": str(e)}

    comparison = _generate_comparison(results)
    return {
        "subreddits": results,
        "comparison": comparison,
    }

def _generate_comparison(scan_results: Dict[str, Dict]) -> Dict[str, Any]:
    """Generate comparative metrics across successfully scanned subreddits."""
    successful_scans = {
        k: v for k, v in scan_results.items() 
        if "error" not in v
    }

    if len(successful_scans) < 2:
        return {"note": "Need at least two successful scans for comparison"}

    return {
        "by_subscribers": _rank_by_metric(successful_scans, ["about", "subscribers"]),
        "by_engagement": _rank_by_engagement(successful_scans),
    }

def _rank_by_metric(
    scan_data: Dict[str, Dict], 
    field_path: List[str]
) -> List[Dict]:
    """Rank subreddits by a specific metric defined via path."""
    ranked_items: List[Dict] = []

    for name, data in scan_data.items():
        value = _get_nested_value(data, field_path)
        ranked_items.append({
            "subreddit": name,
            "value": value if not isinstance(value, dict) else 0
        })

    return sorted(ranked_items, key=lambda x: x["value"], reverse=True)

def _rank_by_engagement(scan_data: Dict[str, Dict]) -> List[Dict]:
    """Rank subreddits by average engagement score across content types."""
    ranked_items: List[Dict] = []

    for name, data in scan_data.items():
        strategy = data.get("strategy", {})
        avg_score = _calculate_avg_engagement(strategy)
        ranked_items.append({
            "subreddit": name,
            "avg_score_across_types": avg_score
        })

    return sorted(ranked_items, key=lambda x: x["avg_score_across_types"], reverse=True)

