import os
import sys
from pathlib import Path
from graph_net.torch.fx_graph_cache_util import (
    parse_immutable_model_path_into_sole_graph_module,
)

class GraphModuleProcessor:
    def __init__(self, settings=None):
        self.settings = self._configure(**(settings or {}))
        self.processed_count = 0

    def _configure(
        self,
        base_model_dir,
        result_dir,
        skip_processed=False,
        max_models=None,
    ):
        return {
            "base_model_dir": base_model_dir,
            "result_dir": result_dir,
            "skip_processed": skip_processed,
            "max_models": max_models,
        }

    def process(self, relative_path):
        full_path = os.path.join(self.settings["base_model_dir"], relative_path)

        if self.settings["skip_processed"] and self._already_processed(relative_path):
            return

        graph_module = parse_immutable_model_path_into_sole_graph_module(full_path)

        target_dir = Path(self.settings["result_dir"]) / relative_path
        target_dir.mkdir(parents=True, exist_ok=True)

        op_count = self._count_operations(graph_module)
        (target_dir / "operation_count.txt").write_text(str(op_count))

        self._update_processed_count()

    def _count_operations(self, gm):
        excluded_ops = {"placeholder", "output"}
        return sum(1 for node in gm.graph.nodes if node.op not in excluded_ops)

    def _already_processed(self, rel_path):
        return (Path(self.settings["result_dir"]) / rel_path).is_dir()

    def _update_processed_count(self):
        self.processed_count += 1
        threshold = self.settings["max_models"]
        if threshold is not None and self.processed_count >= threshold:
            print(
                "Processed model count reached the configured limit",
                file=sys.stderr,
            )
            sys.exit(0)

