from megatron.core.dist_checkpointing.strategies.filesystem_async import FileSystemWriterAsync

class ROCmFileSystemWriterAsync(FileSystemWriterAsync):
    """
    FileSystemWriterAsync wrapper for ROCm compatibility.
    On ROCm/HIP, using non_blocking=True causes tensors to be stored in pinned memory,
    which triggers segmentation faults when forking subprocesses afterward.
    """
    @staticmethod
    def preload_tensors(*args, **kwargs):
        # Ensure non_blocking is False on HIP platforms to avoid segfaults
        # Pinned memory usage with forking processes is problematic on ROCm
        if hasattr(torch, 'version') and getattr(torch.version, 'hip', False):
            print("HIP/ROCm environment detected: disabling non_blocking in preload_tensors")

            # Override non_blocking parameter regardless of how it's passed
            if "non_blocking" in kwargs:
                kwargs["non_blocking"] = False
            else:
                # If not in kwargs, check positional arguments (last one typically controls non_blocking)
                modified_args = list(args)
                if len(modified_args) > 1 and isinstance(modified_args[-1], bool):
                    modified_args[-1] = False
                    args = tuple(modified_args)
                elif len(modified_args) == 1:
                    # Only first argument present; insert non_blocking=False as second arg
                    args = args + (False,)

        return FileSystemWriterAsync.preload_tensors(*args, **kwargs)

from typing import Optional, Dict, Any
from loguru import logger
from .worker import TorchrunInferenceWorker

class DistributedInferenceService:
    def __init__(self):
        self._inference_worker = None
        self._service_active = False
        self._configuration = None

    def begin_distributed_inference(self, config) -> bool:
        self._configuration = config
        if self._service_active:
            logger.warning("Distributed inference service is already operational")
            return True

        try:
            self._inference_worker = TorchrunInferenceWorker()
            if not self._inference_worker.bootstrap(config):
                raise RuntimeError("Worker bootstrap failed")

            self._service_active = True
            logger.info(f"Rank {self._inference_worker.global_rank} inference service initialized successfully")
            return True

        except Exception as error:
            logger.error(f"Exception during service initialization: {str(error)}")
            self.terminate_distributed_inference()
            return False

    def terminate_distributed_inference(self):
        if not self._service_active:
            return

        try:
            if self._inference_worker:
                self._inference_worker.shutdown()
            logger.info("Inference service shutdown completed")
        except Exception as error:
            logger.error(f"Error during service shutdown: {str(error)}")
        finally:
            self._inference_worker = None
            self._service_active = False

    async def enqueue_task_async(self, task_payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        if not self._service_active or not self._inference_worker:
            logger.error("Inference service is inactive")
            return None

        if self._inference_worker.global_rank != 0:
            return None

        try:
            if self._inference_worker.busy:
                logger.info(f"Queueing task {task_payload.get('task_id')} - previous task still processing")

            self._inference_worker.busy = True
            result = await self._inference_worker.handle_request(task_payload)
            self._inference_worker.busy = False
            return result

        except Exception as error:
            self._inference_worker.busy = False
            logger.error(f"Task execution failed: {str(error)}")
            return {
                "task_id": task_payload.get("task_id", "unknown"),
                "status": "failed",
                "error": str(error),
                "message": f"Task execution failed: {str(error)}",
            }

    def get_service_info(self) -> Dict[str, Any]:
        assert hasattr(self, "_configuration"), "Distributed inference service has not been started. Call begin_distributed_inference() first."
        return {
            "nproc_per_node": self._inference_worker.world_size,
            "model_cls": self._configuration.model_cls,
            "model_path": self._configuration.model_path
        }

    async def execute_worker_loop(self):
        if self._inference_worker and self._inference_worker.global_rank != 0:
            await self._inference_worker.run_worker_cycle()

