from typing_extensions import Literal, TypeAlias

# Define allowed processor types using a set for validation
VALID_PROCESSORS = {
    "canny", "depth", "softedge", "lineart", "lineart_anime",
    "openpose", "normal", "tile", "none", "inpaint"
}

Processor_id: TypeAlias = Literal[
    "canny", "depth", "softedge", "lineart", "lineart_anime",
    "openpose", "normal", "tile", "none", "inpaint"
]

class Annotator:
    def __init__(self, processor_id: Processor_id, model_path="models/Annotators", 
                 detect_resolution=None, device='cuda', skip_processor=False):
        # Validate processor_id early
        if processor_id not in VALID_PROCESSORS:
            raise ValueError(f"Unsupported processor_id: {processor_id}")

        self.processor_id = processor_id
        self.detect_resolution = detect_resolution

        # Initialize processor based on type
        if skip_processor or processor_id in {"tile", "none", "inpaint"}:
            self.processor = None
        else:
            self.processor = self._create_processor(processor_id, model_path, device)

    def _create_processor(self, proc_id: str, model_path: str, device: str):
        """Factory method to instantiate the appropriate processor."""
        if proc_id == "canny":
            from controlnet_aux.processor import CannyDetector
            return CannyDetector()
        elif proc_id == "depth":
            from controlnet_aux.processor import MidasDetector
            return MidasDetector.from_pretrained(model_path).to(device)
        elif proc_id == "softedge":
            from controlnet_aux.processor import HEDdetector
            return HEDdetector.from_pretrained(model_path).to(device)
        elif proc_id == "lineart":
            from controlnet_aux.processor import LineartDetector
            return LineartDetector.from_pretrained(model_path).to(device)
        elif proc_id == "lineart_anime":
            from controlnet_aux.processor import LineartAnimeDetector
            return LineartAnimeDetector.from_pretrained(model_path).to(device)
        elif proc_id == "openpose":
            from controlnet_aux.processor import OpenposeDetector
            return OpenposeDetector.from_pretrained(model_path).to(device)
        elif proc_id == "normal":
            from controlnet_aux.processor import NormalBaeDetector
            return NormalBaeDetector.from_pretrained(model_path).to(device)
        else:
            raise ValueError(f"Unexpected processor ID '{proc_id}'")

    def to(self, device):
        """Move underlying model to specified device if applicable."""
        if self.processor is not None and hasattr(self.processor, 'model'):
            if hasattr(self.processor.model, 'to'):
                self.processor.model.to(device)

    def __call__(self, image, mask=None):
        width, height = image.size

        # Prepare kwargs for special processors
        kwargs = {}
        if self.processor_id == "openpose":
            kwargs.update({
                "include_body": True,
                "include_hand": True,
                "include_face": True
            })

        # Process image if a valid processor exists
        if self.processor is not None:
            target_res = self.detect_resolution if self.detect_resolution is not None else min(width, height)
            processed = self.processor(
                image, 
                detect_resolution=target_res, 
                image_resolution=min(width, height), 
                **kwargs
            )
            result_image = processed.resize((width, height))
        else:
            result_image = image.resize((width, height))

        return result_image

import os

class MemoryLimitNotFoundException(Exception):
    """Raised when the memory limit cannot be determined from the cgroup system."""

def retrieve_container_memory_limit() -> int:
    """Obtains the memory constraint for the current container by inspecting the cgroup filesystem.
    Supports both cgroup v1 and v2, reading the relevant file to get the memory cap in bytes.

    Returns:
        int: The memory limit in bytes.

    Raises:
        MemoryLimitNotFoundException: If the memory limit cannot be ascertained.
    """
    # Attempt cgroup v2 first
    v2_mem_file = "/sys/fs/cgroup/memory.max"
    if os.path.isfile(v2_mem_file):
        try:
            with open(v2_mem_file, "r", encoding="utf-8") as file_obj:
                raw_value = file_obj.read().strip()
                if raw_value == "max":
                    raise MemoryLimitNotFoundException(
                        "No memory restriction defined in cgroup v2 (value is 'max')."
                    )
                return int(raw_value)
        except (OSError, ValueError) as err:
            raise MemoryLimitNotFoundException(
                f"Unable to parse cgroup v2 memory limit: {err}"
            ) from err

    # Fallback to cgroup v1
    v1_mem_file = "/sys/fs/cgroup/memory/memory.limit_in_bytes"
    if os.path.isfile(v1_mem_file):
        try:
            with open(v1_mem_file, "r", encoding="utf-8") as file_obj:
                raw_value = file_obj.read().strip()
                mem_limit = int(raw_value)
                # Consider extremely large values as "unlimited"
                if mem_limit >= (1 << 60):
                    raise MemoryLimitNotFoundException(
                        "Memory limit is effectively unlimited in cgroup v1."
                    )
                return mem_limit
        except (OSError, ValueError) as err:
            raise MemoryLimitNotFoundException(
                f"Unable to parse cgroup v1 memory limit: {err}"
            ) from err

    raise MemoryLimitNotFoundException("No cgroup memory limit file accessible.")

