import numpy as np

logger = logging.getLogger(__name__)

class EmbeddingProvider:
    _singleton = None
    _encoder = None

    def __init__(self):
        self.model_id = os.getenv("EMBEDDING_MODEL_NAME", "all-MiniLM-L6-v2")
        self.use_cloud_embeddings = os.getenv("USE_OPENAI_EMBEDDINGS", "false").lower() == "true"
        self.cloud_api_token = os.getenv("OPENAI_API_KEY")
        self.cloud_model_id = os.getenv("OPENAI_EMBEDDING_MODEL", "text-embedding-3-small")

    @classmethod
    def get_provider(cls):
        if cls._singleton is None:
            cls._singleton = cls()
        return cls._singleton

    def _initialize_local_encoder(self):
        if self._encoder is None:
            try:
                from sentence_transformers import SentenceTransformer
                logger.info(f"Initializing local encoder: {self.model_id}")
                self._encoder = SentenceTransformer(self.model_id)
            except ImportError:
                logger.error("sentence-transformers package missing. Install via: pip install sentence-transformers")
                raise
            except Exception as err:
                logger.error(f"Error loading local embedding model: {err}")
                raise

    async def produce_vector(self, content: str) -> List[float]:
        """Produce a numerical vector representation for the input string."""
        if not content:
            return []
        if self.use_cloud_embeddings:
            return await self._produce_cloud_embedding(content)
        else:
            return await self._produce_local_via_gateway(content)

    async def _produce_local_via_gateway(self, content: str) -> List[float]:
        """Route embedding request through the dedicated ML service."""
        from ..ml.inference_server import inference_proxy
        try:
            result = inference_proxy.run_inference(
                "generate_embedding", 
                {"text": content, "model_name": self.model_id}
            )
            return result
        except Exception as ex:
            logger.warning(f"ML gateway failed for embedding: {ex}. Switching to inline processing.")
            # Fallback: load and compute locally within current process
            self._initialize_local_encoder()
            vector = self._encoder.encode(content)
            return vector.tolist()

    async def _produce_cloud_embedding(self, content: str) -> List[float]:
        try:
            from openai import AsyncOpenAI
            client = AsyncOpenAI(api_key=self.cloud_api_token)
            response = await client.embeddings.create(
                input=[content],
                model=self.cloud_model_id
            )
            return response.data[0].embedding
        except ImportError:
            logger.error("openai library not found. Install via: pip install openai")
            raise
        except Exception as ex:
            logger.error(f"Cloud embedding generation error: {ex}")
            raise

    def vector_size(self) -> int:
        """Determine the dimensionality of generated embeddings."""
        if self.use_cloud_embeddings:
            # Standard OpenAI embedding models (e.g., text-embedding-3-small, ada-002) use 1536 dimensions
            return 1536
        else:
            self._initialize_local_encoder()
            # Common sentence-transformer models typically output 384 or 768 dimensions
            return self._encoder.get_sentence_embedding_dimension()

