from rich.text import Text

def format_dict_to_rich(d) -> Text:
    """Convert a dictionary to Rich Text format.
    This function is deprecated. Use format_json_to_rich instead.
    """
    return format_json_to_rich(d)

def format_json_to_rich(data) -> Text:
    """Format JSON-compatible data into Rich Text representation.
    Supports dictionaries, lists, strings, numbers, booleans, and None values.
    """
    result = Text()

    if isinstance(data, dict):
        for key, value in data.items():
            if value is None:
                continue  # omit null entries

            result.append(f"\n  {key}: ", style="bold")

            if isinstance(value, str):
                # Process multiline strings with appropriate indentation
                if "\n" in value:
                    result.append("\n")
                    for line in value.split("\n"):
                        result.append(f"    {line}\n")
                else:
                    result.append(f'"{value}"')
            elif isinstance(value, (list, dict)):
                result.append(str(value))
            else:
                result.append(str(value))

    elif isinstance(data, list):
        result.append(f"[List containing {len(data)} elements]\n")
        for index, element in enumerate(data):
            result.append(f"  [{index}]: ", style="bold")
            if isinstance(element, str):
                result.append(f'"{element}"\n')
            else:
                result.append(f"{element}\n")

    elif isinstance(data, str):
        # Format multiline strings with proper indentation
        if "\n" in data:
            result.append("String:\n")
            for line in data.split("\n"):
                result.append(f"  {line}\n")
        else:
            result.append(f'"{data}"')

    elif data is None:
        result.append("null")

    else:
        # Handle numeric, boolean, and other primitive types
        result.append(str(data))

    return result

