from typing import Any, Dict, List, Optional

class ValidateResult:
    """A simple validation outcome structure used in volcengine-api.
    It provides minimal interface: validity flag, list of error strings,
    and an optional mapping for additional contextual data.
    """
    __slots__ = ("valid", "messages", "metadata")

    def __init__(self, valid: bool, messages: Optional[List[str]] = None, metadata: Optional[Dict[str, Any]] = None):
        self.valid = bool(valid)
        self.messages = list(messages) if messages is not None else []
        self.metadata = dict(metadata) if metadata is not None else {}

    def as_dict(self) -> Dict[str, Any]:
        return {"valid": self.valid, "messages": self.messages, "metadata": self.metadata}

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, ValidateResult):
            return NotImplemented
        return (self.valid == other.valid and 
                self.messages == other.messages and 
                self.metadata == other.metadata)

    def __str__(self) -> str:
        return f"ValidateResult(valid={self.valid}, messages={self.messages}, metadata={self.metadata})"

