from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """Determine whether any pair of numbers in the list are within the specified threshold distance."""
    n = len(numbers)
    for idx1 in range(n):
        for idx2 in range(idx1 + 1, n):
            if abs(numbers[idx1] - numbers[idx2]) <= threshold and abs(numbers[idx1] - numbers[idx2]) != 0:
                return True
    return False

