# Set up logger for checkpoint-related messages
logger = logging.getLogger(__name__)

def determine_checkpoint_directory(checkpoint_base_path, step_count, is_release=False):
    """Determine the directory name for this rank's checkpoint."""
    if is_release:
        dir_name = 'release'
    else:
        dir_name = 'iter_{:07d}'.format(step_count)

    full_path = os.path.join(checkpoint_base_path, dir_name)
    return full_path

def get_tracker_file_path(checkpoint_root):
    """Tracker file records the latest checkpoint during training for resumption."""
    return os.path.join(checkpoint_root, 'latest_checkpointed_iteration.txt')

def parse_checkpoint_metadata(tracker_file):
    # Examine the tracker file to retrieve checkpoint state info
    current_step = 0
    is_release_version = False

    try:
        with open(tracker_file, 'r') as meta_file:
            content = meta_file.read().strip()

            try:
                current_step = int(content)
            except ValueError:
                # If not an integer, check if it indicates a release checkpoint
                is_release_version = (content == 'release')

                if not is_release_version:
                    raise ValueError('ERROR: Invalid metadata file {}.'.format(tracker_file))

    except FileNotFoundError:
        print(f"Warning: Tracker file {tracker_file} not found")
        return 0, False

    if not (current_step > 0 or is_release_version):
        print(f'Error parsing metadata file {tracker_file}')

    return current_step, is_release_version

import os
from ..process import Process
from ..command_decorators import command
from . import register_command

@command()
@register_command('download')
def cmd_download(process: Process) -> int:
    """
    Download an AGFS file or directory to local filesystem
    Usage: download [-r] <agfs_path> <local_path>
    """
    # Parse arguments
    recursive_flag = False
    argument_list = list(process.args)

    if argument_list and argument_list[0] == '-r':
        recursive_flag = True
        argument_list = argument_list[1:]

    if len(argument_list) != 2:
        process.stderr.write("download: usage: download [-r] <agfs_path> <local_path>\n")
        return 1

    remote_path = argument_list[0]
    target_path = argument_list[1]

    # Normalize remote path relative to current working directory
    if not remote_path.startswith('/'):
        remote_path = os.path.join(process.cwd, remote_path)
        remote_path = os.path.normpath(remote_path)

    try:
        # Get information about the remote resource
        metadata = process.filesystem.get_file_info(remote_path)

        # Handle local path if it's a directory
        if os.path.isdir(target_path):
            item_name = os.path.basename(remote_path)
            target_path = os.path.join(target_path, item_name)

        is_directory = metadata.get('isDir', False)

        if is_directory:
            if not recursive_flag:
                process.stderr.write(f"download: {remote_path}: Is a directory (use -r to download recursively)\n")
                return 1
            return _recursive_download_dir(process, remote_path, target_path)
        else:
            return _single_file_transfer(process, remote_path, target_path)

    except FileNotFoundError:
        process.stderr.write(f"download: {target_path}: Cannot create file\n")
        return 1
    except PermissionError:
        process.stderr.write(f"download: {target_path}: Permission denied\n")
        return 1
    except Exception as exc:
        exception_text = str(exc)
        if "No such file or directory" in exception_text or "not found" in exception_text.lower():
            process.stderr.write(f"download: {remote_path}: No such file or directory\n")
        else:
            process.stderr.write(f"download: {exception_text}\n")
        return 1


def _single_file_transfer(process: Process, remote_path: str, local_path: str, show_progress: bool = True) -> int:
    """Helper: Transfer a single file from AGFS to local storage"""
    try:
        data_stream = process.filesystem.read_file(remote_path, stream=True)
        total_bytes = 0

        with open(local_path, 'wb') as output_file:
            for segment in data_stream:
                if segment:
                    output_file.write(segment)
                    total_bytes += len(segment)

        if show_progress:
            process.stdout.write(f"Downloaded {total_bytes} bytes to {local_path}\n")
            process.stdout.flush()
        return 0

    except Exception as error:
        process.stderr.write(f"download: {remote_path}: {str(error)}\n")
        return 1


def _recursive_download_dir(process: Process, remote_dir: str, local_dir: str) -> int:
    """Helper: Recursively download a directory from AGFS"""
    try:
        # Ensure local directory exists
        os.makedirs(local_dir, exist_ok=True)

        # Enumerate contents of remote directory
        items = process.filesystem.list_directory(remote_dir)

        for item in items:
            name = item['name']
            is_directory = item.get('isDir', False)

            remote_item_path = os.path.normpath(os.path.join(remote_dir, name))
            local_item_path = os.path.join(local_dir, name)

            if is_directory:
                sub_result = _recursive_download_dir(process, remote_item_path, local_item_path)
                if sub_result != 0:
                    return sub_result
            else:
                file_result = _single_file_transfer(process, remote_item_path, local_item_path)
                if file_result != 0:
                    return file_result

        return 0

    except Exception as issue:
        process.stderr.write(f"download: {str(issue)}\n")
        return 1

