from collections import OrderedDict
import torch
from megatron.core.inference.inference_request import InferenceRequest
from megatron.core.inference.text_generation_controllers.text_generation_controller import (
    TextGenerationController,
)


class TokenAdapter:
    """Adapts tokenizer for inference tasks by exposing standardized interfaces."""
    def __init__(self, base_tokenizer):
        self.end_of_dialogue_id = base_tokenizer.eos_token_id
        self.token_vocab_size = None
        self._base_tokenizer = base_tokenizer

    def decode_sequence(self, token_ids):
        return self._base_tokenizer.decode(token_ids, skip_special_tokens=False)

    def encode_text(self, input_text):
        return self._base_tokenizer.encode(input_text, add_special_tokens=False)


class VisionLanguageTextGenerator(TextGenerationController):
    """Controller for vision-language models that handle image inputs during generation."""
    def __init__(self, model_wrapper, tokenizer, img_processor):
        super().__init__(model_wrapper, TokenAdapter(tokenizer))
        self.image_preprocessor = img_processor

    def prepare_input_representations(self, user_prompt: str, image_data):
        token_seq = self.tokenizer.encode_text(user_prompt)
        if image_data is None:
            height = self.image_preprocessor.size["height"]
            width = self.image_preprocessor.size["width"]
            image_info = {
                "pixel_values": torch.zeros(1, 4, 3, height, width),
                "aspect_ratio_ids": torch.tensor([0], dtype=torch.long),
                "num_tiles": [0],
            }
        else:
            processed = self.image_preprocessor.preprocess(image_data, return_tensors="pt")
            image_info = {
                key: processed[key][0]
                for key in ["pixel_values", "aspect_ratio_ids", "num_tiles"]
                if key in processed
            }
        return token_seq, image_info

    def format_batch_inputs(
        self,
        token_batches: torch.Tensor,
        pending_requests: OrderedDict[str, InferenceRequest],
        apply_mask: bool = False,
    ):
        """Constructs batched inputs for inference using underlying model's preprocessing.

        Args:
            token_batches: Tensor of shape [batch_size, max_seq_len]
            pending_requests: Mapping of request IDs to active InferenceRequest objects
            apply_mask: Flag indicating whether to use attention masking (currently unused)
        """
        images = [req.encoder_prompt for req in pending_requests.values()]
        return self.model_wrapper.format_inference_inputs(
            token_sequences=token_batches,
            visual_data=images,
        )


class QwenVLInferenceController(VisionLanguageTextGenerator):
    """Specialized controller for Qwen-VL model inference."""
    def __init__(self, model_wrapper, tokenizer, img_processor, multimodal_processor):
        super().__init__(model_wrapper, tokenizer, img_processor)

        class QwenVLEncoder(TokenAdapter):
            def decode_sequence(self, token_ids):
                adjusted = []
                for tid in token_ids:
                    if tid == 151652:
                        adjusted.append(tid)
                        adjusted.append(151655)
                    elif tid != 151655:
                        adjusted.append(tid)
                return self._base_tokenizer.decode(adjusted, skip_special_tokens=False)

        self.tokenizer = QwenVLEncoder(tokenizer)
        self.multimodal_processor = multimodal_processor

    def prepare_input_representations(self, user_prompt: str, image_data):
        """Processes prompt and image via multimodal processor to produce tokens and image metadata."""
        encoded = self.multimodal_processor(
            text=[user_prompt],
            images=image_data,
            padding=True,
            return_tensors="pt",
        )
        token_list = encoded["input_ids"][0].tolist()

        image_metadata = None
        if "pixel_values" in encoded:
            image_metadata = {
                "pixel_values": encoded["pixel_values"],
                "image_grid_thw": encoded["image_grid_thw"],
            }

        return token_list, image_metadata

