import math
import torch
import torch.nn as nn
from einops import rearrange, repeat

def generate_time_embeddings(time_indices, embedding_dim, max_duration=10000, only_repeat=False, tensor_type=torch.float32):
    if not only_repeat:
        half_dim = embedding_dim // 2
        # Compute frequency components using logarithmic spacing
        log_max_duration = math.log(max_duration)
        frequencies = torch.exp(-log_max_duration * torch.arange(
            start=0, end=half_dim, dtype=torch.float32, device=time_indices.device) / half_dim)

        # Scale time indices by frequencies
        scaled_times = time_indices[:, None].float() * frequencies[None]

        # Combine cosine and sine components
        embeddings = torch.cat([torch.cos(scaled_times), torch.sin(scaled_times)], dim=-1)

        # Handle odd-dimensional case by padding with zeros
        if embedding_dim % 2 == 1:
            embeddings = torch.cat([embeddings, torch.zeros_like(embeddings[:, :1])], dim=-1)
    else:
        # Simple repetition of time indices across dimensions
        embeddings = repeat(time_indices, "b -> b d", d=embedding_dim)

    return embeddings.to(tensor_type)

class TemporalFeatureEmbedder(nn.Module):
    def __init__(self, feature_size, projection_dim=None, max_duration=10000, only_repeat=False):
        super().__init__()
        self.feature_size = feature_size
        self.projection_dim = projection_dim if projection_dim is not None else feature_size
        self.max_duration = max_duration
        self.only_repeat = only_repeat

        # Build the embedding transformation network
        self.temporal_transform = nn.Sequential(
            nn.Linear(feature_size, self.projection_dim),
            nn.SiLU(),
            nn.Linear(self.projection_dim, self.projection_dim),
        )

    @property
    def data_type(self) -> torch.dtype:
        """Determine the data type of this module based on its parameters or buffers."""
        params = list(self.parameters())
        if len(params) > 0:
            return params[0].dtype
        else:
            buffers = list(self.buffers())
            return buffers[0].dtype if buffers else torch.get_default_dtype()

    def forward(self, time_steps):
        base_emb = generate_time_embeddings(
            time_steps, 
            self.feature_size, 
            self.max_duration, 
            self.only_repeat, 
            tensor_type=self.data_type
        )
        return self.temporal_transform(base_emb)

