    assert len(result.interrupts) > 0

    interrupt_event = result.interrupts[0]

    # Second session run with approval response
    session_manager = FileSessionManager(session_id="strands-test-interrupt", storage_dir=tmpdir)
    agent = Agent(hooks=[approval_hook], session_manager=session_manager, tools=[clock_tool, forecast_tool])

    # Submit approval response
    responses = [
        {
            "interruptResponse": {
                "interruptId": interrupt_event.id,
                "response": "APPROVE",
            },
        },
    ]

    # Continue execution with approval
    result = agent(responses)

    # Verify successful completion
    assert result.stop_reason == "end_turn"

    # Verify both tools executed successfully
    result_json = json.dumps(result.message).lower()
    assert "12:00" in result_json
    assert "sunny" in result_json

