# Type III Clone: Refactored platform detection with equivalent logic and behavior

from __future__ import annotations
import torch
from transformers.utils.import_utils import is_torch_npu_available
import areal.utils.logging as logging
from .cpu import CpuPlatform
from .cuda import CudaPlatform
from .npu import NPUPlatform
from .platform import Platform
from .unknown import UnknownPlatform

logger = logging.getLogger("PlatformInit")
npu_support_flag = is_torch_npu_available()

def _detect_and_build_platform() -> Platform:
    """
    Determine the optimal computing backend based on hardware availability.
    Order of preference:
      1. NVIDIA GPU (CUDA)
      2. Huawei Ascend NPU (if supported)
      3. General CPU fallback
    Returns:
        A configured instance of a Platform subclass matching the system's capabilities.
    """
    if torch.cuda.is_available():
        gpu_model = torch.cuda.get_device_name().upper()
        logger.info(f"GPU identified: {gpu_model}")

        if "NVIDIA" in gpu_model:
            logger.info("CUDA backend selected (NVIDIA GPU).")
            return CudaPlatform()
        else:
            logger.warning("CUDA device not recognized as NVIDIA. Using UnknownPlatform.")
            return UnknownPlatform()

    elif npu_support_flag:
        logger.info("Ascend NPU backend selected.")
        return NPUPlatform()

    else:
        logger.info("No GPU/NPU detected; defaulting to CPU backend.")
        return CpuPlatform()


class _DeferredPlatform:
    """
    Delayed initialization mechanism for platform configuration.
    Avoids triggering CUDA context creation during module import by
    deferring detection until first use.
    """
    def __init__(self):
        self._backend: Platform | None = None
        self._setup_complete = False

    def _prepare_backend(self) -> Platform:
        """Initialize backend only once, then reuse."""
        if not self._setup_complete:
            self._backend = _detect_and_build_platform()
            self._setup_complete = True
        assert self._backend is not None, "Backend must be initialized at this point."
        return self._backend

    def __getattr__(self, attr_name: str):
        """Forward attribute requests to the underlying platform."""
        backend = self._prepare_backend()
        return getattr(backend, attr_name)

    def __setattr__(self, attr_name: str, value):
        """Handle setting attributes either on wrapper or delegated backend."""
        if attr_name.startswith("_"):
            super().__setattr__(attr_name, value)
        else:
            backend = self._prepare_backend()
            setattr(backend, attr_name, value)

    def __repr__(self) -> str:
        """Custom string representation reflecting initialization state."""
        if self._setup_complete:
            return f"DeferredPlatform({self._backend!r})"
        else:
            return "DeferredPlatform(not yet initialized)"


# Global singleton proxy for current platform — initialized lazily upon first access
current_platform: Platform | _DeferredPlatform = (
    _DeferredPlatform()
)  # NOTE: This acts as a proxy object, not inheriting from Platform directly.

__all__ = ["Platform", "current_platform", "npu_support_flag"]

import math
import pytest
import torch
import tilegym
from tests import common

class Test_MLADecodingSplitKV(common.PyTestCase):
    @staticmethod
    def _compute_attn_scores(q, qpe, kv, kpe, scale):
        """Compute attention logits: QK^T + QPE KPE^T"""
        # Ensure float precision for stable numerics
        qk = torch.matmul(q.float(), kv.transpose(-1, -2))
        if kpe.numel() > 0:
            qk += torch.matmul(qpe.float(), kpe.transpose(-1, -2))
        return qk * scale

    @staticmethod
    def _softmax_with_normalization(logits):
        """Apply softmax with numerical stability via max subtraction"""
        max_vals, _ = torch.max(logits, dim=-1, keepdim=True)
        exp_logits = torch.exp(logits - max_vals)
        sum_exp = torch.sum(exp_logits, dim=-1, keepdim=True)
        return exp_logits / sum_exp

    @staticmethod
    def reference_impl(q, qpe, kv, kpe, sm_scale=None, compute_dtype=torch.float16):
        """Alternative reference implementation using modular steps"""
        if sm_scale is None:
            total_dim = q.size(-1) + qpe.size(-1)
            sm_scale = 1.0 / math.sqrt(total_dim)

        # Cast inputs to compute dtype
        q_f, qpe_f = q.to(compute_dtype), qpe.to(compute_dtype)
        kv_f, kpe_f = kv.to(compute_dtype), kpe.to(compute_dtype)

        # Step 1: Compute attention scores
        attn_logits = Test_MLADecodingSplitKV._compute_attn_scores(q_f, qpe_f, kv_f, kpe_f, sm_scale)

        # Step 2: Apply softmax
        attn_weights = Test_MLADecodingSplitKV._softmax_with_normalization(attn_logits).to(q.dtype)

        # Step 3: Weighted sum over values
        output = torch.matmul(attn_weights, kv_f).to(q.dtype)
        return output

    @staticmethod
    def _infer_sm_scale(q_tensor, qpe_tensor):
        """Derive scaling factor from combined head & positional dims"""
        combined_dim = q_tensor.shape[-1] + qpe_tensor.shape[-1]
        return 1.0 / math.sqrt(combined_dim)

    _BACKENDS = ["cutile"]

    @pytest.mark.parametrize("num_heads", [16, 32])
    @pytest.mark.parametrize("seq_len", [129, 1024, 8192, 11049])
    @pytest.mark.parametrize("kv_chunk_size", [128, 512])
    @pytest.mark.parametrize("dtype", [torch.float16])
    @pytest.mark.parametrize("backend", _BACKENDS)
    def test_mla_decoding_split_kv(self, num_heads, seq_len, kv_chunk_size, dtype, backend, arch):
        """Verify MLA decoding with split KV cache matches reference implementation"""
        if not tilegym.is_backend_available(backend):
            pytest.skip(f"Backend '{backend}' unavailable")
        self.setUp()

        if not torch.cuda.is_available():
            pytest.skip("CUDA not available; skipping GPU-dependent test")

        batch_size = 1
        head_dim = 512
        pos_dim = 64
        device = torch.device("cuda")

        # Seed for deterministic randomness
        torch.manual_seed(42)

        # Prepare inputs
        query = torch.randn(batch_size, num_heads, head_dim, device=device, dtype=dtype)
        query_pe = torch.randn(batch_size, num_heads, pos_dim, device=device, dtype=dtype)
        key_val = torch.randn(batch_size, seq_len, head_dim, device=device, dtype=dtype)
        key_pe = torch.randn(batch_size, seq_len, pos_dim, device=device, dtype=dtype)

        scale = self._infer_sm_scale(query, query_pe)

        # Define target function under test
        def target_fn():
            return tilegym.ops.mla_decoding_split_kv(query, query_pe, key_val, key_pe, scale, kv_chunk_size)

        # Reference computation
        def baseline_fn():
            return self.reference_impl(query, query_pe, key_val, key_pe, scale)

        # Validate correctness
        self.assertCorrectness(target_fn, baseline_fn, atol=1e-2, rtol=1e-2, multiple_outputs=False)

import dataclasses
import einops
import numpy as np
from openpi import transforms
from openpi.models import model as _model


def generate_robocasa_sample() -> dict:
    """Generates a synthetic input sample mimicking Robocasa observations."""
    return {
        "observation/state": np.random.rand(8),  # eef position (3) + orientation (4) + gripper width (1)
        "observation/image": np.random.randint(0, 256, size=(3, 224, 224), dtype=np.uint8),
        "observation/wrist_image": np.random.randint(0, 256, size=(3, 224, 224), dtype=np.uint8),
        "prompt": "perform task",
    }


def _normalize_and_rearrange(img):
    """Converts image to HWC uint8 format, handling both float and int inputs."""
    arr = np.array(img)
    if np.issubdtype(arr.dtype, np.floating):
        arr = np.clip(arr * 255.0, 0, 255).astype(np.uint8)
    elif arr.dtype != np.uint8:
        arr = arr.astype(np.uint8)
    # Ensure channel-last layout
    if arr.ndim == 3 and arr.shape[0] == 3:
        arr = einops.rearrange(arr, "c h w -> h w c")
    return arr


@dataclasses.dataclass(frozen=True)
class RobocasaInputFormatter(transforms.DataTransformFn):
    """
    Transforms raw Robocasa-style inputs into the expected model schema.
    Supports base and wrist camera views; pads missing right-wrist view.
    """
    model_kind: _model.ModelType

    def __call__(self, batch_item: dict) -> dict:
        # Preprocess images to standard format
        main_view = _normalize_and_rearrange(batch_item["observation/image"])
        arm_view = _normalize_and_rearrange(batch_item["observation/wrist_image"])

        # Construct standardized input dictionary
        formatted = {
            "state": batch_item["observation/state"],
            "image": {
                "base_0_rgb": main_view,
                "left_wrist_0_rgb": arm_view,
                "right_wrist_0_rgb": np.zeros_like(arm_view),
            },
            "image_mask": {
                "base_0_rgb": True,
                "left_wrist_0_rgb": True,
                "right_wrist_0_rgb": False,  # Only mask for PI0 models
            },
        }

        # Include actions if present (training-time only)
        if "actions" in batch_item:
            formatted["actions"] = batch_item["actions"]

        # Propagate language instruction
        if "prompt" in batch_item:
            formatted["prompt"] = batch_item["prompt"]

        return formatted


@dataclasses.dataclass(frozen=True)
class RobocasaOutputAdapter(transforms.DataTransformFn):
    """
    Converts model outputs back to environment-specific action space.
    Handles both 7D (Panda) and 12D (PandaOmron) action formats.
    """
    target_action_dim: int | None = None

    def __call__(self, model_output: dict) -> dict:
        raw_actions = np.asarray(model_output["actions"])

        # Use explicit dimension if provided
        if self.target_action_dim is not None:
            trimmed = raw_actions[:, : self.target_action_dim]
            return {"actions": trimmed}

        # Auto-detect based on known robot configurations
        last_dim = raw_actions.shape[-1]
        if last_dim in {7, 12}:
            return {"actions": raw_actions}
        else:
            # Default to 12D for mobile-base robots
            return {"actions": raw_actions[:, :12]}

import argparse
import os
import sys
import requests

def fetch_api_credentials():
    """Retrieve API key from environment variables"""
    api_token = os.environ.get('TESSIE_API_KEY')
    if not api_token:
        print("Error: TESSIE_API_KEY environment variable not set", file=sys.stderr)
        sys.exit(1)
    return api_token

def main():
    parser = argparse.ArgumentParser(description='Check Tesla software updates')
    parser.add_argument('--vin', help='Vehicle VIN (optional, uses first vehicle if not specified)')

    parsed_args = parser.parse_args()
    token = fetch_api_credentials()

    auth_headers = {'Authorization': f'Bearer {token}'}

    try:
        # Fetch vehicle list
        api_response = requests.get('https://api.tessie.com/vehicles', headers=auth_headers)
        api_response.raise_for_status()
        vehicle_data = api_response.json()

        target_vehicle = None

        if parsed_args.vin:
            # Search for specific vehicle by VIN
            for car in vehicle_data.get('results', []):
                if car.get('vin') == parsed_args.vin:
                    target_vehicle = car
                    break

            if not target_vehicle:
                print(f"Error: Vehicle with VIN {parsed_args.vin} not found", file=sys.stderr)
                sys.exit(1)
        else:
            # Use first available vehicle if no VIN provided
            vehicles_list = vehicle_data.get('results', [])
            if not vehicles_list:
                print("Error: No vehicles found in account", file=sys.stderr)
                sys.exit(1)
            target_vehicle = vehicles_list[0]

        # Extract software update information
        update_info = target_vehicle.get('last_state', {}).get('vehicle_state', {}).get('software_update')

        if update_info and 'status' in update_info:
            version_num = update_info.get('version', 'unknown')
            current_status = update_info.get('status')

            if current_status == 'available':
                print(f"UPDATE_AVAILABLE: Software update {version_num} is ready to install!")
            elif current_status == 'downloading':
                progress_pct = update_info.get('download_perc', 0)
                print(f"UPDATE_DOWNLOADING: Downloading update {version_num} ({progress_pct}%)")
            elif current_status == 'installing':
                progress_pct = update_info.get('install_perc', 0)
                print(f"UPDATE_INSTALLING: Installing update {version_num} ({progress_pct}%)")
            elif current_status == 'scheduled':
                print(f"UPDATE_SCHEDULED: Update {version_num} is scheduled")
            else:
                print("NO_UPDATE")
        else:
            print("NO_UPDATE")

    except requests.exceptions.RequestException as error:
        print(f"Error: Failed to check for updates: {error}", file=sys.stderr)
        sys.exit(1)
    except Exception as error:
        print(f"Unexpected error: {error}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

