class LibrispeechLmConfig(datasets.BuilderConfig):
    """Configuration for LibriSpeech language modeling dataset."""

    def __init__(self, **kwargs):
        # Extract custom language model corpus path if provided
        self.lm_corpus_path = kwargs.pop("lm_corpus_path", None)
        super().__init__(
            **kwargs,
        )

    def __post_init__(self):
        # Set default corpus path if not explicitly provided
        if self.lm_corpus_path is None:
            self.lm_corpus_path = _DL_URL


class LibrispeechLm(datasets.GeneratorBasedBuilder):
    """Dataset builder for LibriSpeech language modeling tasks."""

    VERSION = datasets.Version("0.1.0")
    BUILDER_CONFIG_CLASS = LibrispeechLmConfig

    def _info(self):
        return datasets.DatasetInfo(
            description=_DESCRIPTION,
            features=datasets.Features({"text": datasets.Value("string")}),
            supervised_keys=("text", "text"),
            homepage=_URL,
            citation=_CITATION,
        )

    def _split_generators(self, dl_manager):
        """Prepare split-specific data paths."""
        split_paths = {}

        for split_name, files in self.config.data_files.items():
            if split_name == "train":
                # For training: combine LM corpus with transcript files
                downloaded_items = dl_manager.download_and_extract(
                    [self.config.lm_corpus_path] + files
                )
                split_paths[split_name] = downloaded_items
            else:
                # For validation/test: only process provided files
                split_paths[split_name] = dl_manager.download_and_extract(files)

        return [
            datasets.SplitGenerator(
                name=split_name,
                gen_kwargs={"file_paths": file_paths}
            )
            for split_name, file_paths in split_paths.items()
        ]

    def _generate_examples(self, file_paths):
        """Generate text examples from downloaded files."""
        example_id = 0

        for filepath in file_paths:
            with open(filepath, "r", encoding="utf-8") as file_handle:
                for line_content in file_handle:
                    # Clean up transcript IDs (e.g., "123-456-789 ")
                    cleaned_line = re.sub(r"\d+-\d+-\d+\s", "", line_content).strip()

                    # Filter out empty lines and overly long sequences
                    if cleaned_line and len(cleaned_line) < 1000:
                        yield example_id, {"text": cleaned_line}
                        example_id += 1

import base64
from typing import Optional

def decode_base64_string(encoded_data: str) -> Optional[str]:
    """Attempt to decode a base64-encoded string, handling URL-safe variants and padding issues."""
    # Remove leading/trailing whitespace
    processed = encoded_data.strip()
    if not processed:
        return None

    # Add necessary padding to make length a multiple of 4
    padding_needed = (4 - len(processed) % 4) % 4
    padded_data = processed + "=" * padding_needed

    # Try decoding with both standard and URL-safe base64 decoders
    for decode_func in [base64.urlsafe_b64decode, base64.b64decode]:
        try:
            decoded_bytes = decode_func(padded_data)
            return decoded_bytes.decode("utf-8")
        except (ValueError, UnicodeDecodeError):
            continue

    return None

from ..process import Process
from ..command_decorators import command
from . import register_command

@command()
@register_command('export')
def cmd_export(process: Process) -> int:
    """
    Set or display environment variables
    Usage: export [VAR=value ...]
    """
    # Handle case when no arguments provided - show current environment
    if len(process.args) == 0:
        if hasattr(process, 'env') and process.env is not None:
            for key in sorted(process.env.keys()):
                process.stdout.write(f"{key}={process.env[key]}\n".encode('utf-8'))
        return 0

    # Process each argument to set environment variables
    for parameter in process.args:
        if '=' not in parameter:
            process.stderr.write(f"export: usage: export VAR=value\n")
            return 1

        # Split into variable name and value
        parts = parameter.split('=', 1)
        var_name = parts[0].strip()
        var_value = parts[1].strip() if len(parts) > 1 else ''

        # Validate variable name contains only alphanumeric characters and underscores/hyphens
        if var_name and all(c.isalnum() or c in ('_', '-') for c in var_name):
            if hasattr(process, 'env'):
                process.env[var_name] = var_value
        else:
            process.stderr.write(f"export: invalid variable name: {var_name}\n")
            return 1

    return 0

# RMSNorm implementation using mlx.core for normalization with root mean square

import mlx.core as mx

class RMSNormalization:
    def __init__(self, features: int, scale: mx.array, epsilon: float = 1e-5):
        self.dim = features
        self.weight = scale
        self.eps = epsilon

    def forward(self, input_tensor: mx.array) -> mx.array:
        # Compute RMS normalization: x / sqrt(mean(x^2) + eps) * weight
        norm = mx.sqrt(mx.mean(input_tensor ** 2, axis=-1, keepdims=True) + self.eps)
        normalized = (input_tensor / norm) * self.weight
        return normalized

    def __call__(self, x: mx.array) -> mx.array:
        return self.forward(x)

import json
import sys
from pypdf import PdfReader, PdfWriter
from extract_form_field_info import get_field_info

def populate_pdf_form(input_path: str, config_path: str, output_path: str):
    with open(config_path) as file:
        form_data = json.load(file)

    organized_fields = {}
    for entry in form_data:
        if "value" in entry:
            field_identifier = entry["field_id"]
            page_number = entry["page"]
            if page_number not in organized_fields:
                organized_fields[page_number] = {}
            organized_fields[page_number][field_identifier] = entry["value"]

    document_reader = PdfReader(input_path)
    encountered_issues = False

    field_metadata = get_field_info(document_reader)
    field_lookup = {item["field_id"]: item for item in field_metadata}

    for entry in form_data:
        registered_field = field_lookup.get(entry["field_id"])
        if not registered_field:
            encountered_issues = True
            print(f"ERROR: `{entry['field_id']}` is not a recognized field identifier")
        elif entry["page"] != registered_field["page"]:
            encountered_issues = True
            print(f"ERROR: Page mismatch for `{entry['field_id']}` (provided: {entry['page']}, expected: {registered_field['page']})")
        else:
            if "value" in entry:
                validation_issue = validate_field_value(registered_field, entry["value"])
                if validation_issue:
                    print(validation_issue)
                    encountered_issues = True

    if encountered_issues:
        sys.exit(1)

    document_writer = PdfWriter(clone_from=document_reader)
    for page_num, field_entries in organized_fields.items():
        target_page = document_writer.pages[page_num - 1]
        document_writer.update_page_form_field_values(target_page, field_entries, auto_regenerate=False)

    document_writer.set_need_appearances_writer(True)

    with open(output_path, "wb") as output_file:
        document_writer.write(output_file)

def validate_field_value(field_descriptor, provided_value):
    field_category = field_descriptor["type"]
    field_name = field_descriptor["field_id"]

    if field_category == "checkbox":
        selected_state = field_descriptor["checked_value"]
        deselected_state = field_descriptor["unchecked_value"]
        if provided_value != selected_state and provided_value != deselected_state:
            return f'ERROR: Invalid value "{provided_value}" for checkbox field "{field_name}". Expected either "{selected_state}" or "{deselected_state}"'

    elif field_category == "radio_group":
        available_options = [option["value"] for option in field_descriptor["radio_options"]]
        if provided_value not in available_options:
            return f'ERROR: Invalid value "{provided_value}" for radio group field "{field_name}". Acceptable options: {available_options}'

    elif field_category == "choice":
        permitted_choices = [option["value"] for option in field_descriptor["choice_options"]]
        if provided_value not in permitted_choices:
            return f'ERROR: Invalid value "{provided_value}" for dropdown field "{field_name}". Valid selections: {permitted_choices}'

    return None

def apply_pypdf_patch():
    from pypdf.generic import DictionaryObject
    from pypdf.constants import FieldDictionaryAttributes

    original_inherited_getter = DictionaryObject.get_inherited

    def modified_inherited_getter(self, key: str, default=None):
        base_result = original_inherited_getter(self, key, default)
        if key == FieldDictionaryAttributes.Opt:
            if isinstance(base_result, list) and all(isinstance(item, list) and len(item) == 2 for item in base_result):
                base_result = [inner[0] for inner in base_result]
        return base_result

    DictionaryObject.get_inherited = modified_inherited_getter

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    apply_pypdf_patch()
    input_pdf_file = sys.argv[1]
    fields_config = sys.argv[2]
    output_pdf_file = sys.argv[3]

    populate_pdf_form(input_pdf_file, fields_config, output_pdf_file)

