def extract_question_text(prompt):
    # Extract question from various prompt formats
    if prompt.startswith('OCR tokens: '):
        pattern = r"Question:\s*(.*?)\s*Short answer:"
        match = re.search(pattern, prompt, re.DOTALL)
        if match:
            return match.group(1).strip().lower()

    elif 'Reference OCR token:' in prompt and len(prompt.split('\n')) == 3:
        lines = prompt.split('\n')
        if lines[0].startswith('Reference OCR token:'):
            return lines[1].strip().lower()
        else:
            return lines[0].strip().lower()

    elif len(prompt.split('\n')) == 2:
        return prompt.split('\n')[0].strip().lower()

    raise ValueError(f"Unexpected prompt format: {prompt[:50]}...")

def evaluate_predictions(annotation_path, prediction_path):
    # Get experiment name from file
    filename = os.path.basename(prediction_path)
    experiment_name = os.path.splitext(filename)[0]
    print(experiment_name)

    # Load annotations
    with open(annotation_path, 'r') as f:
        data = json.load(f)
    annotations_dict = data['data']

    # Create lookup dictionary for annotations
    annotation_lookup = {}
    for item in annotations_dict:
        key = (item['image_id'], item['question'].lower())
        annotation_lookup[key] = item

    # Load predictions
    with open(prediction_path, 'r') as f:
        predictions = [json.loads(line) for line in f]

    # Prepare evaluation data
    evaluation_samples = []
    for pred in predictions:
        question_key = (pred['question_id'], extract_question_text(pred['prompt']))
        gt_annotation = annotation_lookup[question_key]

        evaluation_samples.append({
            "predicted_answer": pred['text'],
            "ground_truth_answers": gt_annotation['answers'],
        })

    # Run evaluation
    evaluator = TextVQAAccuracyEvaluator()
    accuracy = evaluator.eval_pred_list(evaluation_samples)

    print(f"Tested samples: {len(evaluation_samples)}")
    print(f"Accuracy: {accuracy * 100:.2f}%")

if __name__ == "__main__":
    cli_args = parse_arguments()

    # Process single file if specified
    if cli_args.predictions is not None:
        evaluate_predictions(cli_args.annotations, cli_args.predictions)

    # Process all files in directory if specified
    if cli_args.predictions_dir is not None:
        for filename in sorted(os.listdir(cli_args.predictions_dir)):
            if not filename.endswith('.jsonl'):
                print(f"Ignoring non-prediction file: {filename}")
                continue

            full_path = os.path.join(cli_args.predictions_dir, filename)
            evaluate_predictions(cli_args.annotations, full_path)

# Custom weighted aggregation logic for grader results

from typing import Dict, Any
from openjudge.graders.schema import GraderError, GraderRank, GraderResult, GraderScore
from openjudge.runner.aggregator.base_aggregator import BaseAggregator


class WeightedSumAggregator(BaseAggregator):
    """
    Combines multiple grading outcomes using a weighted average approach.
    Supports scores, ranks, and error states from various graders,
    producing a unified score with detailed traceability.
    """

    def __init__(self, label: str, weight_map: Dict[str, float] = None):
        """
        Construct the aggregator instance.
        Args:
            label: Identifier for this aggregator
            weight_map: Optional mapping of grader identifiers to their importance factors.
                        Defaults to uniform distribution if omitted.
        """
        super().__init__(label)
        self.weight_map = weight_map or {}

    def __call__(self, evaluation_results: Dict[str, GraderResult], **context) -> GraderResult:
        """
        Fuse multiple evaluation outputs into one composite score.
        Args:
            evaluation_results: Mapping of grader names to their individual assessment outcomes
            **context: Reserved for future extensions (currently unused)
        Returns:
            Composite result encapsulated in GraderResult format
        """
        if not evaluation_results:
            return GraderError(
                name=self.name,
                reason="Missing input data",
                error="No evaluation results available for fusion",
            )

        # Determine weights: use provided ones or default to equal contribution
        if not self.weight_map:
            keys = list(evaluation_results.keys())
            base_weight = 1.0 / len(keys) if keys else 0.0
            current_weights = {k: base_weight for k in keys}
        else:
            current_weights = self.weight_map

        aggregate_score = 0.0
        cumulative_weight = 0.0
        outcome_details = {}

        # Process each grader's output individually
        for evaluator_name, outcome in evaluation_results.items():
            if isinstance(outcome, GraderScore):
                factor = current_weights.get(evaluator_name, 0.0)
                aggregate_score += outcome.score * factor
                cumulative_weight += factor
                outcome_details[evaluator_name] = {
                    "value": outcome.score,
                    "importance": factor,
                    "note": outcome.reason,
                }
            elif isinstance(outcome, GraderError):
                outcome_details[evaluator_name] = {
                    "issue": outcome.error,
                }
            elif isinstance(outcome, GraderRank):
                outcome_details[evaluator_name] = {
                    "position": outcome.rank,
                    "comment": outcome.reason,
                }

        # Normalize final score only when valid weights exist
        normalized_score = (
            aggregate_score / cumulative_weight if cumulative_weight > 0 else 0.0
        )

        # Build interpretable summary string
        summary_clauses = []
        for identifier, details in outcome_details.items():
            if "value" in details:
                summary_clauses.append(
                    f"{identifier}: {details['value']:.3f} (importance: {details['importance']:.2f})"
                )
            elif "issue" in details:
                summary_clauses.append(f"{identifier}: FAILURE")
            elif "position" in details:
                summary_clauses.append(f"{identifier}: position {details['position']}")

        summary = f"Weighted fusion of {', '.join(summary_clauses)}"

        # Deliver final aggregated result
        return GraderScore(
            name=self.name,
            score=normalized_score,
            reason=summary,
            metadata={
                "factors": current_weights,
            },
        )

# Mock implementation for pytorch3d-like functionality
import torch
import numpy as np


class AlternativeTransforms:
    """Alternative mock implementation for rotation transformations."""

    @staticmethod
    def rot_mat_to_quat(matrix):
        """Convert rotation matrix to quaternion using simplified approach."""
        batch_count = matrix.shape[0] if len(matrix.shape) > 2 else 1
        return torch.tensor([[1.0, 0.0, 0.0, 0.0]] * batch_count)

    @staticmethod
    def quat_to_rot_mat(quaternion):
        """Convert quaternion to rotation matrix using simplified approach."""
        batch_count = quaternion.shape[0] if len(quaternion.shape) > 1 else 1
        return torch.eye(3).unsqueeze(0).repeat(batch_count, 1, 1)

    @staticmethod
    def axis_angle_to_rot_mat(axis_angle):
        """Convert axis-angle representation to rotation matrix."""
        batch_count = axis_angle.shape[0] if len(axis_angle.shape) > 1 else 1
        return torch.eye(3).unsqueeze(0).repeat(batch_count, 1, 1)

    @staticmethod
    def rot_mat_to_axis_angle(matrix):
        """Convert rotation matrix to axis-angle representation."""
        batch_count = matrix.shape[0] if len(matrix.shape) > 2 else 1
        return torch.zeros(batch_count, 3)

    @staticmethod
    def euler_to_rot_mat(euler_angles, order="XYZ"):
        """Convert Euler angles to rotation matrix."""
        batch_count = euler_angles.shape[0] if len(euler_angles.shape) > 1 else 1
        return torch.eye(3).unsqueeze(0).repeat(batch_count, 1, 1)

    @staticmethod
    def rot_mat_to_euler(matrix, order="XYZ"):
        """Convert rotation matrix to Euler angles."""
        batch_count = matrix.shape[0] if len(matrix.shape) > 2 else 1
        return torch.zeros(batch_count, 3)


# Build module structure with alternative naming
class pytorch3d_module:
    transforms = AlternativeTransforms()


# Inject into sys.modules for import compatibility
import sys
sys.modules['pytorch3d'] = pytorch3d_module
sys.modules['pytorch3d.transforms'] = AlternativeTransforms

import torch
from graph_net.optional import Optional
from torch.profiler import profile, record_function, ProfilerActivity

class KernelCounterWrapper(torch.nn.Module):
    def __init__(self, base_model: torch.nn.Module, kernel_counter_ref: Optional):
        super().__init__()
        self.base_model = base_model
        self.optimized_model = torch.compile(self.base_model)
        self.kernel_counter_ref = kernel_counter_ref

    def forward(self, *args, **kwargs):
        outputs, kernel_count = measure_kernel_launches(
            self.optimized_model, args, kwargs
        )
        self.kernel_counter_ref.set(Optional(kernel_count))
        return outputs


def measure_kernel_launches(model, positional_inputs=(), keyword_inputs=None) -> tuple:
    """
    Estimate how many CUDA kernels are launched during one inference pass.
    Uses PyTorch’s profiler to detect kernel launch events.
    """
    model.eval()

    def execute_inference():
        if keyword_inputs is not None and len(keyword_inputs) > 0:
            return model(**keyword_inputs)
        elif len(positional_inputs) > 0:
            return model(*positional_inputs)
        else:
            return model()

    # Warm-up runs to stabilize compilation
    for _ in range(3):
        execute_inference()

    # Run profiling session
    with profile(
        activities=[ProfilerActivity.CUDA, ProfilerActivity.CPU],
        record_shapes=True,
        schedule=torch.profiler.schedule(wait=0, warmup=0, active=1),
    ) as prof:
        with record_function("inference_execution"):
            output_tensors = execute_inference()

    # Aggregate kernel event counts
    kernel_events = prof.key_averages()
    launch_count = 0
    for evt in kernel_events:
        event_name = evt.key.lower()
        if "launchkernel" in event_name:
            launch_count += evt.count

    return output_tensors, launch_count

import torch
