except ImportError:
    _tensorrt_module = None


class TensorRTBackend(GraphCompilerBackend):
    def __init__(self, config):
        super().__init__(config)

    def __call__(self, model):
        # Check if torch_tensorrt is available before proceeding
        if _tensorrt_module is None:
            raise ImportError("torch_tensorrt is not installed")

        # Compile the model using TensorRT backend
        return torch.compile(model, backend="tensorrt")

    def synchronize(self):
        # Synchronize CUDA operations
        torch.cuda.synchronize()

    def version(self):
        # Return the version of torch_tensorrt if available
        return getattr(_tensorrt_module, "version", None)

