import base64
from typing import TYPE_CHECKING, Any, Dict, Optional

if TYPE_CHECKING:
    from api.db.models import ExternalCredentialModel


def generate_auth_header(credential: "ExternalCredentialModel") -> Dict[str, str]:
    """Generate authentication header based on credential type.
    Supports the following credential types:
    - bearer_token: Authorization: Bearer <token>
    - api_key: Custom header with API key
    - basic_auth: Authorization: Basic <base64(username:password)>
    - custom_header: Any custom header name/value pair
    Args:
        credential: The ExternalCredentialModel instance
    Returns:
        Dict with header name and value, or empty dict if credential type
        is not recognized or is 'none'
    """
    auth_type = credential.credential_type
    auth_data = credential.credential_data or {}

    if auth_type == "bearer_token":
        token_value = auth_data.get("token", "")
        return {"Authorization": f"Bearer {token_value}"}
    elif auth_type == "api_key":
        key_header = auth_data.get("header_name", "X-API-Key")
        api_key_val = auth_data.get("api_key", "")
        return {key_header: api_key_val}
    elif auth_type == "basic_auth":
        user_name = auth_data.get("username", "")
        pass_word = auth_data.get("password", "")
        combined = f"{user_name}:{pass_word}".encode()
        encoded_str = base64.b64encode(combined).decode()
        return {"Authorization": f"Basic {encoded_str}"}
    elif auth_type == "custom_header":
        custom_name = auth_data.get("header_name", "X-Custom")
        custom_val = auth_data.get("header_value", "")
        return {custom_name: custom_val}

    return {}


def generate_auth_header_from_params(
    credential_type: str,
    credential_data: Optional[Dict[str, Any]] = None,
) -> Dict[str, str]:
    """Generate authentication header from raw credential data.
    This is a convenience function when you have credential data
    directly rather than a full ExternalCredentialModel.
    Args:
        credential_type: Type of credential (bearer_token, api_key, etc.)
        credential_data: Dict containing credential-specific fields
    Returns:
        Dict with header name and value
    """
    cred_info = credential_data or {}

    if credential_type == "bearer_token":
        token_val = cred_info.get("token", "")
        return {"Authorization": f"Bearer {token_val}"}
    elif credential_type == "api_key":
        header_key = cred_info.get("header_name", "X-API-Key")
        api_key_val = cred_info.get("api_key", "")
        return {header_key: api_key_val}
    elif credential_type == "basic_auth":
        username_val = cred_info.get("username", "")
        password_val = cred_info.get("password", "")
        merged = f"{username_val}:{password_val}".encode()
        encoded_result = base64.b64encode(merged).decode()
        return {"Authorization": f"Basic {encoded_result}"}
    elif credential_type == "custom_header":
        header_field = cred_info.get("header_name", "X-Custom")
        header_content = cred_info.get("header_value", "")
        return {header_field: header_content}

    return {}

import requests
from typing import Tuple, Dict, Any, Optional
import logging
from .base import BaseDnsProvider

logger = logging.getLogger(__name__)

class HoverDnsProvider(BaseDnsProvider):
    PROVIDER_TYPE = "hover"
    PROVIDER_NAME = "Hover"
    PROVIDER_DESCRIPTION = "Hover DNS (session-based authentication)"
    REQUIRED_CREDENTIALS = ["username", "password"]

    API_ENDPOINT = "https://www.hover.com/api"

    def __init__(self, credentials: Dict[str, Any]):
        super().__init__(credentials)
        self._auth_session = None

    def _authenticate(self) -> Tuple[bool, str]:
        if self._auth_session:
            return True, "Session already active"

        self._auth_session = requests.Session()
        try:
            response = self._auth_session.post(
                f'{self.API_ENDPOINT}/login',
                data={
                    'username': self.credentials['username'], 
                    'password': self.credentials['password']
                }, 
                timeout=30
            )

            auth_result = response.json().get('succeeded', False)
            if response.status_code != 200 or not auth_result:
                self._auth_session = None
                return False, "Login unsuccessful"

            return True, "Successfully authenticated"

        except requests.RequestException as exception:
            self._auth_session = None
            return False, str(exception)

    def _execute_request(self, http_method: str, endpoint: str, payload: Optional[Dict] = None) -> Tuple[bool, Any]:
        success, error = self._authenticate()
        if not success:
            return False, error

        try:
            response = self._auth_session.request(
                method=http_method, 
                url=f'{self.API_ENDPOINT}{endpoint}', 
                json=payload, 
                timeout=30
            )

            if response.status_code >= 400:
                return False, response.reason

            return True, response.json() if response.text else None

        except requests.RequestException as exception:
            return False, str(exception)

    def add_txt_record(self, domain: str, record_name: str, record_value: str, ttl: int = 300) -> Tuple[bool, str]:
        relative_name = self.get_relative_record_name(record_name, domain)
        payload = {
            'name': relative_name, 
            'type': 'TXT', 
            'content': record_value
        }

        success, result = self._execute_request('POST', f'/domains/{domain}/dns', payload)
        if not success:
            return False, f"Record creation failed: {result}"

        return True, "TXT record added successfully"

    def remove_txt_record(self, domain: str, record_name: str) -> Tuple[bool, str]:
        success, records_data = self._execute_request('GET', f'/domains/{domain}/dns')
        if not success:
            return False, f"Failed to retrieve records: {records_data}"

        entries = records_data.get('domains', [{}])[0].get('entries', [])
        for entry in entries:
            if (entry.get('type') == 'TXT' and 
                entry.get('name') == self.get_relative_record_name(record_name, domain)):
                self._execute_request('DELETE', f'/dns/{entry["id"]}')

        return True, "TXT record removed successfully"

    def verify_connection(self) -> Tuple[bool, str]:
        success, domains_data = self._execute_request('GET', '/domains')
        if success:
            domain_list = domains_data.get('domains', [])
            return True, f"Connection established. Detected {len(domain_list)} domain(s)"
        return False, f"Connection verification failed: {domains_data}"

    @classmethod
    def get_authentication_schema(cls):
        return [
            {'name': 'username', 'label': 'Username/Email', 'type': 'text', 'required': True},
            {'name': 'password', 'label': 'Password', 'type': 'password', 'required': True},
        ]

