from dataclasses import dataclass

logger = logging.getLogger(__name__)

@dataclass
class MooncakeTransferEngineConfig:
    local_host: str
    meta_server: str
    comm_protocol: str
    nic_name: str

    @staticmethod
    def from_json_file(path: str) -> "MooncakeTransferEngineConfig":
        with open(path, 'r') as fp:
            raw_data = json.load(fp)
        return MooncakeTransferEngineConfig(
            local_host=raw_data.get("local_hostname", ""),
            meta_server=raw_data.get("metadata_server"),
            comm_protocol=raw_data.get("protocol", "rdma"),
            nic_name=raw_data.get("device_name", "")
        )

    @classmethod
    def create_via_environment(cls) -> "MooncakeTransferEngineConfig":
        config_path = os.environ.get("MOONCAKE_CONFIG_PATH", "/data/nvme1/yongyang/FL/LightX2V/configs/mooncake_config.json")
        if not config_path:
            raise ValueError("Environment variable 'MOONCAKE_CONFIG_PATH' must be set.")
        return cls.from_json_file(config_path)


class MooncakeDataTransmitter:
    def __init__(self):
        self.transmitter = None
        try:
            from mooncake.engine import TransferEngine
            self.transmitter = TransferEngine()
        except ImportError:
            logger.warning(
                "Mooncake library not found. Install it following the guide at "
                "https://github.com/kvcache-ai/Mooncake/blob/main/docs/source/getting_started/build.md"
            )

        try:
            self.settings = MooncakeTransferEngineConfig.create_via_environment()
            logger.info("Configuration loaded successfully.")
        except Exception as err:
            logger.error(f"Failed to load configuration: {err}")
            raise

        self.setup(
            self.settings.local_host,
            self.settings.meta_server,
            self.settings.comm_protocol,
            self.settings.nic_name
        )
        # session_id = f"{self.settings.local_host}:{self.transmitter.get_rpc_port()}" if self.transmitter else ""
        self.session_id = f"{self.settings.local_host}:{self.transmitter.get_rpc_port()}" if self.transmitter else ""

    def setup(self, hostname: str, server: str, protocol: str, device: str) -> None:
        """Initialize the transfer engine."""
        if self.transmitter:
            self.transmitter.initialize(hostname, server, protocol, device)

    def bind_memory(self, address: int, size: int) -> None:
        """Register a memory region for transfer."""
        if self.transmitter:
            status = self.transmitter.register_memory(address, size)
            if status != 0:
                logger.error("Memory binding failed.")
                raise RuntimeError("Memory binding failed.")

    def unbind_memory(self, address: int) -> None:
        """Deregister a previously bound memory region."""
        if self.transmitter:
            status = self.transmitter.unregister_memory(address)
            if status != 0:
                logger.error("Memory unbinding failed.")
                raise RuntimeError("Memory unbinding failed.")

    def send_sync(self, session: str, src_addr: int, dst_addr: int, bytes_count: int) -> int:
        """Perform synchronous write transfer."""
        if self.transmitter:
            result = self.transmitter.transfer_sync_write(session, src_addr, dst_addr, bytes_count)
            if result < 0:
                logger.error("Synchronous transfer failed.")
                raise RuntimeError("Synchronous transfer failed.")
            return result
        return -1

    def get_local_identifier(self) -> str:
        return self.settings.local_host

    def get_session_handle(self) -> str:
        return self.session_id

# SkillPay API client for billing operations

import json
import sys
import argparse
import os
import urllib.request
import urllib.error

BASE_URL = "https://skillpay.me/api/v1"
SKILL_IDENTIFIER = "66a1cf1e-9177-4fd9-a417-8917978118e3"

def _get_api_key(key=None):
    """Retrieve API key from parameter or environment variable."""
    return key if key else os.environ.get("SKILLPAY_API_KEY")

def _make_post_request(endpoint, payload, api_key):
    """Send POST request to SkillPay API with JSON payload."""
    url = f"{BASE_URL}{endpoint}"
    headers = {
        "Content-Type": "application/json",
        "X-API-Key": api_key
    }
    data = json.dumps(payload).encode()
    request = urllib.request.Request(url, data=data, headers=headers, method="POST")

    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            return json.loads(response.read().decode())
    except urllib.error.HTTPError as error:
        return json.loads(error.read().decode())

def _make_get_request(endpoint, api_key):
    """Send GET request to SkillPay API."""
    url = f"{BASE_URL}{endpoint}"
    headers = {"X-API-Key": api_key}
    request = urllib.request.Request(url, headers=headers)

    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            return json.loads(response.read().decode())
    except urllib.error.HTTPError as error:
        return json.loads(error.read().decode())

def deduct_credits(user_id, amount=0.005, api_key=None):
    """Deduct credits from user's account."""
    key = _get_api_key(api_key)
    if not key:
        return {"success": False, "error": "SKILLPAY_API_KEY not configured"}

    payload = {
        "user_id": user_id,
        "skill_id": SKILL_IDENTIFIER,
        "amount": amount,
        "currency": "USDT",
        "description": "Prompt Artist"
    }

    result = _make_post_request("/billing/charge", payload, key)

    if result.get("success"):
        return {"success": True, "deducted": amount, "details": result}

    return {
        "success": False,
        "requires_payment": bool(result.get("payment_url")),
        "payment_url": result.get("payment_url", ""),
        "current_balance": result.get("balance", 0),
        "status_message": result.get("message", "credit deduction failed")
    }

def check_account_balance(user_id, api_key=None):
    """Check current balance for a user."""
    key = _get_api_key(api_key)
    if not key:
        return {"success": False, "error": "SKILLPAY_API_KEY not configured"}

    endpoint = f"/billing/balance?user_id={user_id}"
    result = _make_get_request(endpoint, key)

    return {"success": True, "data": result}

def generate_payment_link(user_id, amount=5.0, api_key=None):
    """Generate a payment link for adding funds."""
    key = _get_api_key(api_key)
    if not key:
        return {"success": False, "error": "SKILLPAY_API_KEY not configured"}

    payload = {
        "user_id": user_id,
        "skill_id": SKILL_IDENTIFIER,
        "Amount": amount
    }

    result = _make_post_request("/billing/payment-link", payload, key)

    return {"success": True, "data": result}

