from typing import Any, ClassVar, cast
from klaude_code.core.tool.context import ToolContext
from klaude_code.protocol import llm_param, message, tools


def _normalize_json_schema_types(schema: dict[str, Any]) -> dict[str, Any]:
    """Recursively normalize JSON schema type values to lowercase.

    Some LLMs (e.g., Gemini 3) generate type values in uppercase like "OBJECT", "STRING".
    Standard JSON Schema requires lowercase type values.
    """
    normalized_result: dict[str, Any] = {}
    for field_name, field_value in schema.items():
        if field_name == "type" and isinstance(field_value, str):
            normalized_result[field_name] = field_value.lower()
        elif isinstance(field_value, dict):
            normalized_result[field_name] = _normalize_json_schema_types(
                cast(dict[str, Any], field_value)
            )
        elif isinstance(field_value, list):
            processed_list: list[Any] = []
            for element in cast(list[Any], field_value):
                if isinstance(element, dict):
                    processed_list.append(_normalize_json_schema_types(
                        cast(dict[str, Any], element)
                    ))
                else:
                    processed_list.append(element)
            normalized_result[field_name] = processed_list
        else:
            normalized_result[field_name] = field_value
    return normalized_result


class ReturnResultTool:
    """Special tool for sub-agents to return structured output and end the task.

    This tool is dynamically injected when a parent agent calls a sub-agent with
    an output_schema. The schema for this tool's parameters is defined by the
    parent agent, allowing structured data to be returned.

    Note: This class does not inherit from ToolABC because it's not registered
    in the global tool registry. Instead, it's handled specially by the
    TurnExecutor and SubAgentManager.
    """
    _output_schema: ClassVar[dict[str, Any]] = {}

    @classmethod
    def create_with_schema(cls, schema: dict[str, Any]) -> type["ReturnResultTool"]:
        """Create a tool class with the specified output schema.

        Args:
            schema: JSON Schema defining the expected structure of the report_back arguments.

        Returns:
            A new class with the schema set as a class variable.
        """
        normalized_schema = _normalize_json_schema_types(schema)
        return type("ReturnResultTool", (ReturnResultTool,), {"_output_schema": normalized_schema})

    @classmethod
    def get_tool_schema(cls) -> llm_param.ToolSchema:
        """Generate the tool schema for this report_back tool."""
        return llm_param.ToolSchema(
            name=tools.REPORT_BACK,
            type="function",
            description=(
                "Report the final structured result back to the parent agent. "
                "Call this when you have completed the task and want to return structured data. "
                "The task will end after this tool is called."
            ),
            parameters=cls._output_schema,
        )

    @classmethod
    async def execute(
        cls, 
        arguments: str, 
        context: ToolContext
    ) -> message.ToolResultMessage:
        # Explicitly ignore unused parameters
        _ = arguments
        _ = context

        """Execute the report_back tool.

        The actual handling of report_back results is done by TurnExecutor.
        This method just returns a success status to maintain the tool call flow.
        """
        return message.ToolResultMessage(
            status="success",
            output_text="Result reported successfully. Task will end.",
        )

class ProgressReporter(object):
    """Observer class to monitor and report the progress of the dependency resolution process."""
    def begin_resolution(self):
        """Invoked prior to initiating the resolution procedure."""
    def start_round(self, round_number):
        """Triggered at the beginning of each resolution iteration.
        The round_number is zero-indexed.
        """
    def finish_round(self, round_number, current_state):
        """Triggered at the conclusion of each resolution iteration.
        This method is NOT invoked when resolution terminates in this round; use `finish_resolution`
        for final reporting. The round_number is zero-indexed.
        """
    def finish_resolution(self, final_state):
        """Invoked just before a successful resolution concludes."""
    def incorporate_requirement(self, requirement, source):
        """Triggered when introducing a new constraint into the resolution process.
        :param requirement: The supplementary constraint used to narrow down candidate selections.
        :param source: The candidate that necessitates ``requirement`` as a dependency,
            or None if ``requirement`` originates from root inputs passed to ``Resolver.resolve()``.
        """
    def handle_conflict(self, conflict_details):
        """Triggered when initiating conflict resolution via backtracking.
        :param conflict_details: Information describing the collision that triggered the backtrack.
        """
    def discard_candidate(self, constraint_set, option):
        """Triggered when removing a candidate during backtracking."""
    def accept_candidate(self, option):
        """Triggered when incorporating a candidate into the emerging solution."""

import json
import sys
from extract_form_field_info import get_field_info
from pypdf import PdfReader, PdfWriter

def populate_pdf_form(input_pdf_path: str, fields_json_path: str, output_pdf_path: str):
    # Load field data from JSON file
    with open(fields_json_path) as file:
        form_fields = json.load(file)

    # Organize fields by page for easier access later
    page_field_map = {}
    for field in form_fields:
        if "value" in field:
            field_identifier = field["field_id"]
            page_number = field["page"]
            if page_number not in page_field_map:
                page_field_map[page_number] = {}
            page_field_map[page_number][field_identifier] = field["value"]

    # Initialize PDF reader and validate fields
    pdf_reader = PdfReader(input_pdf_path)
    validation_failed = False

    # Get detailed field information
    field_details = get_field_info(pdf_reader)
    field_lookup = {f["field_id"]: f for f in field_details}

    # Validate each provided field
    for field in form_fields:
        existing_field = field_lookup.get(field["field_id"])
        if not existing_field:
            validation_failed = True
            print(f"ERROR: `{field['field_id']}` is not a valid field ID")
        elif field["page"] != existing_field["page"]:
            validation_failed = True
            print(
                f"ERROR: Incorrect page number for `{field['field_id']}` (got {field['page']}, expected {existing_field['page']})"
            )
        else:
            if "value" in field:
                error_msg = validate_field_value(existing_field, field["value"])
                if error_msg:
                    print(error_msg)
                    validation_failed = True

    # Exit early if any validation errors occurred
    if validation_failed:
        sys.exit(1)

    # Prepare PDF writer with cloned content
    pdf_writer = PdfWriter(clone_from=pdf_reader)

    # Fill in the form fields per page
    for page_num, field_values in page_field_map.items():
        pdf_writer.update_page_form_field_values(
            pdf_writer.pages[page_num - 1], 
            field_values, 
            auto_regenerate=False
        )

    # Ensure appearance streams are regenerated
    pdf_writer.set_need_appearances_writer(True)

    # Write the filled PDF to output file
    with open(output_pdf_path, "wb") as output_file:
        pdf_writer.write(output_file)

def validate_field_value(field_info, field_value):
    field_type = field_info["type"]
    field_id = field_info["field_id"]

    if field_type == "checkbox":
        checked_val = field_info["checked_value"]
        unchecked_val = field_info["unchecked_value"]
        if field_value != checked_val and field_value != unchecked_val:
            return f'ERROR: Invalid value "{field_value}" for checkbox field "{field_id}". The checked value is "{checked_val}" and the unchecked value is "{unchecked_val}"'

    elif field_type == "radio_group":
        option_values = [opt["value"] for opt in field_info["radio_options"]]
        if field_value not in option_values:
            return f'ERROR: Invalid value "{field_value}" for radio group field "{field_id}". Valid values are: {option_values}'

    elif field_type == "choice":
        choice_values = [opt["value"] for opt in field_info["choice_options"]]
        if field_value not in choice_values:
            return (
                f'ERROR: Invalid value "{field_value}" for choice field "{field_id}". Valid values are: {choice_values}'
            )

    return None

def patch_pypdf_behavior():
    from pypdf.constants import FieldDictionaryAttributes
    from pypdf.generic import DictionaryObject

    original_get_inherited = DictionaryObject.get_inherited

    def modified_get_inherited(self, key: str, default=None):
        result = original_get_inherited(self, key, default)
        if (
            key == FieldDictionaryAttributes.Opt
            and isinstance(result, list)
            and all(isinstance(v, list) and len(v) == 2 for v in result)
        ):
            result = [r[0] for r in result]
        return result

    DictionaryObject.get_inherited = modified_get_inherited

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: fill_fillable_fields.py [input pdf] [field_values.json] [output pdf]")
        sys.exit(1)

    patch_pypdf_behavior()
    input_pdf_file = sys.argv[1]
    fields_json_file = sys.argv[2]
    output_pdf_file = sys.argv[3]

    populate_pdf_form(input_pdf_file, fields_json_file, output_pdf_file)

