import gdsfactory as gf
from gdsfactory.typings import LayerSpec
from qpdk.cells.waveguides import rectangle
from qpdk.helper import show_components

@gf.cell
def fabrication_edge_frame(
    chip_dimensions: tuple[float, float] = (10000.0, 10000.0),
    border_thickness: float = 200.0,
    etch_layer: LayerSpec = "M1_ETCH",
) -> gf.Component:
    """Generates a chip boundary frame for fabrication edge definition.

    Constructs a hollow rectangular frame on an etched metal layer to delineate
    the chip perimeter, commonly used in photonic device fabrication processes.

    Args:
        chip_dimensions: (tuple) Overall width and height of the chip area.
        border_thickness: Thickness of the frame's border segments.
        etch_layer: Target layer for the etched frame structure.
    """
    component = gf.Component()

    # Define positions and dimensions for each side of the frame
    frame_segments = [
        {
            "dimensions": (chip_dimensions[0], border_thickness),
            "offset": (0, chip_dimensions[1] - border_thickness),  # Top segment
        },
        {
            "dimensions": (chip_dimensions[0], border_thickness),
            "offset": (0, 0),  # Bottom segment
        },
        {
            "dimensions": (border_thickness, chip_dimensions[1]),
            "offset": (0, 0),  # Left segment
        },
        {
            "dimensions": (border_thickness, chip_dimensions[1]),
            "offset": (chip_dimensions[0] - border_thickness, 0),  # Right segment
        },
    ]

    base_settings = {
        "layer": etch_layer,
        "centered": False,
        "port_type": None,
    }

    # Build each side of the frame
    for segment in frame_segments:
        frame_part = component << rectangle(
            size=segment["dimensions"],
            **base_settings
        )
        frame_part.move(segment["offset"])

    return component


if __name__ == "__main__":
    show_components(
        fabrication_edge_frame,
        spacing=50,
    )

# Custom exception hierarchy for character loading errors

from enum import IntEnum

class ReturnStatus(IntEnum):
    OK = 0
    COMM_FAILURE = 10
    CORRUPT_DATA = 20
    INPUT_ISSUE = 30
    STORAGE_PROBLEM = 40

class CharacterLoadException(Exception):
    status_code = ReturnStatus.CORRUPT_DATA

class ConnectionFailure(CharacterLoadException):
    status_code = ReturnStatus.COMM_FAILURE

class CorruptDataException(CharacterLoadException):
    status_code = ReturnStatus.CORRUPT_DATA

class InputValidationException(CharacterLoadException):
    status_code = ReturnStatus.INPUT_ISSUE

class StorageFailure(CharacterLoadException):
    status_code = ReturnStatus.STORAGE_PROBLEM

