from typing import Any, Optional
import torch
from vllm.model_executor.layers.fused_moe.layer import FusedMoE, UnquantizedFusedMoEMethod
from vllm.model_executor.layers.linear import LinearBase, UnquantizedLinearMethod
from vllm.model_executor.layers.quantization import QuantizationMethods
from vllm.model_executor.layers.quantization.base_config import (
    QuantizationConfig,
    QuantizeMethodBase,
)


class _INCQuantizationConfig(QuantizationConfig):
    """Custom INC-based quantization config class for FP8 support via Intel Neural Compressor."""

    @classmethod
    def get_name(cls) -> QuantizationMethods:
        return "inc"

    @classmethod
    def get_supported_activation_dtypes(cls) -> list[torch.dtype]:
        return [torch.bfloat16]

    @classmethod
    def from_model_config(cls, config_dict: dict[str, Any]) -> "_INCQuantizationConfig":
        raise NotImplementedError("INC config must be instantiated explicitly.")

    def get_quantization_method(
        self, module: torch.nn.Module, layer_name: str
    ) -> Optional["QuantizeMethodBase"]:
        if isinstance(module, LinearBase):
            return UnquantizedLinearMethod()
        elif isinstance(module, FusedMoE):
            return UnquantizedFusedMoEMethod(module.moe_config)
        return None

    @classmethod
    def get_minimum_gpu_capability(cls) -> int:
        raise NotImplementedError("GPU capability not applicable for this config.")

    @staticmethod
    def list_config_files() -> list[str]:
        return []

