from __future__ import annotations
import uuid as uid_generator
from fastapi import APIRouter, Depends, HTTPException, Request
from .manager import CronManager
from .models import CronJobSpec, CronJobView

cron_router = APIRouter(prefix="/cron", tags=["cron"])

def retrieve_cron_manager(request: Request) -> CronManager:
    manager = getattr(request.app.state, "cron_manager", None)
    if manager is None:
        raise HTTPException(
            status_code=503,
            detail="cron manager not initialized",
        )
    return manager

@cron_router.get("/jobs", response_model=list[CronJobSpec])
async def fetch_all_jobs(manager: CronManager = Depends(retrieve_cron_manager)):
    return await manager.list_jobs()

@cron_router.get("/jobs/{job_identifier}", response_model=CronJobView)
async def fetch_single_job(job_identifier: str, manager: CronManager = Depends(retrieve_cron_manager)):
    job = await manager.get_job(job_identifier)
    if not job:
        raise HTTPException(status_code=404, detail="job not found")
    return CronJobView(spec=job, state=manager.get_state(job_identifier))

@cron_router.post("/jobs", response_model=CronJobSpec)
async def add_new_job(
    job_spec: CronJobSpec,
    manager: CronManager = Depends(retrieve_cron_manager),
):
    # server generates id; ignore client-provided spec.id
    job_id = str(uid_generator.uuid4())
    new_job = job_spec.model_copy(update={"id": job_id})
    await manager.create_or_replace_job(new_job)
    return new_job

@cron_router.put("/jobs/{job_identifier}", response_model=CronJobSpec)
async def update_existing_job(
    job_identifier: str,
    job_spec: CronJobSpec,
    manager: CronManager = Depends(retrieve_cron_manager),
):
    if job_spec.id != job_identifier:
        raise HTTPException(status_code=400, detail="job_id mismatch")
    await manager.create_or_replace_job(job_spec)
    return job_spec

@cron_router.delete("/jobs/{job_identifier}")
async def remove_job(
    job_identifier: str,
    manager: CronManager = Depends(retrieve_cron_manager),
):
    success = await manager.delete_job(job_identifier)
    if not success:
        raise HTTPException(status_code=404, detail="job not found")
    return {"deleted": True}

@cron_router.post("/jobs/{job_identifier}/pause")
async def suspend_job(job_identifier: str, manager: CronManager = Depends(retrieve_cron_manager)):
    try:
        await manager.pause_job(job_identifier)
    except Exception as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    return {"paused": True}

@cron_router.post("/jobs/{job_identifier}/resume")
async def activate_job(
    job_identifier: str,
    manager: CronManager = Depends(retrieve_cron_manager),
):
    try:
        await manager.resume_job(job_identifier)
    except Exception as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    return {"resumed": True}

@cron_router.post("/jobs/{job_identifier}/run")
async def trigger_job(job_identifier: str, manager: CronManager = Depends(retrieve_cron_manager)):
    try:
        await manager.run_job(job_identifier)
    except KeyError as error:
        raise HTTPException(status_code=404, detail="job not found") from error
    except Exception as error:
        raise HTTPException(status_code=500, detail=str(error)) from error
    return {"started": True}

@cron_router.get("/jobs/{job_identifier}/state")
async def fetch_job_state(
    job_identifier: str,
    manager: CronManager = Depends(retrieve_cron_manager),
):
    job = await manager.get_job(job_identifier)
    if not job:
        raise HTTPException(status_code=404, detail="job not found")
    return manager.get_state(job_identifier).model_dump(mode="json")

