import base64
import re
import time
from io import BytesIO
from cosmos_rl_reward.handler.reward_base import BaseRewardHandler
from cosmos_rl_reward.handler.registry import RewardRegistry
from cosmos_rl_reward.utils.logging import logger

@RewardRegistry.register()
class UnifiedReward(BaseRewardHandler):
    NEEDS_LATENT_DECODER = False
    reward_name = "unified_reward"

    def __init__(self, endpoint_url="", endpoint_api_key="", **kwargs):
        super().__init__()
        self.api_endpoint = endpoint_url
        self.api_token = endpoint_api_key

    def initialize(self):
        from openai import OpenAI
        self.llm_client = OpenAI(api_key=self.api_token, base_url=self.api_endpoint)

    def encode_image_to_base64(self, img):
        buffer = BytesIO()
        img.save(buffer, format="PNG")
        raw_bytes = buffer.getvalue()
        encoded = base64.b64encode(raw_bytes).decode("utf-8")
        return f"data:image/png;base64,{encoded}"

    def parse_score_from_response(self, response_texts):
        extracted_scores = []
        regex_pattern = r"Final Score:\s*([1-5](?:\.\d+)?)"
        for resp in response_texts:
            found = re.search(regex_pattern, resp)
            if found:
                try:
                    val = float(found.group(1))
                    extracted_scores.append(val)
                except (ValueError, TypeError):
                    extracted_scores.append(0.0)
            else:
                extracted_scores.append(0.0)
        return extracted_scores

    def assess_single_image(self, caption, image_obj):
        instruction = (
            "<image>\n"
            "You are evaluating an image against its corresponding text caption. "
            "Please rate the image on two aspects:\n"
            "1. Alignment with Caption: How accurately does the image reflect the caption’s content?\n"
            "2. Visual Quality: Consider sharpness, color fidelity, composition, and overall aesthetics.\n"
            "Assign a score from 1 to 5 after 'Final Score:'.\n\n"
            f"Caption: [{caption}]"
        )
        encoded_img = self.encode_image_to_base64(image_obj)
        completion = self.llm_client.chat.completions.create(
            model="UnifiedReward-7b-v1.5",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "image_url", "image_url": {"url": encoded_img}},
                        {"type": "text", "text": instruction},
                    ],
                }
            ],
            temperature=0.0,
            stream=False,
        )
        return completion.choices[0].message.content

    def batch_evaluate(self, images_list, captions_list):
        outputs = []
        for cap, img in zip(captions_list, images_list):
            outputs.append(self.assess_single_image(cap, img))
        return outputs

    def compute_reward(self, image_batch, meta_info):
        import torch
        from PIL import Image

        def _fail_with(msg: str):
            logger.error(msg)
            return {
                "error": msg,
                "scores": None,
                "input_info": meta_info.get("input_info", {}),
                "duration": "0.00",
                "decoded_duration": meta_info.get("decode_duration", "N/A"),
                "type": self.reward_name,
            }

        start_time = time.perf_counter()

        # Input validation
        if image_batch is None:
            return _fail_with("[unified_reward] image tensor is missing.")
        if not isinstance(image_batch, torch.Tensor) or image_batch.ndim != 4:
            return _fail_with(
                f"[unified_reward] expects 4D tensor (BHWC/NHWC); got {type(image_batch)}, shape={getattr(image_batch, 'shape', None)}"
            )
        if image_batch.size(0) == 0:
            return _fail_with("[unified_reward] empty batch.")

        data = image_batch
        if data.dtype != torch.uint8:
            data = data.to(torch.uint8)

        # Ensure channel-last layout (HWC)
        if data.shape[-1] == 3:
            nhwc_data = data
        elif data.shape[1] == 3:
            nhwc_data = data.permute(0, 2, 3, 1).contiguous()
        else:
            raise ValueError(f"Expected 3 channels; got shape {data.shape}")

        pil_images = [
            Image.fromarray(nhwc_data[i].numpy()) for i in range(nhwc_data.shape[0])
        ]

        prompts = meta_info.get("prompts")
        if prompts is None:
            return _fail_with("[unified_reward] missing prompts.")
        if isinstance(prompts, str):
            prompts = [prompts]
        if len(prompts) != len(pil_images):
            return _fail_with(
                f"[unified_reward] prompt count ({len(prompts)}) ≠ image count ({len(pil_images)})."
            )

        llm_responses = self.batch_evaluate(pil_images, prompts)
        raw_scores = self.parse_score_from_response(llm_responses)
        normalized_scores = [s / 5.0 for s in raw_scores]

        elapsed = time.perf_counter() - start_time
        return {
            "scores": {"unified_reward": normalized_scores},
            "input_info": meta_info.get("input_info", {}),
            "duration": f"{elapsed:.2f}",
            "decoded_duration": meta_info.get("decode_duration", "N/A"),
            "type": self.reward_name,
        }

import os
from pathlib import Path
from typing import Optional

def _normalize_path_separators(path_str: str) -> str:
    """Convert backslashes to forward slashes on Windows systems."""
    if os.name == "nt":
        return path_str.replace("\\", "/")
    return path_str

def resolve_relative_file_path(project_root: Path, input_path: str) -> Optional[str]:
    """Determine the relative file path with respect to the project root.

    Args:
        project_root (Path): The root directory of the Lean project.
        input_path (str): The input file path (absolute or relative).

    Returns:
        Optional[str]: The normalized relative path using forward slashes,
                       or None if the file cannot be resolved.
    """
    # Try interpreting as absolute path first
    abs_candidate = Path(input_path)
    if abs_candidate.is_absolute() and abs_candidate.exists():
        try:
            rel_path = abs_candidate.relative_to(project_root)
            return _normalize_path_separators(str(rel_path))
        except ValueError:
            pass  # Not under project root

    # Try relative to project root
    project_relative = project_root / input_path
    if project_relative.exists():
        return _normalize_path_separators(str(project_relative.relative_to(project_root)))

    # Try relative to current working directory, but ensure it's within project root
    cwd = Path.cwd()
    cwd_relative = cwd / input_path
    if cwd_relative.exists():
        try:
            resolved = cwd_relative.resolve()
            rel_path = resolved.relative_to(project_root)
            return _normalize_path_separators(str(rel_path))
        except ValueError:
            pass  # Not under project root after resolution

    return None

def read_file_with_fallback_encoding(file_path: str) -> str:
    """Read file content trying multiple encodings in sequence.

    Tries UTF-8 first, then Latin-1, and finally falls back to UTF-8 with error replacement.
    """
    for encoding in ["utf-8", "latin-1"]:
        try:
            with open(file_path, "r", encoding=encoding) as file:
                return file.read()
        except UnicodeDecodeError:
            continue

    # Final fallback: use UTF-8 but replace invalid characters
    with open(file_path, "r", encoding="utf-8", errors="replace") as file:
        return file.read()

