# Alternative implementation: Diffusion-based AutoEncoder wrapper with modular design

import importlib
import warnings
from abc import ABC, abstractmethod
from functools import wraps

import torch
import torch.nn as nn
from diffusers.utils.accelerate_utils import apply_forward_hook


def _normalize_latents_tensor(latent_tensor, mode, config):
    """Internal function to handle latent normalization based on specified strategy."""
    if mode == "value_shift_scale":
        shift = getattr(config, "shift_factor", 0.0)
        scale = getattr(config, "scale_factor", 1.0)
        return (latent_tensor - shift) * scale
    elif mode == "channel_specified_shift_scale":
        mean_arr = torch.tensor(config.latents_mean, dtype=latent_tensor.dtype, device=latent_tensor.device)
        std_arr = torch.tensor(config.latents_std, dtype=latent_tensor.dtype, device=latent_tensor.device)
        # Reshape for broadcasting across spatial/temporal dims
        shape = [1] * len(latent_tensor.shape)
        shape[1] = -1  # channel dimension
        mean_view = mean_arr.view(shape)
        std_view = std_arr.view(shape)
        return (latent_tensor - mean_view) / (std_view + 1e-7)
    else:
        raise ValueError(f"Unsupported normalization mode: {mode}")


class DiffusionAutoEncoder(nn.Module):
    """
    A flexible wrapper around diffusers' AutoEncoder implementations,
    supporting custom tiling, sampling strategies, and latent normalization.
    """

    def __init__(self, arch_name: str, settings: dict):
        super().__init__()

        # Load model dynamically from diffusers
        diffusers_module = importlib.import_module("diffusers")
        autoencoder_class = getattr(diffusers_module, arch_name)
        pretrained_path = settings.pop("from_pretrained", None)
        dtype = settings.pop("dtype", None)

        self._model = autoencoder_class.from_pretrained(pretrained_path, torch_dtype=dtype)
        self._model_type = arch_name

        # Sampling behavior
        self._sample_mode = settings.get("do_sample", True)

        # Tiling configuration
        self._use_custom_tiling = False
        self._tiling_opts = None
        if settings.get("enable_tiling", False):
            self.activate_tiling(settings.get("tiling_param"))

        # Latent normalization settings
        self._apply_norm = settings.pop("norm_latents", True)
        self._norm_strategy = settings.pop("norm_mode", "value_shift_scale")

    def activate_tiling(self, params=None):
        """Enable tiling either via built-in method or mark for custom handling."""
        if hasattr(self._model, "enable_tiling"):
            if params is not None:
                self._model.enable_tiling(**params)
            else:
                self._model.enable_tiling()
        else:
            self._use_custom_tiling = True
            self._tiling_opts = params or {}
            warnings.warn(
                f"{self._model_type} lacks native tiling; ensure custom tiling is implemented."
            )

    def deactivate_tiling(self):
        """Disable tiling if supported, otherwise reset internal flag."""
        if hasattr(self._model, "disable_tiling"):
            self._model.disable_tiling()
        else:
            self._use_custom_tiling = False

    @apply_forward_hook
    def forward_encoder(self, input_tensor, **kwargs):
        """Encode input tensor into latent representation."""
        if self._use_custom_tiling:
            latent_code = self.perform_custom_encoding(input_tensor, **kwargs)
        else:
            encoded_result = self._model.encode(input_tensor, return_dict=True, **kwargs)
            if self._sample_mode:
                latent_code = encoded_result.latent_dist.sample()
            else:
                latent_code = encoded_result.latent_dist.mode()

        if self._apply_norm:
            latent_code = _normalize_latents_tensor(
                latent_code, self._norm_strategy, self._model.config
            )
        return latent_code

    @abstractmethod
    def perform_custom_encoding(self, x, **kwargs):
        """Custom encoding logic when built-in tiling is unavailable."""
        raise NotImplementedError

    @apply_forward_hook
    def forward_decoder(self, latent_input, **kwargs):
        """Decode latent tensor back to pixel space."""
        if self._use_custom_tiling:
            decoded_output = self.perform_custom_decoding(latent_input, **kwargs)
        else:
            decoded_output = self._model.decode(latent_input).sample
        return decoded_output

    @abstractmethod
    def perform_custom_decoding(self, x, **kwargs):
        """Custom decoding logic for tiled reconstruction."""
        raise NotImplementedError

    # Optional utility: expose underlying config for inspection
    @property
    def config(self):
        return self._model.config

