# Reimplementation with equivalent wrapping behavior using alternative structure

from areal.utils.wrapper import (
    wrap,
    wrap_get_method,
    wrap_get_method_name,
    wrap_remove_meta,
    wrapable,
)

class BaseCalc:
    def __init__(self):
        self.offset = 2

    @wrapable()
    def plus(self, first, second):
        return first + second + self.offset

    @wrapable(name="times")
    def times(self, left, right):
        return left * right * self.offset


class AugmentedCalc:
    def __init__(self, base_instance: BaseCalc):
        super().__init__()
        self.label = "Output:"
        self._base = base_instance
        wrap(self, base_instance, self._intercept)

    def _intercept(self, *args, **kwargs):
        # Extract metadata from kwargs to determine target method
        method_id = wrap_get_method_name(kwargs)
        func_ptr = wrap_get_method(kwargs)
        clean_kwargs = wrap_remove_meta(kwargs)

        print("intercepted call:", method_id)
        print("callable object:", func_ptr)
        return func_ptr(*args, **clean_kwargs)


def run_test():
    calculator = BaseCalc()
    enhanced = AugmentedCalc(calculator)

    # Verify wrapped method calls behave as expected
    assert enhanced.plus(2, 3) == 7
    assert enhanced.times(4, 5) == 40


if __name__ == "__main__":
    run_test()

# Image generation script using Volcengine Seedream API (Type III clone)
import argparse
import json
import os
import sys
import urllib.request
import urllib.error

def create_image_request(prompt, model, size, api_key, image_input=None, sequential=False, max_images=1):
    endpoint_url = "https://ark.cn-beijing.volces.com/api/v3/images/generations"
    request_headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {api_key}"
    }

    request_body = {
        "model": model,
        "prompt": prompt,
        "size": size,
    }

    if image_input:
        request_body["image"] = image_input

    if sequential:
        request_body["sequential_image_generation"] = "auto"
        request_body["sequential_image_generation_options"] = {"max_images": max_images}
    else:
        request_body["sequential_image_generation"] = "disabled"

    return endpoint_url, request_headers, request_body

def execute_api_call(url, headers, payload):
    try:
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(url, data=data, headers=headers, method="POST")

        with urllib.request.urlopen(req) as response:
            result = json.loads(response.read().decode("utf-8"))

            if "data" in result and len(result["data"]) > 0:
                for entry in result["data"]:
                    if "url" in entry:
                        print(f"MEDIA_URL: {entry['url']}")
                    elif "b64_json" in entry:
                        print("ERROR: Received base64 data but expected URL.")
            else:
                print(f"ERROR: No image data in response. Full response: {json.dumps(result)}")

    except urllib.error.HTTPError as http_err:
        print(f"ERROR: API request failed: {http_err}")
        print(f"Response body: {http_err.read().decode('utf-8')}")
        sys.exit(1)
    except urllib.error.URLError as url_err:
        print(f"ERROR: Network issue encountered: {url_err.reason}")
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description="Generate images using Volcengine Seedream API.")
    parser.add_argument("--prompt", required=True, help="Text prompt for image generation")
    parser.add_argument("--model", default="doubao-seedream-4-5-251128", help="Model ID or Endpoint ID")
    parser.add_argument("--size", default="2048x2048", help="Image size (e.g., 2K, 4K, 2048x2048)")
    parser.add_argument("--api-key", help="Volcengine API Key")
    parser.add_argument("--image", help="Input image URL or base64 (optional)")
    parser.add_argument("--sequential", action="store_true", help="Enable sequential image generation (group)")
    parser.add_argument("--max-images", type=int, default=1, help="Max images for sequential generation (1-15)")
    args = parser.parse_args()

    api_key = args.api_key or os.environ.get("VOLC_API_KEY")
    if not api_key:
        print("ERROR: API key is required. Provide via --api-key or VOLC_API_KEY environment variable.")
        sys.exit(1)

    target_url, request_headers, payload = create_image_request(
        prompt=args.prompt,
        model=args.model,
        size=args.size,
        api_key=api_key,
        image_input=args.image,
        sequential=args.sequential,
        max_images=args.max_images
    )

    execute_api_call(target_url, request_headers, payload)

if __name__ == "__main__":
    main()

# Abstract base class for file handling operations
from abc import ABC, abstractmethod

class FileHandlerBase(ABC):
    # Flag to determine if the handler works with string-like (True) or bytes-like (False) data
    is_string_based = True

    @abstractmethod
    def read_from_stream(self, stream, **options):
        """Abstract method to load data from a file-like object"""
        pass

    @abstractmethod
    def write_to_stream(self, data, stream, **options):
        """Abstract method to serialize and write data to a file-like object"""
        pass

    @abstractmethod
    def serialize_to_string(self, data, **options):
        """Abstract method to serialize data into a string representation"""
        pass

    def read_from_disk(self, path, open_mode="r", **options):
        """Load data from a file path using standard file operations"""
        with open(path, open_mode) as file_handle:
            return self.read_from_stream(file_handle, **options)

    def write_to_disk(self, data, path, open_mode="w", **options):
        """Write serialized data to a file path using standard file operations"""
        with open(path, open_mode) as file_handle:
            self.write_to_stream(data, file_handle, **options)

