# Skills Indexer using Azure OpenAI for embedding generation

import os
import json
import hashlib
from typing import List, Dict, Any
from openai import AzureOpenAI

class SkillsIndexer:
    def __init__(self, azure_endpoint: str, azure_api_key: str):
        self.client = AzureOpenAI(
            api_version="2024-08-01-preview",
            azure_endpoint=azure_endpoint,
            api_key=azure_api_key
        )
        self.embedding_model_name = "text-embedding-ada-002"
        self.vector_length = 1536

    def create_vector(self, text: str) -> List[float]:
        """Generate vector representation for input text."""
        try:
            result = self.client.embeddings.create(
                input=[text],
                model=self.embedding_model_name
            )
            return result.data[0].embedding
        except Exception as error:
            print(f"Embedding generation failed: {error}")
            return [0.0] * self.vector_length

    def construct_skill_description(self, skill: Dict[str, Any]) -> str:
        """Build a composite description string from skill attributes."""
        segments = []

        if 'title' in skill and skill['title']:
            segments.append(f"Title: {skill['title']}")
        if 'description' in skill and skill['description']:
            segments.append(f"Description: {skill['description']}")
        if 'content' in skill and skill['content']:
            # Limit content length to prevent exceeding token constraints
            truncated_content = skill['content'][:2000]
            segments.append(f"Content: {truncated_content}")
        if 'tags' in skill and skill['tags']:
            segments.append(f"Tags: {', '.join(skill['tags'])}")
        if 'domain' in skill and skill['domain']:
            segments.append(f"Domain: {skill['domain']}")

        return "\n".join(segments)

    def compute_skill_identifier(self, skill: Dict[str, Any]) -> str:
        """Create deterministic identifier using content-based hashing."""
        base_string = f"{skill.get('title', '')}{skill.get('repo', '')}{skill.get('path', '')}"
        hash_digest = hashlib.sha256(base_string.encode()).hexdigest()
        return hash_digest[:16]

    def process_skills_in_groups(self, skills: List[Dict[str, Any]], group_size: int = 50) -> List[Dict[str, Any]]:
        """Process skills in manageable groups with progress tracking."""
        processed_items = []

        total_groups = (len(skills) - 1) // group_size + 1 if skills else 0

        for idx in range(0, len(skills), group_size):
            current_group = skills[idx:idx + group_size]
            group_number = idx // group_size + 1

            print(f"Processing group {group_number}/{total_groups}...")

            for item in current_group:
                combined_text = self.construct_skill_description(item)
                vector_data = self.create_vector(combined_text)

                formatted_item = {
                    'id': self.compute_skill_identifier(item),
                    'title': item.get('title', 'Untitled'),
                    'content': item.get('content', ''),
                    'embedding': vector_data,
                    'metadata': {
                        'source': item.get('source', 'github'),
                        'repo': item.get('repo', ''),
                        'path': item.get('path', ''),
                        'tags': item.get('tags', []),
                        'domain': item.get('domain', ''),
                    }
                }
                processed_items.append(formatted_item)

        return processed_items

