    "bash_shebang": re.compile(r"^#!.*(?:bash|sh)\b"),
    "permission_commands": re.compile(r"\b(?:chown|chmod|id\s+-u|id\s+-g)\b"),
    "audio_system": re.compile(r"\b(?:pulseaudio|pactl)\b"),
    "service_manager": re.compile(r"\bs6-"),
    "socket_type": re.compile(r"unix:"),
    "containerization": re.compile(
        r"(?:docker[-\s]?compose|Dockerfile|docker-compose\.yml)", 
        re.IGNORECASE
    ),
}

# Store findings
FINDINGS = []

# Traverse all files in the project directory
for item in ROOT_DIR.rglob("*"):
    # Only process regular files with specific extensions or no extension
    if not item.is_file() or item.suffix not in (".sh", ".py", ""):
        continue

    try:
        content = item.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        continue  # Skip files that can't be read

    # Check each pattern against the file content
    for rule_name, pattern in DETECTION_RULES.items():
        if pattern.search(content):
            FINDINGS.append((rule_name, str(item)))

# Output results
if not FINDINGS:
    print("No platform-specific patterns detected.")
else:
    print("Platform-specific scan completed:")

    # Group findings by type
    grouped = {}
    for category, filepath in FINDINGS:
        grouped.setdefault(category, []).append(filepath)

    # Print categorized results
    for category, files in grouped.items():
        print(f"\n[{category}]")
        for f in files[:30]:
            print(" •", f)
        if len(files) > 30:
            print("  ... and more")

print("\nScanning finished.")

# Import necessary modules
import asyncio
from dotenv import load_dotenv
from haive.agents.planning.p_and_e.agent import PlanAndExecuteAgent
from langchain_core.tools import tool

# Load environment variables
load_dotenv()

# Define calculation tools with alternative implementations
@tool
def sum_two_numbers(x: int, y: int) -> int:
    """Compute the sum of two integers."""
    return x + y

@tool
def product_of_two(a: int, b: int) -> int:
    """Return the product of two integers."""
    return a * b

@tool
def check_prime(value: int) -> bool:
    """Determine whether a number is prime."""
    if value < 2:
        return False
    for divisor in range(2, int(value ** 0.5) + 1):
        if value % divisor == 0:
            return False
    return True

@tool
def find_prime_at_position(index: int) -> int:
    """Find the prime number at the specified 1-based position."""
    if index <= 0:
        return 0

    found_count = 0
    candidate = 2
    while found_count < index:
        if check_prime(candidate):
            found_count += 1
            if found_count == index:
                return candidate
        candidate += 1
    return candidate

async def run_test():
    # Initialize the planning and execution agent with custom tools
    planner_agent = PlanAndExecuteAgent(
        name="planning_executor",
        tools=[sum_two_numbers, product_of_two, check_prime, find_prime_at_position],
    )

    # Define test scenarios
    test_cases = [
        "What is the total when adding up the first five prime numbers?",
        "Determine the result of multiplying 7 by 8.",
        "Verify if 17 qualifies as a prime number.",
    ]

    # Execute only the first test case
    try:
        await planner_agent.arun(test_cases[0])
    except Exception:
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    asyncio.run(run_test())

