# AI Note Generation Task Creator - Alternative Implementation
import os
import sys
import json
import urllib.request
import urllib.error

def generate_ai_note(video_link: str, token: str) -> dict:
    """Submit a request to create an AI note generation task.

    Args:
        video_link: Publicly accessible video URL
        token: Baidu API authentication token

    Returns:
        Dictionary containing task information including task_id

    Raises:
        Exception: If request fails or server returns error status
    """
    endpoint = "https://qianfan.baidubce.com/v2/tools/ai_note/task_create"
    request_headers = {
        "Authorization": f"Bearer {token}",
        "X-Appbuilder-From": "openclaw",
        "Content-Type": "application/json"
    }
    payload = json.dumps({"url": video_link}).encode('utf-8')

    try:
        req = urllib.request.Request(
            endpoint,
            data=payload,
            headers=request_headers,
            method="POST"
        )

        with urllib.request.urlopen(req, timeout=30) as response:
            result = json.loads(response.read().decode('utf-8'))

            # Check for application-level errors
            if isinstance(result, dict):
                if "code" in result and result["code"] != 200:
                    raise Exception(result.get("detail", "API returned error"))

                if "errno" in result and result["errno"] != 0:
                    raise Exception(result.get("errmsg", "Server-side error occurred"))

                return result.get("data", {})
            else:
                raise Exception("Unexpected response format")

    except urllib.error.HTTPError as e:
        error_body = e.read().decode('utf-8')
        raise Exception(f"HTTP error {e.code}: {error_body}")
    except urllib.error.URLError as e:
        raise Exception(f"Network connectivity issue: {str(e.reason)}")
    except TimeoutError:
        raise Exception("Connection timed out. Verify video URL accessibility.")
    except Exception as e:
        raise Exception(f"Request processing failed: {str(e)}")

def main():
    if len(sys.argv) < 2:
        print(json.dumps({
            "error": "Missing required argument",
            "usage": "python ai_notes_task_create.py <video_url>"
        }, indent=2))
        sys.exit(1)

    video_url = sys.argv[1]
    api_token = os.environ.get("BAIDU_API_KEY")

    if not api_token:
        print(json.dumps({
            "error": "Required environment variable BAIDU_API_KEY is not configured"
        }, indent=2))
        sys.exit(1)

    try:
        task_info = generate_ai_note(video_url, api_token)

        output = {
            "status": "success",
            "message": "Task created successfully",
            "task_id": task_info.get("task_id"),
            "next_step": f"Query task status: python ai_notes_task_query.py {task_info.get('task_id')}"
        }
        print(json.dumps(output, indent=2))

    except Exception as e:
        error_response = {
            "status": "error",
            "error": str(e)
        }
        print(json.dumps(error_response, indent=2))
        sys.exit(1)

if __name__ == "__main__":
    main()

