# API endpoints for managing developer API keys

from typing import Annotated
from fastapi import APIRouter, Body, status
from app.database import DbSession
from app.schemas.api_key import ApiKeyRead, ApiKeyUpdate
from app.services import DeveloperDep, api_key_service

router = APIRouter()

@router.get("/api-keys", response_model=list[ApiKeyRead])
async def get_api_keys_list(db: DbSession, current_developer: DeveloperDep):
    """Retrieve all API keys associated with the current developer."""
    return api_key_service.fetch_all_keys(db, current_developer.id)

@router.post("/api-keys", status_code=status.HTTP_201_CREATED, response_model=ApiKeyRead)
async def generate_new_api_key(
    db: DbSession,
    current_developer: DeveloperDep,
    key_name: Annotated[str, Body(embed=True, description="Descriptive name for the new API key")] = "Default",
):
    """Create a new API key for the developer."""
    return api_key_service.create_new_key(db, current_developer.id, key_name)

@router.delete("/api-keys/{key_identifier}", response_model=ApiKeyRead)
async def remove_api_key(key_identifier: str, db: DbSession, current_developer: DeveloperDep):
    """Delete an existing API key using its unique identifier."""
    return api_key_service.remove_key(db, key_identifier, raise_not_found=True)

@router.patch("/api-keys/{key_identifier}", response_model=ApiKeyRead)
async def modify_api_key(
    key_identifier: str,
    update_data: ApiKeyUpdate,
    db: DbSession,
    current_developer: DeveloperDep,
):
    """Modify properties of an existing API key (e.g., name, permissions)."""
    return api_key_service.apply_updates(db, key_identifier, update_data, raise_not_found=True)

@router.post("/api-keys/{key_identifier}/regenerate", status_code=status.HTTP_201_CREATED, response_model=ApiKeyRead)
async def regenerate_api_key(key_identifier: str, db: DbSession, current_developer: DeveloperDep):
    """Replace an existing API key with a newly generated one."""
    return api_key_service.rotate_key(db, key_identifier, current_developer.id)
